window.__SUM[6]={"LR003553":{"pair":"ADAM10 -> EPHA3","headline":"ADAM10 associates with EphA3 and sheds its ephrin ligand; association is supported by two papers but is an enzyme-receptor partnership.","interaction_type":"direct binding","direction_and_effect":"ADAM10 constitutively associates with EphA3, and the EphA3/ephrin-A5 complex creates a recognition motif for the ADAM10 cysteine-rich domain [PMID:16239146]. Activated EphA3 extends its intracellular domain and facilitates productive association with ADAM10, enabling ephrin shedding in trans [PMID:19823572].","molecular_requirements":"Co-immunoprecipitation showed robust ADAM10 binding to an EphA3 mutant lacking the whole intracellular domain, so extracellular domains suffice for association (results in this paper) [PMID:19823572]. Shedding depends on EphA3 conformation rather than kinase activity [PMID:19823572].","affinity_potency":[],"species_and_systems":"Human proteins in curator rows; HEK293T cells with EphA3 and ADAM10 constructs [PMID:19823572].","localisation_and_range":"EPHA3 flagged both secreted and transmembrane; ADAM10 flagged not secreted [flag]. Shedding acts in trans between cells [PMID:16239146].","caveats":"Both papers read mainly as abstracts; one has full-text excerpts. IntAct lists a co-immunoprecipitation record [DB:IntAct]. The mutual effect on EphA3 signalling is not reported.","key_references":[{"PMID":"19823572","why":"EphA3 conformation controls ADAM10 association and shedding"},{"PMID":"16239146","why":"ADAM10 cysteine-rich domain recognises EphA3/ephrin-A5 complex"}],"covers":["LR000003","LR003553"]},"LR001627":{"pair":"ADAM11 -> ITGA4","headline":"Non-catalytic ADAM11 supports integrin alpha4-dependent cell adhesion in one abstract-only paper.","interaction_type":"functional only","direction_and_effect":"Human ADAM11, ADAM23 and ADAM29 selectively support integrin alpha4-dependent cell adhesion; their disintegrin-like domains are ligands for a subset of integrins [PMID:28913673].","molecular_requirements":"The beta partner and domain details beyond the disintegrin-like domain are not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human proteins; integrin binding assays [PMID:28913673].","localisation_and_range":"ADAM11 is flagged not secreted [flag]; adhesive ligand on a cell surface.","caveats":"One paper, abstract only; the curator's evidence sentence is truncated mid-word. Assay is cell adhesion, not purified binding.","key_references":[{"PMID":"28913673","why":"Non-catalytic ADAMs support integrin alpha4 adhesion"}],"covers":["LR001627","LR005015"]},"LR002068":{"pair":"ADAM17 -> IL6R","headline":"ADAM17 extracellular domains were shown to interact with IL-6R in one abstract-only paper; the effect is protease-substrate recognition.","interaction_type":"direct binding","direction_and_effect":"ADAM17 is a sheddase and IL-6R is one of its substrates; the paper reports an interaction needed for recognition, not receptor signalling [PMID:22575642].","molecular_requirements":"Only the ADAM17 extracellular domains are needed; the transmembrane and cytoplasmic regions are dispensable, and the membrane-proximal domain is mandatory for recognition of IL-6R [PMID:22575642].","affinity_potency":[],"species_and_systems":"Differently tagged ADAM17 deletion variants; species and cell system are not stated in the abstract [PMID:22575642]. Our pair is human, flagged as ortholog-inferred.","localisation_and_range":"ADAM17 is flagged as not secreted and IL-6R as transmembrane [flag]; this is a membrane-membrane (contact) interaction.","caveats":"Abstract read only. This is an enzyme-substrate recognition, not a classic ligand-to-receptor signalling pair. Species of the experiments not reported in our evidence.","key_references":[{"PMID":"22575642","why":"ADAM17 extracellular/membrane-proximal domain mediates IL-6R interaction"}],"covers":["LR002068"]},"LR003562":{"pair":"ADAM17 -> ITGA5","headline":"ADAM17 supports cell adhesion via integrin alpha5beta1 (functional, human HeLa); IntAct lists ADAM17-ITGB1 related records.","interaction_type":"functional only","direction_and_effect":"Recombinant ADAM-17 extracellular fragments support cell adhesion through alpha5beta1 in a trans orientation; adhesion was sensitive to RGD peptides and EDTA, indicating a ligand-receptor relationship via the alpha5beta1 ligand-binding pocket [PMID:14970227].","molecular_requirements":"The integrin-binding site within ADAM-17 maps to the disintegrin/cysteine-rich region [PMID:14970227]. The result concerns alpha5beta1 as a heterodimer; ITGA5 alone is not tested separately in our evidence.","affinity_potency":[],"species_and_systems":"Human cell lines and HeLa cells with recombinant human ADAM-17 fragments [PMID:14970227].","localisation_and_range":"Trans-adhesion with recombinant ectodomain; ADAM17 and alpha5beta1 also co-localise in HeLa membrane ruffles and focal adhesions, suggestive of a cis orientation [PMID:14970227]. ADAM17 is flagged non-secreted [flag].","caveats":"Abstract read only; labelled functional rather than direct binding. IntAct holds two records (co-IP, ELISA) listing the pair, with PMIDs 30455686 and 22413019 [DB:IntAct]; those papers were not read by curators here.","key_references":[{"PMID":"14970227","why":"ADAM-17 supports alpha5beta1-dependent adhesion, RGD/EDTA sensitive"}],"covers":["LR000012","LR003562"]},"LR003571":{"pair":"ADAM9 -> ITGA3","headline":"ADAM9 disintegrin domain captures integrin alpha3 from human renal lysate; abstract only.","interaction_type":"direct binding","direction_and_effect":"Immobilised GST-disintegrin domain with renal cortical lysates specifically recovered the alpha3, alpha6, alphav and beta1 chains; anti-alpha3 antibody also blocked HEK-293 adhesion [PMID:15361064].","molecular_requirements":"Alpha3 is recovered together with beta1 [PMID:15361064]; the disintegrin domain is responsible for competitive inhibition of cell-matrix binding [PMID:15361064].","affinity_potency":[],"species_and_systems":"Human HEK-293 cells and renal cortical lysate; recombinant GST-disintegrin [PMID:15361064]. Mouse pair is ortholog-inferred.","localisation_and_range":"ADAM9 flagged secreted [flag]; basolateral renal tubular expression per the paper [PMID:15361064].","caveats":"Abstract read only; affinity capture from lysate, so not necessarily direct.","key_references":[{"PMID":"15361064","why":"GST-disintegrin pull-down recovers alpha3"}],"covers":["LR000021","LR003571"]},"LR008215":{"pair":"ADAM9 -> ITGAV:ITGB1","headline":"alphaV and beta1 chains were captured by ADAM9 disintegrin domain, but the alphaVbeta1 heterodimer is not shown; one abstract-only paper.","interaction_type":"direct binding","direction_and_effect":"GST-ADAM9 disintegrin domain recovered alphav and beta1 integrin chains from renal cortical lysate, and the domain competitively inhibited HEK-293 adhesion to matrix proteins [PMID:15361064].","molecular_requirements":"Both chains were seen separately by Western; whether alphaVbeta1 specifically is the binding unit is not shown in our evidence [PMID:15361064].","affinity_potency":[],"species_and_systems":"Human HEK-293 and renal cortical lysate [PMID:15361064].","localisation_and_range":"Annotation flags mark ADAM9 as secreted [flag], but the papers use its disintegrin domain as a recombinant or cell-surface-expressed protein, so the physiologically relevant range (juxtacrine versus shed) is not settled in our evidence.","caveats":"One abstract-only paper [PMID:15361064]; the complex assignment is inferred from chains. Affinity not reported. No database support.","key_references":[{"PMID":"15361064","why":"disintegrin domain recovers alphav and beta1 chains"}],"covers":["LR008215"]},"LR002077":{"pair":"ADAMTS13 -> CD36","headline":"Recombinant human ADAMTS13 binds CD36 dose-dependently in an immunoassay; one abstract-only paper.","interaction_type":"direct binding","direction_and_effect":"rHuCD36 bound rHuADAMTS13 in a dose-dependent fashion; ADAMTS13 also preferentially bound platelet membrane fragments expressing CD36 over those expressing GPIb/IX. Binding did not inhibit ADAMTS13 VWF-cleaving activity, so CD36 may localise active enzyme rather than inhibit it [PMID:19389207].","molecular_requirements":"Thrombospondin-2 competed but even high concentrations failed to fully block binding, suggesting partly overlapping sites [PMID:19389207].","affinity_potency":[],"species_and_systems":"Recombinant human proteins in enzyme-linked immunoassay; platelet membrane fragments [PMID:19389207].","localisation_and_range":"Ligand flagged secreted [flag]; CD36 is described as a transmembrane protein on endothelial cells and platelets [PMID:19389207].","caveats":"Abstract-only read; no affinity value in our evidence; no cell-signalling readout. No database support.","key_references":[{"PMID":"19389207","why":"dose-dependent ADAMTS13 binding to CD36, thrombospondin-2 competition"}],"covers":["LR002077","LR005403"]},"LR005407":{"pair":"ADGRL1 -> NRXN2","headline":"Latrophilin-1 ectodomain binds neurexins with nanomolar affinity; evidence is one abstract-only paper that covers neurexins as a group.","interaction_type":"direct binding","direction_and_effect":"Direct binding between the extracellular domains of latrophilin-1 (CL1) and neurexins; CL1 competed with neuroligin-1 for neurexin binding [PMID:22262843]. Cells expressing both formed stable adhesion, so trans-cellular [PMID:22262843].","molecular_requirements":"Neurexins lacking an insert at splice site 4 (SS4) bind CL1; those with an SS4 insert do not. The olfactomedin-like domain of CL1 mediates binding [PMID:22262843].","affinity_potency":[{"value":"nanomolar affinity (value not given)","assay":"saturation binding","system":"purified ectodomains","cite":"PMID:22262843"}],"species_and_systems":"Purified ectodomains and cell adhesion assays; species not stated beyond curator label human [PMID:22262843]. Pair is ortholog-inferred in both species.","localisation_and_range":"Both partners are membrane proteins [flag]; interaction is trans-cellular, suggesting juxtacrine signalling [PMID:22262843].","caveats":"Abstract only, and the abstract speaks of neurexins generally, so isoform specificity for NRXN2 is not shown in our evidence. Only the SS4-minus form binds [PMID:22262843]. Ligand-receptor direction is not defined, as both are membrane proteins.","key_references":[{"PMID":"22262843","why":"identifies latrophilin-1/neurexin binding"}],"covers":["LR002081","LR005407"]},"LR003580":{"pair":"ADIPOQ -> ADIPOR1","headline":"AdipoR1 was expression-cloned as an adiponectin receptor; one abstract-only paper plus Reactome and UniProt records.","interaction_type":"direct binding","direction_and_effect":"AdipoR1/R2 overexpression or siRNA suppression supports a role as receptors for globular and full-length adiponectin, mediating increased AMP kinase and PPAR-alpha ligand activities, fatty-acid oxidation and glucose uptake [PMID:12802337]. Activating effect.","molecular_requirements":"Reactome lists an ADIPOQ trimer bound to ADIPOR dimers [DB:Reactome]. Whether one receptor chain suffices is not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human cDNAs and cells per curator label [PMID:12802337]. Mouse pair is non-inferred, human pair is ortholog-inferred.","localisation_and_range":"Adiponectin is flagged secreted [flag], so hormonal/endocrine action is implied; the receptor is plasma membrane per Reactome [DB:Reactome].","caveats":"Evidence is functional (gain and loss of function), not a direct binding measurement, in the abstract [PMID:12802337]. Paper covers both AdipoR1 and AdipoR2, not separated. No affinity reported.","key_references":[{"PMID":"12802337","why":"expression cloning of AdipoR1 and AdipoR2"}],"covers":["LR000030","LR003580"]},"LR002086":{"pair":"ADIPOQ -> LAIR1","headline":"The globular adiponectin domain interacts with inhibitory receptor LAIR-1 (one 2021 abstract).","interaction_type":"functional only","direction_and_effect":"Globular adiponectin (gAdp) interacted with LAIR-1 and inhibited T cell activation via LAIR-1, involving downstream SHP-2 [PMID:34403808]. Inhibitory effect.","molecular_requirements":"The globular domain was the form studied; other forms not reported in our evidence [PMID:34403808].","affinity_potency":[],"species_and_systems":"In vitro T cell experiments; species not specified in our evidence [PMID:34403808].","localisation_and_range":"Adiponectin flagged secreted [flag]; LAIR1 flagged transmembrane [flag].","caveats":"Abstract only; binding method and affinity not reported, so classed as direct_binding by curators on limited detail. Mouse pair is ortholog-inferred.","key_references":[{"PMID":"34403808","why":"reports gAdp-LAIR-1 interaction"}],"covers":["LR002086","LR005412"]},"LR001636":{"pair":"ADM -> RAMP3","headline":"ADM acts on CLR:RAMP3 (the AM2 receptor); binding shown on the RAMP3/CRLR complex in HEK cells, so RAMP3 is a co-receptor, not a stand-alone receptor.","interaction_type":"direct binding","direction_and_effect":"ADM is an agonist at the RAMP3-containing receptor: 125I-ADM radioligand binding and cAMP responses characterise RAMP3/CRLR as an ADM receptor [PMID:10347248][PMID:11693189]. In HUVEC, ADM-driven migration and invasion is mediated by CRLR/RAMP2 and CRLR/RAMP3 [PMID:14712479]. GtoPdb lists a full agonist [DB:GtoPdb].","molecular_requirements":"RAMP3 acts with CLR/CRLR (obligate heterodimer; RAMP2 or RAMP3 gives AM1 or AM2 receptors) [PMID:27013657]. RAMP2/CRLR and RAMP3/CRLR were indistinguishable for ADM binding and cAMP [PMID:10347248]. Both subunits should be counted when scoring this pair. RAMP3 shapes the CLR juxtamembrane region and gives the most negative ECD electrostatic potential [PMID:27013657].","affinity_potency":[{"value":"pKi 8.3-9.0","assay":"binding, GtoPdb agonist record","system":"not given in the database record","cite":"DB:GtoPdb"},{"value":"pEC50 6.9-8.3","assay":"functional, GtoPdb agonist record","system":"not given in the database record","cite":"DB:GtoPdb"}],"species_and_systems":"Experiments used human or porcine CRLR with rat-ADM tracer in HEK-293/293T cells [PMID:11693189][PMID:10347248], HUVEC [PMID:14712479], and mutagenesis with modelling [PMID:27013657]. The mouse pair is projected from human. A PDB structure (6UUS) contains chains of ADM-pathway receptor proteins P35318 and O60896 [DB:PDB 6UUS].","localisation_and_range":"ADM is flagged secreted and RAMP3 transmembrane [flag]; so paracrine or endocrine signalling to a membrane receptor.","caveats":"Evidence is at complex level, not RAMP3 alone. All papers were read as abstracts (one with full text). One paper counted here concerns AM2/IMD, not ADM [PMID:30139742]. Four papers were abstract_insufficient and one is pending.","key_references":[{"PMID":"10347248","why":"125I-ADM binding on RAMP3/CRLR in HEK293T"},{"PMID":"11693189","why":"radioligand binding and cAMP, human and porcine CRLR with RAMP3"},{"PMID":"27013657","why":"RAMP2/RAMP3 give distinct AM receptor subtypes"}],"covers":["LR001636","LR005024"]},"LR005416":{"pair":"AGR2 -> LYPD3","headline":"AGR2 is reported as a ligand of LYPD3 (C4.4A) by two-hybrid records; the paper adds only a structure and docking suggestion, not a direct demonstration.","interaction_type":"database-asserted only","direction_and_effect":"UniProt says AGR2 interacts with LYPD3 and DAG1 [DB:UniProt]; BioGRID lists two two-hybrid records [DB:BioGRID]. The paper's Fab site on C4.4A appears to be the AGR2 binding site, and docking placed AGR2 near that site [PMID:32140067].","molecular_requirements":"Both LU-domains of LYPD3 contribute to the Fab combining site and the proposed AGR2 contact; the docking points to the DII-Lk1 region [PMID:32140067].","affinity_potency":[],"species_and_systems":"Human C4.4A crystal structures and a ZDOCK docking model; no AGR2-LYPD3 experiment [PMID:32140067].","localisation_and_range":"AGR2 is flagged secreted [flag].","caveats":"The paper calls AGR2 a 'reported ligand' and does not test the interaction. Abstract plus excerpts only. Direction or effect is not reported in our evidence.","key_references":[{"PMID":"32140067","why":"structure of two LU-domain C4.4A with docking of AGR2"}],"covers":["LR002090","LR005416"]},"LR002095":{"pair":"AGRP -> MC1R","headline":"AGRP competes with alpha-MSH for the binding site at MC1R in one 1998 abstract-only study; the receptor binding is shown for agouti protein, not AGRP itself.","interaction_type":"conflicting","direction_and_effect":"In 293T cells, Mc1r conferred a specific, high-affinity binding site for HA-Agouti, and this binding was inhibited by alpha-MSH or by Agrp, indicating mutually exclusive binding [PMID:9450927]. The abstract describes Agouti and Agrp as antagonists of melanocortins [PMID:9450927].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"293T cells and Xenopus melanophores, with mouse in vivo mutant studies; curation tags human/human [PMID:9450927].","localisation_and_range":"Agouti protein and Agrp are described as paracrine-signalling molecules [PMID:9450927].","caveats":"Abstract-only. The direct binding measured is of agouti protein, with AGRP acting only as a competitor, so AGRP binding to MC1R is inferred. The curator effect label is 'agonist', whereas AGRP is described as an antagonist at melanocortin receptors.","key_references":[{"PMID":"9450927","why":"Agouti binds Mc1r and is competed by AGRP"}],"covers":["LR002095","LR005421"]},"LR005425":{"pair":"ALCAM -> ALCAM","headline":"ALCAM binds itself homophilically with weak measured affinity (KD 29-48 microM); the interaction is mentioned in a second paper as background.","interaction_type":"direct binding","direction_and_effect":"ALCAM mediates adhesion through homophilic ALCAM-ALCAM or heterophilic ALCAM-CD6 interactions [PMID:23052204]. Tetraspanin CD9 upregulated both [PMID:23052204]; the homophilic effect was not measured directly. UniProt notes homotypic interactions with ALCAM-expressing cells [DB:UniProt].","molecular_requirements":"Not reported in our evidence beyond ALCAM chains interacting.","affinity_potency":[{"value":"KD 29-48 microM; Koff >= 5.3 s-1","assay":"homophilic binding measured in the study","system":"human CD166","cite":"PMID:15048703"}],"species_and_systems":"Human proteins and leukocytes [PMID:15048703, PMID:23052204]. IntAct lists molecular sieving and solid phase assays [DB:IntAct Q13740-Q13740].","localisation_and_range":"Membrane-bound adhesion molecule acting between cells (juxtacrine); ALCAM carries secreted and transmembrane flags [flag].","caveats":"Affinity is about 100-fold weaker than ALCAM-CD6 [PMID:15048703]. Abstracts only. PMID:23052204 is about CD9 regulation, and the cited sentence is background.","key_references":[{"PMID":"15048703","why":"Measures homophilic CD166 affinity versus CD6"},{"PMID":"23052204","why":"CD9 raises ALCAM homophilic and heterophilic adhesion"}],"covers":["LR002099","LR005425"]},"LR005029":{"pair":"ALCAM -> CHL1","headline":"Antibody blocking suggests Chl1 is needed for ALCAM-promoted axon growth of mouse midbrain dopamine neurons; no direct binding shown in our evidence.","interaction_type":"functional only","direction_and_effect":"ALCAM promoted axon growth of mouse midbrain dopamine neurons, and neutralizing antibodies for Chl1 abolished the effect; the authors propose a trans-heterophilic interaction [PMID:31300520]. ALCAM also abolished Sema3A's growth effect and induced branching with Sema3C [PMID:31300520].","molecular_requirements":"Chl1 is described as one of three components of a Semaphorin receptor complex (Nrp1, Chl1, L1cam) [PMID:31300520]; which is needed alone is not reported in our evidence.","affinity_potency":[],"species_and_systems":"Murine primary midbrain cultures [PMID:31300520]; curator records human for both partners.","localisation_and_range":"ALCAM acts as an extracellular substrate presented to cell-bound partners (juxtacrine/matrix-like) [PMID:31300520]. ","caveats":"Single paper, abstract only; inhibition by antibodies is indirect and shows no binding. No affinity.","key_references":[{"PMID":"31300520","why":"Antibody blocking of Nrp1/Chl1/L1cam abolishes ALCAM growth effect"}],"covers":["LR001641","LR005029"]},"LR001645":{"pair":"ALKAL1 -> LTK","headline":"ALKAL1 is a crystallographically and biochemically supported agonist ligand of LTK; evidence is human, in vitro and in cells.","interaction_type":"direct binding","direction_and_effect":"ALKAL1 (FAM150A) activates LTK; it is described as an LTK-specific ligand that only weakly binds ALK [PMID:26630010]. Both ALKAL1 and ALKAL2 are strong LTK activators [PMID:34646012]. GtoPdb lists an agonist/activation interaction [DB:GtoPdb].","molecular_requirements":"Crystal structure of the LTK cytokine-binding (TNF-like plus glycine-rich) domain with ALKAL1 shows ALKAL1 helix A residues Phe80 and Phe76 inserting into an LTK hydrophobic pocket [PMID:34646012]. LTK-ALKAL1 complexes were 2 receptors : 1 cytokine, not the canonical 2:2 [PMID:34646012]. Site 1 charge-reversal mutants in ALKAL1 markedly reduced affinity for both receptors [PMID:34646012]. Other subunit or co-receptor needs: not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human proteins: purified human LTK ectodomain fragments and ALKAL1 for crystallography [PMID:34646012]; human ALK/LTK-expressing cells in binding and activation assays [PMID:26630010]. The mouse pair is inferred from human by orthology.","localisation_and_range":"ALKAL1 is flagged as secreted in the entity annotation [flag]; Reactome places the LTK dimer:ALKAL1,2 complex at the plasma membrane [DB:Reactome]. Acts as a secreted ligand on a membrane receptor.","caveats":"[PMID:26630010] was read as abstract only. Affinity values are not reported in our evidence. The dossier also lists a PDB entry [DB:PDB 7NX0] and IntAct co-immunoprecipitation [DB:IntAct]. One further row is still pending.","key_references":[{"PMID":"34646012","why":"Crystal structures of LTK with ALKAL1, interface mutagenesis, stoichiometry"},{"PMID":"26630010","why":"Specificity of ALKAL1 for LTK versus ALK in cells"}],"covers":["LR001645","LR005033"]},"LR009610":{"pair":"AMELX -> LAMP1","headline":"Amelogenin binds a cell-surface pool of LAMP1 in murine dental cells; one paper, immunofluorescence evidence, unusual receptor.","interaction_type":"functional only","direction_and_effect":"Full-length recombinant amelogenin showed specific cell-surface binding to murine dental follicle cells and cementoblasts, with a pattern similar to and co-localised with LAMP-1 [PMID:20382373]. Competitive inhibition of 79% by Emdogain suggests a common cell-surface receptor [PMID:20382373].","molecular_requirements":"LAMP-1 was previously suggested as a surface receptor for the LRAP amelogenin isoform; this paper tests full-length amelogenin [PMID:20382373]. Other subunit requirements: not reported in our evidence.","affinity_potency":[],"species_and_systems":"Murine dental follicle cells and OCCM-30 cementoblasts with recombinant mouse amelogenin rp(H)M180, per the abstract [PMID:20382373]; curators record human.","localisation_and_range":"Cell-surface binding on cultured cells; secreted amelogenin flagged [flag].","caveats":"Co-localisation and competition do not show direct LAMP1 binding in this abstract and excerpts. LAMP1 is normally lysosomal. Single paper; no database records. Direction/effect not reported.","key_references":[{"PMID":"20382373","why":"Amelogenin cell-surface binding and LAMP-1 co-localisation"}],"covers":["LR009610"]},"LR007351":{"pair":"AMH -> AMHR2:BMPR1A","headline":"AMH signals through AMHR2 with a type I partner; AMHR2 specificity and mouse Bmpr1a requirement are supported, direct BMPR1A binding is not shown.","interaction_type":"functional only","direction_and_effect":"AMH is the secreted ligand and activates the receptor (agonist); AMH signals through its dedicated type II receptor AMHR2 [PMID:32333774]. Conditional deletion of Bmpr1a in mouse M\u00fcllerian duct mesenchyme blocks AMH-driven duct regression, identifying Bmpr1a as a type I receptor for Amh [PMID:12368913]. GtoPdb lists AMH-AMHR2 and AMH-BMPR1A as agonist interactions [DB:GtoPdb].","molecular_requirements":"Both chains are evidenced separately: AMHR2 (type II) and BMPR1A (type I). In the HEK-293T luciferase assay, co-transfected ACVR1 was essential for a robust AMH signal, and BMPR1A, BMPR1B and ACVR1 were the type I receptors tested [PMID:32333774]. UniProt names ACVR1 and BMPR1A as type I partners [DB:UniProt]. AMHR2 residues in the modelled binding interface (F62, R80, T108 and others) were mutated to probe signalling [PMID:32333774].","affinity_potency":[{"value":"EC50 ~0.4 nM","assay":"BRE luciferase signalling assay","system":"HEK-293T cells transfected with AMHR2 and ACVR1","cite":"PMID:32333774"}],"species_and_systems":"Human AMH and AMHR2 in recombinant HEK-293T cells and modelling [PMID:32333774]; mouse Bmpr1a conditional knockout in vivo [PMID:12368913]. Database records include a human PDB structure with AMH and AMHR2 chains [DB:PDB 7L0J].","localisation_and_range":"AMH is flagged as secreted and the receptor complex as transmembrane [flag], so signalling is paracrine/endocrine to cell-surface receptors.","caveats":"Both papers were read as abstracts for the curator judgement; one was supplemented by full text. The AMH:AMHR2 complex in the 2020 paper is a homology model, not an experimental structure [PMID:32333774]. That paper does not show BMPR1A to be required; in its assay ACVR1 gave the robust signal. The mouse Bmpr1a paper shows a genetic requirement, not binding [PMID:12368913].","key_references":[{"PMID":"32333774","why":"AMHR2 specificity, mutagenesis and signalling assay with EC50"},{"PMID":"12368913","why":"In vivo requirement of Bmpr1a for AMH-driven M\u00fcllerian duct regression in mouse"}],"covers":["LR007351"]},"LR011194":{"pair":"AMH -> BMPR1A","headline":"Mouse genetics show Bmpr1a is needed for AMH-induced M\u00fcllerian duct regression; direct AMH-BMPR1A binding is not shown.","interaction_type":"functional only","direction_and_effect":"Conditional deletion of Bmpr1a in M\u00fcllerian duct mesenchyme leaves oviducts and uteri in male mice, identifying Bmpr1a as a type I receptor for Amh-induced regression (agonist direction) [PMID:12368913]. GtoPdb lists AMH-BMPR1A as an agonist interaction [DB:GtoPdb].","molecular_requirements":"The abstract states Amh acts by binding a specific type II receptor, Amhr2 [PMID:12368913]; UniProt describes AMHR2 as the specific type II receptor that heterodimerizes with type I receptors including BMPR1A [DB:UniProt]. So BMPR1A likely acts as the type I chain of a complex; whether it works alone is not reported in our evidence.","affinity_potency":[],"species_and_systems":"Mouse in vivo conditional knockout [PMID:12368913]; the pair itself is human-annotated.","localisation_and_range":"AMH is flagged as secreted and BMPR1A as transmembrane [flag].","caveats":"Single paper, read as abstract only. It is a loss-of-function genetic result and does not show physical binding. Three further rows are pending.","key_references":[{"PMID":"12368913","why":"Mouse conditional knockout of Bmpr1a blocks AMH-driven duct regression"}],"covers":["LR011194"]},"LR005038":{"pair":"ANG -> PLXNB2","headline":"ANG binds PLXNB2 with nM Kd by SPR and PLXNB2 mediates ANG function; well supported by one major paper.","interaction_type":"direct binding","direction_and_effect":"PLXNB2 is the functional receptor for ANG: knockdown abolished ANG cell-surface binding, nuclear translocation, proliferation and AKT/ERK phosphorylation; ectopic human PLXNB2 in COS-7 cells enabled ANG responses. Antibodies to the ANG-binding site on PLXNB2 restricted ANG activity [PMID:29100074]. Agonist direction.","molecular_requirements":"The Sema domain of PLXNB2 is needed; the putative ANG binding site lies between residues 334 and 449. ANG did not bind the Sema domain of PLXNB1 or PLXNB3, and RNASE4 did not bind PLXNB2 [PMID:29100074].","affinity_potency":[{"value":"apparent Kd 0.74 nM","assay":"surface plasmon resonance","system":"ANG with purified PLXNB2 Sema domain","cite":"PMID:29100074"},{"value":"steady-state Kd 2.87 nM","assay":"surface plasmon resonance","system":"ANG with purified PLXNB2 Sema domain","cite":"PMID:29100074"}],"species_and_systems":"Human ANG and PLXNB2 in recombinant protein, cancer cell lines and COS-7 transfectants; mouse in vivo xenograft work is described in the abstract [PMID:29100074].","localisation_and_range":"ANG is flagged as secreted and PLXNB2 as transmembrane [flag]; ANG is endocytosed and translocates to the nucleus [DB:UniProt].","caveats":"One paper only. The UniProt note about endocytosis via PLXNB2 cites the same paper plus PMID:32510170 [DB:UniProt]. Mouse pair listed as not ortholog-inferred, but the mouse experiments are not detailed in our excerpts.","key_references":[{"PMID":"29100074","why":"PLXNB2 identified as ANG receptor; SPR Kd, specificity vs PLXNB1/B3"}],"covers":["LR001650","LR005038"]},"LR008206":{"pair":"ANGPT1 -> ITGA5:ITGB1","headline":"Monomeric ANGPT1 fragment binds the alpha5beta1 integrin complex in one abstract-only paper.","interaction_type":"direct binding","direction_and_effect":"Monomeric DeltaAng1 bound alpha(5)beta(1) integrin with similar affinity compared with Tie2, and activated MAPKs, increased endothelial adhesion and reduced permeability [PMID:15781448].","molecular_requirements":"The measured receptor is the alpha5beta1 heterodimer, matching the ITGA5:ITGB1 complex. The ligand was the truncated, monomeric fibrinogen-like domain, which ligated Tie2 without triggering its phosphorylation [PMID:15781448]; full-length oligomer behaviour at the integrin is not reported in our evidence.","affinity_potency":[],"species_and_systems":"Recombinant human DeltaAng1 from insect cells; endothelial cells and chick chorioallantoic membrane [PMID:15781448].","localisation_and_range":"ANGPT1 is flagged as secreted; both integrin chains are flagged as receptors and not secreted [flag].","caveats":"Single paper, abstract only; no numeric affinity reported. Effects might be partly mediated through Tie2, which the same fragment also binds. No database support.","key_references":[{"PMID":"15781448","why":"Monomeric Ang1 fragment binds alpha5beta1 integrin"}],"covers":["LR008206"]},"LR003607":{"pair":"ANGPT2 -> TEK","headline":"Ang2 binds Tie2 and acts as a context-dependent antagonist or weak agonist; strong database support, abstract-only papers.","interaction_type":"direct binding","direction_and_effect":"Ang2 was identified as a naturally occurring antagonist for Ang1 and Tie2 [PMID:9204896]. In hematopoietic cells Ang2 bound TEK with similar affinity to Ang1, induced a low level of TEK phosphorylation and weakened Ang1-induced phosphorylation [PMID:9723709]. The annotated modulatory effect is Stimulatory, which conflicts with the antagonist label from these papers.","molecular_requirements":"UniProt says Ang2 binds TEK/TIE2 competing for the same binding site as ANGPT1 [DB:UniProt]. Single receptor chain (TEK).","affinity_potency":[],"species_and_systems":"Human ligand and receptor in hematopoietic cells [PMID:9723709]; Ang2 overexpression in transgenic mice [PMID:9204896]. Database records include SPR and a PDB structure 2GY7 with both chains [DB:IntAct][DB:PDB 2GY7].","localisation_and_range":"ANGPT2 is flagged as secreted and TEK as transmembrane [flag].","caveats":"Both papers were abstract only, and no numeric affinity is given. The effect is context-dependent, so the Stimulatory flag may mislead. One row was different_entity, one review-only, one pending.","key_references":[{"PMID":"9204896","why":"Ang2 identified as antagonist of Ang1 and Tie2"},{"PMID":"9723709","why":"Ang2 binds TEK with affinity similar to Ang1 and gives weak phosphorylation"}],"covers":["LR000057","LR003607"]},"LR005434":{"pair":"ANGPTL4 -> CLDN5","headline":"cANGPTL4 is reported to bind claudin-5 and decluster it; one abstract-level paper.","interaction_type":"direct binding","direction_and_effect":"cANGPTL4 subsequently associates with and declusters claudin-5 after activating integrin \u03b15\u03b21, leading to endothelial disruption; curator labels it antagonist [PMID:21841165]. ANGPTL4-knockout versus wild-type mice show it induces vascular leakiness and lung metastasis [PMID:21841165].","molecular_requirements":"The acting ligand is the C-terminal fibrinogen-like domain (cANGPTL4), a proteolytic fragment, not full-length ANGPTL4 [PMID:21841165]. Claudin-5 engagement comes after integrin \u03b15\u03b21 and alongside VE-cadherin [PMID:21841165].","affinity_potency":[],"species_and_systems":"Human ligand and receptor per curator fields; mice used in vivo [PMID:21841165]. The mouse pair is ortholog-inferred, not tested directly.","localisation_and_range":"ANGPTL4 is flagged secreted [flag]; claudin-5 is an endothelial tight-junction protein (location taken from paper text on junction declustering) [PMID:21841165].","caveats":"Single paper read as abstract only; no affinity; CLDN5 is not flagged transmembrane in our entity record; fragment, not full-length.","key_references":[{"PMID":"21841165","why":"cANGPTL4 binds claudin-5 as third sequential partner"}],"covers":["LR002112","LR005434"]},"LR005443":{"pair":"ANGPTL4 -> SDC4","headline":"Direct ANGPTL4-SDC4 binding is shown by cell-surface binding assay and ELISA, with Wnt-antagonist consequences.","interaction_type":"direct binding","direction_and_effect":"Soluble ANGPTL4 binds all four syndecans (SDC1-4) in cell-surface binding assays, and AP-tagged soluble SDC4 binds immobilised ANGPTL4 dose-dependently in ELISA [PMID:29017031]. The complex is internalised by clathrin-mediated endocytosis, promotes LRP6-SDC4 clustering and LRP6 turnover, and attenuates Wnt/\u03b2-catenin signalling [PMID:29017031].","molecular_requirements":"nANGPTL4 increased LRP6-SDC4 clusters while cANGPTL4 had no effect; chlorate sensitivity suggests syndecan binding is required for clustering [PMID:29017031].","affinity_potency":[],"species_and_systems":"Human ANGPTL4 and human SDC4 constructs in HEK293T cells; Xenopus embryos for function [PMID:29017031]. The mouse pair is ortholog-inferred, not tested directly.","localisation_and_range":"ANGPTL4 flagged secreted; SDC4 is a membrane receptor [flag]; binds on the cell surface.","caveats":"No affinity number in our excerpts; Wnt antagonism is shown through LRP6, not a classical receptor activation.","key_references":[{"PMID":"29017031","why":"ANGPTL4 binds syndecans, including SDC4, and promotes LRP6 turnover"}],"covers":["LR002121","LR005443"]},"LR010609":{"pair":"ANOS1 -> SDC2","headline":"Supported only by one BioGRID affinity-capture record; four papers were abstract-insufficient.","interaction_type":"database-asserted only","direction_and_effect":"No curator-verified paper supports this pair; BioGRID lists an affinity capture-western record (PMID 8832397) [DB:BioGRID]. Direction and effect are not reported in our evidence.","molecular_requirements":"not reported in our evidence.","affinity_potency":[],"species_and_systems":"Species not reported in our evidence; human pair only [DB:BioGRID].","localisation_and_range":"ANOS1 flagged secreted; SDC2 flagged receptor, transmembrane [flag].","caveats":"Rests on a single database record; no paper judged confirmed.","key_references":[],"covers":["LR010609"]},"LR001654":{"pair":"ANPEP -> SELE","headline":"CD13 (ANPEP) is reported as an E-selectin ligand through sLeX glycans, from a glycoproteomics screen.","interaction_type":"direct binding","direction_and_effect":"A glycoproteomics screen of E-selectin-binding glycoproteins from a human breast cancer cell line identified CD44 (HCELL) and CD13 as key E-selectin ligands [PMID:29777742]. Both display sLeX, which is the E-selectin ligand glycan [PMID:29777742].","molecular_requirements":"Binding is via the sLeX glycan on CD13, so the glycoform matters, not the protein core alone [PMID:29777742].","affinity_potency":[],"species_and_systems":"Human breast cancer cell line CF1_T and clinical tissue [PMID:29777742]. The mouse pair is ortholog-inferred, not tested directly.","localisation_and_range":"ANPEP flagged secreted; SELE transmembrane [flag]; cell-surface adhesion.","caveats":"Abstract only; validation is by flow cytometry, Western blot, IHC and PLA, not a purified binding assay; no affinity.","key_references":[{"PMID":"29777742","why":"CD13 and CD44 identified as sLeX-bearing E-selectin ligands"}],"covers":["LR001654","LR005041"]},"LR012148":{"pair":"APCDD1 -> FZD5:LRP5","headline":"APCDD1 interacts in vitro with LRP5 and inhibits Wnt signalling; no evidence for this specific FZD5 subunit.","interaction_type":"direct binding","direction_and_effect":"APCDD1 is described as a Wnt inhibitor: it inhibits Wnt signalling cell-autonomously and upstream of beta-catenin, and represses Wnt reporters and target genes [PMID:20393562]. The paper reports an in vitro interaction with WNT3A and LRP5 [PMID:20393562]; IntAct and UniProt record the LRP5 interaction [DB:IntAct, DB:UniProt].","molecular_requirements":"Only LRP5 is shown to interact with APCDD1; FZD5 is not mentioned in the evidence sentence or abstract, so the complex-level pair rests on the LRP5 chain alone. A CCC tool scoring by the least-expressed subunit would add a requirement for FZD5 that our evidence does not support.","affinity_potency":[],"species_and_systems":"Human genetics and human cells for the interaction in vitro; Wnt inhibition also in chick neural development and Xenopus embryos [PMID:20393562].","localisation_and_range":"APCDD1 is described as a membrane-bound glycoprotein [PMID:20393562]; it is not flagged as secreted in the dossier, so juxtacrine or cell-autonomous action is more likely than long-range signalling.","caveats":"Single paper, abstract plus excerpts. Chain-only evidence (LRP5); no data for FZD5. The interaction is 'in vitro' with no affinity. APCDD1 may act as a Wnt-pathway inhibitor rather than a classical ligand.","key_references":[{"PMID":"20393562","why":"APCDD1 interacts with LRP5 and WNT3A and inhibits Wnt signalling."}],"covers":["LR012148"]},"LR005452":{"pair":"APOA1 -> CUBN","headline":"ApoA-I binds cubilin with high affinity by surface plasmon resonance in one paper; read as abstract only.","interaction_type":"direct binding","direction_and_effect":"Surface plasmon resonance showed high-affinity binding of apoA-I and HDL to cubilin; cubilin-expressing yolk sac cells endocytosed 125I-HDL, blocked by antibodies against apoA-I and cubilin [PMID:10371504]. Cubilin is proposed as a receptor in epithelial apoA-I/HDL metabolism [PMID:10371504].","molecular_requirements":"Reactome models the complex as apoA-I bound to CUBN:AMN, so AMN may be part of the receptor [DB:Reactome]; the abstract does not test this.","affinity_potency":[],"species_and_systems":"Human ligand and receptor listed; the abstract gives no further system detail, and the yolk sac cell species is not stated [PMID:10371504].","localisation_and_range":"Cubilin carries a receptor flag [flag]; endocytosis of HDL implies a membrane receptor on epithelial cells [PMID:10371504].","caveats":"No numeric affinity in the abstract. Single paper, abstract only.","key_references":[{"PMID":"10371504","why":"SPR binding and HDL endocytosis"}],"covers":["LR002135","LR005452"]},"LR003616":{"pair":"APOB -> LDLR","headline":"Well-known pair; here one NMR/SPR study with LR5 and ApoB peptides plus structures, and one weak mutation paper.","interaction_type":"direct binding","direction_and_effect":"NMR and SPR show peptides from ApoB (site A and site B) bind LDLR repeat LR5 on its convex face; complexes weaken at low Ca2+ and low pH, favouring endosomal dissociation [PMID:24447298]. IntAct lists NMR records and PDB lists structures (9BD8, 9BDE, 9BDT, 9COO) with chains from both proteins [DB:IntAct][DB:PDB 9BD8].","molecular_requirements":"LDLR uses calcium-binding repeats; more than one repeat may be used to chelate lipoproteins [PMID:24447298].","affinity_potency":[],"species_and_systems":"Peptides and LR5 domain in vitro, species not reported [PMID:24447298]; human LDL on cultured fibroblasts [PMID:12031600]. Mouse pair is ortholog-inferred.","localisation_and_range":"ApoB is flagged secreted, not transmembrane; LDLR carries a receptor flag [flag].","caveats":"Peptide fragments, not full-length ApoB. The N3516K paper gave discordant results (poor cell growth but normal or better binding), so it is weak support [PMID:12031600]. Both read as abstracts.","key_references":[{"PMID":"24447298","why":"NMR/SPR of LR5 with ApoB peptides"},{"PMID":"12031600","why":"Receptor binding of mutant ApoB LDL (weak)"}],"covers":["LR000067","LR003616"]},"LR005461":{"pair":"APOC3 -> LRP1","headline":"Mouse genetics show APOC3 inhibits triglyceride-rich lipoprotein clearance through LRP1; direct binding is not shown.","interaction_type":"functional only","direction_and_effect":"An APOC3-targeting antisense oligonucleotide lowered fasting triglycerides in a manner dependent on LDLR and LRP1; the effect was lost only in mice lacking both [PMID:27400128]. The authors conclude APOC3 inhibits clearance of triglyceride-rich lipoproteins (antagonist-like) through the hepatic LDLR/LRP1 axis [PMID:27400128].","molecular_requirements":"Redundant: either LRP1 or LDLR alone suffices for the effect; both knocked out abolishes it [PMID:27400128].","affinity_potency":[],"species_and_systems":"Mouse, in vivo with knockout lines and injections of lipoproteins [PMID:27400128]. Human pair is ortholog-inferred.","localisation_and_range":"APOC3 flagged secreted; the receptor carries a receptor flag [flag]. Mainly hepatic clearance [PMID:27400128].","caveats":"Indirect genetic evidence; no binding assay in our evidence. Abstract only. Single paper, same for both receptors.","key_references":[{"PMID":"27400128","why":"ASO and receptor knockouts show LDLR/LRP1-dependent effect"}],"covers":["LR002144","LR005461"]},"LR003625":{"pair":"APOE -> LRP8","headline":"Quantified binding of apoE particles to apoER2 (Kd in microg/mL) in cells; abstract level.","interaction_type":"direct binding","direction_and_effect":"POPC-apoE particles of apoE3, apoE4 and truncations bound tightly to apoER2 (Kd 12 +/- 3 to 19 +/- 4 microg/mL); apoE2 bound with reduced affinity (Kd = 31 +/- 5.3 microg/mL) [PMID:12950167]. BioGRID and IntAct record the interaction [DB:BioGRID] [DB:IntAct].","molecular_requirements":"The apoER2-binding domain maps to apoE residues 1-165 [PMID:12950167].","affinity_potency":[{"value":"Kd 12 +/- 3 to 19 +/- 4 microg/mL","assay":"binding of POPC-apoE particles (apoE3, apoE4, truncations)","system":"ldlA-7 and COS-M6 cells expressing apoER2","cite":"PMID:12950167"},{"value":"Kd = 31 +/- 5.3 microg/mL","assay":"POPC-apoE2 binding","system":"ldlA-7 and COS-M6 cells expressing apoER2","cite":"PMID:12950167"}],"species_and_systems":"Human apoE and human apoER2 in cell lines [PMID:12950167]. Human and mouse pairs are listed.","localisation_and_range":"ApoE flagged secreted, LRP8 transmembrane [flag]; UniProt calls LRP8 a cell surface receptor for apoE-containing ligands [DB:UniProt].","caveats":"Affinities are in microg/mL on lipid particles, not molar. Two papers abstract-insufficient.","key_references":[{"PMID":"12950167","why":"apoER2 binding of apoE isoforms and domains"}],"covers":["LR000076","LR003625"]},"LR002149":{"pair":"APOE -> LSR","headline":"Old binding-type evidence for apoE-rich lipoproteins at LSR plus a genetic association; indirect.","interaction_type":"functional only","direction_and_effect":"LSR showed higher apparent affinity for triglyceride-rich lipoproteins and apoE-supplemented lipid emulsions than for apoB-only LDL; apoE2/2 VLDL failed to bind [PMID:7509190]. A study of LSR and APOE polymorphisms found age-specific epistasis on lipid levels [PMID:29178324].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human fibroblasts (FH, LDL-receptor-lacking) and rat hepatocytes [PMID:7509190]; human cohorts [PMID:29178324]. Mouse pair is ortholog-inferred.","localisation_and_range":"ApoE flagged secreted; LSR flagged receptor and not secreted [flag].","caveats":"Binding is to lipoproteins, not purified apoE; the 2018 paper is a genetic association, not binding; both abstract only. One paper pending.","key_references":[{"PMID":"7509190","why":"LSR lipoprotein binding, apoE dependence"},{"PMID":"29178324","why":"LSR-APOE epistasis, genetic only"}],"covers":["LR002149","LR005464"]},"LR000079":{"pair":"APOE -> VLDLR","headline":"No curator-verified paper; support is IntAct ELISA and UniProt text only.","interaction_type":"database-asserted only","direction_and_effect":"IntAct lists an ELISA interaction [DB:IntAct]. UniProt states apoE binds receptors including VLDLR that mediate uptake of apoE-containing lipoprotein particles [DB:UniProt].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Species not reported in our evidence; human pair is ortholog-inferred.","localisation_and_range":"ApoE flagged secreted, VLDLR flagged transmembrane [flag].","caveats":"Three papers were abstract-insufficient and one review-only; none confirmed.","key_references":[],"covers":["LR000079","LR003628"]},"LR005470":{"pair":"APP -> APLP2","headline":"APP-APLP2 association shown by FRET and co-IP in cis on the same membrane; a family interaction, not classical signalling.","interaction_type":"direct binding","direction_and_effect":"APP and APLP2 formed heterotypic cis interactions (same membrane) detected by FRET and co-immunoprecipitation; coexpression with APP diminished Abeta42 generation [PMID:19126676]. The trans (cell-cell) interaction was seen only for APLP1, not for APP or APLP2 [PMID:19126676].","molecular_requirements":"The N-terminal half of the ectodomain is crucial for the interaction [PMID:19126676].","affinity_potency":[],"species_and_systems":"Human proteins in cell imaging [PMID:19126676]. Mouse pair is ortholog-inferred.","localisation_and_range":"Both partners flagged secreted and receptor; the evidence is cis, same-membrane [flag] [PMID:19126676].","caveats":"Abstract only. Cis association is not a classical secreted ligand to receptor signalling event; direction not applicable.","key_references":[{"PMID":"19126676","why":"APP family cis interactions by FRET and co-IP"}],"covers":["LR002155","LR005470"]},"LR002158":{"pair":"APP -> CNTN5","headline":"APP binds CNTN5 in the same Fn2/copper-binding-domain mode as CNTN4, but the only paper shows weaker binding.","interaction_type":"direct binding","direction_and_effect":"APP and APLP1 interact with CNTN3-5 [PMID:34958801]. A mouse CNTN5-APP complex structure at 3.5 \u00c5 shows a binding site similar to the CNTN4-APP interface [PMID:34958801]. The paper says CNTN4 associates more strongly with amyloid proteins than CNTN3 or CNTN5 [PMID:34958801].","molecular_requirements":"Conserved interface of the CNTN second fibronectin repeat with the APP copper-binding domain [PMID:34958801]. Contactins act through co-receptor complexes because they lack an intracellular region [PMID:34958801].","affinity_potency":[{"value":"K = 26.8 \u03bcM","assay":"biolayer interferometry","system":"zebrafish APPb with CNTN5","cite":"PMID:34958801"}],"species_and_systems":"Recombinant protein work (extracellular binding, BLI, crystallography) with human, mouse, chicken and zebrafish proteins [PMID:34958801]. Human pair is ortholog-inferred.","localisation_and_range":"CNTN5 is flagged secreted and receptor, APP secreted and transmembrane [flag]; contactins are described as GPI-anchored [PMID:34958801].","caveats":"Single paper, read as abstract plus excerpts; no database record. The only affinity shown for APP-CNTN5 is the zebrafish value, and the human/mouse APP-CNTN5 value is not in our excerpts. ","key_references":[{"PMID":"34958801","why":"Binding and structure of CNTN5-APP"}],"covers":["LR002158","LR005473"]},"LR002167":{"pair":"APP -> TRPC6","headline":"One full-text paper shows TRPC6 binds APP C99 and inhibits gamma-secretase cleavage, reducing Abeta.","interaction_type":"direct binding","direction_and_effect":"TRPC6 interacts with APP (C99), prevents C99 interaction with PS1 and reduces Abeta production; labelled antagonist [PMID:26581893].","molecular_requirements":"TRPC6 does not interact with Notch; the effect is independent of its channel activity [PMID:26581893].","affinity_potency":[],"species_and_systems":"HEK293 and COS7 cells, mouse brain lysates, and APP/PS1 x TRPC6-transgenic mice [PMID:26581893].","localisation_and_range":"TRPC6 and APP (C99) colocalised in certain organelles [PMID:26581893].","caveats":"This is a regulator-substrate relationship rather than classical signalling. Single paper; no database support in the dossier.","key_references":[{"PMID":"26581893","why":"TRPC6-APP C99 interaction and Abeta reduction"}],"covers":["LR002167","LR005481"]},"LR003634":{"pair":"ARTN -> GFRA1","headline":"Artemin can activate the GFRalpha1-RET complex as an alternative to its preferred GFRalpha3-RET; abstract-level functional evidence.","interaction_type":"functional only","direction_and_effect":"Artemin can activate the GFRalpha1-RET complex and support survival of dopaminergic midbrain neurons in culture [PMID:9883723].","molecular_requirements":"RET is the signalling component with a GFRalpha binding component [PMID:9883723]; GFRA1 alone is not tested separately. Reactome lists RET:GFRA1,GFRA3:ARTN [DB:Reactome].","affinity_potency":[],"species_and_systems":"Cultured neurons; species not specified in the abstract [PMID:9883723].","localisation_and_range":"ARTN flagged secreted [flag].","caveats":"Abstract only; preferred receptor is GFRalpha3-RET, so GFRA1 is a secondary receptor. No direct binding or affinity reported.","key_references":[{"PMID":"9883723","why":"Artemin identification and receptor usage"}],"covers":["LR000085","LR003634"]},"LR000088":{"pair":"ASIP -> ATRN","headline":"Agouti protein (ASIP) binds attractin with low affinity by SPR in mouse; direct binding shown in one abstract-only paper.","interaction_type":"direct binding","direction_and_effect":"Attractin is described as a low-affinity receptor for agouti protein, but not Agrp, in vitro and in vivo; loss of Atrn blocks the effects of ectopic agouti in mice [PMID:11137996]. Effect direction not specified by the curator; the paper links attractin to agouti action.","molecular_requirements":"The N-terminal fragment (His23-Arg85) of agouti protein binds the attractin ectodomain (ATRNEc); the C-terminal fragment does not [PMID:11137996]. Agrp and alpha-MSH did not bind attractin in the same study [PMID:11137996].","affinity_potency":[{"value":"Kd 7.02e-7 M (702 nM)","assay":"BIAcore SPR with Scatchard analysis","system":"recombinant mouse attractin ectodomain and agouti N-terminal fragment","cite":"PMID:11137996"}],"species_and_systems":"All experiments were mouse (mouse Atrn and agouti protein), recombinant SPR plus transgenic and genetic-interaction mice; the human pair is ortholog-inferred [PMID:11137996].","localisation_and_range":"ASIP is flagged secreted and described as a paracrine molecule normally limited to skin [flag] [PMID:11137996]. Attractin is described as a widely expressed transmembrane protein [PMID:11137996].","caveats":"Single paper, abstract only. Affinity is low. Human evidence not reported in our evidence.","key_references":[{"PMID":"11137996","why":"Identified attractin as low-affinity agouti receptor; SPR Kd and negatives"}],"covers":["LR000088"]},"LR003643":{"pair":"AVP -> AVPR1A","headline":"Well supported direct binding and agonism of vasopressin at the V1a receptor, with consistent nanomolar affinity in human recombinant systems.","interaction_type":"direct binding","direction_and_effect":"AVP binds the V1a receptor as a full agonist; GtoPdb lists Type=Agonist, Action=Full agonist [DB:GtoPdb]. AVP raised [Ca2+]i in V1A-expressing cells [PMID:9459574]. Replacing aromatic TM VI residues did not change AVP binding but increased AVP-induced G protein coupling efficacy [PMID:10866830]. A photoreactive antagonist labelled a region including transmembrane domain VII (Asn327-Lys370) [PMID:9334232].","molecular_requirements":"Single-chain GPCR; no co-receptor or extra subunit is reported in our evidence. Human V1a is degraded during incubation with the photoreactive ligand, giving a 46-kDa species lacking the N-terminal region [PMID:9334232].","affinity_potency":[{"value":"Ki 1.4 nmol/L","assay":"radioligand competition binding","system":"human receptor-transfected cell lines","cite":"PMID:10519430"},{"value":"Kd 0.67 nM","assay":"[3H]AVP saturation binding, Scatchard","system":"COS-1 cells expressing human V1A","cite":"PMID:9459574"},{"value":"Kd 0.39 nM","assay":"[3H]AVP saturation binding, Scatchard","system":"CHO cells expressing hV1A","cite":"PMID:9884074"}],"species_and_systems":"Mostly human receptor in transfected CHO, COS-1 or HeLa cells [PMID:9884074][PMID:9459574][PMID:10780976]. The rat hepatic V1a cDNA was also cloned and binds AVP with affinities similar to native rat V1a [PMID:1560825]. The mouse pair is projected from human evidence (ortholog-inferred); no mouse experiment is in the dossier.","localisation_and_range":"AVP is flagged secreted and V1a as a transmembrane receptor [flag], so signalling is paracrine or endocrine.","caveats":"All papers were read as abstracts only. Several confirmed rows use V1a as a selectivity-panel comparator rather than a primary AVP finding, and one notes AVP affinity was not re-measured [PMID:16158071]. 7 further papers were judged abstract_insufficient.","key_references":[{"PMID":"8106369","why":"Cloning of human V1a; single high-affinity [3H]AVP site"},{"PMID":"9884074","why":"Kd of [3H]AVP at hV1A, hV1B, hV2 in CHO cells"},{"PMID":"9459574","why":"Kd of [3H]AVP and AVP-induced Ca2+ response in COS-1 cells"}],"covers":["LR000094","LR003643"]},"LR000097":{"pair":"AVP -> OXTR","headline":"Vasopressin acts as a partial agonist at the oxytocin receptor, supported by human receptor assays and GtoPdb; the mouse pair is projected from human.","interaction_type":"direct binding","direction_and_effect":"AVP is a full agonist of vasopressin receptors but acts as a partial agonist on the oxytocin receptor [PMID:8955347]; GtoPdb lists Agonist, Partial agonist [DB:GtoPdb].","molecular_requirements":"Two aromatic residues of the oxytocin receptor determine the partial response: AVP becomes a full agonist when they are replaced by the residues found in vasopressin receptor subtypes [PMID:8955347]. Co-receptors or subunits: not reported in our evidence.","affinity_potency":[{"value":"Ki 48 nmol/L","assay":"radioligand competition binding (value recorded by curators; abstract truncated)","system":"human receptor-transfected cell lines","cite":"PMID:10519430"},{"value":"pKi 7.3 to 9.3","assay":"GtoPdb affinity range","system":"not stated","cite":"DB:GtoPdb"}],"species_and_systems":"Experiments used human ligand and human receptor, in transfected cells [PMID:10519430] and in a human OT receptor functional study [PMID:8955347]. The mouse pair is inferred from human evidence.","localisation_and_range":"Ligand is flagged secreted and receptor transmembrane [flag]; this implies paracrine or endocrine signalling to a cell-surface receptor.","caveats":"Only 2 of the 5 judged papers measure AVP at this receptor [PMID:10519430, PMID:8955347]; the other 3 are about synthetic V1b analogues and use OT as a selectivity comparator, with no AVP value for OT [PMID:12446593, PMID:15084136, PMID:16158071]. All papers were read as abstracts only. Cross-reactivity within the vasopressin/oxytocin family is not quantified beyond the Ki above.","key_references":[{"PMID":"8955347","why":"AVP is a partial agonist at human OT receptor; two receptor residues identified"},{"PMID":"10519430","why":"Receptor binding Ki in transfected human receptor cell lines"}],"covers":["LR000097","LR003646"]},"LR012382":{"pair":"BAMBI -> FZD6:LRP6","headline":"Database-asserted only: a single IntAct coimmunoprecipitation record; no curator-verified paper for this pair.","interaction_type":"database-asserted only","direction_and_effect":"BAMBI is annotated as stimulatory toward this receptor complex [flag]. The only support is one IntAct coimmunoprecipitation record citing PMID 18838381 [DB:IntAct]. No verified paper for this pair is in our evidence; the one judged abstract was marked insufficient.","molecular_requirements":"Complex FZD6:LRP6 is annotated; LRP6 carries a transmembrane flag [flag]. Which subunit the IntAct record covers, and whether both are needed, is not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human pair [flag]. IntAct method: anti tag coimmunoprecipitation [DB:IntAct]; cell system not reported in our evidence.","localisation_and_range":"Not reported in our evidence; BAMBI has no secreted or transmembrane flag in the dossier.","caveats":"Database support only, from one co-IP record. BAMBI is called a pseudoreceptor in the related paper title [PMID:18838381], so a ligand role is unclear. The same record is attached to several Frizzled:LRP6 pairs, so it does not distinguish between Frizzled paralogs.","key_references":[],"covers":["LR012382"]},"LR012049":{"pair":"BAMBI -> TGFBR1:TGFBR2","headline":"Database-asserted only: BioGRID records link BAMBI to TGFBR1; no verified paper, and TGFBR2 is not covered.","interaction_type":"database-asserted only","direction_and_effect":"BAMBI is annotated as inhibitory toward TGFBR1:TGFBR2 [flag]. BioGRID holds two records for TGFBR1-BAMBI (Reconstituted Complex; Affinity Capture-Western) citing PMID 19758997 [DB:BioGRID]. No curator-verified paper is available; two papers were marked different_entity and three abstracts insufficient.","molecular_requirements":"The records name TGFBR1 only [DB:BioGRID]; any role of TGFBR2 is not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human pair [flag]. Reconstituted complex and affinity capture-Western; cell system not reported in our evidence [DB:BioGRID].","localisation_and_range":"Complex flagged transmembrane [flag]; BAMBI localisation not reported in our evidence.","caveats":"Database support only, one cited study, chain-only evidence (TGFBR1). The inhibitory effect rests on the annotation, not on a verified paper.","key_references":[],"covers":["LR012049"]},"LR002176":{"pair":"BGN -> P2RX4","headline":"Biglycan activates the NLRP3 inflammasome through TLR2/4 and P2X4; evidence is functional, one abstract-only paper.","interaction_type":"functional only","direction_and_effect":"Soluble biglycan induces the NLRP3/ASC inflammasome in macrophages, activating caspase-1 and releasing mature IL-1beta; this is brought about by interaction of biglycan with TLR2/4 and purinergic P2X(4)/P2X(7) receptors, which induces receptor cooperativity [PMID:19605353]. Biglycan-deficient mice had lower active caspase-1 and mature IL-1beta in kidney and lung in obstruction and sepsis models [PMID:19605353].","molecular_requirements":"TLR2/4 are also involved, and P2X4 and P2X7 are named together; whether P2X4 alone is sufficient is not reported in our evidence [PMID:19605353].","affinity_potency":[],"species_and_systems":"Macrophages and biglycan-deficient mice (mouse); human and mouse pairs are both ortholog-inferred [PMID:19605353].","localisation_and_range":"Soluble biglycan (secreted flag) acting on macrophage surface receptors [flag][PMID:19605353].","caveats":"Abstract-only. P2X4 and P2X7 are not distinguished in the evidence sentence, and no direct binding or affinity is shown.","key_references":[{"PMID":"19605353","why":"biglycan activates NLRP3 inflammasome via TLR2/4 and P2X4/P2X7"}],"covers":["LR002176","LR005490"]},"LR003652":{"pair":"BGN -> TLR4","headline":"Biglycan is an endogenous TLR4 agonist in macrophages, shown genetically, with a microscale thermophoresis record in IntAct.","interaction_type":"functional only","direction_and_effect":"Biglycan acts in macrophages as an endogenous ligand of TLR4 and TLR2, activating p38, ERK and NF-kappaB and stimulating TNF-alpha and MIP-2 [PMID:16025156]. Effects were reduced in TLR4-mutant, TLR2-/- and MyD88-/- macrophages and abolished in TLR2-/-/TLR4-mutant cells [PMID:16025156]. Biglycan-null mice had a survival benefit in LPS- or zymosan-induced sepsis [PMID:16025156]. IntAct lists a microscale thermophoresis record P21810-O00206 citing PMID 24480070 [DB:IntAct].","molecular_requirements":"TLR2 and TLR4 each contribute, with complete loss only in the double mutant; MyD88 is needed [PMID:16025156].","affinity_potency":[],"species_and_systems":"Mouse macrophages and mice (genetic models); human and mouse pairs listed [PMID:16025156]. Abstract-only read.","localisation_and_range":"Biglycan released from the matrix or from macrophages acts as a soluble signal [PMID:16025156]; secreted flag [flag].","caveats":"Abstract-only; evidence is functional, with no affinity values in our evidence. The two TLRs are not separated except by the genetic series; the IntAct record gives no values here.","key_references":[{"PMID":"16025156","why":"biglycan signals through TLR4 and TLR2 in macrophages"}],"covers":["LR000103","LR003652"]},"LR007108":{"pair":"BMP15 -> BMPR1B:BMPR2","headline":"Both chains have abstract-level support from one paper, via separate ectodomain tests rather than the assembled complex.","interaction_type":"direct binding","direction_and_effect":"BMP15 activated Smad1/5/8 signalling in granulosa cells [PMID:12419820]. The BMPR1B (ALK6) ectodomain co-immunoprecipitated BMP15 most effectively, and the BMPR2 ectodomain most effectively inhibited BMP15 bioactivity on FSH-induced progesterone production and thymidine incorporation [PMID:12419820].","molecular_requirements":"Both chains of the type I/II pair are supported individually; whether both are required together was not tested in the abstract [PMID:12419820].","affinity_potency":[],"species_and_systems":"Rat primary granulosa cells and the human COV434 line with recombinant ectodomains [PMID:12419820].","localisation_and_range":"BMP15 is annotated as secreted and the receptor complex as transmembrane [flag].","caveats":"One abstract-only paper; BMPR2 evidence is neutralisation of activity, not binding. No affinity in our evidence.","key_references":[{"PMID":"12419820","why":"ALK6 and BMPRII ectodomain tests for BMP15 receptors"}],"covers":["LR007108"]},"LR003670":{"pair":"BMP2 -> BMPR2","headline":"BMP2 binds the type II receptor BMPR2 directly but with lower affinity than type I receptors; well supported.","interaction_type":"direct binding","direction_and_effect":"BMP-2 and BMP-7 bind BMPR-II, which signals only with a type I receptor present; the response needs both ActR-I and BMPR-II [PMID:7791754]. Mutating the low-affinity epitope 2 yields BMP-2 antagonists that inhibit its activity in C2C12 cells [PMID:10880444]. GtoPdb: agonist [DB:GtoPdb].","molecular_requirements":"BMPR-II binds BMP-2/-7 on its own, but binding is enhanced by type I receptor coexpression; kinase activity of both receptors is essential [PMID:7791754]. BMP-2 binding and cross-linking showed receptor complexes at the cell surface [PMID:10712517].","affinity_potency":[],"species_and_systems":"Receptor ectodomain assays and cell-surface cross-linking; SPR with recombinant BMP2 bound BMPR2 more weakly than the tight type I interactions [PMID:21702718]. Species of experiments not reported; the mouse pair is projected from human evidence.","localisation_and_range":"BMP2 flagged secreted [flag]; BMPR2 is a transmembrane receptor [PMID:7791754].","caveats":"Most confirming papers were abstract-only. Numeric Kd for BMPR2 are in a table not reproduced in our evidence.","key_references":[{"PMID":"7791754","why":"BMPR-II cloning; binds BMP-2 with type I receptors"},{"PMID":"10880444","why":"epitope mapping of BMP-2 for BMPR-II"},{"PMID":"21702718","why":"SPR with BMP2 across type I/II receptors"}],"covers":["LR000121","LR003670"]},"LR005047":{"pair":"BMP2 -> RGMB","headline":"RGMB (DRAGON) binds BMP2 directly and enhances BMP signalling; strongly supported, with structures.","interaction_type":"direct binding","direction_and_effect":"DRAGON binds directly to BMP2 but not to BMP7 or other TGFbeta ligands; its enhancing action on BMP signalling is reduced by Noggin and by dominant-negative Smad1 or ALK3/6 [PMID:15671031].","molecular_requirements":"DRAGON also associates directly with BMP type I receptors (ALK2, ALK3, ALK6) and type II receptors (ActRII, ActRIIB) [PMID:15671031].","affinity_potency":[{"value":"Kd 5.5 nM","assay":"surface plasmon resonance","system":"system not reported in our evidence","cite":"PMID:23029472"}],"species_and_systems":"Xenopus embryos showed DRAGON lowers the threshold for Smad1-induced marker induction [PMID:15671031]; SPR in another study [PMID:23029472]. PDB 4UHZ, 4UI0, 4UI2 hold structures with BMP2 and RGMB chains [DB:PDB 4UHZ].","localisation_and_range":"DRAGON is GPI-anchored per the paper [PMID:15671031]; the entity flag marks RGMB not secreted [flag]. Membrane-bound co-receptor.","caveats":"Both papers were abstract-only reads. The Kd is from the curator's assay note.","key_references":[{"PMID":"15671031","why":"DRAGON binds BMP2 directly, enhances BMP signalling"},{"PMID":"23029472","why":"SPR affinities of RGMs for BMPs"}],"covers":["LR001661","LR005047"]},"LR007117":{"pair":"BMP4 -> ACVR2A:BMPR1B","headline":"Complex not supported: BMPR1B was not required for BMP4 signalling in hMSC (explicit negative); BMPR1B binding is only database-recorded.","interaction_type":"conflicting","direction_and_effect":"In primary human mesenchymal stem cells, BMPR1B (and ACVR2B) were expressed at low levels and were not found to play a significant role in BMP signalling; ACVR2A was a contributing type II receptor [PMID:18436533]. GtoPdb lists BMP4 as agonist at ACVR2A and BMPR1B separately [DB:GtoPdb]; BioGRID records BMP4-BMPR1B and ACVR2A-BMP4 reconstituted complexes [DB:BioGRID 282659; DB:BioGRID 2469097].","molecular_requirements":"The combined ACVR2A:BMPR1B complex is not shown as a unit in our evidence.","affinity_potency":[],"species_and_systems":"Human primary mesenchymal stem cells (negative result) [PMID:18436533]; BioGRID reconstituted systems.","localisation_and_range":"BMP4 flagged secreted; receptors transmembrane [flag].","caveats":"The only verified paper is a negative for BMPR1B and was read as abstract only; absence of a role in hMSC reflects low expression there, so it does not exclude binding elsewhere [PMID:18436533]. Other rows were review_only or abstract_insufficient.","key_references":[{"PMID":"18436533","why":"Negative result for BMPR1B in hMSC BMP-2/4 signalling"}],"covers":["LR007117"]},"LR007126":{"pair":"BMP5 -> ACVR2A:BMPR1B","headline":"BMP5 to ACVR2A:BMPR1B rests on a GtoPdb agonist assertion only; no verified paper in our evidence.","interaction_type":"database-asserted only","direction_and_effect":"GtoPdb lists BMP5 as agonist (Stimulatory) on the receptor chain(s) [DB:GtoPdb].","molecular_requirements":"Chains in the complex: ACVR2A and BMPR1B; whether both are required or either alone suffices is not reported in our evidence. The pair is a complex; the database rows are per chain, not for the assembled complex, and not every chain has UniProt support.","affinity_potency":[],"species_and_systems":"Experimental species and system not reported in our evidence; the pair is annotated human.","localisation_and_range":"BMP5 is flagged secreted and not transmembrane [flag], so signalling would be paracrine or endocrine; the receptor's localisation is not reported in our evidence.","caveats":"No curator-confirmed paper. Screened papers: 4 review_only, 4 abstract_insufficient. GtoPdb entries show no affinity ('Affinity Units=-') [DB:GtoPdb].","key_references":[],"covers":["LR007126"]},"LR007135":{"pair":"BMP6 -> ACVR2A:BMPR1B","headline":"BMP6 with ACVR2A:BMPR1B has one curated paper, but its evidence sentence names BMPR-IB with BMPR-II, not ACVR2A.","interaction_type":"conflicting","direction_and_effect":"In ROB-C26 cells, BMP-6 binding to BMPR-IB (ALK-6), and less efficiently to ALK-2 and BMPR-IA, together with BMPR-II was detected [PMID:10504300]. GtoPdb lists agonist at ACVR2A and BMPR1B [DB:GtoPdb].","molecular_requirements":"The paper pairs BMPR-IB with BMPR-II, not ACVR2A [PMID:10504300]; the ACVR2A:BMPR1B assembly itself is not shown in our evidence.","affinity_potency":[],"species_and_systems":"ROB-C26 cell line, read from the abstract by curators [PMID:10504300]; BioGRID adds ACVR2A-BMP6 capture from the same paper and reconstituted-complex records from [PMID:18070108] [DB:BioGRID]. Species not stated.","localisation_and_range":"BMP6 is flagged secreted and the complex transmembrane [flag].","caveats":"One confirmed row among 1 confirmed, 1 abstract_insufficient and 4 review_only. The confirmed sentence supports chain BMPR1B, not the ACVR2A:BMPR1B complex. Affinity not reported.","key_references":[{"PMID":"10504300","why":"BMP-6 binds BMPR-IB with BMPR-II in ROB-C26 cells"}],"covers":["LR007135"]},"LR001663":{"pair":"BMP6 -> HJV","headline":"Direct SPR binding of BMP6 to HJV, Kd 8.1 nM, in one 2012 paper; highest affinity among RGMs for BMP6.","interaction_type":"direct binding","direction_and_effect":"Surface plasmon resonance measured binding of HJV to BMP6 with K(D) 8.1 nM; curated effect is agonist [PMID:23029472].","molecular_requirements":"RGM proteins are described as BMP co-receptors; the paper measured RGM protein binding to BMP ligands, and receptor chains needed for signalling are not reported in our evidence [PMID:23029472].","affinity_potency":[{"value":"Kd 8.1 nM","assay":"surface plasmon resonance","system":"recombinant RGM proteins with BMP ligands","cite":"PMID:23029472"}],"species_and_systems":"Recombinant human proteins per curator; abstract-level curation with full-text excerpts describing SPR (mean of 4-9 experiments) [PMID:23029472]. Mouse pair is ortholog-inferred.","localisation_and_range":"UniProt notes BMP6 acts as a ligand for hemojuvelin/HJV in regulating HAMP/hepcidin expression and iron metabolism [DB:UniProt]. The receptor is flagged as secreted [flag], which may reflect a soluble form; membrane or soluble role is not shown in our evidence.","caveats":"Affinity data are from an in vitro SPR matrix; no cellular signalling result for this pair is reported in our evidence. Compared with other RGMs: HJV 8.1, RGMB 28, RGMA 55 nM for BMP6 [PMID:23029472].","key_references":[{"PMID":"23029472","why":"SPR affinity matrix of RGM proteins for BMP ligands"}],"covers":["LR001663","LR005049"]},"LR002185":{"pair":"BMP6 -> RGMA","headline":"Direct SPR binding of BMP6 to RGMA, Kd 55 nM, in one 2012 paper; lowest affinity of the three RGMs for BMP6.","interaction_type":"direct binding","direction_and_effect":"Surface plasmon resonance measured binding of RGMA to BMP6 with K(D) 55 nM; curated effect is agonist [PMID:23029472].","molecular_requirements":"RGM proteins are described as BMP co-receptors; the paper measured RGM protein binding to BMP ligands, and receptor chains needed for signalling are not reported in our evidence [PMID:23029472].","affinity_potency":[{"value":"Kd 55 nM","assay":"surface plasmon resonance","system":"recombinant RGM proteins with BMP ligands","cite":"PMID:23029472"}],"species_and_systems":"Recombinant human proteins per curator; abstract-level curation with full-text excerpts describing SPR (mean of 4-9 experiments) [PMID:23029472]. Mouse pair is ortholog-inferred.","localisation_and_range":"The receptor is flagged as secreted [flag]; localisation is otherwise not reported in our evidence.","caveats":"Affinity data are from an in vitro SPR matrix; no cellular signalling result for this pair is reported in our evidence. Compared with other RGMs: HJV 8.1, RGMB 28, RGMA 55 nM for BMP6 [PMID:23029472].","key_references":[{"PMID":"23029472","why":"SPR affinity matrix of RGM proteins for BMP ligands"}],"covers":["LR002185","LR005499"]},"LR007144":{"pair":"BMP7 -> ACVR2A:BMPR1B","headline":"BMP7 binds BMPR-IB only in the presence of ActR-II; direct binding evidence for the combined complex from two papers.","interaction_type":"direct binding","direction_and_effect":"OP-1 (BMP7) bound BMPR-IB in the presence of ActR-II, and transcriptional activation followed binding to the BMPR-IB plus ActR-II complex [PMID:7790373]. ActRII is a high-affinity receptor for BMP7 [PMID:12667445]. GtoPdb lists agonist action for each chain [DB:GtoPdb].","molecular_requirements":"Both chains are needed: type I receptor binding was observed only in the presence of a type II receptor (ActR-II or ActR-IIB) [PMID:7790373]. A crystal-structure-based model shows type I and type II ECDs make no direct contact [PMID:12667445].","affinity_potency":[],"species_and_systems":"Human, transfected cells [PMID:7790373]; human recombinant ECDs [PMID:12667445]. No mouse data.","localisation_and_range":"BMP7 is flagged secreted and the receptor transmembrane [flag], suggesting paracrine signalling to a cell-surface receptor; the papers do not address range.","caveats":"PMID 12667445's cited sentence concerns ActRII and BMP7 only and does not itself test BMPR1B. The complex-level evidence rests on one 1995 paper. Four papers were review_only and two abstract_insufficient.","key_references":[{"PMID":"7790373","why":"Names BMPR-IB and ActR-II together; type I binding depends on type II"},{"PMID":"12667445","why":"ActRII binding to BMP7 and receptor assembly"}],"covers":["LR007144"]},"LR007153":{"pair":"BMP8A -> ACVR2A:BMPR1B","headline":"BMP8A -> ACVR2A:BMPR1B has a zebrafish Alk6a abstract and GtoPdb records; the combined complex is not shown.","interaction_type":"functional only","direction_and_effect":"Zebrafish study: Bmp8a interacts with Alk6a, promoting Tbk1 and Irf3 phosphorylation through p38 MAPK and type I interferon production on viral infection [PMID:33750893]. GtoPdb lists agonist records at ACVR2A and BMPR1B [DB:GtoPdb].","molecular_requirements":"The paper names Alk6a only; ACVR2A as partner is not reported in this paper.","affinity_potency":[],"species_and_systems":"bmp8a-/- zebrafish infected with viruses; abstract-only read; a non-human system [PMID:33750893].","localisation_and_range":"BMP8A is flagged secreted [flag]; the abstract does not state range of action.","caveats":"The curators label the evidence direct binding but the abstract says only 'interacts' and gives no binding assay. The dossier maps zebrafish Alk6a onto this human receptor, which the abstract does not do. Abstract only.","key_references":[{"PMID":"33750893","why":"Bmp8a-Alk6a interaction in zebrafish antiviral immunity"}],"covers":["LR007153"]},"LR005506":{"pair":"BSG -> KDR","headline":"BSG (EMMPRIN) directly interacts with VEGFR-2 (KDR) as a co-receptor that enhances VEGF-driven activation, human cells, one full-text paper.","interaction_type":"direct binding","direction_and_effect":"EMMPRIN is described as a coreceptor of VEGFR-2 that regulates its VEGF-mediated activation; EMMPRIN knockdown reduced VEGF-induced VEGFR-2 phosphorylation and VEGFR-2 homodimerization, and overexpression potentiates activation [PMID:25825981]. UniProt records the same coreceptor function [DB:UniProt].","molecular_requirements":"Not a free ligand: BSG acts alongside VEGFA at KDR. Docking and mutagenesis put the binding site in the EMMPRIN extracellular domain near amino acids 195/199 [PMID:25825981]. Pull-down of recombinant EMMPRIN and VEGFR-2 in a cell-free system supports direct binding.","affinity_potency":[],"species_and_systems":"Human endothelial (HMEC) and tumour (M10, MDA-MB-231) cells, tumour xenograft and patient breast and melanoma tissue; recombinant proteins in vitro [PMID:25825981]. Ortholog-inferred mouse version.","localisation_and_range":"BSG is flagged transmembrane and not secreted [flag]; proximity ligation places the interaction at the cell surface [PMID:25825981].","caveats":"Co-receptor relationship; BSG also interacts with VEGF in this paper at lower level [PMID:25825981]. No affinity reported.","key_references":[{"PMID":"25825981","why":"Pull-down, IP, proximity ligation and knockdown showing EMMPRIN-VEGFR-2 interaction and co-receptor role."}],"covers":["LR002192","LR005506"]},"LR001672":{"pair":"BST2 -> LILRA4","headline":"BST2 binds ILT7 (LILRA4) directly and inhibits interferon production by human plasmacytoid dendritic cells; one full-text paper.","interaction_type":"direct binding","direction_and_effect":"BST2 directly binds purified ILT7 protein, initiates signalling via the ILT7-FcepsilonRIgamma complex and strongly inhibits IFN and proinflammatory cytokine production by pDCs; effect is inhibitory (curator: antagonist) [PMID:19564354]. Recombinant BST2-Fc activated ILT7 reporter cells and induced calcium mobilization in pDCs [PMID:19564354].","molecular_requirements":"ILT7 signals through the FcepsilonRIgamma adaptor [PMID:19564354]. UniProt notes BST2 interacts with LILRA4/ILT7 [DB:UniProt]. Other co-receptors are not reported in our evidence.","affinity_potency":[{"value":"~10-6 M (estimated)","assay":"surface plasmon resonance, BST2-Fc with ILT7-Fc","system":"recombinant human proteins","cite":"PMID:19564354"}],"species_and_systems":"Human pDCs, HEK293 cells, ILT7 reporter cells and recombinant proteins [PMID:19564354].","localisation_and_range":"Ligand localisation from our records: BST2 expressed on cell surfaces (HEK293 cells, cell lines) and also presented as soluble Fc fusion [PMID:19564354]; contact-mediated signalling is implied. Entity flags not set in the dossier.","caveats":"BST2 is induced by IFN, suggesting negative feedback [PMID:19564354]. IntAct also lists SPR and solid-phase assay records [DB:IntAct]. A second paper is review-only.","key_references":[{"PMID":"19564354","why":"Identifies BST2 as ILT7 ligand with binding, reporter and pDC functional assays."}],"covers":["LR001672"]},"LR005533":{"pair":"C1QTNF5 -> ADIPOR1","headline":"Conflicting: CTRP5 relaxes vessels, a paper excerpt describes AdipoR-independent action, and UniProt describes CTRP5 as an ADIPOR1 antagonist.","interaction_type":"conflicting","direction_and_effect":"CTRP5 caused vasorelaxation comparable to adiponectin [PMID:21836066]. UniProt states CTRP5 antagonises ADIPOR1 and negatively regulates ADIPOR1-dependent AMPK activation in retinal pigment epithelium [DB:UniProt, PMID:34887495]. The ADIPOR1 mechanism in the vasorelaxation paper was tested for CTRP9 only.","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Aortic vascular rings (murine CTRPs) and human umbilical vein endothelial cells (HUVECs) [PMID:21836066]. The ADIPOR1 knockdown was done with CTRP9. The excerpt notes, citing earlier work, that CTRP5's metabolic effect is AdipoR-independent (background, not this paper's result).","localisation_and_range":"Secreted ligand [flag]; range not reported.","caveats":"Direction conflicts (vasorelaxant agonist-like effect versus UniProt antagonist). No direct binding data in our evidence. Mouse interaction ortholog-inferred.","key_references":[{"PMID":"21836066","why":"CTRP5 vasorelaxation; ADIPOR1 mechanism tested for CTRP9"}],"covers":["LR002220","LR005533"]},"LR000169":{"pair":"C5 -> C5AR2","headline":"C5a binds C5AR2 (C5L2) with high affinity but does not signal through G proteins, suggesting a modulatory or decoy role.","interaction_type":"direct binding","direction_and_effect":"C5L2 is a high-affinity C5a binding protein that is obligately uncoupled from G proteins and does not mediate calcium flux or chemotaxis; slow on/off rates suggest it modulates C5a function [PMID:12899627]. In transfected RBL-2H3 cells it did not support degranulation or calcium rise, though ligation potentiated FcepsilonRI-driven degranulation [PMID:11773063].","molecular_requirements":"Single receptor chain; C5a des-Arg(74) binds with higher affinity than at CD88 [PMID:11773063]. Active ligand is C5a fragment.","affinity_potency":[{"value":"pEC50 8.85","assay":"binding, as curated","system":"human, transfected cells","cite":"PMID:11773063"}],"species_and_systems":"Human ligand and receptor in 11773063; species unspecified in 12899627 (which mentions human and murine C5L2) [PMID:12899627].","localisation_and_range":"C5 (C5a) flagged secreted; C5AR2 flagged transmembrane [flag].","caveats":"Both papers read as abstracts. Curated effect_direction is inconsistent between rows (neutral vs full agonist) and GtoPdb lists the interaction as full agonist [DB:GtoPdb], which the papers contradict. One further row is still pending.","key_references":[{"PMID":"11773063","why":"High-affinity C5a binding to C5L2"},{"PMID":"12899627","why":"C5L2 is a non-signalling C5a binding protein"}],"covers":["LR000169"]},"LR005056":{"pair":"CADM1 -> CRTAM","headline":"Well-supported direct CADM1-CRTAM binding with nM affinity and an immune-cell functional effect.","interaction_type":"direct binding","direction_and_effect":"NK cells and CD8+ T cells recognise CADM1 (Necl-2) through CRTAM, which is expressed only on activated cells; the interaction promotes NK cytotoxicity and CD8+ T-cell IFN-gamma secretion in vitro and NK-cell-mediated rejection of CADM1-expressing tumours in vivo [PMID:15811952]. UniProt gives the same functional summary [DB:UniProt]. CADM1 acts as the epithelial/tumour ligand, CRTAM as the receptor on cytotoxic lymphocytes.","molecular_requirements":"Whole ectodomains bound in SPRi. The paper states the IgV loops are primarily involved while IgC loops facilitate binding [PMID:30131958]. UniProt notes the interaction competes with CRTAM and CADM1 homodimerisation [DB:UniProt]. No extra subunit reported.","affinity_potency":[{"value":"Kd 3.3 nM","assay":"SPRi, CADM1-Fc with CRTAM-Fc, ectodomains","system":"Fc fusions from 293-F cells","cite":"PMID:30131958"}],"species_and_systems":"SPRi used human-labelled recombinant ectodomains [PMID:30131958]; the NK/CD8 T-cell and tumour work is labelled human in the dossier but species is not stated in the abstract read [PMID:15811952]. Structure of a complex is deposited [DB:PDB 4H5S]; IntAct lists cosedimentation and solid-phase assays [DB:IntAct].","localisation_and_range":"Both partners are flagged membrane-bound [flag]; the paper describes the interaction between epithelial cells expressing CADM1 and CD8+ T/NK cells expressing CRTAM, i.e. contact-dependent [PMID:30131958].","caveats":"The earlier functional paper was read as an abstract only [PMID:15811952]. The paper reports an earlier E. coli IgV-IgV Kd of 12.5 uM, far weaker than 3.3 nM, and attributes it to the IgC loops [PMID:30131958]. Dissociation is very slow versus other CADM partners [PMID:30131958].","key_references":[{"PMID":"15811952","why":"CRTAM recognises CADM1; NK/CD8 T-cell function and tumour rejection"},{"PMID":"30131958","why":"SPRi Kd 3.3 nM, slow off-rate"}],"covers":["LR001680","LR005056"]},"LR001681":{"pair":"CADM1 -> NECTIN3","headline":"Functional evidence only: a neutralizing anti-nectin-3 antibody blocks CADM1-dependent mast cell-neuron interaction; direct binding not shown here.","interaction_type":"functional only","direction_and_effect":"Mast-cell CADM1 mediated attachment to dorsal root ganglion (DRG) neurites and calcium responses to activated neurites, although neuronal CADM1 was low; nectin-3 was expressed on DRG neurons, and a neutralizing anti-nectin-3 antibody inhibited both attachment and calcium responses. The authors infer heterophilic CADM1-nectin-3 binding [PMID:22703826].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"In vitro mast cell-DRG co-culture; species not stated in the abstract read, dossier labels it human [PMID:22703826]. The human pair is ortholog-inferred; the mouse pair is not.","localisation_and_range":"Both flagged membrane-bound [flag]; nectin-3 localised to neuron-neuron contact regions [PMID:22703826]. Contact-dependent between mast cell and neuron.","caveats":"Abstract only; binding is inferred from antibody blockade, not measured [PMID:22703826]. Reactome lists a Necl-2:Nectin-3 trans heterodimer reaction [DB:Reactome].","key_references":[{"PMID":"22703826","why":"Neutralizing nectin-3 antibody blocks CADM1-dependent mast cell-DRG interaction"}],"covers":["LR001681","LR005057"]},"LR005542":{"pair":"CADM3 -> CADM2","headline":"Direct CADM3-CADM2 binding detected by SPRi in one paper; no pair-specific affinity.","interaction_type":"direct binding","direction_and_effect":"SPRi detected heterophilic interactions of CADM3 with all CADM family proteins, including CADM2 [PMID:30131958].","molecular_requirements":"Whole ectodomain Fc fusions [PMID:30131958].","affinity_potency":[],"species_and_systems":"Human-labelled recombinant ectodomains in SPRi [PMID:30131958]. Mouse pair is ortholog-inferred.","localisation_and_range":"Both flagged non-secreted [flag].","caveats":"One paper. The curated sentence describes CADM1-Fc binding CADM2, not CADM3. A CADM1-CADM2 Kd exists in the paper but is not for this pair.","key_references":[{"PMID":"30131958","why":"SPRi of CADM family"}],"covers":["LR002232","LR005542"]},"LR003715":{"pair":"CALCA -> CALCR","headline":"Alpha-CGRP acts as a weak agonist at CALCR alone and more potently at CALCR+RAMP; much of the binding evidence is for calcitonin.","interaction_type":"functional only","direction_and_effect":"Alpha-CGRP is an agonist (cAMP readouts). At CALCR alone it is weak: about 100-fold less potent than hCT [PMID:12565884]; CTR2/RAMP heterodimers gave cAMP responses approximately 50-fold greater than CTR2 alone [PMID:14722252]. It is far more potent at CALCR+RAMP1 (AMY1a) [PMID:15692146]; AMY1 (CALCR/RAMP1) was reported as a functional second CGRP receptor in rat trigeminal neurons [PMID:26125036]. GtoPdb records the pair as full agonist [DB:GtoPdb].","molecular_requirements":"RAMP co-expression is needed for physiologically relevant CGRP potency; the RAMP1 C-terminal domain increased CGRP potency over CTRa alone, the RAMP2 one did not [PMID:16531504]. RAMP1 and CTR2 form cell-surface complexes [PMID:11023820]. RAMP3 co-expression changed relative potency of hCTR to calcitonin and amylin [PMID:11033437].","affinity_potency":[{"value":"Kd 4.6 nM","assay":"calcitonin (human CT) binding to calcitonin receptor, not CGRP","system":"human ovarian carcinoma BIN-67 cells","cite":"PMID:1331173"},{"value":"IC50 8.1 nM","assay":"hCT inhibition of [125I]hCT binding (CGRP-I over 100 times less potent)","system":"human MCF-7 cells","cite":"PMID:9487987"}],"species_and_systems":"Mostly human proteins in transfected cells (HEK-293, COS-7, RAEC, Xenopus melanophores) [PMID:14722252][PMID:12565884][PMID:11033437]; trigeminal work used rat and human tissue [PMID:26125036]. Mouse pair is ortholog-inferred. PDB 7TYH and 7TYO contain CALCA and CALCR chains [DB:PDB 7TYH].","localisation_and_range":"CALCA is flagged secreted and CALCR transmembrane [flag]: paracrine/endocrine peptide acting on a membrane GPCR.","caveats":"All 11 papers shown were read as abstracts only. Several binding papers measure calcitonin (hCT), not CGRP [PMID:1331173][PMID:9487987][PMID:7588285]. Many cite CTR2 or isoforms, not the AMY1 complex. Reactome lists a CALCA(83-119) fragment binding CALCR [DB:Reactome]; UniProt lists calcitonin and CGRP1/CALCA as CALCR activators [DB:UniProt].","key_references":[{"PMID":"15692146","why":"alpha-CGRP weak at CALCR alone, potent at CALCR+RAMP1 (AMY1a)"},{"PMID":"12565884","why":"CGRP about 100-fold less potent than hCT at CTR alone; RAMP raises potency"},{"PMID":"26125036","why":"AMY1 (CALCR/RAMP1) as functional CGRP receptor in trigeminal neurons"}],"covers":["LR000170","LR003715"]},"LR002239":{"pair":"CALCA -> RAMP3","headline":"alpha-CGRP signals weakly through RAMP3-containing receptors; support is functional, abstract-level, with GtoPdb agonist records.","interaction_type":"functional only","direction_and_effect":"CTR2/RAMP3 mediated hCGRPalpha-stimulated cAMP production, but binding and signalling were markedly weaker than with CTR2/RAMP1 [PMID:14722252]. A dominant-negative RAMP3 reduced hCGRPalpha signalling below the CTR2-alone level [PMID:14722252]. GtoPdb lists full agonist records [DB:GtoPdb].","molecular_requirements":"Requires a partner receptor (CTR2 here) [PMID:14722252]; RAMP3 alone is not shown to bind CGRP. Another paper on RAMP3 with human calcitonin receptor concerns human calcitonin and amylin, not CGRP [PMID:11033437].","affinity_potency":[{"value":"pKi 6.5 to 6.8","assay":"GtoPdb agonist record","system":"database record","cite":"DB:GtoPdb"},{"value":"pEC50 7.6 to 9.7","assay":"GtoPdb agonist record","system":"database record","cite":"DB:GtoPdb"}],"species_and_systems":"Human CTR2/RAMP3 in HEK-293 cells [PMID:14722252]. Mouse pair is projected from human evidence.","localisation_and_range":"Ligand flagged secreted [flag].","caveats":"All papers read as abstracts only. [PMID:11033437] measured potency shifts for calcitonin in Xenopus melanophores, which concerns the CALCA gene product calcitonin, not alpha-CGRP. [PMID:30139742] concerns AM2/IMD binding in RAMP-CLR ECD complexes.","key_references":[{"PMID":"14722252","why":"CTR2/RAMP3 responds to hCGRPalpha, more weakly than RAMP1"}],"covers":["LR002239","LR005549"]},"LR008512":{"pair":"CALM1 -> EGFR","headline":"Calmodulin-EGFR rests on IntAct co-IP and related association records; no curated paper.","interaction_type":"direct binding","direction_and_effect":"IntAct lists five records: anti-bait coimmunoprecipitation [DB:IntAct EBI-1256982], affinity chromatography [DB:IntAct EBI-32717697], and ubiquitin reconstruction (split-ubiquitin) [DB:IntAct EBI-5234930]. Direction and effect are not reported in our evidence.","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human; methods per IntAct records.","localisation_and_range":"Intracellular calmodulin; no secreted flag in our evidence. Not reported in our evidence beyond the entity annotation flags.","caveats":"No papers were confirmed; support is from curated database records only. Rows were review_only or different_entity; EGFR is flagged receptor [flag]; some assays are indirect.","key_references":[],"covers":["LR008512"]},"LR009205":{"pair":"CALM1 -> KCNQ1","headline":"Calmodulin binds the C-terminus of KCNQ1, shown by crystal and cryo-EM structures.","interaction_type":"direct binding","direction_and_effect":"Structures include Kv7.1 proximal C-terminal domain with calmodulin [DB:PDB 4UMO] and KCNQ1-CaM-PIP2 [DB:PDB 12DK]. UniProt says calmodulin forms a potassium channel complex with KCNQ1 and regulates its activity via calcium binding [DB:UniProt].","molecular_requirements":"Binding is via the KCNQ1 C-terminus [DB:UniProt].","affinity_potency":[],"species_and_systems":"Human, from databases.","localisation_and_range":"Intracellular calmodulin; no secreted flag in our evidence. Not reported in our evidence beyond the entity annotation flags.","caveats":"No papers were confirmed; support is from curated database records only. 36 structures exist, five shown.","key_references":[],"covers":["LR009205"]},"LR000178":{"pair":"CALR -> SCARF1","headline":"Calreticulin is endocytosed via SREC-I in an abstract-read paper; supported by one study.","interaction_type":"direct binding","direction_and_effect":"SREC-I (SCARF1) mediates endocytosis of calreticulin and gp96; ectopic SREC-I in CHO cells conferred recognition and uptake, competed by fucoidin and acetylated LDL, and SREC-I overexpression in macrophages increased chaperone endocytosis [PMID:15371419].","molecular_requirements":"Not all scavenger receptors that bind acetylated LDL bind calreticulin or gp96, so specificity goes beyond generic scavenging [PMID:15371419]. Co-receptors are not reported in our evidence.","affinity_potency":[],"species_and_systems":"CHO cells with ectopic SREC-I, and macrophages including SRA-knockout macrophages; the curator records human for both partners but the abstract does not state species [PMID:15371419].","localisation_and_range":"CALR is flagged secreted [flag]; the paper describes endocytic uptake of extracellular chaperone.","caveats":"Only the abstract was read. The function is endocytic clearance and antigen cross-presentation, so this is an uptake receptor and not clearly a signalling one. A second confirmed paper exists but was not shown. Direct binding is inferred from uptake competition, as no affinity is given.","key_references":[{"PMID":"15371419","why":"SREC-I mediates calreticulin endocytosis"}],"covers":["LR000178","LR003723"]},"LR003724":{"pair":"CAMP -> FPR2","headline":"LL-37 (CAMP) activates FPR2 in chemotaxis and calcium assays; two abstract-read papers, human and mouse.","interaction_type":"functional only","direction_and_effect":"LL-37 is chemotactic and induces Ca(2+) mobilization in monocytes and FPRL1-transfected HEK293 cells, with cross-desensitization by an FPRL1-specific agonist [PMID:11015447]. The mouse orthologue CRAMP acts as a full agonist using FPRL1 / mouse FPR2 [PMID:15879124]. GtoPdb lists Agonist, Full agonist [DB:GtoPdb].","molecular_requirements":"Only the receptor chain FPR2 is involved; the active peptide is the cleaved 37-residue LL-37 from the CAMP precursor hCAP18 [PMID:11015447].","affinity_potency":[{"value":"pEC50 6.0","assay":"LL-37 agonist potency, as recorded by curators and GtoPdb","system":"FPRL1-transfected HEK293 cells / human cells","cite":"PMID:11015447"}],"species_and_systems":"Human LL-37 on human monocytes and transfected HEK293 cells [PMID:11015447]; mouse CRAMP on human and mouse leukocytes and HEK293 cells expressing FPRL1 or mouse FPR2, plus mouse air pouch in vivo [PMID:15879124]. The mouse pair is ortholog-inferred in our database.","localisation_and_range":"CAMP is flagged secreted and FPR2 transmembrane [flag]; paracrine chemoattractant action is described [PMID:11015447].","caveats":"Both papers were read as abstracts only; evidence is functional (chemotaxis, calcium flux), not direct binding, and the pEC50 is as recorded and its assay detail is not reported in our evidence. A third confirmed paper was not shown.","key_references":[{"PMID":"11015447","why":"LL-37 uses FPRL1 for chemotaxis and Ca2+ mobilization"},{"PMID":"15879124","why":"Mouse CRAMP uses FPRL1 / mFPR2 as receptor"}],"covers":["LR000179","LR003724"]},"LR005551":{"pair":"CBLIF -> CUBN","headline":"Intrinsic factor-cobalamin binds cubilin with high affinity; SPR plus structural and Reactome records.","interaction_type":"direct binding","direction_and_effect":"Surface plasmon resonance of ligand-affinity-purified human cubilin showed high-affinity, calcium- and cobalamin-dependent binding of IF-cobalamin [PMID:9572993]. Reactome lists CUBN:AMN binding CBLIF:RCbl [DB:Reactome].","molecular_requirements":"Binding depends on calcium and on cobalamin being bound to intrinsic factor [PMID:9572993]. Reactome describes a CUBN:AMN complex as the binder, so a second chain (AMN) may be required [DB:Reactome]; the abstract does not test this.","affinity_potency":[],"species_and_systems":"Purified human cubilin by SPR; cDNA cloning of human cubilin, a 3597 amino acid peripheral membrane protein [PMID:9572993]. The mouse pair is ortholog-inferred.","localisation_and_range":"CBLIF is flagged secreted [flag]; cubilin is described as a peripheral membrane protein in intestinal and kidney epithelium [PMID:9572993].","caveats":"The abstract gives no numerical affinity. A second confirmed paper was not shown. Other records are a PDB structure [DB:PDB 3KQ4], an IntAct molecular sieving record and BioGRID reconstituted complex [DB:BioGRID]. Uptake of vitamin B12 is the context, so the ligand is the cobalamin-loaded form.","key_references":[{"PMID":"9572993","why":"SPR binding of IF-cobalamin to human cubilin; cubilin cloning"}],"covers":["LR002241","LR005551"]},"LR002248":{"pair":"CBLN2 -> NRXN3","headline":"Functional evidence only for secreted CBLN2 acting with splice-variant NRXN3 (SS4+) in mouse circuits; direct binding data not in our evidence.","interaction_type":"functional only","direction_and_effect":"The paper's introduction states that Nrxn3SS4+ acts by binding secreted Cbln2, which then activates postsynaptic GluD1 receptors [PMID:36205393]. The paper's own result: in prefrontal cortex Nrxn3SS4+-Cbln2 signalling had no apparent role, while in cerebellum Nrxn3SS4+-Cbln1 regulated AMPA-receptors [PMID:36205393].","molecular_requirements":"Needs the SS4+ splice variant of NRXN3; GluD1 is the downstream postsynaptic partner [PMID:36205393]. Whether NRXN3 alone suffices is not reported in our evidence.","affinity_potency":[],"species_and_systems":"Constitutive Cbln2 deletions in mice (CA1-to-subiculum, prefrontal cortex, cerebellum) [PMID:36205393]. The curated fields say human, but the abstract describes mouse work. Only the mouse pair is non-inferred; the human pair is projected.","localisation_and_range":"CBLN2 is flagged secreted and NRXN3 transmembrane [flag]; the paper describes secreted Cbln2 binding neurexins [PMID:36205393].","caveats":"Binding is asserted as background, not measured in this dossier. Read as abstract only. The paper reports no role for Nrxn3SS4+-Cbln2 in prefrontal cortex [PMID:36205393].","key_references":[{"PMID":"36205393","why":"Maps neurexin-splice-variant x cerebellin combinations across circuits in mice"}],"covers":["LR002248","LR005558"]},"LR005560":{"pair":"CBLN4 -> NEO1","headline":"Genetic evidence in mouse that postsynaptic neogenin-1 matches presynaptic Cbln4 for LTP; direct binding data are not shown in our evidence.","interaction_type":"functional only","direction_and_effect":"Cbln4 bound to cell-surface neurexins forms transcellular complexes by interacting with postsynaptic DCC or neogenin-1; neogenin-1 deletion in dentate granule cells blocked EC-to-DG LTP without affecting basal transmission, mirroring presynaptic Cbln4 deletion [PMID:35544694]. Curators label it agonist.","molecular_requirements":"Cbln4 acts bound to neurexins [PMID:35544694]. Neogenin-1, not DCC, is abundant in dentate granule cells [PMID:35544694].","affinity_potency":[],"species_and_systems":"Mouse dentate gyrus, entorhinal cortex to dentate gyrus synapses, with conditional deletions [PMID:35544694]. Curated species fields say human, but the work is mouse; the human pair is projected.","localisation_and_range":"Transsynaptic, presynaptic Cbln4 to postsynaptic neogenin-1 [PMID:35544694]. CBLN4 is flagged secreted [flag].","caveats":"Read as abstract only; binding affinity and specificity are not reported in our evidence [PMID:35544694].","key_references":[{"PMID":"35544694","why":"Postsynaptic neogenin-1 deletion blocks EC-DG LTP like presynaptic Cbln4 deletion"}],"covers":["LR002250","LR005560"]},"LR000187":{"pair":"CCL11 -> CXCR3","headline":"CCL11 binds CXCR3 with high affinity but does not activate it; reported as a silent binder or antagonist, not an agonist.","interaction_type":"conflicting","direction_and_effect":"CCL11 does not activate CXCR3 and can block IP10-mediated activation in CXCR3-transfected cells [PMID:9660793]. A second paper reports CCL11 binds with high affinity but is neither agonist nor antagonist, and proposes a decoy role [PMID:12884299]. GtoPdb lists an antagonist [DB:GtoPdb].","molecular_requirements":"Chimeras localise the CCL11/CXCL11 shared binding site to the CXCR3 extracellular loops [PMID:12884299].","affinity_potency":[{"value":"pKi 7.2","assay":"competition binding against IP10","system":"CXCR3-transfected cells","cite":"PMID:9660793"}],"species_and_systems":"Human ligand and receptor, recombinant cells [PMID:9660793][PMID:12884299]. The mouse pair is ortholog-inferred.","localisation_and_range":"Secreted ligand, transmembrane receptor [flag].","caveats":"The two papers disagree on whether CCL11 is a weak antagonist or functionally silent. The pair is not an activating pair despite the Stimulatory/Inhibitory flag in the record; both papers are abstract-only.","key_references":[{"PMID":"12884299","why":"High-affinity but functionally silent CCL11 binding to CXCR3"},{"PMID":"9660793","why":"Eotaxin blocks IP10 activation of CXCR3"}],"covers":["LR000187","LR003732"]},"LR000196":{"pair":"CCL14 -> CCR3","headline":"CCL14 is an agonist at CCR3 only as the processed HCC-1[9-74] form, shown functionally in one abstract-level paper.","interaction_type":"functional only","direction_and_effect":"HCC-1[9-74] was a potent agonist of CCR3 (also CCR1 and CCR5) and promoted calcium flux and chemotaxis, including in eosinophils [PMID:11085751].","molecular_requirements":"Activity requires proteolytic processing; full-length HCC-1 is described as a nonfunctional precursor [PMID:11085751].","affinity_potency":[],"species_and_systems":"Human ligand and human cells; abstract-level reading plus methods excerpts [PMID:11085751].","localisation_and_range":"Secreted ligand and transmembrane receptor according to entity annotation flags [flag]; paracrine/endocrine range implied by the secreted flag only.","caveats":"Single paper, no binding or affinity data for CCR3 reported in our evidence, and no database record. The paper's CCR3 result is in the abstract, not in the supplied full-text excerpts.","key_references":[{"PMID":"11085751","why":"HCC-1[9-74] agonist at CCR1/CCR3/CCR5"}],"covers":["LR000196"]},"LR002257":{"pair":"CCL16 -> ACKR1","headline":"CCL16 binds human ACKR1 (Duffy) on erythrocytes with weak affinity; one paper.","interaction_type":"direct binding","direction_and_effect":"Binding only; ACKR1 is an atypical receptor and no signalling is reported in our evidence. CCL16 showed weak binding to Duffy antigen on red blood cells, in the 100 nM to 1 uM Ki class [PMID:15358176].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[{"value":"Ki 257.7 nM","assay":"radioligand displacement (Ki 100 nM-1 uM defined as weak)","system":"human red blood cells","cite":"PMID:15358176"}],"species_and_systems":"Human chemokine and human Duffy antigen on erythrocytes [PMID:15358176].","localisation_and_range":"Secreted ligand and transmembrane receptor according to entity annotation flags [flag]; paracrine/endocrine range implied by the secreted flag only.","caveats":"Weak binder; single paper; no database support. The paper found strong binding mainly for inflammatory chemokines.","key_references":[{"PMID":"15358176","why":"Chemokine binding profile of human Duffy antigen"}],"covers":["LR002257"]},"LR003733":{"pair":"CCL17 -> CCR4","headline":"CCL17 (TARC) is a high-affinity, selective CCR4 agonist, confirmed by two binding papers and database records.","interaction_type":"direct binding","direction_and_effect":"Agonist: TARC bound CCR4 selectively among five CC receptors [PMID:9169480] and induced calcium mobilisation in CCR4 transfectants [PMID:9430724]. GtoPdb lists a full agonist [DB:GtoPdb]; UniProt says it acts by binding CCR4 on T cells [DB:UniProt].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[{"value":"Kd 0.5 nM","assay":"TARC-SEAP binding","system":"K562 cells stably expressing CCR4","cite":"PMID:9169480"},{"value":"pIC50 8.7","assay":"binding competition (curator-recorded)","system":"CCR4-transfected L1.2 cells","cite":"PMID:9430724"}],"species_and_systems":"Human ligand and receptor in transfected K562 and L1.2 cells; abstract-only [PMID:9169480][PMID:9430724].","localisation_and_range":"Secreted ligand and transmembrane receptor according to entity annotation flags [flag]; paracrine/endocrine range implied by the secreted flag only.","caveats":"The mouse pair is projected from human evidence. TARC did not desensitize the MDC response [PMID:9430724].","key_references":[{"PMID":"9169480","why":"Identifies CCR4 as the TARC receptor, Kd 0.5 nM"},{"PMID":"9430724","why":"Competition and signalling at CCR4"}],"covers":["LR000205","LR003733"]},"LR003760":{"pair":"CCL2 -> CCR5","headline":"Weak-affinity binding of MCP-1 to CCR5 from one abstract-read paper, with no stated functional activation for MCP-1.","interaction_type":"direct binding","direction_and_effect":"MCP-1 competed for [125I]-MIP-1beta binding to CCR5; the paper highlights MCP-3 as a natural antagonist, but the abstract does not state MCP-1 activity [PMID:10477718]. GtoPdb lists a full agonist record [DB:GtoPdb].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[{"value":"IC50 29.9 nM","assay":"competition vs [125I]-MIP-1beta","system":"stable CCR5-expressing cell line","cite":"PMID:10477718"}],"species_and_systems":"Human ligand and receptor in a recombinant cell line [PMID:10477718]. Mouse pair is ortholog-inferred.","localisation_and_range":"Ligand is flagged as secreted and not transmembrane [flag], so signalling is presumably paracrine or endocrine; receptor is flagged transmembrane [flag].","caveats":"Abstract only; MCP-1 is one of several weaker competitors. Two other papers pending, one abstract_insufficient. The GtoPdb entry cites a different paper [DB:GtoPdb].","key_references":[{"PMID":"10477718","why":"CCR5 competition binding, MCP-1 IC50 29.9 nM"}],"covers":["LR000239","LR003760"]},"LR001690":{"pair":"CCL20 -> ACKR4","headline":"Two recent papers show CCL20 is taken up by and recruits beta-arrestin to ACKR4, with lower affinity than CCL19, CCL21 and CCL25.","interaction_type":"functional only","direction_and_effect":"CCL20 acts as agonist at ACKR4: all four chemokines recruit beta-arrestin1 and beta-arrestin2 to human ACKR4 [PMID:32533638], and a screen of 43 human chemokines confirmed CCL20 as an agonist [PMID:32480426].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human ligand and receptor in both papers; fluorescent CCL20 uptake and cross-species tests: mouse CCL20 did not recruit beta-arrestins to human ACKR4, while mouse ACKR4 internalises mouse and human CCL20 [PMID:32533638]. Mouse interaction is listed without ortholog inference.","localisation_and_range":"Ligand is flagged as secreted and not transmembrane [flag], so signalling is presumably paracrine or endocrine; receptor is flagged transmembrane [flag].","caveats":"Both papers abstract only; no direct binding constant in our evidence, the 'lower affinity' is a qualitative statement [PMID:32533638]. No database records.","key_references":[{"PMID":"32533638","why":"CCL20 uptake and beta-arrestin recruitment by ACKR4"},{"PMID":"32480426","why":"Systematic 43-chemokine screen confirms CCL20"}],"covers":["LR001690","LR005063"]},"LR003742":{"pair":"Ccl21b -> Ackr4","headline":"Mouse pair projected from human CCL21-ACKR4 evidence; a single abstract-read paper on CCX-CKR beta-arrestin recruitment.","interaction_type":"functional only","direction_and_effect":"CCX-CKR (ACKR4) acts as a decoy that efficiently internalises CCL19, CCL21 and CCL25, and beta-arrestins were recruited to it in response to CCL21 [PMID:23341447]. It is not known to activate classical Gi signalling [PMID:23341447].","molecular_requirements":"Not reported in our evidence beyond ACKR4 as the receptor; signalling to CRE needed an intact DRY motif [PMID:23341447].","affinity_potency":[],"species_and_systems":"The dossier does not state the species used in PMID:23341447, and the mouse pair is inferred from human, not tested. No database record.","localisation_and_range":"Ligand flagged secreted and receptor flagged a receptor [flag]; no transmembrane flag is given.","caveats":"Single paper read as abstract only; the evidence sentence names CCL21 generically, not mouse Ccl21b. No affinity reported for this pair.","key_references":[{"PMID":"23341447","why":"CCL21 triggers beta-arrestin recruitment to ACKR4; decoy role"}],"covers":["LR003742"]},"LR005065":{"pair":"CCL22 -> ACKR2","headline":"CCL22 competes for uptake by ACKR2 in one trophoblast study; database annotation also lists CCL22 as an ACKR2 ligand.","interaction_type":"functional only","direction_and_effect":"Uptake of fluorescent CCL2 by ACKR2-expressing HEK cells and human trophoblasts fell when a 10-fold excess of unlabelled CCL22 (among others) was added, so CCL22 interacts with ACKR2 [PMID:25297873]. ACKR2 is a scavenger: it binds many inflammatory CC chemokines but does not stimulate migration or conventional signalling [PMID:25297873]. UniProt lists CCL22 among ACKR2 chemokine ligands [DB:UniProt].","molecular_requirements":"ACKR2 alone in HEK cells was enough for competition of uptake; no other subunits reported.","affinity_potency":[],"species_and_systems":"Human HEK-ACKR2 cells and primary human trophoblasts [PMID:25297873]. The mouse pair is projected from human; the same paper used mouse Ackr2 knockouts but not for CCL22 in our evidence.","localisation_and_range":"Ligand is flagged secreted and receptor flagged transmembrane [flag]; this is an annotation, not from the papers, and implies paracrine/endocrine signalling to a cell-surface receptor. ACKR2 is described as an internalising scavenger [PMID:25297873].","caveats":"Only an indirect competition-of-uptake result from a browser-read quote (unverified); no direct CCL22 binding or affinity. UniProt alone lacks a quoted assay. No affinity reported.","key_references":[{"PMID":"25297873","why":"CCL22 competes for ACKR2-mediated CCL2 uptake"}],"covers":["LR001692","LR005065"]},"LR003751":{"pair":"CCL28 -> CCR10","headline":"CCL28 is an agonist of CCR10, shown by calcium flux and chemotaxis in transfectants for human and mouse; supported by GtoPdb and Reactome.","interaction_type":"functional only","direction_and_effect":"CCL28 induces calcium mobilisation in CCR10-expressing transfectants and desensitises the CCL27 response, indicating a shared receptor [PMID:10781587]. Chemotaxis of CCR10-expressing lymphoid cells toward CCL28 is also reported [PMID:10975800]. GtoPdb lists a full agonist [DB:GtoPdb].","molecular_requirements":"Single receptor chain; no co-receptor or processed form reported in our evidence.","affinity_potency":[],"species_and_systems":"Both human and mouse CCL28 and CCR10 were tested in transfectants, so the mouse evidence is direct [PMID:10781587]; the second paper used human proteins [PMID:10975800].","localisation_and_range":"CCL28 is flagged as secreted and CCR10 as transmembrane [flag]; CCL28 is produced predominantly by epithelial cells and is expressed in mucosal tissues [PMID:10781587][PMID:10975800].","caveats":"Both papers were read as abstracts only and show function rather than binding; no affinity reported in our evidence. Reactome records the binding reaction 'CCR10 binds CCL27 and 28' [DB:Reactome].","key_references":[{"PMID":"10781587","why":"Identifies CCL28 as CCR10 ligand: calcium flux, human and mouse"},{"PMID":"10975800","why":"Independent chemotaxis of CCR10 transfectants to CCL28"}],"covers":["LR000230","LR003751"]},"LR008602":{"pair":"CCL3L3 -> CCR1","headline":"LD78beta binds CCR1 in one paper, but the second paper's 'MIP-1delta' mapping to CCL3L3 is doubtful; support is uncertain.","interaction_type":"direct binding","direction_and_effect":"MIP-1delta, one of the panel, displaced 125I-MIP-1alpha at hCCR1 and, like most of the panel, acted as full agonist in [35S]-GTPgammaS exchange [PMID:12381680]. LD78beta(3-70) competed tenfold more efficiently than LD78beta(1-70) with [125I]RANTES for CCR1 and CCR5 [PMID:11449371].","molecular_requirements":"The CD26-processed LD78beta(3-70) form is more potent at CCR1 [PMID:11449371].","affinity_potency":[],"species_and_systems":"Human CCR1 in Ba/F3 transfectant membranes [PMID:12381680]; human proteins in binding competition assays [PMID:11449371].","localisation_and_range":"CCL3L3 is flagged as secreted and CCR1 as transmembrane [flag].","caveats":"Both papers were read as abstracts only. In PMID 12381680 MIP-1alpha and MIP-1delta are listed as separate chemokines, and LD78beta is not named in the abstract. Seven further papers were abstract-insufficient and are not shown.","key_references":[{"PMID":"11449371","why":"LD78beta isoform binding to CCR1"},{"PMID":"12381680","why":"Panel of chemokines at hCCR1 incl. MIP-1delta"}],"covers":["LR008602"]},"LR000259":{"pair":"CCL5 -> CCR5","headline":"Very well supported: CCL5 (RANTES) is a high-affinity CCR5 ligand and agonist, with binding, mutagenesis, structure and database support.","interaction_type":"direct binding","direction_and_effect":"Cells expressing CCR5 bind RANTES with high affinity and generate inositol phosphates [PMID:8663314]. RANTES, MIP-1 alpha and vMIP-II bound CCR5 at high affinity with partial cross-competition [PMID:11700073]. MCP-2 cross-competed with RANTES and showed cross-desensitization in Ca2+ flux [PMID:9790730]. GtoPdb lists a full agonist [DB:GtoPdb].","molecular_requirements":"RANTES Phe12 and Ile15 and P2 are needed for CCR5 binding, and Y3 and D6 for activation [PMID:9289016]. Acidic residues in the CCR5 distal N-terminus and ECL2 are needed for binding [PMID:11700073]. Glycosaminoglycan-bearing syndecan-1/-4 and CD44 co-precipitate with RANTES, and glycosaminidase treatment reduces CCR5 binding [PMID:14637022]. Structures with CCL5 and CCR5 chains exist [DB:PDB 5UIW, DB:PDB 6FGP, DB:PDB 7F1R, DB:PDB 7O7F].","affinity_potency":[{"value":"pKi 9.2 to 9.7","assay":"GtoPdb interaction record","system":"not stated","cite":"DB:GtoPdb"}],"species_and_systems":"Human receptors and ligands in transfected cells and macrophages [PMID:8663314, PMID:14637022]. The mouse pair is inferred from human evidence.","localisation_and_range":"CCL4/CCL5 carry a secreted flag [flag], so paracrine or endocrine range is implied; the receptor carries receptor and transmembrane flags [flag]. RANTES attaches to cell-surface proteoglycans [PMID:14637022].","caveats":"Papers were read as abstracts only. No direct RANTES Kd or IC50 appears in our evidence. IntAct NMR and BioGRID records also exist [DB:IntAct, DB:BioGRID]. PMID:10318947 and PMID:10477718 are mainly about TAK-779 and other chemokines.","key_references":[{"PMID":"8663314","why":"CCR5 cloning; RANTES high-affinity binding and signalling"},{"PMID":"11700073","why":"RANTES binding and CCR5 residues required"},{"PMID":"9289016","why":"RANTES residues for CCR5 binding and activation"}],"covers":["LR000259","LR003769"]},"LR002266":{"pair":"CCL5 -> DPP4","headline":"Evidence shows DPP4 (CD26) truncates RANTES to an inactive form; this is enzyme-substrate processing, not receptor binding.","interaction_type":"functional only","direction_and_effect":"CD26/DPP IV induced N-terminal truncation of RANTES; truncated RANTES(3-68) was inactive in chemotaxis at 300 ng/ml versus intact RANTES(1-68) active at 10 ng/ml, and acted as a chemotaxis inhibitor [PMID:9516414]. It inhibited M-tropic HIV-1 infection of mononuclear cells 5-fold more efficiently than intact RANTES [PMID:9516414].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human cells and proteins; experiment species human for both partners [PMID:9516414]. Mouse pair is ortholog-inferred.","localisation_and_range":"Both are flagged: CCL5 secreted, DPP4 transmembrane receptor [flag].","caveats":"Read as abstract only. No binding measurement or signalling through DPP4 is reported; DPP4 acts as a protease on RANTES, so CCC scoring of this pair as a ligand-receptor signal is questionable. No database records.","key_references":[{"PMID":"9516414","why":"DPP4 cleaves RANTES to inhibitory RANTES(3-68)"}],"covers":["LR002266","LR005567"]},"LR000268":{"pair":"CCL7 -> CCR2","headline":"MCP-3 (CCL7) binds human CCR2B with Ki 7 nM and is a CCR2 agonist; supported by binding, a chemotaxis comparator and GtoPdb.","interaction_type":"direct binding","direction_and_effect":"125I-MCP-3 bound CC CKR2B (Ki 7 nM); MCP-1 and MCP-3 were equipotent agonists, EC50 10 nM for [Ca2+]i changes [PMID:8530354]. CCL7 also acted as a CCR2 chemoattractant comparator in L1.2-CCR2 cells [PMID:12554737]. GtoPdb: full agonist, pIC50 8.4 to 8.7 [DB:GtoPdb].","molecular_requirements":"CCR2B binding was competed only by MCP-3 and MCP-1 among CC chemokines tested [PMID:8530354]. No co-receptor needs reported.","affinity_potency":[{"value":"Ki 7 nM","assay":"125I-MCP-3 direct binding","system":"CC CKR2B transfectants (human)","cite":"PMID:8530354"},{"value":"EC50 10 nM","assay":"[Ca2+]i change","system":"CCR2B-transfected cells (human)","cite":"PMID:8530354"},{"value":"pIC50 8.4 to 8.7","assay":"GtoPdb binding range","system":"human CCR2","cite":"DB:GtoPdb"}],"species_and_systems":"Human ligand and receptor in transfected cells [PMID:8530354][PMID:12554737]; mouse pair is ortholog-inferred.","localisation_and_range":"CCL7 flagged secreted; CCR2 flagged transmembrane receptor [flag].","caveats":"Both papers read as abstract only. The second paper only uses CCL7 as a benchmark, with no CCL7 affinity. The EC50 10 nM is stated jointly for MCP-1 and MCP-3.","key_references":[{"PMID":"8530354","why":"Direct MCP-3 binding to CCR2B, Ki 7 nM, agonism"},{"PMID":"12554737","why":"CCL7 as comparator CCR2 chemoattractant"}],"covers":["LR000268","LR003778"]},"LR000277":{"pair":"CCL8 -> CCR5","headline":"CCL8 (MCP-2) binds CCR5 with high affinity and acts as an agonist; three independent binding and functional papers.","interaction_type":"direct binding","direction_and_effect":"MCP-2 competed for [125I]-MIP-1beta binding on CCR5-expressing cells (IC50 0.22 nmol/L, the most potent of the CC chemokines tested) [PMID:10477718]. It competitively inhibited MIP-1beta binding, induced chemotaxis with potency comparable to MIP-1beta and caused dose-dependent CCR5 internalization [PMID:9468473]. It is a true agonist, cross-desensitizing with RANTES in Ca2+ flux [PMID:9790730]. GtoPdb lists a full agonist [DB:GtoPdb].","molecular_requirements":"CCR5 alone in transfectants was sufficient; on CD3-activated T cells most MCP-2 responses were blocked by anti-CCR5 mAb 2D7 [PMID:9790730]. MCP-2 also blocked HIV-1 entry in CCR5/CD4-expressing cells [PMID:9468473].","affinity_potency":[{"value":"IC50 0.22 nmol/L","assay":"[125I]-MIP-1beta competition binding","system":"stable CCR5-expressing cell line","cite":"PMID:10477718"}],"species_and_systems":"Human ligand and human CCR5 in HEK293 or other stable cell lines, monocytes and activated T cells [PMID:9468473][PMID:9790730]. Mouse pair is ortholog-inferred.","localisation_and_range":"Secreted ligand acting on a transmembrane receptor [flag].","caveats":"All three papers were read as abstracts only. MCP-2 also binds CCR1 and CCR2b [PMID:9790730], so CCR5 is one of several receptors. Other numbers on the dossier curator rows are estimates not stated in the abstract and are not reported here.","key_references":[{"PMID":"10477718","why":"Competition binding IC50 for MCP-2 at CCR5"},{"PMID":"9468473","why":"MCP-2 binds, signals and internalizes CCR5; inhibits HIV-1"},{"PMID":"9790730","why":"MCP-2 is a true CCR5 agonist, main receptor on activated T cells"}],"covers":["LR000277","LR003787"]},"LR000385":{"pair":"CCN2 -> LRP1","headline":"LRP is reported as a heparin-dependent adhesion receptor for CTGF in rat hepatic stellate cells; abstract-level.","interaction_type":"direct binding","direction_and_effect":"LRP is a receptor for CTGF(1-4) or CTGF(3-4) but not CTGF(4). Blocking LRP with RAP, anti-LRP or a thrombospondin type I peptide reduced adhesion of activated HSCs by 50% [PMID:14585398]. Signalling outcome is not reported in our evidence.","molecular_requirements":"Modules 3-4 are needed: the module-4-only isoform did not use LRP [PMID:14585398]. Cell-surface heparan sulfate proteoglycans were binding sites for all isoforms, and heparin or heparinase fully blocked adhesion, so the interaction is heparin-dependent [PMID:14585398].","affinity_potency":[],"species_and_systems":"Rat activated hepatic stellate cells, rat proteins [PMID:14585398]. The human and mouse pairs are ortholog-inferred.","localisation_and_range":"CCN2 is flagged as secreted [flag], so paracrine or autocrine action is plausible; this is annotation, not shown by the papers. Action is adhesion to matrix-presented CTGF.","caveats":"Abstract read only. The protein is called LRP, and the abstract does not say LRP1 specifically. No affinity value is given. Adhesion blockade was only partial (50%).","key_references":[{"PMID":"14585398","why":"LRP as a heparin-dependent CTGF adhesion receptor in rat HSCs"}],"covers":["LR000385","LR003891"]},"LR002275":{"pair":"CCN2 -> TGFBR1","headline":"Only a single-cell computational and cell-culture study links CCN2 to TGFBR1; no direct CCN2-TGFBR1 binding is shown.","interaction_type":"functional only","direction_and_effect":"A single-cell and spatial transcriptomic study of hepatocellular carcinoma proposed a positive loop between tumour cells and fibroblasts mediated by CCN2/TGF-beta-TGFBR1 pairs [PMID:39095854]. Recombinant CCN2 enhanced the effect of recombinant TGF-beta on migration and invasion of PLC cells [PMID:39095854].","molecular_requirements":"The paper describes CCN2 as a coactivator of TGF-beta-SMAD signalling by direct binding to TGF-beta, citing earlier work, so it is background rather than this paper's result [PMID:39095854]. Multiplexed immunofluorescence showed colocalisation of CCN2, TGF-beta and TGFBR1 on tumour cell membranes [PMID:39095854].","affinity_potency":[],"species_and_systems":"Human HCC single-cell and spatial data, human cell lines (LX2, PLC) [PMID:39095854].","localisation_and_range":"CCN2 is flagged as secreted [flag], so paracrine or autocrine action is plausible; this is annotation, not shown by the papers. Fibroblasts were the CCN2 source and tumour cells the receiving cells [PMID:39095854].","caveats":"Computational and co-localisation evidence only. CCN2 binding to TGFBR1 itself is not shown; the mechanism is via TGF-beta. Abstract was the only text read by curators, although full text was available.","key_references":[{"PMID":"39095854","why":"HCC tumour-fibroblast loop involving CCN2/TGF-beta-TGFBR1"}],"covers":["LR002275","LR005576"]},"LR005074":{"pair":"CD200 -> CD200R1","headline":"Well supported direct binding: crystal structure of the CD200-CD200R complex plus FACS and SPR binding; CD200R signals inhibition.","interaction_type":"direct binding","direction_and_effect":"CD200 regulates myeloid cells through the inhibitory receptor CD200R [PMID:23602662]. Anti-CD200R antibody OX131 blocked CD200 binding and prevented CD200-mediated inhibition of IL-2 in a T cell hybridoma assay, while engaging CD200R alone gave an agonistic inhibitory signal [PMID:23691022]. Mice lacking CD200 resisted chemical skin carcinogenesis [PMID:22020332].","molecular_requirements":"Both CD200 and CD200R have two Ig-like domains and interact through their NH2-terminal domains [PMID:23602662]. The activating paralogue CD200RLa fails to bind CD200 [PMID:23602662]. Cells transfected with any CD200R family isoform bound CD200 in one report [PMID:15187158].","affinity_potency":[],"species_and_systems":"Crystal structure of the extracellular regions; the structure figure legend describes mouse CD200R [PMID:23602662]. Cell binding used COS7 transfectants [PMID:15187158] and 2B4 Reay cells with CD200-coated beads and SPR [PMID:23691022]. In vivo evidence is from Cd200-/- mice [PMID:22020332]. Curator species labels say human; the excerpts indicate mouse proteins in several papers. Human and mouse pairs are both listed.","localisation_and_range":"CD200 is a membrane glycoprotein [PMID:23602662]; both partners are flagged transmembrane [flag]. Signalling is by cell-cell contact, compatible with immunological-synapse-like interactions [PMID:23602662].","caveats":"Three of four papers were read as abstract only; no affinity value in our evidence. The knockout paper shows an in vivo functional outcome and not binding itself [PMID:22020332].","key_references":[{"PMID":"23602662","why":"Crystal structure of the CD200-CD200R complex"},{"PMID":"23691022","why":"FACS and SPR binding, antibody blocking, functional inhibition"},{"PMID":"15187158","why":"FACS binding of CD200Fc to CD200R isoforms"}],"covers":["LR001706","LR005074"]},"LR001708":{"pair":"CD200R1 -> CD200","headline":"Established CD200-CD200R binding; this row has the reverse orientation, CD200 is the ligand.","interaction_type":"direct binding","direction_and_effect":"Human CD200R was characterised and its binding to human CD200 defined [PMID:12960329]. CD200R is described as delivering an apparent inhibitory signal, unlike the activating CD200RLa/b [PMID:12960329].","molecular_requirements":"Mouse CD200RLa and CD200RLb pair with DAP12 and did not bind mouse CD200 [PMID:12960329].","affinity_potency":[],"species_and_systems":"Human CD200R with human CD200 per curator labels; mouse pair also listed; mouse work on paralogues [PMID:12960329].","localisation_and_range":"Both partners flagged secreted, receptor and transmembrane [flag]; not otherwise reported.","caveats":"One paper, abstract only; no affinity in our evidence. Database records support CD200-CD200R1 binding (BioGRID reconstituted complex, IntAct, Reactome) [DB:BioGRID][DB:IntAct][DB:Reactome]. The pair is the reverse of the usual CD200 -> CD200R1 direction.","key_references":[{"PMID":"12960329","why":"First human CD200R characterisation and CD200 binding"}],"covers":["LR001708","LR005076"]},"LR002284":{"pair":"CD24 -> SIGLEC10","headline":"CD24 engages inhibitory Siglec-10 on macrophages; supported by two functional papers (one full text), no direct binding measurement.","interaction_type":"functional only","direction_and_effect":"CD24 acts as an inhibitory, antagonist-type signal. CD24 association with Siglec-10 (human) or Siglec-G (mouse) dampens danger-associated inflammatory responses and NF-kappaB activation [PMID:19264983]. Tumour CD24 promotes immune evasion through Siglec-10 on tumour-associated macrophages; ablating CD24 or SIGLEC10, or blocking the interaction with antibodies, increased phagocytosis of CD24-expressing human tumours [PMID:31367043].","molecular_requirements":"Siglec-10-Fc binding to MCF-7 cells fell after surface desialylation, so sialylated CD24 appears to be needed [PMID:31367043]. UniProt notes the interaction depends on CD24 [DB:UniProt]. Single-chain partners; no other subunits reported in our evidence.","affinity_potency":[],"species_and_systems":"Human cells and macrophages (MCF-7 line, donor-derived macrophages, primary tumours) with in vivo tumour work reported in the abstract [PMID:31367043]; the 2009 paper used CD24-deficient mice plus the human Siglec-10 association [PMID:19264983].","localisation_and_range":"CD24 is flagged membrane-bound, so signalling is likely contact-dependent (juxtacrine) [flag]. SIGLEC10 is flagged both secreted and transmembrane [flag].","caveats":"The 2009 paper was read as abstract only and states association 'at least in part' through Siglec-10, without a binding measurement [PMID:19264983]. The 2019 paper's key results come from the abstract; full-text excerpts support desialylation sensitivity [PMID:31367043]. No affinity reported.","key_references":[{"PMID":"31367043","why":"Tumour CD24-Siglec-10 as a macrophage 'don't eat me' checkpoint; ablation and blockade assays"},{"PMID":"19264983","why":"CD24 association with Siglec-10/Siglec-G dampens danger signalling"}],"covers":["LR002284"]},"LR005083":{"pair":"CD28 -> CD86","headline":"Human CD86 binds CD28 with avidity similar (within about 2- to 3-fold) to CD80; one abstract-only paper plus databases.","interaction_type":"direct binding","direction_and_effect":"CD86 binds the same receptors (CD28 and CTLA-4) as CD80 and keeps similar overall receptor binding and T-cell costimulatory properties [PMID:7534620]. UniProt: CD28 engagement by CD80 or CD86 increases T-cell proliferation and cytokine production [DB:UniProt].","molecular_requirements":"Not reported in our evidence; Reactome lists CD28 homodimer binding B7-2 monomer [DB:Reactome].","affinity_potency":[],"species_and_systems":"Human proteins [PMID:7534620]; mouse pair projected from human evidence.","localisation_and_range":"Both partners are flagged membrane-bound, non-secreted [flag]; contact-dependent signalling.","caveats":"Abstract only; the paper's main quantitative contrast concerns CTLA-4 (CD80 binds much better than CD86), not CD28. No affinity values for CD28 reported in our evidence. Databases include IntAct SPR and FACS records.","key_references":[{"PMID":"7534620","why":"Compares CD86 and CD80 binding to CD28 and CTLA-4"}],"covers":["LR001716","LR005083"]},"LR001717":{"pair":"CD34 -> SELE","headline":"Human CD34 on HSPCs is a major vascular selectin ligand; one abstract-only paper.","interaction_type":"direct binding","direction_and_effect":"CD34-positive HSPC fractions bound E- and P-selectin whereas CD34-negative fractions did not, and a proteomics screen identified CD34 as a major vascular selectin ligand; knockdown implicates it in the first step of cell migration [PMID:29296932].","molecular_requirements":"Not reported in our evidence; the paper notes glycoforms of CD34 may matter [PMID:29296932].","affinity_potency":[],"species_and_systems":"Human hematopoietic stem/progenitor cells from human tissue [PMID:29296932]; mouse pair projected.","localisation_and_range":"CD34 is flagged transmembrane, not secreted; SELE membrane-bound [flag]; interaction is cell-cell adhesion on vascular beds.","caveats":"Abstract only; the paper reports selectins jointly (E- and P-selectin) and E-selectin-specific data are not separated in the abstract. No affinity reported. Title also implicates CD44.","key_references":[{"PMID":"29296932","why":"CD34 on human HSPCs as vascular selectin ligand"}],"covers":["LR001717","LR005084"]},"LR000286":{"pair":"CD40LG -> ITGB2","headline":"CD40L binding to the beta2 integrin Mac-1 rests on one abstract-level binding paper; ITGB2 is a chain of that heterodimer.","interaction_type":"direct binding","direction_and_effect":"Flow cytometry, radioactive binding assays and immunoprecipitation showed CD40L interacting with Mac-1, with Mac-1-dependent adhesion, migration and myeloperoxidase release in vitro; CD40-deficient mice were not protected from atherosclerosis, and Mac-1 inhibition reduced lesions [PMID:17372166].","molecular_requirements":"The evidence is for the Mac-1 (alphaM:beta2) heterodimer, not ITGB2 alone [PMID:17372166].","affinity_potency":[],"species_and_systems":"Curators record human for both partners; the abstract also uses mouse models [PMID:17372166]. The mouse pair is ortholog-inferred.","localisation_and_range":"Ligand carries secreted and transmembrane flags [flag].","caveats":"One abstract-only paper shown; a second confirmed paper is not displayed, two abstracts were insufficient and one is pending. No affinity reported.","key_references":[{"PMID":"17372166","why":"CD40L-Mac-1 binding and CD40-independent inflammation"}],"covers":["LR000286","LR003796"]},"LR002293":{"pair":"CD47 -> THBS1","headline":"CD47 and thrombospondin-1 signal in human red cells, but the pair lists them in reversed roles; evidence is functional.","interaction_type":"functional only","direction_and_effect":"Per the abstract, TSP-1 signals through its cognate receptor CD47; recombinant human TSP-1 raised red blood cell Ca2+ and an amiloride-sensitive inward current, promoted microparticle shedding and cell death, and an anti-CD47 antibody (1F7) recapitulated the death-inducing effects [PMID:32948210]. UniProt calls THBS1 a ligand for CD47 and CD47 a THBS1 receptor [DB:UniProt].","molecular_requirements":"Not reported in our evidence beyond a CD47 receptor role for TSP-1 [PMID:32948210].","affinity_potency":[],"species_and_systems":"Human red blood cells and recombinant human TSP-1; CD47 ligation with a mouse IgG1 antibody [PMID:32948210]. Mouse pair is ortholog-inferred.","localisation_and_range":"THBS1 carries a secreted flag and CD47 transmembrane and receptor flags [flag], matching a secreted TSP-1 acting on membrane CD47 [DB:UniProt].","caveats":"Paper is abstract-only (with excerpts) and shows function, not a binding assay. Direction in the pair is the reverse of the biology described [PMID:32948210].","key_references":[{"PMID":"32948210","why":"TSP-1/CD47 signalling in human red blood cells"}],"covers":["LR002293","LR005592"]},"LR001726":{"pair":"CD59 -> CD2","headline":"Second CD2 ligand reported in two 1992 papers; no database records.","interaction_type":"direct binding","direction_and_effect":"CD59 was identified as a second physiological ligand for CD2: CD2+ cells bind immobilised CD59, and anti-CD59 antibodies inhibit CD2-dependent T cell activation in murine hybridomas expressing human CD2 [PMID:1377404]. CD59-CHO cells rosette with human T cells, inhibited by CD59 and CD2 mAbs [PMID:1385156].","molecular_requirements":"CD2 binding sites for CD58 and CD59 overlap but are nonidentical [PMID:1377404]. Two other CD59 mAbs that recognise a different epitope increased rosetting by 50%-70% [PMID:1385156].","affinity_potency":[],"species_and_systems":"Human CD59 and CD2, transfected CHO cells, human T cells and murine thymoma cells expressing human CD2 [PMID:1385156][PMID:1377404].","localisation_and_range":"CD59 is membrane-associated; rosetting indicates cell-contact binding; flag lists the ligand as secreted [flag].","caveats":"Both papers are abstract-only and from the same year; no affinity; no database records for the pair. 125I-CD59 binding to CD2+CHO cells was inhibited by unlabeled CD59 and CD2 mAb [PMID:1385156].","key_references":[{"PMID":"1377404","why":"CD59 identified as CD2 ligand, binding assay"},{"PMID":"1385156","why":"Rosette and radiolabeled CD59 binding to CD2"}],"covers":["LR001726"]},"LR005092":{"pair":"CD6 -> ALCAM","headline":"Established heterophilic CD6-CD166 binding backed by structures, SPR mutagenesis and database records.","interaction_type":"direct binding","direction_and_effect":"CD6 membrane-proximal domain binds the N-terminal IgSF domain of CD166 (ALCAM); the interaction regulates T-cell activation [PMID:26146185]. Heterodimers form at the expense of CD6 and CD166 homodimers [PMID:26146185].","molecular_requirements":"CD6 domain 3 carries the CD166 binding face; domains 1 and 2 made no detectable difference to CD166 binding by SPR [PMID:26146185]. CD166 domain 1 is the binding site [PMID:26146185].","affinity_potency":[],"species_and_systems":"Human recombinant proteins, crystal structures and SPR; human CD166 reported to bind human, mouse and rat CD6 with the same affinity (data not shown) [PMID:26146185]. Mouse pair is ortholog-inferred.","localisation_and_range":"Both transmembrane by flags (also flagged secreted) [flag]; cell-cell contact interaction.","caveats":"The CD6 SNP S351N adds glycosylation and weakens CD166 binding 10-fold [PMID:26146185]. No Kd is given in the shown text. Only one of two confirmed papers is displayed. Database support: BioGRID, IntAct, UniProt [DB:BioGRID][DB:IntAct][DB:UniProt].","key_references":[{"PMID":"26146185","why":"Crystal structures, binding site mapping, homophilic competition"}],"covers":["LR001727","LR005092"]},"LR001735":{"pair":"CD96 -> PVR","headline":"CD96 binds CD155 (PVR) in mouse; human interaction ortholog-inferred, with PDB and Reactome records.","interaction_type":"direct binding","direction_and_effect":"Mouse CD96/CD155 complexes form and are blocked by anti-mCD96 and anti-mCD155 antibodies; T-cell adhesion to mCD155 insect cells is blocked in a T-cell-subtype-dependent manner [PMID:17971293]. Reactome records CD96 binding PVR [DB:Reactome].","molecular_requirements":"Not reported beyond a single chain pair; PDB 6ARQ has a structure with one chain of each partner [DB:PDB 6ARQ].","affinity_potency":[],"species_and_systems":"Mouse thymocytes/T cells and insect cells; the paper states the interaction is preserved between man and mouse [PMID:17971293].","localisation_and_range":"Membrane proteins; adhesion between cells [PMID:17971293].","caveats":"Only one paper, abstract-only; the human pair rests on projection plus databases [DB:IntAct].","key_references":[{"PMID":"17971293","why":"CD96/CD155 adhesion, mouse"}],"covers":["LR001735","LR005100"]},"LR005605":{"pair":"CDH11 -> CDH11","headline":"Cadherin-11 homophilic binding and adhesion in mouse proteins; the human pair is inferred.","interaction_type":"direct binding","direction_and_effect":"Cadherin-11 binds itself: homophilic binding followed heterophilic cadherin-8 binding in SPR, and in co-culture cadherin-11-dendra and cadherin-11-cherry localized equally to homotypic and heterotypic contacts, indicating uniform homophilic interaction [PMID:29742438].","molecular_requirements":"Cadherin-8 and cadherin-11 form a specificity group preferring each other over other cadherins [PMID:29742438].","affinity_potency":[],"species_and_systems":"Type II cadherin binding was measured by SPR and AUC on purified mouse EC1-EC2 fragments, with A431D cell co-culture; the human pair is inferred by orthology [PMID:29742438].","localisation_and_range":"Membrane-bound adhesion molecules, so contact-dependent (juxtacrine); neither partner is flagged secreted [flag].","caveats":"Homophilic binding was weaker than the heterophilic cadherin-8 interaction on the cadherin-11 surface [PMID:29742438]. Human result is ortholog-projected. Reactome lists only catenin association [DB:Reactome]. No affinity reported.","key_references":[{"PMID":"29742438","why":"Homophilic cadherin-11 localization and SPR"}],"covers":["LR002307","LR005605"]},"LR005614":{"pair":"CDH4 -> KLRG1","headline":"KLRG1 binds R-cadherin in one cloning paper read as abstract; brief support.","interaction_type":"direct binding","direction_and_effect":"KLRG1 binds N- and R-cadherins, besides E-cadherin; E-cadherin binding prevented NK-cell lysis of target cells, and KLRG1 is inhibitory [PMID:16461340].","molecular_requirements":"Not reported in our evidence beyond ectodomain tetramer binding.","affinity_potency":[],"species_and_systems":"A mouse KLRG1 tetramer was used on mouse and human cell lines [PMID:16461340]. Mouse pair is the direct one; human pair is ortholog-inferred.","localisation_and_range":"Both membrane proteins [flag]; contact-dependent.","caveats":"The R-cadherin result is stated only in the abstract; excerpts concern cell-line ligand screening, not R-cadherin. The cell-killing result is documented for E-cadherin, not R-cadherin. No affinity reported.","key_references":[{"PMID":"16461340","why":"KLRG1 binds three classical cadherins incl. R-cadherin"}],"covers":["LR002316","LR005614"]},"LR002329":{"pair":"CEACAM5 -> CEACAM1","headline":"Heterophilic CEA-CEACAM1 binding inhibiting NK killing, from one abstract-level paper plus IntAct.","interaction_type":"direct binding","direction_and_effect":"Heterophilic interactions between CEA (CEACAM5) and CEACAM1 inhibit NK killing [PMID:15905509]; inhibitory effect.","molecular_requirements":"The N domains of both proteins are necessary but not sufficient; additional domains are implicated [PMID:15905509].","affinity_potency":[],"species_and_systems":"Human proteins, NK killing assays [PMID:15905509]. IntAct lists protein array and solid phase assays [DB:IntAct].","localisation_and_range":"Not reported in our evidence beyond cell-surface interaction.","caveats":"Abstract only; one review-only row not shown. Direction CEACAM5-to-CEACAM1 is a curation convention; the same evidence supports CEACAM1 -> CEACAM5.","key_references":[{"PMID":"15905509","why":"CEA-CEACAM1 interaction inhibits NK killing"}],"covers":["LR002329"]},"LR005623":{"pair":"CELSR2 -> CELSR2","headline":"Homophilic CELSR2 interaction implied by one neurite-growth paper; no direct binding assay in our evidence.","interaction_type":"functional only","direction_and_effect":"Celsr2 was activated by homophilic interaction and enhanced neurite growth in rat-neuron coculture and silencing assays [PMID:17618280]. Effect direction differs between the two paralogues [PMID:17618280].","molecular_requirements":"Opposite functions of Celsr2 and Celsr3 trace to a single amino acid difference in the transmembrane domain; signalling may involve second messengers [PMID:17618280].","affinity_potency":[],"species_and_systems":"Rat neuron coculture and gene silencing; the curator labels the experiment species as mouse, which conflicts with the rat neurons named in the assay text [PMID:17618280].","localisation_and_range":"Membrane-bound seven-pass cadherin, so homophilic contact (juxtacrine) [flag] [PMID:17618280].","caveats":"Abstract only; no binding measurement or database record. One additional review-only row not shown. Paralog issue: the same paper covers CELSR2 and CELSR3 with opposing effects.","key_references":[{"PMID":"17618280","why":"Celsr2 and Celsr3 homophilic activation with opposing neurite effects"}],"covers":["LR002334","LR005623"]},"LR002338":{"pair":"CFH -> ITGB2","headline":"Factor H binds neutrophil Mac-1 (CD11b/CD18); evidence is for the heterodimer, from one 1998 abstract.","interaction_type":"direct binding","direction_and_effect":"Neutrophil adhesion to factor H was blocked by anti-CD11b and anti-CD18 antibodies, and factor H-Sepharose affinity purification with immunoprecipitation identified Mac-1 as a factor H-binding receptor; classed as agonist [PMID:9558116]. Surface-bound factor H increased neutrophil hydrogen-peroxide generation 2-5-fold [PMID:9558116].","molecular_requirements":"The evidence concerns the Mac-1 heterodimer (CD11b/CD18); the CD18 chain alone is not shown to suffice [PMID:9558116]. Adhesion needed divalent metal ions [PMID:9558116].","affinity_potency":[],"species_and_systems":"Human neutrophils and purified human factor H [PMID:9558116]. Adhesion was neutrophil-specific, not seen with eosinophils.","localisation_and_range":"Secreted factor H acts as an adhesion ligand and may tether tissue through glycosaminoglycans [PMID:9558116].","caveats":"Abstract only; no affinity; the same paper supports both the ITGAM and ITGB2 rows. No database records.","key_references":[{"PMID":"9558116","why":"Factor H as a Mac-1 adhesion ligand on human neutrophils"}],"covers":["LR002338"]},"LR000295":{"pair":"CFH -> SELL","headline":"Factor H binds L-selectin in a calcium-dependent manner in one paper, with a BioGRID record.","interaction_type":"direct binding","direction_and_effect":"Factor H isolated from serum by L-selectin affinity chromatography bound specifically to immobilised L-selectin in the presence of CaCl2; binding was blocked by anti-L-selectin antibodies, fucoidan and LPS [PMID:10377245]. The dossier's annotation lists a stimulatory effect, but the paper's functional effect is not reported in our evidence.","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human serum factor H and immobilised L-selectin [PMID:10377245].","localisation_and_range":"Factor H is flagged secreted; SELL is a transmembrane receptor [flag].","caveats":"Abstract only; no affinity. BioGRID records a reconstituted complex [DB:BioGRID].","key_references":[{"PMID":"10377245","why":"Factor H identified as an L-selectin ligand"}],"covers":["LR000295"]},"LR003805":{"pair":"CGA -> TSHR","headline":"No curated paper supports CGA alone on TSHR; support is database records for the TSH complex.","interaction_type":"database-asserted only","direction_and_effect":"GtoPdb lists an agonist interaction [DB:GtoPdb]. Reactome records TSHR binding TSH/thyrostimulin [DB:Reactome]. Cryo-EM structures of human TSH bound to TSHR with miniGs are in PDB [DB:PDB 7T9I] [DB:PDB 7UTZ].","molecular_requirements":"CGA is the shared alpha chain; the structures contain a chain of CGA and of TSHR [DB:PDB 7T9I]. Beta chain role not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human structures [DB:PDB 7T9I]; mouse pair is ortholog-inferred.","localisation_and_range":"CGA flagged secreted; TSHR transmembrane [flag].","caveats":"No papers shown; outcomes are abstract_insufficient (2) and review_only (1). Support rests on databases alone, and the records concern the TSH heterodimer.","key_references":[],"covers":["LR000298","LR003805"]},"LR011149":{"pair":"CGA:CGB2 -> LHCGR","headline":"Heterodimer CGB2 with CGA on LHCGR is supported only by database records, mostly for CGA; no curated paper.","interaction_type":"database-asserted only","direction_and_effect":"GtoPdb lists CGA-LHCGR as a full agonist; pKd range 9.899999618530273 to 11.800000190734863 [DB:GtoPdb]. Reactome records LH receptor:LH complexes [DB:Reactome]. Cryo-EM structures of chorionic gonadotropin-LHCGR-Gs exist [DB:PDB 7FIG] [DB:PDB 7FII].","molecular_requirements":"Ligand is a CGA:CGB2 heterodimer; the records name CGA and LH or CG, not this specific beta gene; no CGB2 record shown.","affinity_potency":[],"species_and_systems":"Human; species of experiments not reported in our evidence.","localisation_and_range":"Secreted ligand, transmembrane receptor [flag].","caveats":"Two pending rows, no curated paper. Database records are not specific to CGB2. BioGRID lists LHCGR-CGA affinity capture-western [DB:BioGRID].","key_references":[],"covers":["LR011149"]},"LR007180":{"pair":"CGA:TSHB -> TSHR","headline":"TSH (CGA:TSHB) on TSHR rests on databases and cryo-EM structures; no confirmed paper.","interaction_type":"database-asserted only","direction_and_effect":"GtoPdb lists CGA-TSHR and TSHB-TSHR as agonists [DB:GtoPdb]. UniProt describes TSHR as receptor for thyrotropin [DB:UniProt]. Native human TSH bound to TSHR with miniGs is a cryo-EM structure [DB:PDB 7T9I].","molecular_requirements":"Heterodimer ligand; structures have a CGA chain and a TSHR chain [DB:PDB 7T9I].","affinity_potency":[],"species_and_systems":"Human structures [DB:PDB 7T9I]; affinity not reported.","localisation_and_range":"Secreted heterodimer, transmembrane receptor [flag].","caveats":"No papers shown; one row judged different_entity. Support rests on databases alone.","key_references":[],"covers":["LR007180"]},"LR001744":{"pair":"CIRBP -> TREM1","headline":"Extracellular CIRP binds TREM-1 by SPR and FRET and drives inflammation; two abstract-level papers.","interaction_type":"direct binding","direction_and_effect":"eCIRP is a new biologically active ligand of TREM-1, fueling inflammation in sepsis; knockdown, the decoy peptide LP17 or TREM-1-/- mice reduced eCIRP-induced inflammation [PMID:32027618]. A 7-aa eCIRP-derived peptide, M3, blocked the TREM-1 and eCIRP interaction [PMID:32027618]. The eCIRP-TREM-1 axis was reported to promote ICAM-1-Rho-mediated NETosis in sepsis (title only; abstract truncated) [PMID:32506691].","molecular_requirements":"Not reported in our evidence beyond TREM-1 itself.","affinity_potency":[],"species_and_systems":"SPR, FRET in macrophages, siRNA and TREM-1-/- mice (mouse in vivo) [PMID:32027618]; CIRP peptide derived from human eCIRP.","localisation_and_range":"eCIRP is the extracellular form, flagged secreted [flag].","caveats":"SPR showed a 'strong binding affinity' but no value is reported in our evidence. PMID 32506691 is a functional paper with a truncated abstract. Both read as abstracts.","key_references":[{"PMID":"32027618","why":"SPR and FRET binding of eCIRP to TREM-1; blocking peptide"},{"PMID":"32506691","why":"eCIRP-TREM-1 axis and NETosis (functional)"}],"covers":["LR001744","LR005104"]},"LR002347":{"pair":"CLC -> CNTFR","headline":"CLC acts on CNTFR as part of the CLF/CLC heterodimer; evidence is functional (one abstract) plus structure and database records.","interaction_type":"functional only","direction_and_effect":"The stable secreted CLF/CLC complex acted only on cells expressing functional CNTF receptors, activated gp130, LIFR and STAT3 and supported motor neuron survival [PMID:10966616]. UniProt describes CLC as a cytokine working alone or in a stable complex with CRLF1 or CNTFR [DB:UniProt].","molecular_requirements":"The functional ligand in the paper is the CLF/CLC heterodimer; CLF expression is required for CLC secretion and neither component acts alone, per curator notes [PMID:10966616]. Signalling uses gp130 and LIFR [PMID:10966616].","affinity_potency":[],"species_and_systems":"Human proteins; the paper's system is not detailed beyond the abstract [PMID:10966616].","localisation_and_range":"CLC is flagged secreted [flag].","caveats":"Paper read as abstract only. A PDB structure with chains of both proteins [DB:PDB 8D7R] and an IntAct molecular sieving record [DB:IntAct] support association, but no affinity is reported in our evidence.","key_references":[{"PMID":"10966616","why":"Identifies CLF/CLC complex acting on CNTF receptor-expressing cells"}],"covers":["LR002347"]},"LR011338":{"pair":"CLCF1 -> CNTFR:IL6ST:LIFR","headline":"CLCF1 signals through the CNTFR:IL6ST:LIFR complex; two recent abstract-level papers support it functionally, plus database records.","interaction_type":"functional only","direction_and_effect":"CNTFR blockade with an engineered soluble CNTFR (decoy) neutralised CLCF1 and suppressed STAT3 signalling and TGF-beta production in hepatocellular carcinoma models [PMID:42102942]. In cervical squamous cell carcinoma, CLCF1 induced ZIC5 via STAT3 and a CNTFR-neutralising antibody disrupted the loop [PMID:42503245]. GtoPdb lists agonist actions for CLCF1 at CNTFR, IL6ST and LIFR [DB:GtoPdb].","molecular_requirements":"CNTFR is the named chain in both papers; IL6ST and LIFR were not individually tested [PMID:42102942][PMID:42503245]. A cryo-EM structure of the CLCF1 signalling complex is listed [DB:PDB 8D7R].","affinity_potency":[],"species_and_systems":"Human; cancer cells, xenografts and PDX/organoid models [PMID:42102942][PMID:42503245].","localisation_and_range":"CLCF1 is flagged secreted [flag].","caveats":"Both papers read as abstracts only and concern cancer biology, not receptor binding; subunit requirements for IL6ST and LIFR are not shown in these papers.","key_references":[{"PMID":"42102942","why":"Soluble CNTFR decoy blocks CLCF1-CNTFR axis"},{"PMID":"42503245","why":"CLCF1 as CNTFR ligand in a CLCF1-ZIC5-CNTFR loop"}],"covers":["LR011338"]},"LR005632":{"pair":"Clec2i -> Klrb1f","headline":"Mouse Clr-g (Clec2i) stimulates Nkrp1f; functional evidence from two papers, one with the direction reversed.","interaction_type":"functional only","direction_and_effect":"Cell lines transduced with Clrg, but not other Clr molecules, stimulated Nkrp1f reporter cells [PMID:12858173]. A second paper reports OCILRP2/Clr-g and NKRP1f costimulate T cell proliferation and IL-2 production [PMID:15963483].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Mouse; reporter cells (Results sentence read in a browser, not verified) [PMID:12858173]; T cells and antigen presenting cells [PMID:15963483].","localisation_and_range":"Ligand not annotated as secreted; membrane-bound Clr-g presented on transduced cells or APC (inferred from cell-based assays, not stated directly).","caveats":"One paper's quote is a browser-read, unverifiable sentence pending spot-check [PMID:12858173]. The other is abstract-only and describes Clr-g as the T-cell receptor and NKRP1f as the DC-expressed ligand, the reverse of this pair's direction [PMID:15963483]. No binding affinity reported.","key_references":[{"PMID":"12858173","why":"Clrg transductants stimulate Nkrp1f reporter cells"},{"PMID":"15963483","why":"Clr-g/NKRP1f costimulate T cell proliferation and IL-2"}],"covers":["LR005632"]},"LR002356":{"pair":"CLSTN3 -> NRXN3","headline":"Calsyntenin-3 binds \u03b2-neurexins as a synaptic adhesion pair; isoform-specific evidence for NRXN3 is not shown (abstract only).","interaction_type":"direct binding","direction_and_effect":"Clstn3 is a postsynaptic adhesion molecule that induces presynaptic differentiation via presynaptic neurexins; \u03b2-Nrxns directly interact via their LNS domain with Clstn3 and Clstn3 cadherin domains [PMID:32434929].","molecular_requirements":"Splice site 4 (SS4) insert-positive \u03b2-Nrxn variants, but not insert-negative variants, reversed the impaired Clstn3 synaptogenic activity; Clstn3 selectively formed complexes with SS4-positive Nrxns in vivo [PMID:32434929].","affinity_potency":[],"species_and_systems":"Species not specified in the dossier; hippocampal neurons and Clstn3 conditional knockout mice (mouse pair is the non-inferred one) [PMID:32434929]. Human pair is ortholog-inferred.","localisation_and_range":"Both partners transmembrane/adhesion proteins (not flagged secreted [flag]); trans-synaptic, contact-dependent [PMID:32434929].","caveats":"Abstract only. The evidence sentence names \u03b2-Nrxns collectively, not NRXN3 specifically; the paper title mentions both \u03b1- and \u03b2-neurexins but gene-level assignment is not shown. Earlier debate on whether Nrxns bind Clstn3 directly is noted [PMID:32434929].","key_references":[{"PMID":"32434929","why":"\u03b2-neurexin LNS domain binds Clstn3; SS4-dependent synaptogenic activity"}],"covers":["LR002356","LR005636"]},"LR005641":{"pair":"CLU -> VLDLR","headline":"Clusterin binds VLDLR and triggers a Reelin-like signal; one abstract-only paper, no affinity.","interaction_type":"direct binding","direction_and_effect":"Clusterin binds ApoER2 (LRP8) and VLDLR and is internalized by cells expressing either; binding triggers a Reelin-like signal in Dab1-expressing cells, inducing Dab1 phosphorylation and activation of PI3K/Akt and n-cofilin [PMID:24381170]. Agonist-like.","molecular_requirements":"Dab1 is needed for the signal in the described cells; either receptor alone was sufficient for internalization [PMID:24381170].","affinity_potency":[],"species_and_systems":"Species not specified in the dossier abstract; cell lines and subventricular zone explants [PMID:24381170]. Human and mouse pairs are both ortholog-inferred.","localisation_and_range":"Clusterin is flagged secreted [flag]; present in the subventricular zone where Reelin is absent [PMID:24381170], so paracrine.","caveats":"Abstract only; affinity not reported. UniProt records the interaction citing the same paper [DB:UniProt P10909]. Because both pairs rely on one paper, they are not independent.","key_references":[{"PMID":"24381170","why":"Clusterin binds ApoER2/VLDLR and activates the Reelin pathway"}],"covers":["LR002361","LR005641"]},"LR003814":{"pair":"CNTF -> LIFR","headline":"CNTF signals via LIFR as one beta chain of a CNTFR/gp130/LIFR complex; functional evidence plus database records.","interaction_type":"functional only","direction_and_effect":"CNTF acts as an agonist; GtoPdb lists Agonist [DB:GtoPdb]. In cells, CNTF signalling was abolished by a LIFR mutant lacking the N-terminal cytokine binding domain, while LIF and OSM signalling was not [PMID:16051226].","molecular_requirements":"CNTF signals through a receptor complex of CNTFR with gp130 (IL6ST) and LIFR [PMID:10966616][PMID:16051226]. The LIFR N-terminal cytokine binding domain is required for CNTF but not LIF or OSM signalling [PMID:16051226]. UniProt says ligand binding to CNTFR induces dimerization of gp130 and LIFR [DB:UniProt]. A PDB structure has chains of CNTFR and LIFR [DB:PDB 8D74]; IntAct records electron microscopy and molecular sieving [DB:IntAct].","affinity_potency":[],"species_and_systems":"Human proteins, overexpressing cells and receptor reconstitution [PMID:16051226][PMID:10966616]. Mouse pair is projected from human evidence.","localisation_and_range":"CNTF is flagged secreted [flag].","caveats":"Both confirmed papers are abstract-only. LIFR engagement requires CNTFR and gp130; direct CNTF-LIFR binding alone is not shown in our evidence.","key_references":[{"PMID":"16051226","why":"LIFR N-terminal domain needed for CNTF signalling"},{"PMID":"10966616","why":"CNTFR complex with gp130 and LIFR"}],"covers":["LR000308","LR003814"]},"LR009034":{"pair":"CNTN1 -> CNTN2","headline":"Fc-chimera binding reports contactin-1 (F3) interacting with TAG-1 (CNTN2), but a later reading of the same paper shows it depends on TAG-1 presentation.","interaction_type":"direct binding","direction_and_effect":"Fc-chimera binding experiments found TAG-1 interacts with L1, NrCAM and F3/contactin [PMID:12139915]. Effect direction is not reported in our evidence.","molecular_requirements":"Interaction depends on form: the membrane-associated TAG-1 behaved differently from the soluble form [PMID:12139915]. Soluble F3-Fc bound CHO cells expressing GPI-anchored TAG-1 [PMID:12139915].","affinity_potency":[],"species_and_systems":"Human proteins as recombinant Fc chimeras and transfected CHO cells [PMID:12139915]. BioGRID lists a reconstituted complex [DB:BioGRID].","localisation_and_range":"Contactin-1 is annotated transmembrane and CNTN2 secreted [flag], but the paper treats both as GPI-anchored adhesion molecules, so contact-mediated binding is expected [PMID:12139915].","caveats":"Single paper; the abstract was the curated sentence. Bead assays with soluble proteins did not show F3-TAG-1 aggregation (see CNTN2 -> CNTN1 evidence), so binding appears conditional on membrane presentation [PMID:12139915]. Class is receptor-receptor, so direction is arbitrary.","key_references":[{"PMID":"12139915","why":"Fc-chimera binding between TAG-1 and F3/contactin"}],"covers":["LR009034"]},"LR001753":{"pair":"CNTN1 -> NOTCH2","headline":"Functional evidence that Notch2 relays a CNTN1 signal, plus a generic Notch ligand paper; no direct binding measurement.","interaction_type":"functional only","direction_and_effect":"F3/contactin acts as a functional ligand of Notch in oligodendrocyte cells [PMID:14567914]. In airway epithelial exosomes, siRNA and gamma-secretase inhibition characterised Notch2 as necessary for relaying the CNTN1 signal to dendritic cells [PMID:33957164].","molecular_requirements":"Notch2 is necessary for the CNTN1 signal [PMID:33957164]; gamma-secretase-dependent pathway is implicated [PMID:33957164]. Reactome lists a CNTN1:NOTCH2 complex [DB:Reactome].","affinity_potency":[],"species_and_systems":"OLN-93 cells with unspecified species [PMID:14567914]; airway epithelial exosomes and dendritic cells in an asthma setting [PMID:33957164]. Both species are ortholog-inferred.","localisation_and_range":"CNTN1 delivered via exosomes in the asthma study [PMID:33957164]; flagged transmembrane [flag].","caveats":"Both papers abstract-only. 14567914 refers to Notch generally, not NOTCH2 specifically. No binding data; BioGRID affinity capture-Western rests on 14567914 [DB:BioGRID].","key_references":[{"PMID":"33957164","why":"Notch2 necessary for CNTN1 exosome signal"},{"PMID":"14567914","why":"F3/contactin as Notch ligand"}],"covers":["LR001753","LR005111"]},"LR002365":{"pair":"CNTN1 -> PTPRB","headline":"Contactin binds the carbonic anhydrase domain of RPTPbeta; abstract-level evidence from two BioGRID-recorded papers.","interaction_type":"direct binding","direction_and_effect":"A recombinant Fc fusion with the C domain of RPTPbeta binds contactin and supports neuronal adhesion and neurite growth; contactin and Nr-CAM formed a complex that bound betaCFS [PMID:9049255]. Antibodies to Nr-CAM and contactin inhibited betaCFS-induced neurite outgrowth [PMID:9049255].","molecular_requirements":"The carbonic anhydrase (C) domain of RPTPbeta is the contactin-binding region [PMID:9049255]. Contactin acts together with Nr-CAM in the complex [PMID:9049255].","affinity_potency":[],"species_and_systems":"Neurons and recombinant Fc fusions; species not specified [PMID:9049255]. BioGRID lists reconstituted complexes [DB:BioGRID].","localisation_and_range":"RPTPbeta exists as soluble and receptor forms sharing extracellular regions [PMID:9049255]; contactin is GPI-anchored by annotation [flag].","caveats":"Abstract-only; the complex included Nr-CAM, so binding to contactin alone is based on the earlier C-domain result cited as previous work. The second BioGRID paper (7628014) is not among the judged rows shown.","key_references":[{"PMID":"9049255","why":"Contactin/Nr-CAM complex binds RPTPbeta betaCFS"}],"covers":["LR002365","LR005645"]},"LR005650":{"pair":"CNTN4 -> APP","headline":"CNTN4 and APP act in one genetic pathway in mouse retinal axon targeting, with co-immunoprecipitation from brain; direct binding not shown here.","interaction_type":"functional only","direction_and_effect":"Loss of CNTN4 or APP reduces targeting of direction-selective retinal ganglion cell axons to the nucleus of the optic tract; ectopic CNTN4 biases axons to the NOT and this requires APP [PMID:25959733]. Curator labels the effect agonist.","molecular_requirements":"APP was needed for CNTN4-induced targeting: only 3/21 CNTN4-electroporated RGCs arborized in the NOT of APP mutants [PMID:25959733]. Double mutants matched single mutants, consistent with one pathway [PMID:25959733].","affinity_potency":[],"species_and_systems":"Mice in vivo (knockouts, electroporation) and P8 whole-brain lysate; curator species labels say human, but the paper's work was in mice [PMID:25959733].","localisation_and_range":"CNTN4 is annotated secreted and APP secreted and transmembrane [flag]; both are expressed by NOT-projecting RGC axons [PMID:25959733].","caveats":"CNTN4 was pulled down with APP from wild-type but not CNTN4-mutant lysates; the authors state this does not rule out other partners [PMID:25959733]. Direct binding is not shown in this paper; earlier chick binding work is cited only as background.","key_references":[{"PMID":"25959733","why":"Genetic and co-IP evidence for CNTN4-APP in axon targeting"}],"covers":["LR002370","LR005650"]},"LR002374":{"pair":"COL10A1 -> ITGB1","headline":"One abstract-level report of direct COL10A1-ITGB1 interaction driving PI3K/AKT signalling in triple-negative breast cancer.","interaction_type":"direct binding","direction_and_effect":"COL10A1 directly interacted with ITGB1 and activated PI3K/AKT signalling, promoting TNBC growth and metastasis; this was reversed by knocking down COL10A1 or ITGB1 [PMID:38866293]. Effect labelled agonist.","molecular_requirements":"ITGB1 alone is named in this paper; the alpha partner is not reported in our evidence [PMID:38866293].","affinity_potency":[],"species_and_systems":"Human TNBC cells in vitro and in vivo tumour and metastasis models under chronic unpredictable mild stress; the abstract does not give the host species for the in vivo work [PMID:38866293].","localisation_and_range":"COL10A1 is annotated secreted and not transmembrane [flag], consistent with a matrix ligand.","caveats":"Abstract-only; the method used to show direct interaction is not stated in our evidence. The context is a cancer model rather than normal physiology [PMID:38866293].","key_references":[{"PMID":"38866293","why":"COL10A1-ITGB1 interaction activating PI3K/AKT in TNBC"}],"covers":["LR002374"]},"LR003823":{"pair":"COL18A1 -> GPC1","headline":"Endostatin (collagen XVIII fragment) binds glypicans as a low-affinity, heparan sulfate-dependent receptor in one full-text paper.","interaction_type":"direct binding","direction_and_effect":"Alkaline phosphatase-tagged endostatin bound glypican-1 and glypican-4 overexpressed in NIH 3T3 cells; glypicans were identified as lower-affinity endostatin receptors, with antisense data suggesting they mediate endostatin activity [PMID:11336704]. The authors propose glypican acts as a presenting co-receptor passing endostatin to a high-affinity receptor [PMID:11336704]. Curator records agonist.","molecular_requirements":"Heparan sulfate chains are critical for binding; heparinase or salt treatment reduced binding, and GPI-linkage matters (PI-PLC reduces binding) [PMID:11336704]. The ligand acting is endostatin, the collagen XVIII fragment, not intact COL18A1 [PMID:11336704].","affinity_potency":[{"value":"Kd 200 pM","assay":"Scatchard analysis of AP-endostatin binding (lower-affinity site)","system":"cow pulmonary arterial endothelial (CPAE) cells","cite":"PMID:11336704"}],"species_and_systems":"Human and mouse endostatin tested; curator records human ligand and human GPC4 sequence. Binding quantified in cow endothelial cells and NIH 3T3 overexpressing cells; human and mouse pair rows partly ortholog-projected [PMID:11336704].","localisation_and_range":"Receptor is a GPI-anchored cell-surface proteoglycan [PMID:11336704] (entity flag lists it as secreted [flag]). Ligand is a secreted fragment, so action is paracrine or autocrine.","caveats":"Low affinity and glycan-mediated, so other heparan sulfate proteoglycans may bind similarly. The paper contrasts earlier work showing heparinase-resistant binding in situ [PMID:11336704]. Only one paper.","key_references":[{"PMID":"11336704","why":"Glypicans identified as low-affinity endostatin receptors"}],"covers":["LR000317","LR003823"]},"LR003832":{"pair":"COL1A1 -> ITGA11","headline":"Integrin alpha11beta1 binds collagen type I-Sepharose; one abstract-read cloning paper.","interaction_type":"direct binding","direction_and_effect":"Alpha11beta1 bound collagen type I-Sepharose in affinity binding [PMID:10464311]. Effect: not reported in our evidence.","molecular_requirements":"The binder shown is the alpha11beta1 heterodimer, not alpha11 alone; collagen I is the COL1A1/COL1A2 heterotrimer (curator note) [PMID:10464311].","affinity_potency":[],"species_and_systems":"Human fetal muscle cell integrin; abstract only [PMID:10464311].","localisation_and_range":"Receptor is a membrane integrin; collagen is matrix.","caveats":"Abstract-only read; no affinity; heterodimer evidence applied to a single chain.","key_references":[{"PMID":"10464311","why":"Cloning of alpha11 and binding of alpha11beta1 to collagen I"}],"covers":["LR000326","LR003832"]},"LR008521":{"pair":"COL1A1 -> ITGA2:ITGB1","headline":"Type I collagen is a canonical ligand of the alpha2beta1 heterodimer; evidence is mostly abstract-level adhesion and binding studies.","interaction_type":"direct binding","direction_and_effect":"Alpha2beta1 mediates platelet adhesion to collagen types including I [PMID:2156854] and binds dermal type I collagen in migrating keratinocytes, regulating MMP-1 [PMID:11359786]. Annotated effect is stimulatory.","molecular_requirements":"Both ITGA2 and ITGB1 are members of the complex [flag]. The collagen binding site is localised to the alpha2 I-domain, and a gain-of-function mutation there alters binding [PMID:11856343]. Complex needs both chains.","affinity_potency":[],"species_and_systems":"Human platelets [PMID:2156854]; bovine chondrocyte membranes and human fetal chondrocytes [PMID:7688313]; human integrin I-domain mutants [PMID:11856343]; human keratinocytes [PMID:11359786]. No affinity reported in our evidence.","localisation_and_range":"COL1A1 is flagged secreted and not transmembrane [flag]; type I collagen is an extracellular matrix ligand, so signalling is by cell contact with matrix (inferred from the flag; not stated in the papers read).","caveats":"All four papers were read as abstracts. Whole-collagen assays do not separate COL1A1 from COL1A2. Authors of PMID:7688313 could not visualise alpha2 in human fetal cartilage sections and suggest alpha2beta1 may not be required in intact cartilage. PMID:11359786 also reports pro-MMP-1 binding the integrin. BioGRID co-purification records [DB:BioGRID].","key_references":[{"PMID":"2156854","why":"Platelet adhesion to collagen I via alpha2beta1"},{"PMID":"11856343","why":"alpha2 I-domain as collagen binding site"},{"PMID":"11359786","why":"alpha2beta1 binding to type I collagen in keratinocytes"}],"covers":["LR008521"]},"LR009313":{"pair":"COL1A2 -> ITGAV","headline":"Only evidence is a 1990 neuroblastoma study showing an RGD-dependent integrin binds type I collagen; the COL1A2 chain is not resolved and the beta partner is unusual.","interaction_type":"functional only","direction_and_effect":"An Arg-Gly-Asp-dependent integrin complex from neuroblastoma cells, eluted from GRGDSPK-Sepharose with GRGDSP, bound vitronectin, fibronectin and type I collagen in liposome assays [PMID:1693626]. Direction is collagen to integrin; effect described as binding/adhesion only.","molecular_requirements":"The complex is alphaV associated with a novel beta1-related subunit, according to the curator note, not the classical beta1 or beta3 [PMID:1693626]. ITGAV alone is therefore not shown to be sufficient.","affinity_potency":[],"species_and_systems":"Human SK-N-SH and IMR-32 neuroblastoma cell lines; surface-iodinated extracts and liposomes [PMID:1693626].","localisation_and_range":"Ligand COL1A2 is flagged secreted, not transmembrane [flag]; the receptor acts on the cell surface, so signalling is by contact with the secreted matrix protein (inferred from the flags, not stated by the paper).","caveats":"Abstract plus a title/abstract-level full-text excerpt only. 'Type I collagen' is tested as a whole, so the COL1A2 chain is not separated. The beta subunit was not identified in what we can see, and antibodies to beta 1 and beta 3 each immunoprecipitated different polypeptides [PMID:1693626]. No database records.","key_references":[{"PMID":"1693626","why":"Neuroblastoma RGD-dependent integrin binds type I collagen"}],"covers":["LR009313"]},"LR002392":{"pair":"COL3A1 -> ITGA1","headline":"SPR shows the recombinant alpha1 I domain binds collagen III with similar affinity to collagens I and II; I domain only.","interaction_type":"direct binding","direction_and_effect":"Recombinant alpha1 I domain bound fibrillar collagen types I-III with similar affinities and bound a GROGER peptide from type III collagen [PMID:16043429]. Collagen to integrin.","molecular_requirements":"Only the I domain was tested; beta1 not reported [PMID:16043429].","affinity_potency":[{"value":"KD1 0.15-0.32 uM; KD2 5.5-7.3 uM","assay":"SPR (BIAcore), alpha1 I domain over collagens I-III","system":"recombinant human proteins","cite":"PMID:16043429"}],"species_and_systems":"Recombinant human proteins; mouse pair projected [PMID:16043429].","localisation_and_range":"Matrix ligand [flag]; contact-dependent.","caveats":"Full text read; KDs are across all three collagens, not collagen III alone. A second confirmed paper is counted but not shown.","key_references":[{"PMID":"16043429","why":"SPR alpha1 I domain and collagen III"}],"covers":["LR002392","LR005671"]},"LR003850":{"pair":"COL4A1 -> ITGA1","headline":"Collagen IV (alpha1/alpha2 chains) recognised by alpha1beta1 integrin in a structural study; abstract only.","interaction_type":"direct binding","direction_and_effect":"A collagen IV fragment contains the alpha1beta1 recognition site; modifying Arg and Asp residues abolished binding [PMID:8223488]. Database effect label is stimulatory.","molecular_requirements":"The binding site needs Arg(461) in alpha2(IV) and Asp(461) in alpha1(IV), so both COL4A1 and COL4A2 chains contribute [PMID:8223488]. The receptor is the alpha1beta1 heterodimer, ITGB1 being required as partner [PMID:8223488].","affinity_potency":[],"species_and_systems":"Purified type IV collagen fragments; ligand and receptor species not stated in our evidence [PMID:8223488].","localisation_and_range":"Ligand is flagged secreted, not transmembrane [flag]; as a collagen it is a matrix ligand, but this is not shown by the cited papers.","caveats":"Abstract only; no affinity reported. The ITGA1 record stands for alpha1beta1; COL4A1 alone is not shown to be sufficient.","key_references":[{"PMID":"8223488","why":"Maps alpha1beta1 recognition site on collagen IV"}],"covers":["LR000344","LR003850"]},"LR000358":{"pair":"COL5A1 -> ITGB1","headline":"Collagen V-integrin beta1 supported only through alpha2beta1 in fibroblast disease genetics; abstract only.","interaction_type":"functional only","direction_and_effect":"EDS fibroblasts with COL5A1 mutations show reduced alpha2beta1, its functional receptor [PMID:14970208]; database effect label is stimulatory.","molecular_requirements":"ITGB1 stands for the alpha2beta1 heterodimer [PMID:14970208].","affinity_potency":[],"species_and_systems":"Human dermal fibroblasts [PMID:14970208].","localisation_and_range":"Ligand is flagged secreted, not transmembrane [flag]; as a collagen it is a matrix ligand, but this is not shown by the cited papers.","caveats":"No binding assay; abstract only; one other paper abstract_insufficient.","key_references":[{"PMID":"14970208","why":"Fibroblasts with COL5A1 mutations lose alpha2beta1"}],"covers":["LR000358","LR003864"]},"LR008305":{"pair":"COL8A1 -> DDR1","headline":"No valid support: the only database-linked paper does not test COL8A1 against DDR1; a PDAC abstract mentions DDR1 activation downstream of COL8A1.","interaction_type":"functional only","direction_and_effect":"In PDAC cells, activation of ITGB1 and DDR1 receptors and PI3K/AKT and NF-\u03baB signaling occurred downstream of COL8A1, detected by expression, adhesion and EMSA binding studies [PMID:36375776]. Direct binding is not shown in our evidence.","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human PDAC cell lines; abstract only [PMID:36375776].","localisation_and_range":"Ligand is flagged secreted and not transmembrane [flag]; collagen deposited in matrix is not addressed in our evidence beyond that.","caveats":"A curator reading the full text of PMID:9659900 found no test of COL8A1 against DDR1 (a negative, pair_absent) [PMID:9659900]. The remaining support is a downstream-activation statement, not binding. One review-only row also exists.","key_references":[{"PMID":"36375776","why":"COL8A1 downstream DDR1/ITGB1 activation in PDAC (functional)"}],"covers":["LR008305"]},"LR005704":{"pair":"COL8A1 -> SLC4A11","headline":"Mass spectrometry of an SLC4A11 extracellular-loop pull-down identified COL8A1 and COL8A2 peptides; supports binding but not shown with purified proteins.","interaction_type":"direct binding","direction_and_effect":"A GST fusion of SLC4A11 extracellular loop 3 (EL3) pulled down COL8A1 and COL8A2 peptides as the predominant interacting proteins by mass spectrometry [PMID:31691803]. SLC4A11 promoted cell adhesion to Descemet's membrane components, and an anti-EL3 antibody suppressed adhesion [PMID:31691803]. Here SLC4A11 acts as an adhesion receptor.","molecular_requirements":"EL3 of SLC4A11 is the Descemet's membrane binding site [PMID:31691803].","affinity_potency":[],"species_and_systems":"Transfected HEK293 cells and primary human corneal endothelial cells for adhesion; mouse pair is ortholog-inferred [PMID:31691803].","localisation_and_range":"Ligand flagged secreted [flag]; the receptor binds a basement membrane (Descemet's membrane), so adhesion to matrix rather than soluble signaling [PMID:31691803].","caveats":"Pull-down/mass spectrometry only; no affinity. SLC4A11 is a solute transporter, so its role as signaling receptor is not established in our evidence. Two other papers were abstract-insufficient.","key_references":[{"PMID":"31691803","why":"SLC4A11-EL3 pull-down identifies COL8A1/COL8A2; EL3 mediates adhesion"}],"covers":["LR002425","LR005704"]},"LR002428":{"pair":"COLEC12 -> LAIR1","headline":"Proteomic LAIR1 interactome study identifies COLEC12 as a high-affinity LAIR1 ligand; no affinity value reported.","interaction_type":"direct binding","direction_and_effect":"Proteomic definition of the LAIR1 interactome identified Colec12 as a high-affinity LAIR1 ligand; LAIR1 signaling triggered by Collagen1 and Colec12 highlighted survival, proliferation and differentiation pathways [PMID:34260887]. Lair1-/- mice had reduced Ly6C- monocytes [PMID:34260887].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Mouse (Lair1 knockout, mouse melanoma model) with human clinical association; human pair is the primary species listed, mouse is ortholog-inferred [PMID:34260887].","localisation_and_range":"Ligand is not flagged secreted [flag]; the paper calls Colec12 a stromal factor, and its range (membrane or shed) is not reported in our evidence [PMID:34260887].","caveats":"Abstract only; the numerical affinity is not given in the abstract.","key_references":[{"PMID":"34260887","why":"Colec12 identified as high-affinity LAIR1 ligand"}],"covers":["LR002428","LR005707"]},"LR005713":{"pair":"COMP -> NOTCH1","headline":"COMP N-terminus binds the EGF11-12 region of Notch1 and activates it; one abstract-level paper using co-IP and two-hybrid.","interaction_type":"direct binding","direction_and_effect":"COMP's N-terminus directly interacted with Notch1 EGF11-12 and activated Notch1 signalling (co-immunoprecipitation, mammalian two-hybrid); Notch inhibition attenuated COMP-directed differentiation, and COMP deficiency inhibited Notch activation in mice [PMID:29981303].","molecular_requirements":"Notch1 was the main mediator among Notch receptors tested by silencing; no co-ligand requirement reported in our evidence [PMID:29981303].","affinity_potency":[],"species_and_systems":"Mouse embryonic stem cells differentiating to vascular smooth muscle, and COMP-deficient mice; human pair is ortholog-inferred [PMID:29981303].","localisation_and_range":"COMP carries a secreted flag [flag]; Notch1 is a transmembrane receptor [flag].","caveats":"Single paper read as abstract only; no affinity reported; effect shown in mouse systems.","key_references":[{"PMID":"29981303","why":"COMP N-terminus binds Notch1 EGF11-12 and activates signalling"}],"covers":["LR002434","LR005713"]},"LR000367":{"pair":"CORT -> SSTR1","headline":"Cortistatin binds SSTR1 with high affinity in two recombinant-receptor binding papers, plus GtoPdb.","interaction_type":"direct binding","direction_and_effect":"Human cortistatin-17 bound all human SSTR subtypes much like rat CST-14 and inhibited forskolin-induced cAMP production through SSTRs [PMID:9125122]. [125I]Tyr10-CST bound all five receptors with high affinity and no marked selectivity versus somatostatin [PMID:9650799]. GtoPdb lists a full agonist [DB:GtoPdb].","molecular_requirements":"No co-receptor reported in our evidence.","affinity_potency":[{"value":"pKd 10.02","assay":"[125I]Tyr10-CST radioligand binding","system":"human sst1 stably expressed in CCL39 cells","cite":"PMID:9650799"},{"value":"pKi 9.1-9.6","assay":"GtoPdb full agonist","system":"not reported","cite":"PMID:15333679"}],"species_and_systems":"Human receptors in CCL39 cells [PMID:9650799]; human peptide on human SSTRs [PMID:9125122]; mouse pair ortholog-inferred.","localisation_and_range":"CORT secreted and SSTR1 transmembrane by flags [flag].","caveats":"Abstract-level reads; pan-SSTR binding, so not subtype-specific, and the radioligand is an iodinated CST14 analogue [PMID:9650799]. BioGRID also lists the pair [DB:BioGRID]. Other papers were pending or review-only.","key_references":[{"PMID":"9650799","why":"Binding of cortistatin to all five human SSTRs, pKd values"},{"PMID":"9125122","why":"Human cortistatin binds all SSTR subtypes and lowers cAMP"}],"covers":["LR000367","LR003873"]},"LR004822":{"pair":"CRIPTO -> ACVR2A","headline":"Cripto associates with ActRII (ACVR2A) only as part of an activin ternary complex, where it blocks activin signalling.","interaction_type":"direct binding","direction_and_effect":"Cripto forms a complex with activin and ActRII/IIB and, with ALK4 and ActRII/IIB cotransfected, inhibits activin crosslinking to ALK4 and blocks ALK4-ActRII/IIB association, blocking activin signalling in HepG2 and 293T cells [PMID:12682303]. The effect is antagonism of activin.","molecular_requirements":"Activin binding to Cripto was undetectable without ActRII/IIB, so a type II receptor is required, unlike Nodal [PMID:12682303].","affinity_potency":[],"species_and_systems":"Human cell lines (HepG2, 293T) [PMID:12682303]. Human pair is inferred from mouse; BioGRID lists a reconstituted complex [DB:BioGRID].","localisation_and_range":"CRIPTO is flagged secreted [flag].","caveats":"Read as abstract only. This is not shown as an independent pairwise Cripto-ActRIIA interaction; the ligand-receptor framing is indirect.","key_references":[{"PMID":"12682303","why":"Cripto-activin-ActRII complex that blocks activin signalling"}],"covers":["LR001427","LR004822"]},"LR001429":{"pair":"CRIPTO -> GPC1","headline":"Cripto-1 binds Glypican-1 and signals through c-Src independently of Nodal and ALK4; one abstract-level paper.","interaction_type":"direct binding","direction_and_effect":"CR-1 specifically binds Glypican-1 and activates c-Src, triggering MAPK and Akt signalling [PMID:12649175]. Active Src was required for CR-1-induced transformation and migration of mouse mammary epithelial cells [PMID:12649175].","molecular_requirements":"Signalling is independent of Nodal and ALK4 [PMID:12649175]. Glypican-1 is a membrane-associated heparan sulfate proteoglycan, so it is a co-receptor rather than a signalling receptor on its own.","affinity_potency":[],"species_and_systems":"Mouse mammary epithelial cells with human CR-1 [PMID:12649175]. IntAct lists a co-immunoprecipitation record [DB:IntAct].","localisation_and_range":"CRIPTO is flagged secreted and GPC1 flagged secreted and receptor [flag]; GPC1 is described as membrane-associated [PMID:12649175].","caveats":"Single paper read as abstract only; no affinity reported. The mouse pair is inferred from human.","key_references":[{"PMID":"12649175","why":"CR-1 binds Glypican-1 and activates c-Src"}],"covers":["LR001429","LR004824"]},"LR002437":{"pair":"CRIPTO -> LRP2","headline":"Cripto (TDGF1) binds LRP2 ectodomains in pull-downs; one full-text paper.","interaction_type":"direct binding","direction_and_effect":"LRP2 mini-receptor ectodomains bound TDGF1-AP with efficiency similar to CDON-Fc [PMID:32876567]. The paper is a mouse model in which Cdon interacts genetically with Tdgf1 [PMID:32876567].","molecular_requirements":"The LRP2 ectodomain has four repetitive modules; mini-receptor ectodomains were tested [PMID:32876567]. Which modules bind is not stated in the excerpts.","affinity_potency":[],"species_and_systems":"Pull-down assays in HEK293T cells; the study is a mouse model [PMID:32876567]. Mouse pair is inferred.","localisation_and_range":"CRIPTO is flagged secreted [flag].","caveats":"Single paper; no affinity or functional effect on LRP2 reported in our evidence. The curator note mentions sR3/sR4 modules, but our excerpts do not show this.","key_references":[{"PMID":"32876567","why":"Pull-down shows LRP2 binds TDGF1"}],"covers":["LR002437","LR005716"]},"LR005119":{"pair":"CRLF1 -> CNTFR","headline":"CRLF1 forms a heterodimer with CLCF1 that engages CNTFR; CRLF1 alone is not shown to bind.","interaction_type":"direct binding","direction_and_effect":"CLF (CRLF1) associates with CLC (CLCF1) to form a heteromeric ligand for the CNTF receptor complex [PMID:10966616]. The CRLF1/CLCF1 dimer binds CNTFR [PMID:23355913]. GtoPdb lists an agonist record [DB:GtoPdb]. In hepatic stellate cells ectopic CRLF1 retarded myofibroblast activation [PMID:23355913], so effect there is antagonistic.","molecular_requirements":"CRLF1 requires CLCF1 for CNTFR binding; the receptor complex is CNTFR plus gp130 and LIFR [PMID:10966616, PMID:23355913]. UniProt says CRLF1 engages CNTFR through CLCF1 [DB:UniProt].","affinity_potency":[],"species_and_systems":"Mouse system [PMID:10966616]; human hepatic stellate cells [PMID:23355913]. The mouse pair is inferred.","localisation_and_range":"CRLF1 is flagged secreted [flag].","caveats":"Both papers read as abstracts only. CRLF1 does not bind CNTFR alone per the curator note [PMID:23355913]. Pairwise CRLF1-CNTFR binding is not shown separately from the composite ligand.","key_references":[{"PMID":"10966616","why":"CLF-CLC composite ligand for CNTF receptor complex"},{"PMID":"23355913","why":"CRLF1/CLCF1 dimer binds CNTFR; role in fibrosis"}],"covers":["LR001761","LR005119"]},"LR002446":{"pair":"CRP -> FCGR3B","headline":"CRP binding to Fc\u03b3RIIIb is very weak in a single SPR study.","interaction_type":"direct binding","direction_and_effect":"In SPR, binding to Fc\u03b3RIIIb was 'too weak to quantify', ranking with Fc\u03b1RI below Fc\u03b3RIa/IIa/b/IIIa [PMID:33790888]. No signalling effect through Fc\u03b3RIIIb is reported in our evidence.","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Recombinant human receptors [PMID:33790888].","localisation_and_range":"CRP is flagged as secreted and the receptor as a receptor [flag]; CRP would act as a soluble (paracrine/endocrine) ligand on receptor-bearing cells (inferred from flags only).","caveats":"Binding was too weak to quantify; the pair is thinly supported by one paper and no database [PMID:33790888]. Fc\u03b3RIIIb is described there as prone to shedding on neutrophils [PMID:33790888].","key_references":[{"PMID":"33790888","why":"SPR array including Fc\u03b3RIIIb"}],"covers":["LR002446"]},"LR005722":{"pair":"Crp -> Fcgr4","headline":"Mouse pair projected from human Fc\u03b3R data; the cited paper does not name Fcgr4 itself.","interaction_type":"direct binding","direction_and_effect":"The cited SPR evidence shows CRP binding immobilised recombinant human Fc\u03b3RIa, Fc\u03b3RIIa/b and Fc\u03b3RIIIa [PMID:33790888].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human recombinant proteins only; the mouse pair is ortholog-inferred [PMID:33790888].","localisation_and_range":"CRP is flagged as secreted and the receptor as a receptor [flag]; CRP would act as a soluble (paracrine/endocrine) ligand on receptor-bearing cells (inferred from flags only).","caveats":"Mouse Fcgr4 itself was not tested; support is a projection. Two other judged rows were 'different_entity' [PMID:33790888].","key_references":[{"PMID":"33790888","why":"human SPR array of CRP and Fc\u03b3Rs"}],"covers":["LR005722"]},"LR001762":{"pair":"CRTAM -> CADM1","headline":"Well supported: CRTAM and CADM1 bind directly (SPR, expression cloning, structure); membrane-bound adhesion pair.","interaction_type":"direct binding","direction_and_effect":"CRTAM was identified as a CADM1 ligand by expression cloning; CRTAM+ T cells bound CADM1 (Necl2)-expressing cells, inhibited by CRTAM-Ig, with no clear change in cytotoxicity in that assay [PMID:16091383]. UniProt states that interaction with CADM1 promotes NK cell cytotoxicity and IFNG secretion by CD8+ T cells in vitro and tumour rejection in vivo [DB:UniProt]. Directionality is adhesion-like; both are annotated receptors [flag].","molecular_requirements":"Both single chains; CRTAM is a cell-surface dimer, and the interaction competes with CRTAM and CADM1 homodimerisation [PMID:16091383, DB:UniProt].","affinity_potency":[{"value":"KD 3.3 nM","assay":"SPR imaging, CADM1-Fc analyte on immobilised CRTAM-Fc","system":"recombinant human Fc fusions","cite":"PMID:30131958"}],"species_and_systems":"Human recombinant proteins and cells; a PDB structure of the pair exists [DB:PDB 4H5S]. Mouse pair is ortholog-inferred. IntAct has cosedimentation and solid-phase records [DB:IntAct].","localisation_and_range":"Both partners are annotated as transmembrane, non-secreted [flag]; interaction is membrane-to-membrane (juxtacrine, contact).","caveats":"Both partners are annotated as receptors, so the ligand/receptor direction is arbitrary [flag]. The 2005 paper was read as abstract only [PMID:16091383]. Affinity is from Fc-fusion SPR, not native cells.","key_references":[{"PMID":"30131958","why":"SPRi screen with CRTAM showing the highest affinity to CADM1"},{"PMID":"16091383","why":"expression cloning of CADM1 as CRTAM ligand"}],"covers":["LR001762","LR005120"]},"LR000376":{"pair":"CSF2 -> CSF2RA","headline":"GM-CSF binds its alpha receptor chain with low affinity; well supported, with high affinity needing the beta chain.","interaction_type":"direct binding","direction_and_effect":"The alpha chain binds GM-CSF with low affinity [PMID:10572088]. Human GM-CSF in cells expressing the alpha and beta chains induced differentiation, with the alpha cytoplasmic domain needed [PMID:9211889]. Curators label the effect stimulatory; GtoPdb lists agonist [DB:GtoPdb].","molecular_requirements":"Alpha alone confers low-affinity binding only; the beta chain (betac) gives high affinity when associated with alpha [PMID:8910448]. Cotransfection of KH97 (betac) with the low-affinity receptor made a high-affinity receptor [PMID:1702217].","affinity_potency":[{"value":"Kd approximately 37 pM","assay":"125I-GM-CSF binding, single class of high-affinity receptors on mature myelomonocytic cells","system":"human neutrophils, macrophages and eosinophils","cite":"PMID:2828352"}],"species_and_systems":"Human proteins and cells in most papers; murine NIH-3T3 and FDC-P1-derived WT-19 cells were used as hosts [PMID:8910448] [PMID:9211889]. A mouse pair is ortholog-inferred.","localisation_and_range":"Ligand flagged secreted and non-transmembrane [flag]; receptor is a membrane receptor [flag]; paracrine range is not otherwise reported.","caveats":"All shown papers were read as abstracts only. The Kd is for native high-affinity receptors on cells, so it reflects the receptor complex and not alpha alone [PMID:2828352]. The 54-residue alpha cytoplasmic domain matters for signalling through the beta chain [PMID:8910448].","key_references":[{"PMID":"1702217","why":"Cloning of betac and reconstitution of high affinity"},{"PMID":"10572088","why":"Kinetics: alpha low affinity, beta raises k(on)"},{"PMID":"2828352","why":"Receptor numbers and Kd on human cells"}],"covers":["LR000376","LR003882"]},"LR008233":{"pair":"CTF1 -> IL6ST:LIFR","headline":"CTF1 (CT-1) activates a gp130/LIFR complex; supported by a human neural cell paper and a canine study, abstract-read.","interaction_type":"functional only","direction_and_effect":"CT-1 activates its receptor on a human neural cell line by recruiting gp130 and gp190/LIFR, shown by tyrosine phosphorylation; it induces Jak1-, Jak2-, Tyk2-associated kinases and STAT-3 [PMID:9030543]. CT-1 stimulated canine cardiac fibroblast growth, blocked by gp130 or LIFR blockade [PMID:11834704].","molecular_requirements":"gp130-gp190 heterocomplex formation is essential for CT-1 signalling by neutralizing antibody and COS-7 reconstitution [PMID:9030543]. Cross-linking of iodinated CT-1 revealed a third alpha component of 80 kDa, suggesting a tripartite receptor [PMID:9030543].","affinity_potency":[],"species_and_systems":"Human neural cell line and COS-7 cells [PMID:9030543]; cultured canine cardiac fibroblasts [PMID:11834704].","localisation_and_range":"CTF1 flagged secreted; receptor chains flagged receptor/transmembrane [flag].","caveats":"Both papers read as abstract only. A third, unidentified alpha component is reported, so gp130/LIFR may not be the full receptor [PMID:9030543]. The canine paper treats the receptor as known background [PMID:11834704]. One further paper was review_only.","key_references":[{"PMID":"9030543","why":"CT-1 recruits gp130 and LIFR in human neural cells; third alpha component"},{"PMID":"11834704","why":"Functional blockade in canine cardiac fibroblasts"}],"covers":["LR008233"]},"LR002455":{"pair":"CX3CL1 -> ITGB1","headline":"Integrin beta1 (as alpha4beta1) is a reported direct co-receptor for CX3CL1, from one paper plus UniProt and IntAct records.","interaction_type":"direct binding","direction_and_effect":"FKN-CD directly bound alpha(4)beta(1), and membrane-bound fractalkine also bound it [PMID:23125415]. UniProt says ITGA4:ITGB1 binds fractalkine and may act as its coreceptor in CX3CR1-dependent signalling [DB:UniProt]. IntAct has a pull-down record for the beta1 chain with fractalkine [DB:IntAct].","molecular_requirements":"The paper tested the alpha4beta1 heterodimer, not beta1 alone; beta1 acts with alpha4 [PMID:23125415]. Ternary complex with CX3CR1 was shown for integrins generally [PMID:23125415].","affinity_potency":[],"species_and_systems":"Human ligand and human receptor; recombinant FKN-CD and integrin. Mouse pair ortholog-inferred.","localisation_and_range":"Ligand flagged secreted and transmembrane [flag]; membrane-bound fractalkine also bound the integrins [PMID:23125415].","caveats":"One primary paper, abstract-level read with full-text passages. Full text discusses that earlier studies using beta1 blocking antibodies and a CX3CL1-SEAP fusion did not detect integrin dependence; the authors suggest steric hindrance or antibody limits [PMID:23125415]. No affinity for alpha4beta1 reported in our evidence.","key_references":[{"PMID":"23125415","why":"Direct binding to alpha4beta1"}],"covers":["LR002455","LR005731"]},"LR005731":{"pair":"CX3CL1 -> ITGB1","headline":"Integrin beta1 (as alpha4beta1) is a reported direct co-receptor for CX3CL1, from one paper plus UniProt and IntAct records.","interaction_type":"direct binding","direction_and_effect":"FKN-CD directly bound alpha(4)beta(1), and membrane-bound fractalkine also bound it [PMID:23125415]. UniProt says ITGA4:ITGB1 binds fractalkine and may act as its coreceptor in CX3CR1-dependent signalling [DB:UniProt]. IntAct has a pull-down record for the beta1 chain with fractalkine [DB:IntAct].","molecular_requirements":"The paper tested the alpha4beta1 heterodimer, not beta1 alone; beta1 acts with alpha4 [PMID:23125415]. Ternary complex with CX3CR1 was shown for integrins generally [PMID:23125415].","affinity_potency":[],"species_and_systems":"Human ligand and human receptor; recombinant FKN-CD and integrin. Mouse pair ortholog-inferred.","localisation_and_range":"Ligand flagged secreted and transmembrane [flag]; membrane-bound fractalkine also bound the integrins [PMID:23125415].","caveats":"One primary paper, abstract-level read with full-text passages. Full text discusses that earlier studies using beta1 blocking antibodies and a CX3CL1-SEAP fusion did not detect integrin dependence; the authors suggest steric hindrance or antibody limits [PMID:23125415]. No affinity for alpha4beta1 reported in our evidence.","key_references":[{"PMID":"23125415","why":"Direct binding to alpha4beta1"}],"covers":["LR002455","LR005731"]},"LR000394":{"pair":"CXCL10 -> SDC4","headline":"CXCL10 interacts directly with syndecan-4 through its heparin-binding domain, independent of CXCR3; one abstract-level paper.","interaction_type":"direct binding","direction_and_effect":"A direct CXCL10-syndecan-4 interaction inhibited primary lung fibroblast migration; mutating the heparin-binding domain, not the CXCR3 domain, diminished this effect, and CXCL10 inhibited fibrosis in wild-type but not Sdc4-null mice [PMID:20484822].","molecular_requirements":"The heparin-binding domain of CXCL10 is required; CXCR3 binding is not [PMID:20484822].","affinity_potency":[],"species_and_systems":"Experiments in mouse (bleomycin model, Sdc4-null) and fibroblasts including from fibrosis patients [PMID:20484822]. Human pair is ortholog-inferred.","localisation_and_range":"CXCL10 is flagged secreted [flag]; syndecan-4 is a heparan sulfate proteoglycan [PMID:20484822].","caveats":"Abstract only. SDC4 is more a binding partner/co-receptor than a signalling receptor; no affinity reported.","key_references":[{"PMID":"20484822","why":"CXCL10 antifibrotic action via syndecan-4"}],"covers":["LR000394","LR003900"]},"LR002464":{"pair":"CXCL12 -> ACKR5","headline":"CXCL12 binds GPR182 (ACKR5) with nanomolar affinity in one full-text paper; it acts as a scavenger, not a signalling receptor.","interaction_type":"direct binding","direction_and_effect":"CXCL12 bound GPR182 but did not induce Gq/Gi signalling or beta-arrestin recruitment; the receptor internalised in a ligand-independent manner [PMID:33875597]. Endothelium-specific GPR182-deficient mice had increased plasma CXCL12 [PMID:33875597]. UniProt describes it as a chemokine scavenger [DB:UniProt]. The curator's 'agonist' label is not supported by the paper's text.","molecular_requirements":"Not reported in our evidence beyond a single receptor chain; no co-receptor requirement was tested. RAMP co-expression did not restore chemokine-induced G protein responses in the excerpt [PMID:33875597].","affinity_potency":[{"value":"KD 41 nM","assay":"saturation binding of fluorescent human CXCL12","system":"human GPR182 in HEK293 cells","cite":"PMID:33875597"}],"species_and_systems":"Human CXCL12 on human GPR182 in HEK293 cells; murine chemokines on mouse GPR182 had 'very similar affinities'; knockout mice used for physiology [PMID:33875597].","localisation_and_range":"CXCL12 is flagged secreted [flag]; GPR182 is reported in microvascular and lymphatic endothelium, so the chemokine is likely scavenged from plasma [PMID:33875597].","caveats":"Single primary paper; the curator's record was abstract-level but full text was available. Binding is promiscuous (CXCL10 and CXCL13 also bind) [PMID:33875597]. No conventional signalling, so CCC tools should treat this as a decoy/scavenger.","key_references":[{"PMID":"33875597","why":"Binding KD, no signalling, knockout phenotype"}],"covers":["LR002464"]},"LR003904":{"pair":"CXCL12 -> CD4","headline":"One abstract-only 1999 paper reports SDF-1alpha binding to CD4 on cells and blotted soluble CD4; binding is glycan-dependent and unreplicated.","interaction_type":"direct binding","direction_and_effect":"SDF-1alpha bound CD4 on intact cells and on soluble CD4 electroblotted onto Immobilon; soluble CD4 inhibited the binding, but a truncated sCD4 lacking D3 and D4 did not, so the site differs from the gp120 site [PMID:10600606]. Signalling effect is not reported in our evidence.","molecular_requirements":"Heparin, mannan and heparitinase treatment reduced binding, so glycans and glycosaminoglycans are 'directly or indirectly' involved [PMID:10600606]. CXCR4 was co-expressed in some cells.","affinity_potency":[],"species_and_systems":"Human SDF-1alpha and human cell lines (U937, CEM, HOS-CD4+CXCR4+/-); the mouse pair is projected from human evidence [PMID:10600606].","localisation_and_range":"CXCL12 is flagged secreted [flag]; binding to cell-surface CD4 would be paracrine/contact-proximal, but this is not stated in the paper.","caveats":"Abstract only. Glycan dependence means direct protein-protein binding is not established. CXCR4 is the canonical receptor; the curator flagged CD4 for inferability. No affinity reported.","key_references":[{"PMID":"10600606","why":"Only paper: SDF-1alpha binding to CD4"}],"covers":["LR000399","LR003904"]},"LR001771":{"pair":"CXCL12 -> ITGB3","headline":"One abstract-only 2018 paper: CXCL12 binds integrin allosteric site 2 and activates integrin alphavbeta3 independently of CXCR4.","interaction_type":"direct binding","direction_and_effect":"Integrin activation was shown by direct binding to the allosteric site 2: SDF1 activated soluble integrin alphavbeta3 in cell-free conditions and the site 2 peptide bound SDF1 [PMID:29301984]. SDF1 activated integrin alphavbeta3 on CXCR4-negative CHO cells, suppressed by site 2 peptide and not by AMD3100 [PMID:29301984]. Effect is activating. UniProt agrees [DB:UniProt].","molecular_requirements":"The binding unit appears to be the alpha/beta heterodimer, not ITGB3 alone; the paper tested alphavbeta3, alpha4beta1 and alpha5beta1 [PMID:29301984]. Proteoglycan binding of SDF1 is proposed to facilitate activation. Mutations in SDF1's predicted site 2 binding region suppressed activation.","affinity_potency":[],"species_and_systems":"Cell-free soluble integrin and CHO cells; species labelled human by the curator, not stated in the abstract. The mouse pair is projected from human.","localisation_and_range":"CXCL12 is flagged secreted [flag]; activation was proposed for SDF1 presented on proteoglycans [PMID:29301984].","caveats":"Abstract only; one paper from one group; no affinity reported. Receptor is a heterodimer and CCC tools may score subunits separately.","key_references":[{"PMID":"29301984","why":"Only paper: CXCL12 site 2 integrin activation"}],"covers":["LR001771","LR005128"]},"LR005128":{"pair":"CXCL12 -> ITGB3","headline":"One abstract-only 2018 paper: CXCL12 binds integrin allosteric site 2 and activates integrin alphavbeta3 independently of CXCR4.","interaction_type":"direct binding","direction_and_effect":"Integrin activation was shown by direct binding to the allosteric site 2: SDF1 activated soluble integrin alphavbeta3 in cell-free conditions and the site 2 peptide bound SDF1 [PMID:29301984]. SDF1 activated integrin alphavbeta3 on CXCR4-negative CHO cells, suppressed by site 2 peptide and not by AMD3100 [PMID:29301984]. Effect is activating. UniProt agrees [DB:UniProt].","molecular_requirements":"The binding unit appears to be the alpha/beta heterodimer, not ITGB3 alone; the paper tested alphavbeta3, alpha4beta1 and alpha5beta1 [PMID:29301984]. Proteoglycan binding of SDF1 is proposed to facilitate activation. Mutations in SDF1's predicted site 2 binding region suppressed activation.","affinity_potency":[],"species_and_systems":"Cell-free soluble integrin and CHO cells; species labelled human by the curator, not stated in the abstract. The mouse pair is projected from human.","localisation_and_range":"CXCL12 is flagged secreted [flag]; activation was proposed for SDF1 presented on proteoglycans [PMID:29301984].","caveats":"Abstract only; one paper from one group; no affinity reported. Receptor is a heterodimer and CCC tools may score subunits separately.","key_references":[{"PMID":"29301984","why":"Only paper: CXCL12 site 2 integrin activation"}],"covers":["LR001771","LR005128"]},"LR005740":{"pair":"Cxcl13 -> Gpr182","headline":"Mouse Cxcl13 binds and is scavenged by mouse Gpr182, an atypical receptor; two papers with knockout-mouse support.","interaction_type":"direct binding","direction_and_effect":"Murine CXCL13 bound mouse GPR182 with affinities very similar to the human pair [PMID:33875597]. Binding did not induce typical Gq/Gi signalling or beta-arrestin recruitment; the receptor internalises ligand-independently and scavenges chemokines [PMID:33875597]. GPR182-expressing HEK293 cells reduced mCXCL13 in culture medium, and knockout mice showed higher serum CXCL13 (3.5-fold) [PMID:37554323].","molecular_requirements":"Beta-arrestins are required for ligand-independent internalisation and scavenging; the C-terminus is in part dispensable [PMID:37554323].","affinity_potency":[{"value":"Kd 20 nM","assay":"competition binding, mouse GPR182 with hCXCL13","system":"GPR182-expressing cells (Table 1A)","cite":"PMID:37554323"},{"value":"Kd 13 nM","assay":"competition scavenging, mouse GPR182 with hCXCL13","system":"GPR182-expressing cells (Table 1A)","cite":"PMID:37554323"}],"species_and_systems":"Mouse receptor in cell lines and Gpr182-knockout mice; the Table 1A affinities are for human CXCL13 on mouse GPR182, whereas mCXCL13 was shown in uptake experiments [PMID:37554323]. Mouse chemokine binding to mouse GPR182 is also in [PMID:33875597].","localisation_and_range":"Soluble chemokine cleared from plasma and tissue by endothelial Gpr182 [PMID:33875597]; ligand flagged secreted [flag].","caveats":"Both papers read as abstracts, with full text excerpts. Scavenging, not canonical activation. Exact mCXCL13 affinity values are not given in our excerpts.","key_references":[{"PMID":"33875597","why":"Binding of murine CXCL13 to mouse GPR182 and increased plasma CXCL13 in knockouts"},{"PMID":"37554323","why":"Binding and scavenging Kd values and serum/interstitial CXCL13 elevation in knockouts"}],"covers":["LR005740"]},"LR003913":{"pair":"CXCL5 -> CXCR1","headline":"Weak, CXCR2-preferential agonism at human CXCR1; a mouse CXCR1 study reports no response to CXCL5.","interaction_type":"conflicting","direction_and_effect":"CXCL5 acts as a weak agonist at human CXCR1: three-fold higher concentrations were needed for a calcium response than at CXCR2 [PMID:9692902]. Truncated CXCL5 is more potent through CXCR1 and CXCR2 in neutrophils, monocytes and THP-1 [PMID:33688078].","molecular_requirements":"Not reported beyond N-terminal truncation increasing potency [PMID:33688078].","affinity_potency":[],"species_and_systems":"Human CXCR1-transfected cells [PMID:9692902]; human neutrophils, monocytes and THP-1 cells [PMID:33688078]. Negative result is in the mouse receptor [PMID:17197447]; the mouse pair here is ortholog-inferred.","localisation_and_range":"Ligand is flagged secreted and receptor flagged transmembrane [flag], so paracrine signalling to a cell-surface receptor is implied; paper text does not address range.","caveats":"ENA-78 did not compete for 125I-IL-8 binding to CXCR1 [PMID:9692902]. Murine CXCR1 was not responsive to CXCL5 [PMID:17197447]. GRO-family and ENA-78 competed weakly at IL8RA [PMID:8702798]. All abstract-only.","key_references":[{"PMID":"9692902","why":"Reduced CXCL5 activity at CXCR1 vs CXCR2"},{"PMID":"33688078","why":"Truncated CXCL5 acts through CXCR1 and CXCR2"},{"PMID":"17197447","why":"Mouse CXCR1 does not respond to CXCL5"}],"covers":["LR000413","LR003913"]},"LR000925":{"pair":"CXCL8 -> SDC2","headline":"CXCL8 binds syndecan-2 with Kd 23 nM, partly via heparan sulfate; one quantitative paper.","interaction_type":"direct binding","direction_and_effect":"IL-8 associated specifically with syndecan-2 (not other syndecans) in co-immunoprecipitation from TNF-alpha-stimulated HUVEC lysates [PMID:14527339]. Effect on signalling is not reported in our evidence.","molecular_requirements":"Heparan sulfate matters: the glycosylated syndecan-2 ectodomain bound IL-8 with Kd 23 nM, while the non-glycosylated form still bound with Kd >1 microM, so both glycosaminoglycan and protein contacts contribute [PMID:14527339].","affinity_potency":[{"value":"Kd 23 nM","assay":"isothermal fluorescence titration, purified glycosylated syndecan-2 ectodomain","system":"human, recombinant","cite":"PMID:14527339"},{"value":"Kd >1 microM","assay":"isothermal fluorescence titration, non-glycosylated form","system":"human, recombinant","cite":"PMID:14527339"}],"species_and_systems":"Human HUVECs and purified human proteins [PMID:14527339].","localisation_and_range":"Syndecan-2 is flagged transmembrane, not secreted [flag]; membrane-anchored proteoglycan, so contact-dependent or presentation at the cell surface.","caveats":"Single paper, read as abstract only. No database records. Syndecans are not the signalling receptors for IL-8 in our evidence.","key_references":[{"PMID":"14527339","why":"Kd 23 nM; HS and protein contacts"}],"covers":["LR000925"]},"LR002473":{"pair":"CXCL9 -> ACKR5","headline":"CXCL9 is scavenged by GPR182 (ACKR5) in mouse tumours per indirect in vivo data; no direct binding shown here.","interaction_type":"functional only","direction_and_effect":"GPR182 acts as a chemokine scavenger: GPR182-deficient mice had increased intratumoral CXCL9 and other chemokines, more T-cell infiltration and better antitumour immunity, reversed by CXCR3 blockade [PMID:35013216]. UniProt lists CXCL9 among scavenged chemokines [DB:UniProt]. So effect is decoy/scavenger, not signalling agonism.","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Experiments were in GPR182-knockout mice with transplanted melanomas [PMID:35013216]; the curator row labels the species human, which the excerpts do not support.","localisation_and_range":"Receptor flagged as receptor only; no secretion or transmembrane flag for GPR182 [flag]. Acts on tumour lymphatic endothelium per the curator's notes.","caveats":"Evidence is an in vivo knockout readout (chemokine levels), not binding of CXCL9 to GPR182; the paper's abstract was the main source and CXCL9 is one of several chemokines raised. Support otherwise rests on UniProt.","key_references":[{"PMID":"35013216","why":"GPR182 loss raises tumour chemokines incl. CXCL9"}],"covers":["LR002473"]},"LR011563":{"pair":"CYP27B1 -> VDR","headline":"Not a ligand-receptor pair: CYP27B1 is an enzyme making the VDR ligand; database-only, curators judged the papers different-entity.","interaction_type":"database-asserted only","direction_and_effect":"Not a direct interaction. UniProt describes CYP27B1 as hydroxylating 25-hydroxyvitamin D3 to calcitriol, which acts via the vitamin D receptor [DB:UniProt]. Binding of CYP27B1 protein to VDR is not reported in our evidence.","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"No experiments in our evidence; human per the interaction entry.","localisation_and_range":"Not reported in our evidence.","caveats":"Six papers were judged different_entity and one abstract_insufficient; no confirmed evidence. The link is via the metabolite calcitriol, not the enzyme itself.","key_references":[],"covers":["LR011563"]},"LR003922":{"pair":"DCN -> EGFR","headline":"Decorin binds the EGFR ectodomain directly; reported both as an activator and as an EGFR antagonist, with a measured Kd.","interaction_type":"direct binding","direction_and_effect":"Reports differ: decorin induced EGFR dimerisation, autophosphorylation and MAPK/p21-driven growth suppression [PMID:9988678]; a later paper labels it an antagonist competing in part with EGF [PMID:12105206].","molecular_requirements":"Decorin binds the EGFR L2 ligand-binding domain, requires decorin leucine-rich repeat 6, and His394-Ile402 is essential for both decorin and EGF while K465 is needed for EGF but not decorin [PMID:12105206]. Binding is via the decorin protein core [PMID:9988678].","affinity_potency":[{"value":"Kd~87nM","assay":"radioligand binding","system":"EGFR ectodomain or purified EGFR","cite":"PMID:9988678"}],"species_and_systems":"Human systems: squamous carcinoma cells, cell-free purified EGFR, expression cloning and yeast two-hybrid [PMID:9988678] [PMID:12105206].","localisation_and_range":"Decorin is flagged secreted; EGFR transmembrane receptor [flag]. Paracrine/matrix ligand by annotation.","caveats":"Both papers read as abstracts. Agonist versus antagonist labelling conflicts. BioGRID lists reconstituted complex and two-hybrid records [DB:BioGRID 288891].","key_references":[{"PMID":"9988678","why":"Radioligand binding, Kd~87nM, EGFR activation"},{"PMID":"12105206","why":"Epitope mapping on EGFR"}],"covers":["LR000425","LR003922"]},"LR002482":{"pair":"DEFB103B -> MC1R","headline":"Functional evidence only: human beta-defensin 3 is a weak partial agonist at human MC1R in HEK cells, read from the abstract.","interaction_type":"functional only","direction_and_effect":"Beta-defensin 3 acted as a weak partial agonist for cAMP signalling in HEK cells expressing human MC1R and also activated MAPK signalling in cells with wild-type or variant MC1R [PMID:22364200].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Recombinant human MC1R in HEK cells; human ligand [PMID:22364200].","localisation_and_range":"Ligand is flagged secreted [flag]; no range data in our evidence, so paracrine action is implied by the flag only.","caveats":"Abstract only. High-affinity binding is mentioned as a previous report, not measured here, and is not quantified in our evidence [PMID:22364200]. No direct binding assay in this paper.","key_references":[{"PMID":"22364200","why":"cAMP and MAPK agonism at human MC1R"}],"covers":["LR002482"]},"LR000439":{"pair":"DHH -> PTCH2","headline":"Direct binding reported with PTCH2 (abstract only), with PTCH2 proposed as the Dhh receptor in testis.","interaction_type":"direct binding","direction_and_effect":"PTCH2 binds all hedgehog family members with affinity similar to PTCH and can form a complex with SMO [PMID:9811851]. Because Dhh is expressed in testis and PTCH2 is found at high levels in skin and spermatocytes, the authors state PTCH2 likely mediates its activity in vivo [PMID:9811851]. UniProt states DHH binds PTCH1 or PTCH2 [DB:UniProt].","molecular_requirements":"PTCH2 can form a complex with SMO [PMID:9811851]; further subunit requirements are not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human PTCH2 gene isolated and analysed biochemically; mouse expression patterns also described [PMID:9811851]. Both pairs are ortholog-inferred.","localisation_and_range":"DHH flagged secreted and transmembrane; PTCH2 flagged receptor [flag].","caveats":"One paper, abstract only, no affinity value; the in vivo role is an inference stated as likely. One further row is pending.","key_references":[{"PMID":"9811851","why":"PTCH2 binds all hedgehogs; likely Dhh receptor"}],"covers":["LR000439","LR003931"]},"LR003931":{"pair":"DHH -> PTCH2","headline":"Direct binding reported with PTCH2 (abstract only), with PTCH2 proposed as the Dhh receptor in testis.","interaction_type":"direct binding","direction_and_effect":"PTCH2 binds all hedgehog family members with affinity similar to PTCH and can form a complex with SMO [PMID:9811851]. Because Dhh is expressed in testis and PTCH2 is found at high levels in skin and spermatocytes, the authors state PTCH2 likely mediates its activity in vivo [PMID:9811851]. UniProt states DHH binds PTCH1 or PTCH2 [DB:UniProt].","molecular_requirements":"PTCH2 can form a complex with SMO [PMID:9811851]; further subunit requirements are not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human PTCH2 gene isolated and analysed biochemically; mouse expression patterns also described [PMID:9811851]. Both pairs are ortholog-inferred.","localisation_and_range":"DHH flagged secreted and transmembrane; PTCH2 flagged receptor [flag].","caveats":"One paper, abstract only, no affinity value; the in vivo role is an inference stated as likely. One further row is pending.","key_references":[{"PMID":"9811851","why":"PTCH2 binds all hedgehogs; likely Dhh receptor"}],"covers":["LR000439","LR003931"]},"LR012526":{"pair":"DHH -> SMO","headline":"Functional evidence that full-length soluble Dhh activates Smoothened in endothelial cells; no direct binding reported.","interaction_type":"functional only","direction_and_effect":"Endothelial Dhh acts as full-length soluble form (FL-Dhh) and activates Smoothened in ECs, while N-Shh inhibits it; N-Shh prevents FL-Dhh binding to Ptch1 and acts as a competitive antagonist [PMID:33063110]. UniProt describes DHH acting through patched receptors to relieve SMO inhibition [DB:UniProt].","molecular_requirements":"The effect is on SMO downstream of Ptch1; the paper says all Hh ligands bind Ptch1 [PMID:33063110]. Direct DHH-SMO binding is not reported in our evidence.","affinity_potency":[],"species_and_systems":"Endothelial cells and a brain inflammation setting; species not stated in the abstract [PMID:33063110].","localisation_and_range":"DHH is flagged secreted; the paper identifies the full-length soluble form as the acting one [flag] [PMID:33063110].","caveats":"SMO is indirect in the pathway, so this is a pathway link rather than a ligand-receptor contact. Only one confirmed paper (abstract only); five rows were abstract-insufficient.","key_references":[{"PMID":"33063110","why":"FL-Dhh activates Smoothened in ECs; N-Shh antagonises"}],"covers":["LR012526"]},"LR008107":{"pair":"DKK4 -> KREMEN1:LRP6","headline":"Dkk4 CRD2 binds both LRP6 E1E2 and Kremen1 ectodomain, supporting a ternary complex; one structural paper.","interaction_type":"direct binding","direction_and_effect":"Dkk4 CRD2 binds both the LRP6 E1E2 region and the Krm1 ectodomain with high affinity, supporting a ternary Dkk-Krm-LRP6 complex [PMID:29925589]. Refolded Dkk4 inhibited Wnts that bind LRP6 E1 and E3 (Wnt1, Wnt3a) in reporter cells but appeared less potent than Dkk1 [PMID:29925589].","molecular_requirements":"Both receptor chains are involved: LRP6 E1E2 and Krm1 ECD. The N-terminal region alone bound LRP6 E1E2 only moderately and did not interact with Krm proteins [PMID:29925589]. Whether one ternary complex forms on cells is proposed, not shown, in our evidence.","affinity_potency":[],"species_and_systems":"Human, recombinant domains and cells expressing full-length LRP6 (FACS) [PMID:29925589].","localisation_and_range":"Not reported beyond recombinant ectodomains; Kremen1 and LRP6 flagged transmembrane [flag].","caveats":"Single paper; complex is inferred from separate binding to each partner. No affinity values in our evidence for Dkk4.","key_references":[{"PMID":"29925589","why":"Dkk4 binds LRP6 E1E2 and Krm1 ECD; ternary complex proposed"}],"covers":["LR008107"]},"LR001780":{"pair":"DKK4 -> KREMEN2","headline":"Krm2 co-operates with Dkk4 to inhibit Wnt signalling in one cell assay; functional evidence only.","interaction_type":"functional only","direction_and_effect":"Krm2 co-operates with Dkk4 to inhibit Wnt signalling in human 293 fibroblasts [PMID:12527209]. Direct Dkk4-Krm2 binding is not shown in our evidence.","molecular_requirements":"Interaction of Krm2 with Dkks is mediated by the second cysteine-rich domain [PMID:12527209]; LRP6 context noted in the same assay.","affinity_potency":[],"species_and_systems":"Human 293 fibroblasts; Xenopus embryos for Dkk2 [PMID:12527209]. Human pair; mouse pair ortholog-inferred.","localisation_and_range":"Not reported in our evidence; Kremen2 flagged as a receptor [flag].","caveats":"Read as abstract only. The abstract reports Krm2 binding Dkk1 and Dkk2 with high affinity, not Dkk4. Single paper, no database record.","key_references":[{"PMID":"12527209","why":"Krm2 co-operates with Dkk4, not Dkk3, in Wnt inhibition"}],"covers":["LR001780","LR005136"]},"LR005137":{"pair":"DKK4 -> LRP6","headline":"Dkk4 binds LRP6 E1E2 through CRD2 and inhibits Wnt signalling; one structural paper.","interaction_type":"direct binding","direction_and_effect":"Dkk4 CRD2 mediates high-affinity binding to LRP6 E1E2; refolded Dkk4 and Dkk2 bound cells expressing full-length LRP6 by FACS, and Dkk4 inhibited Wnt1 and Wnt3a reporter activity but appeared less potent than Dkk1 [PMID:29925589]. Curator effect: antagonist.","molecular_requirements":"The N-terminal region with the NXI(R/K) motif alone bound LRP6 E1E2 with only moderate affinity [PMID:29925589]. Kremen proteins can join in Dkk-Krm-LRP5/6 ternary complexes [PMID:29925589].","affinity_potency":[],"species_and_systems":"Human recombinant proteins and cells; human pair not ortholog-inferred, mouse pair ortholog-inferred [PMID:29925589].","localisation_and_range":"LRP6 is a transmembrane receptor [flag]; ligand in solution.","caveats":"One paper; no affinity number in our evidence. Assay labelled structural.","key_references":[{"PMID":"29925589","why":"Dkk4 CRD2 high-affinity binding to LRP6 E1E2"}],"covers":["LR001781","LR005137"]},"LR000448":{"pair":"DLL1 -> NOTCH1","headline":"DLL1 directly binds and activates NOTCH1; well supported by binding and functional papers.","interaction_type":"direct binding","direction_and_effect":"DLL1 directly bound soluble Notch1 in solid-phase assays [PMID:11006133] and activates Notch-1 and its HES-1 reporter in a two-cell coculture [PMID:9819428]. DLL1 is equally effective at activating NOTCH1 and NOTCH2 [PMID:30289388], and in absence of Fringes other ligands than DLL4 activated NOTCH2 similarly or slightly more than NOTCH1 [PMID:32820046]. Effect: agonist.","molecular_requirements":"Binding to soluble Notch is Ca2+-dependent [PMID:11006133]. Only mature processed Notch is proposed at the cell surface; Dl-1 signalling depends on Kuzbanian and RBP-J [PMID:9819428]. Fringe enzymes modulate activity [PMID:32820046]. UniProt notes cis and trans binding [DB:UniProt].","affinity_potency":[],"species_and_systems":"Human proteins in cells/recombinant fusions [PMID:11006133, PMID:32820046]; species not specified in PMID:9819428; chimeric ligand mice in PMID:30289388. BioGRID lists a reconstituted complex [DB:BioGRID].","localisation_and_range":"Membrane-bound ligand acting by cell contact (coculture design) [PMID:9819428]; DLL1 is also flagged secreted [flag].","caveats":"Several papers abstract-only. Pair is one of many tested; no affinity numbers reported in the abstracts. Pending and review-only papers not shown.","key_references":[{"PMID":"11006133","why":"Direct Ca2+-dependent binding of Delta1 to soluble Notch1"},{"PMID":"9819428","why":"Dl-1 activates Notch-1 cascade in coculture"},{"PMID":"30289388","why":"DLL1 equally activates NOTCH1 and NOTCH2"}],"covers":["LR000448","LR003940"]},"LR003940":{"pair":"DLL1 -> NOTCH1","headline":"DLL1 directly binds and activates NOTCH1; well supported by binding and functional papers.","interaction_type":"direct binding","direction_and_effect":"DLL1 directly bound soluble Notch1 in solid-phase assays [PMID:11006133] and activates Notch-1 and its HES-1 reporter in a two-cell coculture [PMID:9819428]. DLL1 is equally effective at activating NOTCH1 and NOTCH2 [PMID:30289388], and in absence of Fringes other ligands than DLL4 activated NOTCH2 similarly or slightly more than NOTCH1 [PMID:32820046]. Effect: agonist.","molecular_requirements":"Binding to soluble Notch is Ca2+-dependent [PMID:11006133]. Only mature processed Notch is proposed at the cell surface; Dl-1 signalling depends on Kuzbanian and RBP-J [PMID:9819428]. Fringe enzymes modulate activity [PMID:32820046]. UniProt notes cis and trans binding [DB:UniProt].","affinity_potency":[],"species_and_systems":"Human proteins in cells/recombinant fusions [PMID:11006133, PMID:32820046]; species not specified in PMID:9819428; chimeric ligand mice in PMID:30289388. BioGRID lists a reconstituted complex [DB:BioGRID].","localisation_and_range":"Membrane-bound ligand acting by cell contact (coculture design) [PMID:9819428]; DLL1 is also flagged secreted [flag].","caveats":"Several papers abstract-only. Pair is one of many tested; no affinity numbers reported in the abstracts. Pending and review-only papers not shown.","key_references":[{"PMID":"11006133","why":"Direct Ca2+-dependent binding of Delta1 to soluble Notch1"},{"PMID":"9819428","why":"Dl-1 activates Notch-1 cascade in coculture"},{"PMID":"30289388","why":"DLL1 equally activates NOTCH1 and NOTCH2"}],"covers":["LR000448","LR003940"]},"LR002491":{"pair":"DMP1 -> CD44","headline":"Weakly supported: one abstract-only paper suggests DMP1 N-terminus interacts with CD44 in a complement-regulation context.","interaction_type":"functional only","direction_and_effect":"Overlapping fragment analysis suggests DMP1 and osteopontin interact with cell-surface CD44 through their amino termini [PMID:11825898]. CD44 serves to tether the SIBLING so that Factor H can be recruited, and complement lysis was blocked via alphaVbeta3 or CD44; output is complement regulation, not CD44 signalling [PMID:11825898].","molecular_requirements":"DMP1 N-terminal region is implicated; the effect requires Factor H and Factor I [PMID:11825898].","affinity_potency":[],"species_and_systems":"Human; described by the paper as SIBLING-expressing cells and FACS binding of Factor H [PMID:11825898].","localisation_and_range":"DMP1 annotated secreted [flag]; acts as a surface-bound anchor in this paper.","caveats":"Abstract only; no direct DMP1-CD44 binding measurement or affinity reported. The Ka of about 1 nm in the abstract refers to DMP1 and Factor H, not CD44.","key_references":[{"PMID":"11825898","why":"Fragment mapping of DMP1 to CD44"}],"covers":["LR002491","LR005759"]},"LR005146":{"pair":"DSC2 -> DSG4","headline":"DSC2 -> DSG4: heterophilic desmosomal cadherin binding, supported by a single family-wide paper.","interaction_type":"direct binding","direction_and_effect":"Heterophilic trans binding between the two desmosomal cadherins: every Dsg passed over a Dsc surface, or vice versa, gave binding responses described as strong heterophilic interaction [PMID:27298358]. No directionality beyond the curator's agonist-style label is reported; the pair is best read as symmetric adhesion between cadherins on adjacent cells.","molecular_requirements":"Ectodomain-only recombinant proteins were used for SPR and bead aggregation [PMID:27298358]; no further subunits or co-receptors reported in our evidence.","affinity_potency":[{"value":"KD 3.6-43.9 uM","assay":"SPR (Biacore T100), range over all pairwise human Dsg/Dsc ectodomain combinations, not specific to this pair","system":"recombinant human ectodomains","cite":"PMID:27298358"}],"species_and_systems":"Experiments used human proteins (solution biophysics, SPR and coated-bead aggregation) [PMID:27298358]. Pair is recorded for: human, mouse (ortholog-projected). The mouse entry is projected from human evidence.","localisation_and_range":"Membrane-bound desmosomal cadherins acting in trans between adjacent cells (juxtacrine/contact) [PMID:27298358]; entity flags mark both as receptors and transmembrane where set [flag].","caveats":"The SPR quote was read via browser and is flagged by curators as unverifiable pending spot-check; our dossier gives only the pooled KD range, not a value for this pair. The paper's abstract was the only text in the dossier.","key_references":[{"PMID":"27298358","why":"Family-wise Dsg:Dsc heterophilic binding by biophysics, SPR, bead aggregation and crystal structures"}],"covers":["LR001790","LR005146"]},"LR005155":{"pair":"ECM1 -> ITGB4","headline":"One abstract-only paper reports ECM1 interacting directly with ITGB4 in gastric cancer.","interaction_type":"direct binding","direction_and_effect":"ECM1 directly interacted with ITGB4 and activated the ITGB4/FAK/GSK3beta pathway, inducing SOX2 [PMID:29059156].","molecular_requirements":"Alpha-partner of ITGB4 not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human gastric-cancer cells and xenografts; mouse pair is ortholog-inferred.","localisation_and_range":"Not reported in our evidence beyond ECM1 being an extracellular matrix protein [PMID:29059156].","caveats":"Single paper, abstract only; the assay for direct interaction is not stated in the abstract.","key_references":[{"PMID":"29059156","why":"ECM1 interacts with ITGB4 in gastric cancer"}],"covers":["LR001799","LR005155"]},"LR000457":{"pair":"EDA -> EDA2R","headline":"The EDA-A2 splice isoform activates EDA2R (XEDAR); evidence is functional plus isoform-specific binding.","interaction_type":"direct binding","direction_and_effect":"EDA-A2 binds only XEDAR (EDA2R), not EDAR [PMID:11039935]. In 293F cells expressing XEDAR, EDA-A2 activated NF-kappaB and JNK [PMID:12270937].","molecular_requirements":"Signalling recruits TRAF3 and TRAF6; NF-kappaB needs IKK1, IKK2 and NEMO, and JNK needs TRAF3, TRAF6 and ASK1 [PMID:12270937]. Only the A2 isoform acts on this receptor.","affinity_potency":[],"species_and_systems":"Human proteins, in situ binding and 293F cells; mouse pair is ortholog-inferred.","localisation_and_range":"Not reported beyond UniProt noting it functions as a ligand [DB:UniProt].","caveats":"PMID:11039935 shows EDA-A1 binds only EDAR and EDA-A2 only XEDAR, so isoform matters. A gene-level EDA->EDA2R row hides this. Both papers abstract only; PMID:12270937 reports no binding assay.","key_references":[{"PMID":"11039935","why":"Isoform-specific binding of EDA-A2 to XEDAR"},{"PMID":"12270937","why":"EDA-A2 activates XEDAR signalling"}],"covers":["LR000457","LR003948"]},"LR000466":{"pair":"EFEMP1 -> EGFR","headline":"EFEMP1 reported to bind EGFR and activate it in pancreatic cancer cells; single abstract-read paper.","interaction_type":"direct binding","direction_and_effect":"EFEMP1 binds EGFR competitively with EGF, suggesting shared or adjacent sites; purified EFEMP1 activates EGFR autophosphorylation at Tyr-992 and Tyr-1068 but not Tyr-1048, and downstream Akt and MAPK, all blocked by the EGFR kinase inhibitor PD153035 [PMID:19804359]. Agonist.","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human pancreatic carcinoma cells with purified EFEMP1 [PMID:19804359]; mouse pair ortholog-inferred.","localisation_and_range":"EFEMP1 is annotated secreted [flag]; paracrine ligand acting on a membrane receptor.","caveats":"One paper, abstract only, one lab; no affinity reported and no independent confirmation. Mouse pair untested.","key_references":[{"PMID":"19804359","why":"EFEMP1 binds EGFR and activates MAPK/Akt"}],"covers":["LR000466","LR003957"]},"LR000484":{"pair":"EFNA3 -> EPHA2","headline":"Ephrin-A3 binds EphA2 by ELISA, with a functional readout in dendritic cells; moderately supported.","interaction_type":"direct binding","direction_and_effect":"Ephrin-A3-Fc bound dendritic-cell surface EphA2 and increased adhesion to fibronectin (not poly-L-lysine) via beta1 integrin activation [PMID:12907451]. Ephrin-A3 AP binds EphA2, less well than EphA3, EphA5 and EphA7 [PMID:22568954].","molecular_requirements":"Not reported beyond the recombinant ligand-receptor pair.","affinity_potency":[],"species_and_systems":"ELISA with ephrin-A3 AP and EphA Fc proteins, species unspecified [PMID:22568954]; human CD34+-derived dendritic cells [PMID:12907451]. Mouse pair is ortholog-inferred.","localisation_and_range":"EFNA3 and EPHA2 are both flagged transmembrane [flag]; the dendritic-cell result concerns a ligand-Fc fusion.","caveats":"The adhesion effect is an indirect, substrate-specific readout through integrin activation, and one paper was a browser read with an unverifiable quote [PMID:22568954]. BioGRID lists affinity capture-MS and Western records [DB:BioGRID]. One further judgement is pending.","key_references":[{"PMID":"22568954","why":"ELISA ranking of ephrin-A3 binding across EphA receptors"},{"PMID":"12907451","why":"Ephrin-A3-Fc binds EphA2 on dendritic cells and alters adhesion"}],"covers":["LR000484","LR003975"]},"LR000493":{"pair":"EFNA4 -> EPHA3","headline":"No verified paper; only a BioGRID reconstituted-complex record supports the pair.","interaction_type":"database-asserted only","direction_and_effect":"BioGRID lists an EPHA3-EFNA4 reconstituted complex [DB:BioGRID, PMID:9195962]. Effect not reported in our evidence.","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Experimental species not reported in our evidence; the human pair is ortholog-inferred from mouse.","localisation_and_range":"Both flagged secreted and transmembrane [flag]; annotation only.","caveats":"All judged papers were review-only or abstract-insufficient, so no paper confirms it.","key_references":[],"covers":["LR000493","LR003984"]},"LR002527":{"pair":"EGFL7 -> NOTCH1","headline":"Secreted EGFL7 binds human NOTCH1 by co-IP and acts as a Notch antagonist; one primary paper.","interaction_type":"direct binding","direction_and_effect":"Secreted EGFL7 binds a Notch region involved in ligand-mediated activation and acts as an antagonist of Notch signalling; EGFL7 expression in neural stem cells decreased Notch-specific signalling [PMID:19503073].","molecular_requirements":"Not reported in our evidence beyond Notch receptors binding EGFL7 via EGF-like domains; control receptors with EGF-like domains did not interact [PMID:19503073].","affinity_potency":[],"species_and_systems":"Endogenous human NOTCH1 co-immunoprecipitated recombinant human EGFL7 in cell lines; tagged proteins in HEK293 cells [PMID:19503073]. BioGRID lists two-hybrid and reconstituted complex records [DB:BioGRID].","localisation_and_range":"EGFL7 is secreted [flag] and the Notch receptor is transmembrane [flag]; binding was retained with the two proteins on apposing cells [PMID:19503073].","caveats":"One paper supports all three Notch paralogs, and this row has no independent confirmation. No affinity reported in our evidence.","key_references":[{"PMID":"19503073","why":"EGFL7 binds Notch1-4 and antagonises Notch signalling"}],"covers":["LR002527","LR005795"]},"LR005812":{"pair":"EPHA2 -> EFNA5","headline":"EPHA2-EFNA5 is supported by a crystal structure and IntAct assays, but no verified papers.","interaction_type":"direct binding","direction_and_effect":"A crystal structure of the complete EphA2 ectodomain with the ephrin A5 receptor-binding domain is recorded [DB:PDB 2X11]; IntAct lists light scattering and pull-down [DB:IntAct]. UniProt states EPHA2 engaged by EFNA5 may regulate lens fiber cell shape and interactions [DB:UniProt].","molecular_requirements":"Receptor-binding domain of ephrin-A5 and the EphA2 ectodomain were used in the structure [DB:PDB 2X11].","affinity_potency":[],"species_and_systems":"Experiment species not reported in our evidence.","localisation_and_range":"Neither partner is flagged secreted [flag]. The pair is oriented Eph -> ephrin in our records; the evidence describes Eph-ephrin binding without establishing which partner acts as ligand here.","caveats":"Database evidence only; four review-only rows. No affinity values in our dossier.","key_references":[],"covers":["LR002544","LR005812"]},"LR002545":{"pair":"EPHA3 -> EFNA1","headline":"EPHA3-EFNA1 rests on BioGRID and UniProt records; no verified papers.","interaction_type":"database-asserted only","direction_and_effect":"BioGRID lists EPHA3-EFNA1 as a reconstituted complex [DB:BioGRID]. UniProt states EFNA1 acts as a ligand for EPHA3, inhibiting epithelial-to-mesenchymal transition of cardiac cells and playing a role in heart development [DB:UniProt].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Experiment species not reported in our evidence; the mouse pair is recorded as non-inferred and the human pair as ortholog-inferred.","localisation_and_range":"Both partners are flagged secreted [flag]. The pair is oriented Eph -> ephrin in our records; the evidence describes Eph-ephrin binding without establishing which partner acts as ligand here.","caveats":"Two review-only rows; database support only. No affinity values.","key_references":[],"covers":["LR002545","LR005813"]},"LR005821":{"pair":"EPHA4 -> EFNA4","headline":"EPHA4-EFNA4 has ELISA, co-IP and BioGRID records; no verified papers.","interaction_type":"direct binding","direction_and_effect":"IntAct lists direct interaction by ELISA and an anti-tag coimmunoprecipitation association [DB:IntAct]; BioGRID lists affinity capture-MS [DB:BioGRID]. Effect: not reported in our evidence.","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Experiment species not reported in our evidence.","localisation_and_range":"EFNA4 is flagged secreted, EPHA4 non-secreted [flag]. The pair is oriented Eph -> ephrin in our records; the evidence describes Eph-ephrin binding without establishing which partner acts as ligand here.","caveats":"Database evidence only; two review-only rows. No affinity data.","key_references":[],"covers":["LR002553","LR005821"]},"LR002554":{"pair":"EPHA4 -> EFNA5","headline":"EphA4 binds ephrin-A5 with crystal structures and ELISA data; well supported structurally.","interaction_type":"direct binding","direction_and_effect":"Crystal structures of the complete EphA4 ectodomain and its complexes with ephrin-A5 show ligand binding promotes conformational change in the EphA4 ligand-binding domain, allowing signalling clusters at cell-cell contacts [PMID:23959867]. Ephrin-A5 Fc binds EphA receptors with high apparent affinity in ELISA [PMID:22568954]. Effect: agonist per the curator [PMID:23959867].","molecular_requirements":"A receptor-receptor contact between the EphA4 ligand-binding domain and its own membrane-proximal fibronectin domain is important for efficient activation [PMID:23959867]. EphA4 is activated by both A- and B-class ephrins [PMID:23959867].","affinity_potency":[],"species_and_systems":"Human ligand and receptor in the structural paper [PMID:23959867]; ELISA species unspecified [PMID:22568954]. PDB 4BK5, 4BKA, 4M4R show the pair [DB:PDB 4BK5].","localisation_and_range":"Neither partner is flagged secreted [flag]; the paper describes clusters at sites of cell-cell contact [PMID:23959867]. The pair is oriented Eph -> ephrin in our records; the evidence describes Eph-ephrin binding without establishing which partner acts as ligand here.","caveats":"Structural paper read as abstract; the ELISA paper was browser-read with an unverified quote (spot-check pending). No numeric affinity in our evidence.","key_references":[{"PMID":"23959867","why":"EphA4 ectodomain and EphA4/ephrin-A5 structures"},{"PMID":"22568954","why":"ELISA: ephrin-A5 Fc binds EphA receptors"}],"covers":["LR002554","LR005822"]},"LR005830":{"pair":"EPHA6 -> EFNA1","headline":"Database-only claim: UniProt lists EPHA6 among the receptors bound by EFNA1; no verified paper.","interaction_type":"database-asserted only","direction_and_effect":"UniProt (EFNA1 entry) states it binds the receptor tyrosine kinases EPHA2, EPHA3, EPHA4, EPHA5, EPHA6 and EPHA7 [DB:UniProt]. Effect is not reported. Both partners carry the receptor annotation flag [flag], so ligand/receptor direction is not established by our evidence.","molecular_requirements":"Requirements: not reported in our evidence.","affinity_potency":[],"species_and_systems":"No paper was verified for this pair; species and experimental system of the database records are not reported in our evidence.","localisation_and_range":"EFNA1 carries a secreted flag and a transmembrane flag [flag]; EPHA6 carries a receptor flag only. Range is therefore unclear from our evidence.","caveats":"No curator-verified paper; support is database records only. The only record is a UniProt subunit sentence; no binding assay or affinity in our evidence.","key_references":[],"covers":["LR002562","LR005830"]},"LR000538":{"pair":"EREG -> ERBB4","headline":"Epiregulin binds ErbB-4 directly by cross-linking in human cells; one abstract-level paper plus databases.","interaction_type":"direct binding","direction_and_effect":"[125I]epiregulin directly bound ErbB-4 (and EGFR) in human breast carcinoma lines; the main intracellular signal was mediated by ErbB-4 and/or EGFR [PMID:9419975]. Annotated stimulatory [flag].","molecular_requirements":"No co-receptor requirement reported in our evidence; ErbB-4 binding occurred in lines with different ErbB subsets [PMID:9419975].","affinity_potency":[],"species_and_systems":"Human ligand and receptor, four human breast carcinoma lines [PMID:9419975]. The mouse pair is ortholog-inferred [flag].","localisation_and_range":"EREG flagged secreted and transmembrane; ErbB-4 transmembrane [flag].","caveats":"Abstract-only. No affinity. GtoPdb record has no action or affinity values [DB:GtoPdb].","key_references":[{"PMID":"9419975","why":"Cross-linking shows direct epiregulin binding to ErbB-4"}],"covers":["LR000538","LR004029"]},"LR007063":{"pair":"F11R -> ITGAL:ITGB2","headline":"JAM-A binds the LFA-1 heterodimer (ITGAL:ITGB2); two independent abstract-level papers plus Reactome.","interaction_type":"direct binding","direction_and_effect":"JAM-1 is a ligand of LFA-1, with transfectants supporting LFA-1-mediated leukocyte adhesion [PMID:11812992]. Recombinant JAM-A bound directly to the locked-open alphaL I domain in solid-phase assays [PMID:15528364].","molecular_requirements":"Binding site lies in the alphaL I domain [PMID:15528364]; JAM-A Ig-like domain 2 is needed [PMID:11812992]. Contribution of ITGB2 is not separately reported in our evidence. Reactome lists the alphaLbeta2:F11R complex [DB:Reactome].","affinity_potency":[],"species_and_systems":"Human proteins; Jurkat, Mono Mac 6, CHO transfectants, endothelium, T cells and neutrophils [PMID:15528364][PMID:11812992].","localisation_and_range":"Needs cytokine-induced JAM-1 redistribution from tight junctions [PMID:11812992].","caveats":"Abstract-level reads; no affinity.","key_references":[{"PMID":"15528364","why":"Direct JAM-A binding to the alphaL I domain"},{"PMID":"11812992","why":"JAM-1 as LFA-1 ligand"}],"covers":["LR007063"]},"LR008224":{"pair":"F13A1 -> ITGA9:ITGB1","headline":"Factor XIII supports alpha9beta1-dependent adhesion in human cells; functional evidence from one paper.","interaction_type":"functional only","direction_and_effect":"SW480 cells stably expressing alpha9beta1, not mock transfectants, adhered to FXIII [PMID:10816592].","molecular_requirements":"Complex ITGA9:ITGB1 shown together; each subunit contribution not separated.","affinity_potency":[],"species_and_systems":"Human G-361 melanoma and SW480 transfectants [PMID:10816592].","localisation_and_range":"FXIII flagged secreted [flag].","caveats":"Single paper, adhesion assays; no purified binding, no affinity.","key_references":[{"PMID":"10816592","why":"alpha9beta1 transfectants adhere to FXIII"}],"covers":["LR008224"]},"LR000547":{"pair":"F2 -> F2RL3","headline":"No evidence for thrombin acting on PAR-4 in the verified paper, which reports no effect; a PDB structure exists.","interaction_type":"conflicting","direction_and_effect":"None of the thrombin activities were affected by 50 microM PAR-4 polypeptide, in contrast to PAR-3 [PMID:12732212]. Annotated stimulatory [flag].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Recombinant polypeptide kinetics; species not stated [PMID:12732212]. PDB 3QDZ is human thrombin with human PAR4 fragment [DB:PDB 3QDZ].","localisation_and_range":"F2 flagged secreted; F2RL3 transmembrane [flag].","caveats":"Both verified rows are pair_absent, the human one propagated from the mouse row without re-reading. The PDB structure and Reactome record favour binding, so evidence conflicts. One row pending.","key_references":[{"PMID":"12732212","why":"Verified negative: PAR-4 polypeptide did not affect thrombin"}],"covers":["LR000547","LR004038"]},"LR004039":{"pair":"F2 -> GP1BA","headline":"Thrombin binds the GPIbalpha ectodomain directly (Kd 1 uM); structures exist, but the second paper is indirect.","interaction_type":"direct binding","direction_and_effect":"Glycocalicin (soluble GPIbalpha ectodomain) bound thrombin at exosite II and reduced fibrinopeptide A release from fibrinogen by about 50% through a noncompetitive allosteric mechanism [PMID:11024046]. Reactome lists thrombin binding to GP1b:IX:V [DB:Reactome R-HSA-429529]. Direction as receptor signalling is not shown in our evidence.","molecular_requirements":"Binding maps to thrombin exosite II, confirmed with thrombin mutants and competition binding; exosite I mutations had little effect [PMID:11024046]. A 1985 study placed thrombin and von Willebrand factor binding sites in the same 45-kDa GPIb region and proposed a second thrombin receptor, possibly GPV [PMID:2933256]. Co-crystal structures exist [DB:PDB 1OOK] [DB:PDB 1P8V] [DB:IntAct].","affinity_potency":[{"value":"Kd 1 microm","assay":"solution binding of glycocalicin to thrombin, physiological ionic strength","system":"purified proteins","cite":"PMID:11024046"},{"value":"Kd 0.19 microm","assay":"same, at 100 mm NaCl (salt-dependent)","system":"purified proteins","cite":"PMID:11024046"}],"species_and_systems":"The 1985 paper's species is labelled mouse in the curation row, while its text mentions human leukocyte elastase and platelets [PMID:2933256]; the binding work used purified proteins [PMID:11024046]. Species of the purified proteins is not reported in our evidence. Mouse pair is ortholog-inferred.","localisation_and_range":"GP1BA is annotated as a transmembrane receptor and F2 as secreted [flag], so thrombin acts on platelet surface from plasma; glycocalicin is the soluble fragment [PMID:11024046].","caveats":"Both papers were read as abstracts only. The 1985 paper used enzymatic and antibody perturbation of platelets, not direct binding [PMID:2933256]. The Kd is salt-dependent.","key_references":[{"PMID":"11024046","why":"Kd and exosite II mapping of thrombin-GPIbalpha binding"},{"PMID":"2933256","why":"Early platelet study localising thrombin site to GPIb 45-kDa region"}],"covers":["LR000548","LR004039"]},"LR009331":{"pair":"F2 -> ITGA2B","headline":"Thrombin-ITGA2B is supported only by BioGRID and a UniProt functional note; no direct paper evidence.","interaction_type":"database-asserted only","direction_and_effect":"BioGRID lists a reconstituted complex [DB:BioGRID 278302]. UniProt states that integrin alpha-IIb/beta-3 is a receptor for prothrombin among other ligands [DB:UniProt P08514].","molecular_requirements":"UniProt attributes receptor function to the ITGA2B:ITGB3 heterodimer, not the alpha chain alone [DB:UniProt P08514]; chain-alone binding is not reported in our evidence.","affinity_potency":[],"species_and_systems":"Species and system: not reported in our evidence.","localisation_and_range":"ITGA2B annotated as a receptor [flag].","caveats":"Database only; the single judged paper was review-only. Chain-level pair; the complex entry is more appropriate.","key_references":[],"covers":["LR009331"]},"LR002608":{"pair":"F8 -> ASGR1","headline":"Factor VIII binds the asialoglycoprotein receptor with Kd about 2 nM by SPR; the paper concerns the receptor, not ASGR1 specifically.","interaction_type":"direct binding","direction_and_effect":"Factor VIII bound ASGPR dose-dependently with high affinity; in mice, FVIII residence time was prolonged (abstract truncated) [PMID:15946216]. This is a clearance receptor interaction.","molecular_requirements":"Only the FVIII heavy chain showed high-affinity binding, driven by B-domain elements; binding needed calcium, was inhibited by D-galactose and lost after deglycosylation [PMID:15946216]. ASGPR is described as the ASGR1/ASGR2 heterodimer in curator notes, so ASGR2 may also be required.","affinity_potency":[{"value":"Kd approximately 2 nM","assay":"surface plasmon resonance","system":"FVIII with ASGPR (purified, abstract only)","cite":"PMID:15946216"}],"species_and_systems":"SPR with purified proteins plus mouse clearance experiments [PMID:15946216]; species of proteins not reported in our evidence.","localisation_and_range":"ASGR1 is annotated as secreted [flag], though the receptor is described as an endocytic lectin [PMID:15946216].","caveats":"Abstract-only. The paper tested ASGPR as a whole, not ASGR1 alone. Binding depends on glycosylation, so recombinant or deglycosylated FVIII may differ.","key_references":[{"PMID":"15946216","why":"SPR binding of FVIII to ASGPR, Kd about 2 nM"}],"covers":["LR002608","LR005875"]},"LR001807":{"pair":"FAM3C -> LIFR","headline":"FAM3C (ILEI) is reported to signal through LIFR in breast cancer cells; binding is shown by crosslinking in one paper.","interaction_type":"direct binding","direction_and_effect":"LIFR was identified as the ILEI receptor; ILEI activates STAT3 (and ERK) via LIFR to drive EMT and cancer stem cell formation, and only cells containing LIFR responded to ILEI [PMID:30692635].","molecular_requirements":"A yeast two-hybrid screen found LIFR as a candidate partner; radiolabelled ILEI crosslinked to cell-surface LIFR and co-precipitated with LIFR in HEK293 cells expressing FLAG-LIFR; LIF was the positive control [PMID:30692635]. Roles of gp130 or other co-receptors: not reported in our evidence.","affinity_potency":[],"species_and_systems":"NMuMG and E1KD mammary cell lines, HEK293 cells, mouse xenograft/metastasis models; recombinant ILEI [PMID:30692635]. Species of the cell lines is not stated in our evidence.","localisation_and_range":"FAM3C is annotated secreted [flag].","caveats":"Single paper with no affinity data. Y2H and crosslinking are not purified-protein binding. Receptor identification is stated as LIFR mediating signalling, with LIFR knockdown abolishing rescue by ILEI [PMID:30692635].","key_references":[{"PMID":"30692635","why":"Identifies LIFR as ILEI receptor with crosslinking and STAT3 signalling"}],"covers":["LR001807","LR005163"]},"LR005164":{"pair":"FAM3D -> FPR1","headline":"FAM3D acts as an agonist of FPR1 and FPR2 on human neutrophils, shown functionally with antagonists.","interaction_type":"functional only","direction_and_effect":"FAM3D induced Mac-1 activation and adhesion in human neutrophils, and this was inhibited by the FPR1 antagonist cyclosporin H, the FPR2 antagonist WRW, or the dual antagonist Boc-PLPLP; FAM3D deficiency reduced neutrophil recruitment and aneurysm in mice [PMID:29853563]. It signals through Gi protein and beta-arrestin pathways [PMID:29853563].","molecular_requirements":"The effect depended on both FPR1 and FPR2; blocking either reduced Mac-1 activation [PMID:29853563]. Ability of FPR1 alone to respond: not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human neutrophils and HUVECs; elastase- and CaPO4-induced mouse aneurysm models, FAM3D knockout mice [PMID:29853563]. The dossier includes human and mouse pairs.","localisation_and_range":"FAM3D is annotated secreted and FPR1 transmembrane [flag]; endothelial cells release FAM3D to act on neutrophils [PMID:29853563].","caveats":"Single paper, read in the abstract and excerpts; no direct binding or affinity shown, only antagonist inhibition. The paper cites earlier work calling FAM3D a dual FPR agonist [PMID:29853563].","key_references":[{"PMID":"29853563","why":"FAM3D activates neutrophil Mac-1 via FPR1/FPR2 in aortic aneurysm"}],"covers":["LR001808","LR005164"]},"LR000556":{"pair":"FBLN1 -> ITGB1","headline":"Weak support: a 1989 paper found a 100 kd protein (named fibulin) binding the integrin beta1 cytoplasmic domain.","interaction_type":"direct binding","direction_and_effect":"A 100 kd protein, termed fibulin, was purified on a peptide of the fibronectin receptor beta subunit cytoplasmic domain, bound native fibronectin receptor, and co-localized with it at substrate contacts [PMID:2527614]. Effect on signaling not reported in our evidence.","molecular_requirements":"Only the beta subunit cytoplasmic domain peptide and native fibronectin receptor were used; alpha partner not reported in our evidence [PMID:2527614].","affinity_potency":[],"species_and_systems":"Tissue and cell extracts and cultured cells; species not reported in our evidence.","localisation_and_range":"FBLN1 is flagged secreted [flag]; the paper's binding is to an intracellular tail [PMID:2527614].","caveats":"Single abstract-only paper from 1989. The binding is to the cytoplasmic domain, which a secreted extracellular ligand would not reach, so a classical ligand-receptor reading is doubtful. The paper's protein is called fibulin; link to FBLN1 as annotated is not tested here.","key_references":[{"PMID":"2527614","why":"Original fibulin report; binding to integrin beta1 cytoplasmic domain."}],"covers":["LR000556"]},"LR004048":{"pair":"FBLN2 -> ITGB3","headline":"Fibulin-2 binds beta3 integrins (strongly alpha IIb beta 3), with cell-adhesion support and a species caveat.","interaction_type":"direct binding","direction_and_effect":"Mouse fibulin-2 bound alpha IIb beta 3 almost as strongly as fibrinogen [PMID:7543056]. Mouse fibulin-2 adhesion of HEL cells was mediated by beta3 integrins [PMID:10848816].","molecular_requirements":"RGD site of fibulin-2 is involved; human fibulin-2 with RSS bound less strongly [PMID:7543056]. The beta3 chain's partner (alpha IIb or alpha V) changes affinity [PMID:7543056].","affinity_potency":[],"species_and_systems":"Recombinant proteins and purified integrins [PMID:7543056]; HEL cell adhesion assays and mouse bone marrow culture [PMID:10848816].","localisation_and_range":"FBLN2 is flagged secreted [flag]; localised with fibronectin in bone marrow stroma [PMID:10848816].","caveats":"HEL cells did not adhere to human fibulin-2, and mouse megakaryocytes did not adhere to mouse fibulin-2, so adhesion is species- and cell-type-dependent [PMID:10848816]. Both papers abstract only. The adhesion paper does not show direct binding.","key_references":[{"PMID":"7543056","why":"Purified integrin binding by fibulin-2."},{"PMID":"10848816","why":"Fibulin-2 adhesion via beta3 integrins, species caveats."}],"covers":["LR000557","LR004048"]},"LR002617":{"pair":"FCER2 -> ITGAV","headline":"Human CD23 binds alphaV integrins (alphaVbeta3 and alphaVbeta5) via an RKC motif, shown by SPR with peptides.","interaction_type":"direct binding","direction_and_effect":"CD23 peptides with an Arg-Lys-Cys (RKC) motif bind alphaVbeta3 and alphaVbeta5; they inhibit CD23 binding to B cells and monocytes and stimulate pre-B cell growth and monocyte cytokine release [PMID:22560905]. Curator labels effect agonist.","molecular_requirements":"The motif starts at arg172 of CD23. Substituting both basic residues abolished binding and activity; one substitution reduced but did not abolish it. Binding is cation-independent, chloride-sensitive and distinct from RGD binding [PMID:22560905]. The receptor is the alphaV-containing heterodimer; alphaV alone was not tested here.","affinity_potency":[],"species_and_systems":"Human CD23-derived peptides, purified integrins (SPR) and human cells (THP-1, SMS-SB) [PMID:22560905].","localisation_and_range":"CD23 flagged secreted and transmembrane [flag]; soluble CD23 binding to cells is described [PMID:22560905].","caveats":"Binding shown with CD23-derived peptides, not full-length protein SPR. No affinity values reported in our evidence.","key_references":[{"PMID":"22560905","why":"SPR of RKC peptides with alphaVbeta3/beta5"}],"covers":["LR002617"]},"LR000565":{"pair":"FGA -> ITGA5","headline":"Fibrinogen binds purified integrin alpha5beta1 through the Aalpha C-terminal RGD site; solid-phase, abstract-level.","interaction_type":"direct binding","direction_and_effect":"Fibrinogen bound purified alpha5beta1 in a time-dependent, specific, saturable manner with Mn2+; blocked by RGD peptides and anti-alpha5 and anti-alpha5beta1 antibodies [PMID:11011154].","molecular_requirements":"Receptor is the alpha5beta1 heterodimer. The C-terminal RGD at Aalpha572-574 is required (RGE substitution decreased binding by 90%); the N-terminal RGD at Aalpha95-97 had a minimal effect [PMID:11011154].","affinity_potency":[],"species_and_systems":"Human proteins (curator fields), purified solid-phase [PMID:11011154].","localisation_and_range":"FGA is flagged secreted; ITGA5 not secreted, receptor [flag].","caveats":"Abstract only; no affinity reported. Binding needed Mn2+. A further paper was abstract_insufficient (not shown).","key_references":[{"PMID":"11011154","why":"fibrinogen-alpha5beta1 binding via Aalpha RGD"}],"covers":["LR000565"]},"LR002626":{"pair":"FGF1 -> ITGB3","headline":"FGF1 binds integrin alphaVbeta3 directly, with micromolar affinity; a mutant lacking integrin binding loses signalling.","interaction_type":"direct binding","direction_and_effect":"FGF1 directly bound soluble and cell-surface integrin alphavbeta3; the antagonists 7E3 and cyclic RGDfV blocked this, and an integrin-binding-defective FGF1 mutant (R50E) failed to induce DNA synthesis, proliferation, migration and chemotaxis [PMID:18441324]. Wild-type FGF1 formed an integrin-FGF1-FGFR1 ternary complex that recruited SHP-2; R50E did not [PMID:20422052]. UniProt records the same [DB:UniProt].","molecular_requirements":"The receptor is the alphaV:beta3 heterodimer (UniProt describes ITGAV:ITGB3 binding) [DB:UniProt]; the beta3 specificity loop CYDMKTTC contributes [PMID:18441324]. FGF1 bound several beta1 integrins only weakly [PMID:18441324]. Signalling involves a ternary complex with FGFR1, so FGFR1 expression matters too [PMID:20422052].","affinity_potency":[{"value":"KD about 1 micromolar","assay":"solid-phase and cell-surface binding assay","system":"soluble and cell-surface integrin alphavbeta3","cite":"PMID:18441324"}],"species_and_systems":"Binding assays used soluble and cell-surface alphavbeta3 [PMID:18441324]. Ternary complex shown in mouse NIH 3T3 cells and human umbilical endothelial cells; BaF3 mouse pro-B cells expressed human FGFR1 [PMID:20422052]. The mouse pair is projected from human evidence (ortholog_inferred).","localisation_and_range":"FGF1 is flagged secreted and non-transmembrane; the integrin is a membrane receptor [flag]. Action is paracrine or autocrine via cell-surface integrin, inferred from these flags.","caveats":"Both papers were read as abstracts only (one with some full-text excerpts). Both come from the same research group, so they are not independent. Functional role depends on FGFR1 co-engagement.","key_references":[{"PMID":"18441324","why":"direct binding, KD and R50E mutant"},{"PMID":"20422052","why":"ternary complex with FGFR1 in 3T3 and endothelial cells"}],"covers":["LR002626","LR005892"]},"LR000574":{"pair":"FGF10 -> FGFR1","headline":"FGF10 weakly activates FGFR1b in a mitogenic assay; a weak, isoform-restricted functional signal.","interaction_type":"functional only","direction_and_effect":"In BaF3 cells FGF10 showed weak activity toward FGFR1b and did not activate the other FGFR-expressing lines tested [PMID:16597617]. UniProt lists FGF10 among weaker in vitro FGFR1 partners [DB:UniProt].","molecular_requirements":"Activity was seen with the FGFR1b splice form only; the dossier does not report activity on FGFR1c [PMID:16597617].","affinity_potency":[],"species_and_systems":"BaF3 cell mitogenic assay with relative mitogenic activity against FGF1 as readout; species of constructs not reported [PMID:16597617]. Mouse pair projected from human.","localisation_and_range":"FGF10 flagged secreted; FGFR1 membrane receptor [flag]. Paracrine action is inferred from the flag.","caveats":"Described as weak. Full text read in a browser, quote unverified. A BioGRID protein-peptide record also exists [DB:BioGRID]. This is a weaker pair than FGF10-FGFR2.","key_references":[{"PMID":"16597617","why":"BaF3 receptor-specificity panel"}],"covers":["LR000574","LR004058"]},"LR008530":{"pair":"FGF13 -> SCN8A","headline":"FGF13 and SCN8A are linked only by UniProt interaction statements; likely not a secreted ligand-receptor pair.","interaction_type":"database-asserted only","direction_and_effect":"UniProt records that the proteins interact [DB:UniProt]; the pair is annotated as inhibitory in our records. Mechanism not reported in our evidence.","molecular_requirements":"not reported in our evidence","affinity_potency":[],"species_and_systems":"UniProt only; experimental species and system not reported in our evidence.","localisation_and_range":"Not stated in our evidence; the entity flags were not provided.","caveats":"No curator-verified paper (the judged paper was marked different_entity) and no structure or binding assay in the dossier. Support rests on a database statement.","key_references":[],"covers":["LR008530"]},"LR004075":{"pair":"Fgf15 -> Fgfr4","headline":"Mouse Fgf15 (ortholog of FGF19) is described as binding FGFR4 exclusively, with a structural model rather than a co-structure.","interaction_type":"direct binding","direction_and_effect":"FGF-19 is a high-affinity, heparin-dependent ligand for FGFR4 and the first FGF to show exclusive binding to FGFR4 [PMID:10525310]. A model of the FGF19-FGFR4 complex indicates that unique sequences in both partners drive complex formation [PMID:14730967].","molecular_requirements":"Heparin dependence is reported [PMID:10525310].  KLB involvement is not reported in this pair's papers.","affinity_potency":[],"species_and_systems":"Evidence is written for human FGF19, the ortholog of mouse Fgf15; the mouse pair is projected from human. Both curated papers are on human FGF-19 and read as abstracts.","localisation_and_range":"Fgf15 flagged secreted [flag].","caveats":"Only FGF19 alone was crystallised; the complex is a computational model, not a solved structure [PMID:14730967]. The exclusivity claim should be read alongside the Fgf15-Fgfr1 pair, where separate evidence reports FGFR1 binding in the presence of KLB. One further paper was abstract-insufficient.","key_references":[{"PMID":"10525310","why":"FGF-19 high-affinity, heparin-dependent FGFR4 ligand"},{"PMID":"14730967","why":"FGF19 crystal structure and FGFR4 model"}],"covers":["LR004075"]},"LR004066":{"pair":"FGF17 -> FGFR3","headline":"FGF17 activates FGFR3c in a BaF3 mitogenic panel; one functional paper.","interaction_type":"functional only","direction_and_effect":"FGF8, FGF17 and FGF18 specifically activated FGFR1c, 2c, 3c and the two Ig-like domain form of FGFR4 [PMID:16597617]. Agonist.","molecular_requirements":"c isoform of FGFR3 [PMID:16597617].","affinity_potency":[],"species_and_systems":"BaF3 mitogenic panel [PMID:16597617]; species of FGFR constructs not reported. Mouse pair projected from human.","localisation_and_range":"FGF17 flagged secreted [flag].","caveats":"Mitogenic activity in BaF3 cells, not binding; browser-read full text, quote unverified [PMID:16597617]. Two other judged rows were review-only and one abstract-insufficient.","key_references":[{"PMID":"16597617","why":"BaF3 panel"}],"covers":["LR000582","LR004066"]},"LR000583":{"pair":"FGF17 -> FGFR4","headline":"FGF17 activates the two-Ig-domain form of FGFR4 in BaF3 cells; one functional paper.","interaction_type":"functional only","direction_and_effect":"FGF8, FGF17 and FGF18 activated the two Ig-like domain forms of FGFR4 (4delta) in addition to FGFR1c, 2c and 3c [PMID:16597617]. Agonist.","molecular_requirements":"The active form is the two Ig-like domain FGFR4 variant, which may differ from the canonical receptor [PMID:16597617].","affinity_potency":[],"species_and_systems":"BaF3 mitogenic panel [PMID:16597617]; species of FGFR constructs not reported. Mouse pair projected from human.","localisation_and_range":"FGF17 flagged secreted; FGFR4 flagged secreted and transmembrane [flag].","caveats":"Mitogenic activity in BaF3 cells, not binding; browser-read full text, quote unverified [PMID:16597617].","key_references":[{"PMID":"16597617","why":"BaF3 panel, FGFR4 delta"}],"covers":["LR000583","LR004067"]},"LR000592":{"pair":"FGF19 -> KLB","headline":"FGF19 binds KLB directly in human-protein assays; KLB is a required co-receptor, from a single paper.","interaction_type":"direct binding","direction_and_effect":"Both FGF19 and FGF21, but not FGF1, bound KLB; the paper reports agonist behaviour of FGF19 through FGFR-KLB [PMID:22442730].","molecular_requirements":"KLB is indispensable for FGF19 binding to FGFRs: FGF19 did not bind FGFR1 alone, and it bound FGFR1-KLB and FGFR4-KLB equally [PMID:22442730]. PDB 6NFJ shows KLB with an FGF19 C-terminal peptide [DB:PDB 6NFJ].","affinity_potency":[],"species_and_systems":"Human ligand and receptor, 125I-FGF19 binding and cross-linking in cells [PMID:22442730]. The dossier marks this pair as ortholog-inferred, so the human evidence is the experimental basis.","localisation_and_range":"KLB acts as a membrane co-receptor with an FGFR; ligand is annotated secreted [flag].","caveats":"One paper only. KLB is a co-receptor and alone does not signal; the signalling receptor is FGFR1 or FGFR4. Affinity not reported in our evidence.","key_references":[{"PMID":"22442730","why":"FGF19 binds KLB; KLB essential for FGFR binding"}],"covers":["LR000592"]},"LR004093":{"pair":"FGF2 -> FGFR2","headline":"FGF2 binds FGFR2 well and activates c splice forms, from two abstract-only papers.","interaction_type":"direct binding","direction_and_effect":"FGF-2 binds well to FGFR1, FGFR2 and FGFR4 but poorly to KGFR (FGFR2-IIIb) [PMID:10950949]. In BaF3 mitogenic assays FGF2 preferentially activates c splice forms [PMID:8663044]. Dossier modulatory effect: stimulatory [flag].","molecular_requirements":"Splice form matters: the IIIb form (KGFR) binds FGF2 poorly [PMID:10950949], and c forms are preferred [PMID:8663044]. Heparin dependence is not reported for this pair in our evidence.","affinity_potency":[],"species_and_systems":"Human proteins in the binding study [PMID:10950949]; BaF3 species not stated [PMID:8663044]. BioGRID, IntAct, PDB 1EV2, 1II4, 1IIL and Reactome records [DB:BioGRID][DB:IntAct][DB:PDB 1EV2][DB:Reactome].","localisation_and_range":"FGF2 annotated secreted, FGFR2 transmembrane [flag].","caveats":"Both papers abstract only; the first is mainly about FGF-7 and uses FGF-2 as a comparator. No affinity in our evidence.","key_references":[{"PMID":"10950949","why":"FGF-2 binds FGFR2 well, not KGFR"},{"PMID":"8663044","why":"BaF3 activity favouring c splice forms"}],"covers":["LR000609","LR004093"]},"LR001816":{"pair":"FGF20 -> FGFR2","headline":"FGF20 activating FGFR2 is supported only indirectly by a family mitogenic screen and mouse heart genetics.","interaction_type":"functional only","direction_and_effect":"The BaF3 screen reports FGF9, 16 and 20 activating FGFRc isoforms and FGFR4 with high activity [PMID:16597617]. In mouse heart, FGF signals including Fgf9/16/20 were received by FGFR1 and FGFR2 acting redundantly [PMID:15621532].","molecular_requirements":"FGFR1 and FGFR2 act redundantly [PMID:15621532]; the screen implicates c-splice isoforms [PMID:16597617].","affinity_potency":[],"species_and_systems":"BaF3 lines, species unspecified [PMID:16597617]; mouse knockout and heart organ culture [PMID:15621532].","localisation_and_range":"FGF20 flagged secreted, FGFR2 transmembrane [flag].","caveats":"No direct binding. Neither quote names FGF20 and FGFR2 on their own: one is a subfamily statement, the other a joint knockout inference. Both papers read at abstract level.","key_references":[{"PMID":"16597617","why":"Mitogenic receptor-specificity screen of FGF9/16/20"},{"PMID":"15621532","why":"Mouse heart FGF signals via FGFR1/FGFR2"}],"covers":["LR001816","LR005171"]},"LR004084":{"pair":"FGF21 -> FGFR2","headline":"Functional (mitogenic) activity of FGF21 on FGFR2c reported in one screen; no binding data in our evidence.","interaction_type":"functional only","direction_and_effect":"FGF21 showed consistent activity toward FGFR1c, 2c, 3c and FGFR4 but not FGFR1b, 2b or 3b in a BaF3 mitogenic assay [PMID:16597617]. Effect is stimulatory (activation) [PMID:16597617].","molecular_requirements":"Only the c splice forms were active; KLB involvement is not reported in our evidence for this pair.","affinity_potency":[],"species_and_systems":"BaF3 cell lines expressing individual FGFRs; ligand and receptor species unspecified [PMID:16597617].","localisation_and_range":"Localisation not reported in our evidence beyond flags: FGF21 secreted [flag]; FGFR2 transmembrane [flag].","caveats":"Single paper, functional readout only, abstract-only reading of a browser-read quote that is unverified [PMID:16597617]. No direct binding data. Mouse pair is projected from human.","key_references":[{"PMID":"16597617","why":"BaF3 receptor-specificity screen of the FGF family"}],"covers":["LR000600","LR004084"]},"LR002635":{"pair":"FGF21 -> FGFR3","headline":"Functional (mitogenic) activity of FGF21 on FGFR3c reported in one screen; no binding data in our evidence.","interaction_type":"functional only","direction_and_effect":"FGF21 showed consistent activity toward FGFR1c, 2c, 3c and FGFR4 but not FGFR1b, 2b or 3b in BaF3 cells [PMID:16597617]; stimulatory.","molecular_requirements":"Only c splice forms were active; cofactors not reported in our evidence for this pair.","affinity_potency":[],"species_and_systems":"BaF3 lines expressing individual FGFRs; species unspecified [PMID:16597617].","localisation_and_range":"FGF21 secreted [flag]; FGFR3 transmembrane [flag].","caveats":"Single functional paper; quote browser-read and unverified [PMID:16597617]. Mouse pair is projected from human.","key_references":[{"PMID":"16597617","why":"BaF3 receptor-specificity screen of the FGF family"}],"covers":["LR002635","LR005901"]},"LR005902":{"pair":"FGF21 -> KLB","headline":"FGF21 binds KLB directly in cell binding assays, supported also by structure and SPR records.","interaction_type":"direct binding","direction_and_effect":"Both FGF19 and FGF21, but not FGF1, show binding affinity to KLB [PMID:22442730]. KLB is described as an indispensable co-receptor for FGF21 engagement of FGFRs [PMID:22442730]. Curators label it agonist [PMID:22442730].","molecular_requirements":"KLB alone binds FGF21: 1 ug/ml FGF21 competed with 125I-FGF19 on KLB-only cells with over 90% efficiency [PMID:22442730]. KLB acts together with FGFR1 for FGF21 [PMID:22442730]; a PDB entry shows beta-Klotho with FGF21CT [DB:PDB 5VAQ].","affinity_potency":[{"value":"about 150 ng/ml","assay":"half-maximum competition of FGF21 against 125I-FGF19 (measured on FGFR1-KLB cells, not KLB alone)","system":"T-Rex 293 cells expressing FGFR1 and KLB","cite":"PMID:22442730"}],"species_and_systems":"Human reagents per curators; recombinant cell-based assays plus mouse signaling [PMID:22442730]. Human pair is ortholog-inferred, mouse pair is not.","localisation_and_range":"FGF21 flagged secreted [flag]; KLB flagged receptor [flag].","caveats":"Binding is shown by competition because iodinated FGF21 was inactive [PMID:22442730]. KLB is a co-receptor, not a signalling receptor on its own in this evidence.","key_references":[{"PMID":"22442730","why":"FGF21 and FGF19 binding to KLB, with FGF1 negative control"}],"covers":["LR002636","LR005902"]},"LR005173":{"pair":"FGF22 -> FGFR1","headline":"Weak functional evidence: FGF22 gave only weak activity toward FGFR1b in a mitogenic screen.","interaction_type":"functional only","direction_and_effect":"FGFs 10 and 22 showed weak activity toward FGFR1b and failed to activate other FGFR lines in the BaF3 screen [PMID:16597617].","molecular_requirements":"Only FGFR1b showed weak response; heparan sulfate modulation noted in the abstract generally [PMID:16597617].","affinity_potency":[],"species_and_systems":"BaF3 cells; species unspecified [PMID:16597617].","localisation_and_range":"FGF22 secreted [flag]; FGFR1 transmembrane [flag].","caveats":"Single weak functional result, quote browser-read and unverified [PMID:16597617]. UniProt lists FGF22 among FGFR1 interactors in vitro, citing the same screen [DB:UniProt]. Mouse pair is projected from human.","key_references":[{"PMID":"16597617","why":"BaF3 receptor-specificity screen of the FGF family"}],"covers":["LR001818","LR005173"]},"LR000619":{"pair":"FGF3 -> FGFR1","headline":"FGF3 binds FGFR1 IIIb with high affinity; weak or no binding to FGFR1c.","interaction_type":"direct binding","direction_and_effect":"Fgf3 bound the IIIb isoforms of FgfR1 and FgfR2 with high affinity by receptor binding competition [PMID:7592624]; FGF3 activates b splice forms of FGFR1 and 2 in BaF3 cells [PMID:8663044]. Curated agonist [PMID:7592624].","molecular_requirements":"IIIb isoform of FGFR1 only; no competition seen for FgfR1 IIIc [PMID:7592624]. Heparin dependence varied between cell lines [PMID:7592624].","affinity_potency":[{"value":"ID50 = approximately 0.8 nM","assay":"receptor binding competition vs 125I-Fgf1","system":"IIIb isoforms of FgfR1 and FgfR2 (shared value)","cite":"PMID:7592624"}],"species_and_systems":"Purified mouse fgf3 protein per the abstract [PMID:7592624]; BaF3 screen species unspecified [PMID:8663044].","localisation_and_range":"FGFR1 transmembrane [flag]; localisation otherwise not reported.","caveats":"Gene-level pair hides isoform specificity. The ID50 is shared with FgfR2 in the abstract. Abstract-only readings. Human pair is ortholog-inferred.","key_references":[{"PMID":"7592624","why":"High-affinity binding of Fgf3 to IIIb isoforms"},{"PMID":"8663044","why":"BaF3 mitogenic screen"}],"covers":["LR000619","LR004103"]},"LR000628":{"pair":"FGF5 -> FGFR3","headline":"Only a BaF3 survey statement supports this pair; evidence for FGFR3 specifically is thin.","interaction_type":"functional only","direction_and_effect":"The BaF3 mitogenic survey states that FGFs 4, 5, 6 and 8 specifically activate c receptor splice forms [PMID:8663044]; whether FGFR3c was a responder is not shown in the quoted evidence.","molecular_requirements":"Splice-form (c) selectivity is described [PMID:8663044]; other requirements are not reported in our evidence.","affinity_potency":[],"species_and_systems":"BaF3 mitogenic assays on FGFR-expressing cell lines; species of ligand and receptor listed as unspecified [PMID:8663044]. Mouse pair is projected from human.","localisation_and_range":"Localisation is not reported in our evidence.","caveats":"Single abstract-only paper with a browser-read quote pending spot-check; no binding data, no FGFR3-specific statement, no database records.","key_references":[{"PMID":"8663044","why":"BaF3 survey, FGF5 activates c splice forms"}],"covers":["LR000628","LR004112"]},"LR000637":{"pair":"FGF8 -> FGFR1","headline":"FGF8 activates FGFR1c in BaF3 assays; one other paper conflicts on binding; AIGF/FGFR1 functional support.","interaction_type":"conflicting","direction_and_effect":"FGF8 subfamily members specifically activated FGFRs 1c, 2c and 3c and FGFR4 (4\u0394) in BaF3 cells [PMID:16597617]. Mouse AIGF (FGF8) caused FGFR1-dependent inhibition of differentiation in L6 cells expressing an FGFR1 variant [PMID:8290257].","molecular_requirements":"c splice form of FGFR1 is the responsive isoform [PMID:16597617]. BioGRID, IntAct (surface plasmon resonance) and UniProt records exist [DB:BioGRID][DB:IntAct][DB:UniProt].","affinity_potency":[],"species_and_systems":"BaF3 cells, species unspecified [PMID:16597617]; mouse SC-3-derived FGFR1 variant in L6 cells, abstract only [PMID:8290257]. Human and mouse pairs are both non-inferred.","localisation_and_range":"Localisation is not reported in our evidence.","caveats":"The FGFR1 construct in PMID:8290257 is a variant, and the interaction is inferred from a functional assay.","key_references":[{"PMID":"16597617","why":"FGF8 activates FGFR1c in BaF3"},{"PMID":"8290257","why":"AIGF (FGF8) dependent FGFR1 effect in L6 cells"}],"covers":["LR000637","LR004121"]},"LR004129":{"pair":"FGG -> ITGA2B","headline":"Fibrinogen gamma chain binds integrin alphaIIbbeta3 via its C-terminal gammaC peptide; strong structural support.","interaction_type":"direct binding","direction_and_effect":"The fibrinogen gamma C-terminal peptide binds alphaIIbbeta3 on platelets; the integrin MIDAS Mg2+ binds the gammaC Asp side chain [PMID:18710925]. RGD peptides bind and activate the receptor, giving high-affinity fibrinogen binding [PMID:2018974]. Fibrinogen was recognised by alphaIIbbeta3 in trophoblast outgrowth [PMID:15031111].","molecular_requirements":"The functional receptor is the alphaIIb/beta3 heterodimer, not alphaIIb alone. The KQAGDV motif binds in the groove between the subunits [PMID:26631735]. Fibrinogen is FGA:FGB:FGG and the assay does not separate the chains [PMID:2018974].","affinity_potency":[],"species_and_systems":"Human crystal structures and platelets [PMID:18710925][PMID:2018974]; human fibrinogen on mouse trophoblast cells [PMID:15031111]. Both human and mouse pairs listed, not inferred.","localisation_and_range":"FGG is flagged secreted [flag].","caveats":"PDB structures 2VDO-2VDR include a fibrinogen chain and ITGA2B [DB:PDB 2VDO]; BioGRID has a protein-peptide record [DB:BioGRID]. Several papers were read as abstracts only. Use the complex when scoring.","key_references":[{"PMID":"18710925","why":"Crystal structure of alphaIIbbeta3 with gammaC peptide"},{"PMID":"26631735","why":"KQAGDV of the gamma chain binds the integrin; beta3 binding suffices to open headpiece"},{"PMID":"2018974","why":"RGD binding activates fibrinogen binding to alphaIIbbeta3"}],"covers":["LR000645","LR004129"]},"LR000646":{"pair":"FGG -> ITGAV","headline":"Fibrinogen is recognised by alphaVbeta3; support is one trophoblast paper plus structural database records.","interaction_type":"functional only","direction_and_effect":"Fibrinogen is recognised by alphaVbeta3 and alphaIIbbeta3 but not alpha5beta1 in trophoblast adhesion and migration [PMID:15031111].","molecular_requirements":"The receptor is the alphaV/beta3 heterodimer; ITGAV alone is not shown [PMID:15031111].","affinity_potency":[],"species_and_systems":"Human fibrinogen on mouse trophoblast cells [PMID:15031111]. Both pairs ortholog-inferred.","localisation_and_range":"FGG is flagged secreted [flag].","caveats":"The trophoblast sentence cites earlier work as background rather than showing it, so direct alphaV evidence is weak [PMID:15031111]. Database records (PDB 2VDO, IntAct ELISA) are for the integrin and fibrinogen [DB:PDB 2VDO][DB:IntAct][DB:BioGRID]; the PDB entries are alphaIIbbeta3-related and may not reflect alphaV.","key_references":[{"PMID":"15031111","why":"Trophoblast adhesion to fibrinogen via beta3 integrins"}],"covers":["LR000646","LR004130"]},"LR001825":{"pair":"FGL1 -> LAG3","headline":"FGL1 binds LAG-3 with nanomolar affinity and inhibits T cell activation; well supported.","interaction_type":"direct binding","direction_and_effect":"FGL1 is a major LAG-3 functional ligand independent of MHC-II; it inhibits antigen-specific T cell activation, FGL1 ablation in mice promotes T cell immunity, and antibody blockade of the interaction stimulates tumour immunity [PMID:30580966]. UniProt lists FGL1 as a LAG3 ligand [DB:UniProt].","molecular_requirements":"MHC-II is the canonical LAG-3 ligand, but FGL1 acts independently of it [PMID:30580966]. Other requirements not reported.","affinity_potency":[{"value":"Kd ~1.5 nM","assay":"Octet bio-layer interferometry","system":"FGL1 with LAG3","cite":"PMID:30580966"}],"species_and_systems":"Interaction conserved in human and mouse; mouse tumour models used for blockade [PMID:30580966].","localisation_and_range":"FGL1 is a liver-secreted protein [PMID:30580966]; FGL1 flagged secreted and LAG3 transmembrane [flag]; acts at range.","caveats":"Paper read as abstract plus excerpts. Single primary paper, with IntAct recording bio-layer interferometry from it [DB:IntAct]; UniProt cites follow-up papers [DB:UniProt]. Mouse pair is ortholog-inferred.","key_references":[{"PMID":"30580966","why":"Identifies FGL1 as MHC-II-independent LAG-3 ligand, Kd ~1.5 nM"}],"covers":["LR001825","LR005180"]},"LR002644":{"pair":"FLRT1 -> UNC5B","headline":"FLRT1 binds UNC5B, weakly in one paper and near saturation in a binding screen.","interaction_type":"conflicting","direction_and_effect":"All FLRT1-3 and Unc5A-D combinations bound at or near saturation in a high-throughput binding screen with ELISA titration [PMID:26633812]. Another paper found FLRT1 showed only relatively weak binding to Unc5B [PMID:21673655].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Purified ectodomains, CHO.K1 aggregation and mouse retina [PMID:26633812]; species of the other paper not stated. Human pair ortholog-inferred.","localisation_and_range":"FLRT1 flagged secreted and transmembrane [flag]; contact-mediated.","caveats":"Binding strength disagrees between papers [PMID:21673655][PMID:26633812]. One was a browser-read quote pending spot-check [PMID:21673655]. No affinity values.","key_references":[{"PMID":"26633812","why":"FLRT x Unc5 binding screen"},{"PMID":"21673655","why":"FLRT1 weak on Unc5B; FLRT2-Unc5D specificity"}],"covers":["LR002644","LR005910"]},"LR005911":{"pair":"FLRT1 -> UNC5C","headline":"FLRT1 binds UNC5C directly in a full-text extracellular binding screen; one paper, no affinity reported.","interaction_type":"direct binding","direction_and_effect":"A high-throughput extracellular binding screen found all three FLRTs binding all four Unc5s near saturation (mean Abs650nm value = 2.14), with ELISA titration on purified protein and CHO.K1 cell aggregation [PMID:26633812]. In stripe assays FLRT1 elicited attraction (16%) or repulsion (5%) in a small share of neurons, and Unc5C repelled 11% [PMID:26633812]; whether the FLRT1-UNC5C pair drives these responses was not tested in our evidence.","molecular_requirements":"Purified ectodomains were used for the ELISA titrations and full-length proteins for the cell aggregation assay; subunit or co-receptor requirements are not reported in our evidence.","affinity_potency":[],"species_and_systems":"Binding screen used purified ectodomains and CHO.K1 cells; neurite assays used mouse retinal neurons. The record covers a human and a mouse pair; the paper's species labels in the curated row are human for both partners [PMID:26633812].","localisation_and_range":"Both partners carry transmembrane flags and the cell aggregation assay indicates interaction between opposing cell surfaces (contact-mediated) [PMID:26633812]; FLRT1 is also flagged secreted [flag].","caveats":"Single paper only; the pair-specific functional effect is not shown. Retinal neurons repelled by Unc5C expressed FLRT2 but not FLRT1 or FLRT3 [PMID:26633812].","key_references":[{"PMID":"26633812","why":"Full-text screen showing all FLRT x Unc5 pairs bind near saturation."}],"covers":["LR002645","LR005911"]},"LR002653":{"pair":"FLRT2 -> UNC5B","headline":"FLRT2 signals through UNC5B to cause endothelial repulsion; binding supported by a binding screen, with one abstract-level negative.","interaction_type":"direct binding","direction_and_effect":"A high-throughput extracellular binding screen found all three FLRTs binding all four Unc5s near saturation (mean Abs650nm value = 2.14), with ELISA titration on purified protein and CHO.K1 cell aggregation [PMID:26633812]. In mice, endothelial FLRT2 knockout caused aberrant endothelial alignment in the placental labyrinth, related to endothelial repulsion through binding to UNC5B [PMID:28576770]; the curated row labels the effect antagonist. UniProt notes UNC5B binds FLRT2 and FLRT3, with higher affinity for FLRT3 [DB:UniProt, PMID:25374360].","molecular_requirements":"Extracellular domains interact [DB:UniProt, PMID:25374360]; co-receptors are not reported in our evidence.","affinity_potency":[],"species_and_systems":"Screen on purified ectodomains and CHO.K1 cells [PMID:26633812]; placental work in mice, with the curated row labelled human [PMID:28576770]. Mouse pair not ortholog-inferred.","localisation_and_range":"FLRT2 flagged secreted and transmembrane [flag]; the placental phenotype is described as inter-endothelial repulsion [PMID:28576770].","caveats":"One abstract-only paper was judged pair_absent because it names FLRT2 as specific to Unc5D and FLRT3 as the Unc5B partner [PMID:21673655]; the later screen contradicts exclusivity. The placental paper was read as abstract only.","key_references":[{"PMID":"26633812","why":"Binding screen covering FLRT2-UNC5B."},{"PMID":"28576770","why":"Endothelial FLRT2/UNC5B repulsion in placenta."}],"covers":["LR002653","LR005919"]},"LR005920":{"pair":"FLRT2 -> UNC5C","headline":"FLRT2 and UNC5C are a repulsive pair in retinal neurons, shown in both orientations in one paper.","interaction_type":"direct binding","direction_and_effect":"A high-throughput extracellular binding screen found all three FLRTs binding all four Unc5s near saturation (mean Abs650nm value = 2.14), with ELISA titration on purified protein and CHO.K1 cell aggregation [PMID:26633812]. Neurons expressing FLRT2 are repelled by Unc5C stripes, and neurons expressing Unc5C are repelled by FLRT2 stripes; full-length FLRT2-myc transfection repelled neurons from Unc5C stripes [PMID:26633812]. FLRT2 and Unc5C expression is complementary in vivo [PMID:26633812].","molecular_requirements":"Not reported in our evidence beyond ectodomain interaction.","affinity_potency":[],"species_and_systems":"Mouse retinal neurons in culture and mouse retina in vivo; binding on purified ectodomains and CHO.K1 cells [PMID:26633812]. Human version is ortholog-inferred.","localisation_and_range":"Interaction between opposing cell surfaces (contact-mediated); FLRT2 also flagged secreted [flag; PMID:26633812].","caveats":"Single paper. Neurons transfected with Unc5C-FLAG were not repelled by Unc5C stripes [PMID:26633812].","key_references":[{"PMID":"26633812","why":"Screen plus FLRT2-Unc5C bidirectional repulsion."}],"covers":["LR002654","LR005920"]},"LR007207":{"pair":"FLRT3:TENM2 -> ADGRL1","headline":"Database-only: UniProt text for the components, no curated paper evidence for this complex.","interaction_type":"database-asserted only","direction_and_effect":"No papers are available. UniProt states TENM2 acts as a ligand of ADGRL1 and ADGRL3 on adjacent cells [DB:UniProt], and that FLRT3 interacts with ADGRL1/LPHN1 [DB:UniProt].","molecular_requirements":"A joint FLRT3:TENM2 complex binding ADGRL1 is not shown in our evidence; the records describe each member separately.","affinity_potency":[],"species_and_systems":"Not reported in our evidence.","localisation_and_range":"FLRT3 secreted/transmembrane and TENM2 transmembrane by annotation [flag]; UniProt describes cell-cell contact [DB:UniProt].","caveats":"Two judged rows are pending and no papers shown. Evidence rests on UniProt alone.","key_references":[],"covers":["LR007207"]},"LR002662":{"pair":"FN1 -> CD248","headline":"Reported direct binding of fibronectin to endosialin/TEM1 from a single abstract-level paper.","interaction_type":"direct binding","direction_and_effect":"Fibronectin and collagen types I and IV were identified as specific ligands of endosialin/TEM1; TEM1-expressing cells showed enhanced adhesion to fibronectin and migration [PMID:17986615]. Described as an adhesion-mediating interaction, with the curator assigning agonist.","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human, per curator fields; mouse pair inferred by orthology from human evidence [PMID:17986615].","localisation_and_range":"FN1 is flagged secreted, CD248 transmembrane [flag]; matrix-to-cell contact.","caveats":"One paper, read as an abstract only. The abstract does not give an affinity or binding assay type.","key_references":[{"PMID":"17986615","why":"identifies FN as a specific ligand of endosialin/TEM1"}],"covers":["LR002662","LR005928"]},"LR004138":{"pair":"FN1 -> CD44","headline":"Direct binding of CD44 to the C-terminal heparin-binding domain of fibronectin is shown by one 1992 paper plus BioGRID records.","interaction_type":"direct binding","direction_and_effect":"Affinity-purified CD44 bound fibronectin, mediated through the chondroitin sulfate-containing form of CD44; the binding site on fibronectin is its COOH-terminal heparin-binding domain [PMID:1730778]. Binding was inhibited by chondroitin sulfate and by the syndecan ectodomain [PMID:1730778].","molecular_requirements":"Binding required the chondroitin sulfate-modified CD44 form [PMID:1730778].","affinity_potency":[],"species_and_systems":"Human proteins per curator fields; mouse pair is orthology-inferred [PMID:1730778]. BioGRID lists affinity capture-Western and reconstituted-complex records [DB:BioGRID].","localisation_and_range":"FN1 flagged secreted, CD44 flagged both secreted and transmembrane [flag]; matrix-to-cell contact.","caveats":"Only one confirmed paper; no affinity reported. The cell source for the CD44 isolation is not stated in our evidence.","key_references":[{"PMID":"1730778","why":"CD44 binds the COOH-terminal heparin-binding domain of fibronectin"}],"covers":["LR000654","LR004138"]},"LR000655":{"pair":"FN1 -> COL13A1","headline":"Direct binding of the type XIII collagen ectodomain to fibronectin is shown by SPR, from one abstract-level paper.","interaction_type":"direct binding","direction_and_effect":"By surface plasmon resonance, the recombinant COL13A1 ectodomain interacted with immobilized fibronectin [PMID:11956183]. Effect on signalling is not reported in our evidence.","molecular_requirements":"Fibronectin binding mapped to the collagenous domains of the ectodomain, which forms 240-kDa trimers [PMID:11956183].","affinity_potency":[{"value":"KD in the nanomolar range","assay":"surface plasmon resonance","system":"recombinant shed ectodomain on immobilized fibronectin","cite":"PMID:11956183"}],"species_and_systems":"Human, per curator fields; recombinant ectodomain purified from insect cell culture; mouse pair orthology-inferred [PMID:11956183].","localisation_and_range":"COL13A1 is flagged transmembrane; the ectodomain is shed [PMID:11956183]; FN1 secreted [flag].","caveats":"Single paper read as an abstract only; no exact KD value in our evidence.","key_references":[{"PMID":"11956183","why":"SPR binding of the collagen XIII ectodomain to fibronectin"}],"covers":["LR000655","LR004139"]},"LR007018":{"pair":"FN1 -> ITGA2:ITGB1","headline":"No curated paper supports fibronectin binding to ITGA2:ITGB1; evidence is generic fibronectin-integrin database records.","interaction_type":"database-asserted only","direction_and_effect":"Database records show fibronectin with ITGB1 (BioGRID reconstituted complex, affinity capture-Western) and IntAct SPR/FACS records [DB:BioGRID] [DB:IntAct]. The structural and pathway records are for the alpha5beta1 complex with fibronectin [DB:PDB 7NWL] [DB:Reactome]. Direction and effect are not reported for this pair.","molecular_requirements":"ITGA2:ITGB1 is a complex; the cited records concern ITGB1 or alpha5beta1, not this alpha chain, so alpha-chain specificity is not shown in our evidence.","affinity_potency":[],"species_and_systems":"Human proteins; BioGRID and IntAct experiment species not stated in our evidence.","localisation_and_range":"FN1 flagged secreted; the integrin complex is flagged transmembrane or receptor [flag].","caveats":"No confirmed paper. Support is inferred from ITGB1/alpha5beta1 records.","key_references":[],"covers":["LR007018"]},"LR004147":{"pair":"FN1 -> ITGAV","headline":"Fibronectin binds alphaV-containing integrins, backed by force spectroscopy, reconstitution and structures.","interaction_type":"direct binding","direction_and_effect":"FN1 is an agonist ligand; alphaV-class integrins and alpha5beta1 solely recognise the FN RGD motif, and alphaV-class integrins retain FN-RGE binding [PMID:33141174]. In a neuroblastoma extract, liposomes with all three polypeptides bound vitronectin, fibronectin and type I collagen [PMID:1693626].","molecular_requirements":"AlphaV pairs with a beta chain; a novel beta1-like subunit with alphaV mediated fibronectin/collagen binding, while alphaVbeta3 gave vitronectin binding [PMID:1693626]. Databases cover ITGB3-FN1 and PDB structures with a P05106 chain [DB:PDB 4MMX].","affinity_potency":[],"species_and_systems":"Human cells [PMID:1693626, PMID:33141174]. PMID:15031111 used human FN on mouse trophoblast.","localisation_and_range":"FN1 is flagged secreted and as a receptor, not transmembrane [flag]; the dossier gives no range beyond that.","caveats":"Abstract-only for two papers. PMID:15031111 concerns alphaIIbbeta3, not alphaV (curation flag). Two other judged rows were assigned to a different entity.","key_references":[{"PMID":"33141174","why":"alphaV-class integrins bind the FN RGD motif"},{"PMID":"1693626","why":"Reconstituted liposomes bind fibronectin"}],"covers":["LR000663","LR004147"]},"LR007027":{"pair":"FN1 -> ITGAV:ITGB5","headline":"Only database records, mostly for alphaVbeta3; one paper judged insufficient.","interaction_type":"database-asserted only","direction_and_effect":"Direction and effect not reported in our evidence; class is annotated Adhesion-Adhesion [flag].","molecular_requirements":"Not reported in our evidence for the beta5 pairing specifically. BioGRID has ITGB5-FN1 affinity capture-western [DB:BioGRID].","affinity_potency":[],"species_and_systems":"Not reported in our evidence.","localisation_and_range":"FN1 is flagged secreted and as a receptor, not transmembrane [flag]; the dossier gives no range beyond that.","caveats":"No confirmed paper. PDB, IntAct and Reactome records are for alphaVbeta3 or alphaIIbbeta3 [DB:PDB 4MMX][DB:Reactome]; only the BioGRID record names ITGB5.","key_references":[],"covers":["LR007027"]},"LR000664":{"pair":"FN1 -> ITGB1","headline":"Fibronectin binds beta1 integrins, with cryo-EM and SPR data, but papers span several alpha partners.","interaction_type":"direct binding","direction_and_effect":"FN1 acts on alpha5beta1 with structural opening of the integrin [PMID:33962943]; muscle-secreted FN1 acts via hepatic alpha5beta1 [PMID:36812915]. Annotated stimulatory [flag].","molecular_requirements":"ITGB1 requires an alpha partner. Cryo-EM of human alpha5beta1 with fibronectin shows interactions at the RGD loop, synergy site and a new site [PMID:33962943]. Other papers show alpha3beta1 binding depends on the ninth type III repeat [PMID:26318455], alpha4beta1 for CS-1 [PMID:9842903], alpha8beta1 [PMID:7626807], and alpha5beta1 for hESC adhesion [PMID:18599809].","affinity_potency":[],"species_and_systems":"Human cryo-EM [PMID:33962943]; hESC [PMID:18599809]; human T cells [PMID:9842903]; human chondrocytes [PMID:7688313]; exercised mice [PMID:36812915].","localisation_and_range":"FN1 is flagged secreted and as a receptor, not transmembrane [flag]; the dossier gives no range beyond that.","caveats":"Many rows are abstract-only and concern different alpha chains, so this pair does not say which alpha is needed. PMID:7688313 only shows anti-beta1 blocking of chondrocyte adhesion. Databases support FN1-ITGB1 [DB:BioGRID][DB:UniProt].","key_references":[{"PMID":"33962943","why":"Cryo-EM structure of alpha5beta1 with fibronectin"},{"PMID":"26318455","why":"SPR of alpha3beta1 binding to fibronectin fragments"},{"PMID":"36812915","why":"In vivo mouse role of FN1 via alpha5beta1"}],"covers":["LR000664","LR004148"]},"LR005182":{"pair":"FNDC5 -> ITGB5","headline":"Irisin interacts with alphaV/beta5 integrin in biophysical studies; single paper.","interaction_type":"direct binding","direction_and_effect":"Biophysical studies identified interacting surfaces between irisin and alphaV/beta5 integrin; alphaV inhibition blocked irisin signalling in osteocytes and fat cells [PMID:30550785].","molecular_requirements":"Acts via the alphaV/beta5 heterodimer [PMID:30550785].","affinity_potency":[],"species_and_systems":"Cells and mice; FNDC5-null mice resisted ovariectomy-induced osteolysis [PMID:30550785].","localisation_and_range":"FNDC5 flagged secreted [flag]; muscle-secreted hormone [PMID:30550785].","caveats":"One paper; the inhibition used a general alphaV inhibitor, not beta5-specific. No affinity reported. No database record.","key_references":[{"PMID":"30550785","why":"Irisin interacts with alphaV/beta5 integrin"}],"covers":["LR001827","LR005182"]},"LR004156":{"pair":"FSHB -> FSHR","headline":"Established FSH-FSHR hormone-receptor pair supported by structures and databases; no curator-verified papers in our evidence.","interaction_type":"database-asserted only","direction_and_effect":"GtoPdb lists FSHB-FSHR as an agonist interaction [DB:GtoPdb]. UniProt says FSHB binds FSHR to activate downstream signalling [DB:UniProt].","molecular_requirements":"FSH is a CGA:FSHB heterodimer binding FSHR [DB:UniProt]; crystal structures of FSH with the receptor are PDB 1XWD and 4AY9 [DB:PDB 1XWD].","affinity_potency":[],"species_and_systems":"Structures are of the human complex [DB:PDB 1XWD]; mouse row is inferred.","localisation_and_range":"FSHB flagged secreted; FSHR flagged transmembrane receptor [flag].","caveats":"Papers judged were abstract_insufficient or unresolvable, so no verified paper; GtoPdb affinity units are not given. Co-subunit CGA is needed per UniProt.","key_references":[],"covers":["LR000672","LR004156"]},"LR000673":{"pair":"GALP -> GALR1","headline":"Human GALP binds GALR1 in transfected human cells (IC50 77 nM); a single abstract-level paper plus GtoPdb.","interaction_type":"direct binding","direction_and_effect":"GALP acts as an agonist at GALR1; competition binding in SH-SY5Y cells showed lowest affinity of the three subtypes [PMID:15944009]. GtoPdb lists an agonist action [DB:GtoPdb].","molecular_requirements":"Subunit or co-receptor requirements are not reported in our evidence. GALP(3-32) is at least as potent as full-length GALP(1-60) in the same study [PMID:15944009].","affinity_potency":[{"value":"IC50 = 77 nM","assay":"competition ligand binding","system":"human neuroblastoma SH-SY5Y cells transfected with the receptor, human GALP(1-60)","cite":"PMID:15944009"}],"species_and_systems":"Human receptor in transfected human SH-SY5Y cells; the dossier lists the ligand species as porcine for the experiment. The mouse pair is projected from human evidence.","localisation_and_range":"GALP is flagged as secreted and the receptor as a transmembrane receptor [flag].","caveats":"Single paper, abstract only; other papers are pending. GALP shares its N-terminal 13 residues with galanin, so cross-reactivity with galanin receptors is expected, not specific [PMID:15944009].","key_references":[{"PMID":"15944009","why":"Ligand binding of human GALP(1-60) at GalR1, GalR2 and GalR3"}],"covers":["LR000673","LR004157"]},"LR007216":{"pair":"GALP -> GALR3:GPR151","headline":"No primary evidence for a GALR3:GPR151 complex; support is for GALR3 alone from GtoPdb.","interaction_type":"database-asserted only","direction_and_effect":"Not reported in our evidence for the complex. GtoPdb lists GALP as an agonist at GALR3 alone [DB:GtoPdb].","molecular_requirements":"Whether GPR151 is needed is not reported in our evidence.","affinity_potency":[],"species_and_systems":"No experiments for this complex are in our evidence; the papers judged were review-only or had insufficient abstracts.","localisation_and_range":"GALP is flagged as secreted; the receptor entry is flagged as a transmembrane receptor [flag].","caveats":"Support rests on GALR3 records, not on GPR151 participation [DB:GtoPdb]. Treat as the single-receptor pair. One paper was judged a different entity.","key_references":[],"covers":["LR007216"]},"LR012445":{"pair":"GAS1 -> PTCH1:SMO","headline":"GAS1 is described as a Hedgehog co-receptor handing SHH to PTCH1; no judged paper, database assertion only.","interaction_type":"database-asserted only","direction_and_effect":"UniProt describes GAS1 as a coreceptor that binds dually lipid-modified ShhN downstream of CDON-BOC and transfers it to PTCH1 or PTCH2, followed by activation [DB:UniProt]. Reactome lists a Hh-Npp:GAS1:PTCH complex in the ciliary membrane [DB:Reactome].","molecular_requirements":"GAS1 acts as a co-receptor for ShhN handoff to PTCH1 [DB:UniProt]. Whether SMO is directly bound is not reported in our evidence.","affinity_potency":[],"species_and_systems":"No judged paper; two papers are pending. Experimental species are not reported in our evidence.","localisation_and_range":"GAS1 is flagged as non-secreted and as a receptor [flag]; the evidence points to a membrane-bound co-receptor, so this is not a classical secreted ligand.","caveats":"This pair rests on databases alone. GAS1 is itself a co-receptor, so GAS1 -> PTCH1:SMO may not be a direct ligand-receptor binding event.","key_references":[],"covers":["LR012445"]},"LR004165":{"pair":"GAS6 -> TYRO3","headline":"Direct agonist interaction supported by binding and reporter studies; affinity in the low nM range.","interaction_type":"direct binding","direction_and_effect":"GAS6 is a ligand for TYRO3 (also called Sky/Rse) [PMID:7867073] and stimulated Sky phosphorylation in CHO cells [PMID:8939948]. Reporter-cell activation depends on context [PMID:25074926].","molecular_requirements":"Gas6 bound soluble Sky-Fc [PMID:8939948]; Gla domain and EGF-like repeats were not required for binding to Rse, and the G-domain region activated Rse phosphorylation [PMID:8621659]. Gamma-carboxylation of ligands is essential for full TAM activation [PMID:25074926].","affinity_potency":[{"value":"Kd 2.7 nM","assay":"BIAcore kinetic analysis, rat Gas6 to Sky-Fc","system":"soluble receptor-Fc fusion","cite":"PMID:8939948"}],"species_and_systems":"Curators record human ligand and receptor; the Kd used rat Gas6 [PMID:8939948]. The mouse pair is projected from human evidence.","localisation_and_range":"GAS6 is flagged secreted and TYRO3 transmembrane [flag].","caveats":"All papers were read as abstracts only; two more were review-only. Protein S is also a TYRO3 ligand [PMID:7867073], so TYRO3 is not specific to GAS6.","key_references":[{"PMID":"8939948","why":"Kd of Gas6 for Sky-Fc"},{"PMID":"7867073","why":"Identifies Gas6 and protein S as Tyro 3/Axl ligands"},{"PMID":"8621659","why":"G-domain region binds and activates Rse"}],"covers":["LR000681","LR004165"]},"LR000682":{"pair":"GAST -> CCKBR","headline":"Functional agonist evidence from gastrin I in CHO cells expressing human CCK-B receptor; direct gastrin binding is not shown.","interaction_type":"functional only","direction_and_effect":"Gastrin I markedly augmented phosphoinositide hydrolysis and cytosolic free calcium in CHO cells expressing the human CCK-B receptor, and dose-dependently increased [3H]thymidine incorporation [PMID:8349705]. GtoPdb lists an agonist [DB:GtoPdb].","molecular_requirements":"Not reported in our evidence beyond the single receptor.","affinity_potency":[],"species_and_systems":"Human brain CCK-B receptor expressed in CHO cells; human ligand [PMID:8349705]. The mouse pair is projected from human evidence.","localisation_and_range":"GAST is flagged secreted and CCKBR transmembrane [flag].","caveats":"Human CCK-B receptor had slightly but significantly higher affinity for CCK-8 than for gastrin I, so CCK is the preferred ligand in that system [PMID:8349705]. The cloning paper did not test gastrin binding directly; identity of the CCK-B and gastrin receptors was inferred from sequence and Southern blots [PMID:7681836]. Both papers are abstract-only. The ligand entity is named desulfated gastrin-14, but the paper tested gastrin I; sulfation state is not reported in our evidence. Structures exist [DB:PDB 7F8V].","key_references":[{"PMID":"8349705","why":"Gastrin I activates signalling and growth via human CCK-B receptor"},{"PMID":"7681836","why":"Cloning of the human CCK-B/gastrin receptor, gastrin not directly tested"}],"covers":["LR000682","LR004166"]},"LR002671":{"pair":"GC -> LRP2","headline":"Thinly supported: one abstract-only paper with antibody blockade and co-localisation of Gc-globulin with megalin; no direct binding data.","interaction_type":"functional only","direction_and_effect":"Megalin/gp330 is reported to mediate Ca2+-dependent internalisation of Gc-globulin by hepatic stellate cells; a neutralising anti-megalin antibody decreased intracellular gc-globulin, an effect enhanced by EDTA, and confocal microscopy showed co-localisation [PMID:18194670]. This is clearance/uptake, not signalling.","molecular_requirements":"Ca2+ dependence is reported [PMID:18194670]. Megalin was one of at least four candidate gc-globulin receptors on these cells (megalin, CD44, cubilin, annexin A2) [PMID:18194670]; whether others are needed is not reported in our evidence.","affinity_potency":[],"species_and_systems":"Hepatic stellate cells with hepatocyte-derived gc-globulin; curators label both partners human, but the abstract does not state the species [PMID:18194670]. Both human and mouse pairs are ortholog-projected.","localisation_and_range":"GC is flagged secreted and LRP2 as a receptor [flag].","caveats":"Abstract-only. A competitive antibody and co-localisation do not prove direct binding. BioGRID lists an affinity-capture western record for GC-LRP2 [DB:BioGRID].","key_references":[{"PMID":"18194670","why":"Megalin-dependent uptake of gc-globulin by hepatic stellate cells"}],"covers":["LR002671","LR005936"]},"LR010816":{"pair":"GDF10 -> ACVR2B","headline":"Database-asserted only: GtoPdb agonist record; no verified paper.","interaction_type":"database-asserted only","direction_and_effect":"GtoPdb lists GDF10 as agonist of ACVR2B [DB:GtoPdb].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Not reported in our evidence.","localisation_and_range":"GDF10 is flagged secreted and non-transmembrane [flag], so signalling would be paracrine or autocrine; range not studied in our evidence.","caveats":"No judged papers (three screened were review-only or abstract-insufficient). Affinity not reported.","key_references":[],"covers":["LR010816"]},"LR002680":{"pair":"GDF11 -> ACVR1C","headline":"GDF11 can interact with ALK7 but signals mainly through ALK4 and ALK5; a weaker secondary receptor.","interaction_type":"functional only","direction_and_effect":"GDF11 can interact with ALK7 but predominantly activates the Smad3 reporter through ALK4 and ALK5 [PMID:16845371].","molecular_requirements":"Not reported for ALK7 beyond interaction in a type I receptor panel [PMID:16845371].","affinity_potency":[],"species_and_systems":"Mouse embryo context in the abstract [PMID:16845371]; both human and mouse pairs are ortholog-inferred.","localisation_and_range":"GDF11 flagged secreted [flag].","caveats":"Single abstract-only paper; ALK7 is not shown to mediate the paper's in vivo phenotypes (a heterozygous Alk7 mutation did not potentiate them). No affinity.","key_references":[{"PMID":"16845371","why":"GDF11 interacts with ALK7 among a type I receptor panel"}],"covers":["LR002680","LR005945"]},"LR007225":{"pair":"GDF11 -> ACVR2A:TGFBR1","headline":"Database-asserted only: a ternary PDB structure exists but with ActRIIB, not ACVR2A; no verified paper.","interaction_type":"database-asserted only","direction_and_effect":"PDB 6MAC is described as a ternary structure of GDF11 bound to ActRIIB-ECD and Alk5-ECD [DB:PDB 6MAC]. UniProt: GDF11 interacts directly with ACVR2A (By similarity) [DB:UniProt].","molecular_requirements":"The structure suggests an ActRIIB plus ALK5 (TGFBR1) assembly, which is a different type II chain from ACVR2A [DB:PDB 6MAC].","affinity_potency":[],"species_and_systems":"Species of the structure not reported in our evidence.","localisation_and_range":"GDF11 flagged secreted [flag].","caveats":"No judged papers; the complex with ACVR2A is not itself evidenced.","key_references":[],"covers":["LR007225"]},"LR004174":{"pair":"GDF2 -> ACVR1","headline":"BMP-9 (GDF2) binds ALK2 weakly alone, strongly with BMPR-II or ActR-II, and signals through ALK2 in myoblasts and ovarian cells.","interaction_type":"direct binding","direction_and_effect":"In transfected COS cells BMP-9 bound weakly to ALK2, and binding was greatly facilitated by co-expressed BMPR-II or ActR-II [PMID:17311849]. In ovarian cells BMP9 signalled predominantly via ALK2/Smad1/Smad4 rather than ALK1 [PMID:19996292]. UniProt: interacts with ACVR1 [DB:UniProt]; GtoPdb agonist [DB:GtoPdb].","molecular_requirements":"Type II partner (BMPR-II or ActR-II) increases ALK2 binding; ALK2, ActRIIA and BMPRII were required in ovarian cells [PMID:17311849][PMID:19996292].","affinity_potency":[],"species_and_systems":"Transfected COS cells and myoblasts [PMID:17311849]; ovarian surface epithelial and cancer lines [PMID:19996292]. Mouse pair is ortholog-inferred.","localisation_and_range":"BMP9 can act in an autocrine fashion in ovarian cancer lines [PMID:19996292].","caveats":"Both papers are abstract-level for this pair; ALK1 is the high-affinity receptor in endothelial cells [PMID:17311849], so ALK2 is a weaker, context-dependent receptor. No numeric affinity.","key_references":[{"PMID":"17311849","why":"BMP-9 binding to ALK2 enhanced by type II receptors"},{"PMID":"19996292","why":"BMP9 signals through ALK2 in ovarian cells"}],"covers":["LR000690","LR004174"]},"LR000691":{"pair":"GDF2 -> ACVR2A","headline":"BMP-9 binds the type-II receptor ActRIIA weakly; signalling through it is shown in endothelial and ovarian cells, with ALK1 or ALK2 as the type-I partner.","interaction_type":"direct binding","direction_and_effect":"BMP-9 acts as an agonist: knockdown of ActRIIA and/or BMPRII reduced BMP9-induced BRE-luciferase reporter activity in IOSE397 ovarian surface epithelial cells [PMID:19996292]. In endothelial cells, BMP9 induction of EphrinB2 depended on Alk1 and at least one of BMPRII or ActRII [PMID:22622516]. GtoPdb lists it as agonist [DB:GtoPdb].","molecular_requirements":"ActRIIA acts as a type-II receptor alongside a type-I receptor: ALK1 in endothelial cells [PMID:22622516], or an ALK2/ActRIIA/BMPRII complex in IOSE397 cells [PMID:19996292]. BMPRII can substitute for ActRIIA in the endothelial readout [PMID:22622516].","affinity_potency":[],"species_and_systems":"Binding was reported in transfected COS cells (weak for ActR-II, high for ALK1 and endoglin) [PMID:17311849]. The curator-verified BMP9 papers are largely human cell systems (IOSE397 ovarian cells, endothelial cells); the mouse pair is projected from human evidence.","localisation_and_range":"BMP-9 is flagged as secreted and non-transmembrane, the receptor as transmembrane [flag]; this implies paracrine/endocrine signalling to a cell-surface receptor (from annotation flags only).","caveats":"Binding to ActRIIA is weak compared with ALK1 [PMID:17311849]. Two of the four papers were read as abstracts only [PMID:17311849][PMID:22622516]. The 22718755 abstract reports type-II discrimination by BMP9 but does not give ActRIIA values in our evidence [PMID:22718755]. BioGRID lists reconstituted-complex records [DB:BioGRID].","key_references":[{"PMID":"19996292","why":"ActRIIA/BMPRII knockdown reduces BMP9 reporter activity (full text)"},{"PMID":"17311849","why":"BMP-9 binding to ActR-II in COS cells"},{"PMID":"22622516","why":"BMP9 signalling needs Alk1 plus BMPRII or ActRII"}],"covers":["LR000691","LR004175"]},"LR008251":{"pair":"GDF5 -> BMPR1A:BMPR2","headline":"Complex pair with no curator-verified paper; rests on BioGRID, IntAct and UniProt records.","interaction_type":"database-asserted only","direction_and_effect":"UniProt says GDF5 binds BMPR1B with high affinity and BMPR1A with less affinity [DB:UniProt]. BioGRID has reconstituted-complex records for GDF5 with BMPR1B and BMPR2 [PMID:9525338][DB:BioGRID].","molecular_requirements":"The complex is assembled from separate subunit records and not shown as a unit in our evidence.","affinity_potency":[],"species_and_systems":"Not reported in our evidence.","localisation_and_range":"The receptor complex is flagged transmembrane [flag].","caveats":"One review-only row judged. The BioGRID records shown name BMPR1B and BMPR2, not BMPR1A [DB:BioGRID]. IntAct entries are SPR records [DB:IntAct].","key_references":[],"covers":["LR008251"]},"LR004183":{"pair":"GDF5 -> BMPR1B","headline":"Well-supported direct GDF5 binding to the type I receptor BMPR1B, by SPR and radioligand binding, with stimulatory Smad signalling.","interaction_type":"direct binding","direction_and_effect":"GDF5 binds BMPR-IB and signals stimulatorily: GDF-5 induced alkaline phosphatase activity in rat ROB-C26 cells and bound BMPR-IB but not BMPR-IA in non-transfected cells [PMID:8702914]. GDF-5 activates Smad1/5/8 in osteoprogenitor cells [PMID:11282024]. UniProt describes high-affinity BMPR1B binding and lower-affinity BMPR1A binding [DB:UniProt].","molecular_requirements":"In COS-1 cells GDF-5 bound BMPR-IB alone among type I receptors; type II receptors (BMPR-II, ActR-II, ActR-IIB) were bound too [PMID:8702914]. Ror2 forms a ligand-independent complex with BRI-b (BMPR1B) and modulates GDF5 signalling [PMID:15569154]. GDF5 Asn445 lies in both the type I receptor and NOGGIN interaction sites in a GDF5:BMPR1B structural model (PDB 3EVS) [PMID:19956691].","affinity_potency":[{"value":"apparent KD 1.3 nM","assay":"SPR biosensor, GDF5 analyte on immobilised BMPR-IB ectodomain","system":"recombinant proteins","cite":"PMID:19735544"}],"species_and_systems":"Binding: recombinant SPR [PMID:19735544]; 125I-GDF-5 on rat ROB-C26 cells and COS-1 transfectants [PMID:8702914]; iodinated GDF5 crosslinking in COS7 cells with BRI-b-HA, construct species not stated [PMID:15569154]. Pair is recorded for human and mouse.","localisation_and_range":"Ligand is flagged secreted [flag], so signalling is expected to be paracrine; not otherwise reported in our evidence.","caveats":"PMID:15569154 was read only as an abstract plus a browser-read sentence not yet spot-checked. PMID:11282024 is functional (Smad activation, type I receptor synergy), not binding. PMID:19956691 supports the pair only through a structural model and a C2C12 line stably expressing Bmpr1b.","key_references":[{"PMID":"19735544","why":"SPR affinity of GDF5 for BMPR-IB (1.3 nM)"},{"PMID":"8702914","why":"Radioligand binding and receptor specificity of GDF-5"},{"PMID":"15569154","why":"BRI-b/GDF5 binding and Ror2 modulation"}],"covers":["LR000699","LR004183"]},"LR007234":{"pair":"GDF5 -> BMPR1B:BMPR2","headline":"GDF5 binds both BMPR-IB and BMPR-II, and signals through BMPR-IB with BMPR-II; evidence is from abstracts only.","interaction_type":"direct binding","direction_and_effect":"125I-GDF-5 bound BMPR-IB and BMPR-II but not BMPR-IA in ROB-C26 and other non-transfected cells, and a transcriptional signal was efficiently transduced by BMPR-IB together with BMPR-II or ActR-II [PMID:8702914]. CDMP-1 (named as GDF5 in the curator notes) bound BMPR-IB and BMPR-II, and weakly BMPR-IA; a reporter signal was transduced by BMPR-IB in the presence of BMPR-II [PMID:9525338]. Effect is stimulatory (Smad-based signalling).","molecular_requirements":"Both chains are supported: BMPR-IB as the type I chain and BMPR-II as a type II partner; ActR-II can substitute for BMPR-II in signalling [PMID:8702914]. Whether BMPR-II alone, without BMPR-IB, suffices for signalling is not reported in our evidence.","affinity_potency":[],"species_and_systems":"ROB-C26 rat osteoprogenitor line and COS-1 transfectants [PMID:8702914]; ATDC5, ROB-C26, MC3T3-E1 and primary chondrocytes [PMID:9525338]. Human pair only is listed.","localisation_and_range":"Ligand is flagged secreted [flag], so signalling is expected to be paracrine; not otherwise reported in our evidence.","caveats":"Both key papers were judged on abstracts only. Four further papers were review_only and one abstract_insufficient, so were not used. Ror2 modulates BRI-b/GDF5 signalling [PMID:15569154], a further component not captured by this pair. Database records (BioGRID reconstituted complex, IntAct SPR) exist for the individual GDF5 receptor chains [DB:BioGRID] [DB:IntAct].","key_references":[{"PMID":"8702914","why":"Binding to BMPR-IB and BMPR-II; signalling needs both"},{"PMID":"9525338","why":"Independent confirmation of BMPR-IB/BMPR-II use"},{"PMID":"15569154","why":"BRI-b/GDF5 signalling modulated by Ror2"}],"covers":["LR007234"]},"LR007243":{"pair":"GDF7 -> ACVR2B:BMPR1B","headline":"GDF7 -> ACVR2B:BMPR1B: functional evidence only, from one abstract-only paper; chains not shown together.","interaction_type":"functional only","direction_and_effect":"ALK6 overexpression conferred GDF7 signalling in COS7 cells [PMID:16049014]. ACVR2B itself is not named in the cited sentence. GtoPdb lists agonist records for the individual chains [DB:GtoPdb].","molecular_requirements":"Complex of ACVR2B and BMPR1B (ALK6). Evidence comes from separate manipulations (receptor overexpression or shRNA of one chain), not from a test of the assembled pair [PMID:16049014]. Whether one chain alone suffices is not reported in our evidence.","affinity_potency":[],"species_and_systems":"COS7 transfectants and MC3T3 cells with shRNA and Smad1/5/8 reporters; curator species fields are blank or human, abstract-only [PMID:16049014].","localisation_and_range":"Ligand is flagged secreted and the receptor complex as transmembrane [flag], implying paracrine signalling to a cell-surface receptor; not otherwise reported in our evidence.","caveats":"Single abstract-only paper. No binding or affinity data for the assembled complex in our evidence. Direct binding of GDF7 to the individual chains is documented in other rows, not this one.","key_references":[{"PMID":"16049014","why":"Receptor overexpression and shRNA define the type I and type II requirements for GDF7."}],"covers":["LR007243"]},"LR010762":{"pair":"GDF9 -> ACVR1B:BMPR2","headline":"GDF9 binds BMPR2 directly (coprecipitation); the ACVR1B chain rests on GtoPdb only.","interaction_type":"direct binding","direction_and_effect":"The BMPRII ectodomain directly interacted with GDF-9 in a coprecipitation study, and BMPRII ectodomain-Fc most effectively blocked GDF-9 action on granulosa cells [PMID:12135884]. BioGRID lists a reconstituted BMPR2-GDF9 complex [DB:BioGRID]; GtoPdb lists agonist records for ACVR1B and BMPR2 [DB:GtoPdb].","molecular_requirements":"BMPR2 (type II) is supported by the paper. ACVR1B as the type I partner is supported only by GtoPdb; the abstract names BMPR-IA, BMPR-IB and ActR-IIA as partial blockers, not ACVR1B [PMID:12135884].","affinity_potency":[],"species_and_systems":"Cultured granulosa cells with receptor ectodomain-Fc chimeras; species not reported in our evidence; abstract-only [PMID:12135884].","localisation_and_range":"GDF-9 is described as secreted by the oocyte, acting on granulosa cells [PMID:12135884]; ligand secreted flag also set [flag].","caveats":"Abstract-only. No affinity values. The ACVR1B component has no paper support in our evidence.","key_references":[{"PMID":"12135884","why":"BMPRII ectodomain binds GDF-9 and blocks its action."}],"covers":["LR010762"]},"LR004192":{"pair":"GDF9 -> BMPR2","headline":"Direct binding supported: the BMPRII ectodomain co-precipitates GDF-9 and is the most effective blocker; type I partner needed.","interaction_type":"direct binding","direction_and_effect":"GDF-9 acts as an agonist: the BMPRII ectodomain was most effective in blocking GDF-9 stimulation of granulosa cell proliferation and suppression of FSH-stimulated progesterone, and BMPRII antisense oligomers prevented GDF-9-induced thymidine incorporation [PMID:12135884]. BioGRID and GtoPdb agree [DB:BioGRID][DB:GtoPdb].","molecular_requirements":"Signalling requires an unidentified type I partner in addition to BMPRII, per the curator note [PMID:12135884].","affinity_potency":[],"species_and_systems":"Human GDF-9 with rat granulosa cells and neonatal ovary; the human and mouse pair rows are ortholog-inferred, not tested directly [PMID:12135884].","localisation_and_range":"GDF9 is flagged as secreted and non-transmembrane [flag], so signalling is paracrine/autocrine; the receptor is flagged transmembrane [flag].","caveats":"Only one paper, read as abstract; binding was by ectodomain co-precipitation, not full-length receptor [PMID:12135884].","key_references":[{"PMID":"12135884","why":"BMPRII ectodomain coprecipitates GDF-9; antisense blocks signalling"}],"covers":["LR000708","LR004192"]},"LR010780":{"pair":"GDF9 -> FXYD6","headline":"Database-asserted only: a two-hybrid pooling interaction record; no curated paper evidence.","interaction_type":"database-asserted only","direction_and_effect":"Direction and effect are not reported in our evidence.","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"IntAct record from a physical association by two-hybrid pooling approach [DB:IntAct]; species of the screen is not stated in our evidence.","localisation_and_range":"GDF9 is flagged secreted [flag]; FXYD6 has no localisation flags.","caveats":"Rests on a high-throughput two-hybrid record alone [PMID:16169070]; the one literature row was review-only. Treat as unverified.","key_references":[{"PMID":"16169070","why":"Source of the IntAct two-hybrid record"}],"covers":["LR010780"]},"LR000709":{"pair":"GDF9 -> TGFBR1","headline":"Functional evidence that GDF9 signals through ALK5 (TGFBR1) in the presence of BMPRII; binding to ALK5 not measured.","interaction_type":"functional only","direction_and_effect":"GDF-9 is an agonist: it stimulated the ALK5-responsive CAGA-luciferase reporter and Smad2/Smad3 phosphorylation in P19 cells, blocked by Smad7; ALK5 overexpression made Cos7 cells responsive; ALK5 siRNA or Smad7 suppressed the response in rat granulosa cells [PMID:14684852]. GtoPdb lists an agonist interaction [DB:GtoPdb].","molecular_requirements":"GDF-9 binds the BMP-activated type II receptor, and its downstream actions are mediated by the type I receptor ALK5 and Smad2/3 [PMID:14684852].","affinity_potency":[],"species_and_systems":"P19 cells, Cos7 reconstitution and rat granulosa cells; the curators record human ligand and receptor [PMID:14684852]. The mouse pair is ortholog-inferred.","localisation_and_range":"GDF9 is flagged as secreted and non-transmembrane [flag], so signalling is paracrine/autocrine; the receptor is flagged transmembrane [flag].","caveats":"Abstract only; direct GDF-9/ALK5 binding was not measured, and ALK5 is also the type I receptor of TGF-beta per the curator note [PMID:14684852].","key_references":[{"PMID":"14684852","why":"GDF-9 signalling needs ALK5 and Smad2/3"}],"covers":["LR000709","LR004193"]},"LR000718":{"pair":"GHRL -> GPR39","headline":"Only obestatin (a different peptide from the ghrelin gene), not ghrelin, was reported to bind GPR39, and that is an abstract-only claim.","interaction_type":"direct binding","direction_and_effect":"The abstract states that obestatin, isolated from rat stomach, bound the orphan receptor GPR39 and that the two peptides activate distinct receptors [PMID:16284174].","molecular_requirements":"Not reported in our evidence beyond the single receptor.","affinity_potency":[],"species_and_systems":"Rat peptide and receptor [PMID:16284174].","localisation_and_range":"Ligand flagged secreted, receptor transmembrane [flag].","caveats":"The ligand shown is obestatin, not mature ghrelin; curator notes say the pairing was later contested and recommend downweighting. Abstract only; no affinity; no database support.","key_references":[{"PMID":"16284174","why":"Obestatin reported to bind GPR39"}],"covers":["LR000718","LR004201"]},"LR010555":{"pair":"GLS2:SLC1A1 -> GRIN1:GRIN2C","headline":"Protein-association records only; no paper confirms GLS2:SLC1A1 -> GRIN1:GRIN2C as a ligand-receptor pair.","interaction_type":"database-asserted only","direction_and_effect":"Direction and effect not reported in our evidence. BioGRID lists affinity capture-Western records between SLC1A1 and NMDA receptor subunits (GRIN1 and GRIN2 chains) [DB:BioGRID][PMID:17459877].","molecular_requirements":"Only the SLC1A1 member of the ligand complex appears in the BioGRID records; the other ligand subunit (GLS/GLS2) is not covered in our evidence [DB:BioGRID].","affinity_potency":[],"species_and_systems":"Not reported in our evidence.","localisation_and_range":"Not reported in our evidence.","caveats":"No paper confirmed; judged papers were different_entity or abstract_insufficient. The records are transporter-receptor co-capture, not binding of a secreted ligand.","key_references":[],"covers":["LR010555"]},"LR009007":{"pair":"GNAI2 -> C5AR1","headline":"GNAI2-C5AR1 is supported only by database interaction records; no curator-confirmed paper.","interaction_type":"database-asserted only","direction_and_effect":"BioGRID lists a co-purification record [DB:BioGRID][PMID:7962171]. Direction and effect as a ligand-receptor pair not reported in our evidence.","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Not reported in our evidence.","localisation_and_range":"Receptor flagged transmembrane where annotated [flag]; otherwise not reported in our evidence.","caveats":"No paper confirmed; judged papers were different_entity, abstract_insufficient, unresolvable or review_only. The records describe protein association, not a ligand activating a receptor.","key_references":[],"covers":["LR009007"]},"LR002707":{"pair":"GPR15LG -> GPR15","headline":"GPR15LG is a well-supported agonist of GPR15; functional evidence in two papers, plus GtoPdb, UniProt and PDB structures.","interaction_type":"functional only","direction_and_effect":"GPR15LG is an agonist of GPR15: it induced dose-dependent beta-arrestin-2 recruitment to GPR15 in NanoBit assays [PMID:40394646], and a ligand purified from porcine colon agonistically activated GPR15 [PMID:28900043]. Gpr15l-deficient skin grafts were protected in mice, implying a role in effector T cell responses [PMID:28900043]. GtoPdb lists an agonist [DB:GtoPdb].","molecular_requirements":"No co-receptor requirement is reported in our evidence.","affinity_potency":[{"value":"EC50 400 nM","assay":"beta-arrestin-2 recruitment, NanoBit","system":"GPR15-expressing cells","cite":"PMID:40394646"}],"species_and_systems":"Ligand purified from porcine colon, tested on human GPR15; human and mouse tissue expression; mouse graft experiments [PMID:28900043]. Recombinant human-protein assays [PMID:40394646].","localisation_and_range":"GPR15LG is flagged as secreted [flag]; the paper calls it a chemokine-like ligand [PMID:28900043]. Structures with both chains are in PDB [DB:PDB 8ZQE] [DB:PDB 9WXM].","caveats":"Three further papers are still pending. The 28900043 abstract does not report a direct binding assay. In 40394646 the GPR15 data are a side result to the CXCR4 work.","key_references":[{"PMID":"28900043","why":"Purification and functional characterisation of GPR15LG as a GPR15 agonist"},{"PMID":"40394646","why":"Beta-arrestin-2 recruitment EC50 for GPR15"}],"covers":["LR002707","LR005972"]},"LR008404":{"pair":"GRN -> SORT1","headline":"Progranulin is endocytosed via sortilin; support is functional plus database binding records.","interaction_type":"direct binding","direction_and_effect":"Sortilin is described as a neuronal receptor mediating extracellular PGRN clearance by endocytosis; SORT1 antagonists and a PGRN-binding small molecule inhibit SORT1-mediated PGRN endocytosis [PMID:24163244]. This is a clearance receptor, not a signalling one.","molecular_requirements":"PGRN residues 588-593 are described as critical for PGRN-SORT1 binding; elastase cleavage between Ala-588 and Leu-589 destroys the SORT1-interaction motif [PMID:24163244].","affinity_potency":[],"species_and_systems":"Human cells (M17 cells, patient-derived iPSC neurons and lymphoblastoid cell lines); the endocytosis assay used M17 cells overexpressing SORT1 [PMID:24163244]. IntAct records include coimmunoprecipitation and a solid-phase assay [DB:IntAct]; PDB structures 8T8R and 8T8S contain both chains [DB:PDB 8T8R] [DB:PDB 8T8S].","localisation_and_range":"GRN is flagged secreted and SORT1 as a transmembrane receptor [flag].","caveats":"The paper's main evidence is functional (siRNA, small molecules); the paper states PGRN's neurotrophic effects are SORT1-independent (cited as other work). Read as abstract with full-text excerpts.","key_references":[{"PMID":"24163244","why":"Sortilin-progranulin axis, PGRN endocytosis"}],"covers":["LR008404"]},"LR001834":{"pair":"GRN -> TNFRSF1B","headline":"Progranulin is reported to bind TNFR2 directly and antagonise TNF-alpha, from one mouse-focused paper.","interaction_type":"direct binding","direction_and_effect":"PGRN bound directly to TNF receptors and disturbed the TNF\u03b1-TNFR interaction; PGRN is called an antagonist of TNF\u03b1 signalling [PMID:21393509].","molecular_requirements":"The abstract says 'TNFRs' in plural; TNFR2 is not named separately. Atsttrin showed selective TNFR binding [PMID:21393509].","affinity_potency":[],"species_and_systems":"Mostly mouse in vivo arthritis models [PMID:21393509]; human pair is ortholog-inferred. IntAct lists solid-phase assay and pull-down records [DB:IntAct].","localisation_and_range":"GRN is flagged secreted; TNFRSF1B is flagged secreted, receptor and transmembrane [flag].","caveats":"Abstract-only reading; receptor-specific (TNFR2) binding is inferred from a plural statement.","key_references":[{"PMID":"21393509","why":"PGRN binds TNFRs and blocks TNF\u03b1"}],"covers":["LR001834","LR005189"]},"LR000727":{"pair":"GRP -> BRS3","headline":"Evidence argues against GRP binding BRS3 in human or mouse; BRS3 is reported as an orphan.","interaction_type":"conflicting","direction_and_effect":"A 2019 study concludes that placental mammalian BRS3 lost binding affinity for NMB/GRP and signals constitutively, ligand-independently [PMID:30840614]. The 2001 paper says BRS-3 has high affinity for no known natural bombesin peptides [PMID:11112777].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human BRS-3 binding to synthetic bombesin analogues (22 peptides tested against hBRS-3, hGRPR and hNMBR) [PMID:11112777]; evolutionary and functional analysis across 17 vertebrate BRS3, including human and mouse [PMID:30840614].","localisation_and_range":"GRP is flagged secreted [flag].","caveats":"Both curated papers argue against the pair; one was confirmed only on comparative binding. In the 2019 paper, only nonplacental vertebrate BRS3 retains GRP/NMB binding [PMID:30840614]. Both read as abstract (the first with excerpts).","key_references":[{"PMID":"30840614","why":"BRS3 is an orphan in placental mammals"},{"PMID":"11112777","why":"BRS-3 has no high-affinity natural bombesin ligand"}],"covers":["LR000727","LR004209"]},"LR006811":{"pair":"GUCA1B -> GUCY2F","headline":"Supported by GtoPdb and a UniProt regulation note; no judged papers.","interaction_type":"database-asserted only","direction_and_effect":"UniProt states GUCY2F is activated by GUCA1B at low free calcium and inhibited at high free calcium [DB:UniProt]; GtoPdb lists an activator [DB:GtoPdb].","molecular_requirements":"Calcium level determines activation versus inhibition [DB:UniProt].","affinity_potency":[],"species_and_systems":"Not reported in our evidence.","localisation_and_range":"Not reported in our evidence.","caveats":"No curated paper confirmation; a different_entity row was recorded. Affinity not given.","key_references":[],"covers":["LR006811"]},"LR005191":{"pair":"HAVCR1 -> HAVCR1","headline":"Homophilic TIM-1 self-binding is supported by structure and binding assays in mouse, with human TIM-1 also shown to bind itself.","interaction_type":"direct binding","direction_and_effect":"Crystal structure of murine TIM-1 identified a homophilic TIM-TIM adhesion interaction [PMID:17363299]. This is a self-adhesion interaction, not a classical ligand-to-receptor signal; effect on signalling is not reported in our evidence.","molecular_requirements":"Mutations in the DE loop of the IgV domain affected homophilic binding. For human TIM-1, high-affinity binding required both IgV and mucin domains, as seen with mouse TIM-1 [PMID:17363299].","affinity_potency":[],"species_and_systems":"Structures and binding were of murine TIM-1; human TIM-1-Fc proteins also bound human TIM-1, with lower affinity than mTIM-1, using Fc proteins and receptor-coated beads on cells [PMID:17363299]. UniProt separately notes HAVCR1 on injured kidney tubular epithelial cells interacts with CD5L, which is a different partner [DB:UniProt].","localisation_and_range":"Membrane-bound adhesion receptor (flag: not secreted), so acts by cell contact [flag].","caveats":"Evidence is a single structural paper read as abstract by curators; no affinity value reported. The UniProt record concerns CD5L, not self-binding [DB:UniProt].","key_references":[{"PMID":"17363299","why":"Structure of mTIM-1 and homophilic binding, conserved in human TIM-1"}],"covers":["LR001836","LR005191"]},"LR000736":{"pair":"HBEGF -> EGFR","headline":"HB-EGF binds and activates EGFR with strong support from binding and functional papers plus several database records.","interaction_type":"direct binding","direction_and_effect":"Synthetic HB-EGF EGF-like domain (44-86) showed high binding affinity to EGFR on A431 cells, like human EGF [PMID:12725245]. HB-EGF induced tyrosine phosphorylation of ErbB2 and ErbB4 and, to a lesser degree, EGFR in mouse cardiac myocytes [PMID:12621152]. Binding to HER1 was shown alongside HER4 [PMID:9135143].","molecular_requirements":"Truncating C-terminal Leu86 caused a drastic reduction in binding [PMID:12725245]. EGFR homodimer requirement not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human A431 cells with synthetic peptide [PMID:12725245]; NIH 3T3 overexpressing HER1 [PMID:9135143]; mouse in vivo [PMID:12621152]. Mouse pair ortholog-inferred.","localisation_and_range":"HB-EGF is flagged secreted and transmembrane, so soluble or juxtacrine [flag].","caveats":"All papers abstract only. In vivo paper shows EGFR phosphorylation weaker than ErbB2/ErbB4 [PMID:12621152]. Databases: BioGRID, IntAct, Reactome, GtoPdb (pKi unit listed, no value) [DB:GtoPdb].","key_references":[{"PMID":"12725245","why":"Binding affinity of HB-EGF EGF domain to EGFR"},{"PMID":"9135143","why":"HB-EGF binds HER1 and HER4"},{"PMID":"12621152","why":"In vivo ErbB phosphorylation by HB-EGF"}],"covers":["LR000736","LR004218"]},"LR004219":{"pair":"HBEGF -> ERBB2","headline":"HB-EGF stimulates ERBB2 phosphorylation in cells, but direct ERBB2 binding is not shown.","interaction_type":"functional only","direction_and_effect":"Recombinant HB-EGF stimulated tyrosine phosphorylation of ErbB1 and ErbB2 and SMC migration, while neuregulin-1 did not [PMID:12958167]. Blocking ErbB1 or ErbB2 reduced EC-stimulated SMC migration by 70-90% [PMID:12958167].","molecular_requirements":"ErbB1 and ErbB2 were both present in the smooth muscle cells, which lacked ErbB3 and ErbB4 [PMID:12958167]; whether ErbB2 acts alone or with ErbB1 is not reported in our evidence.","affinity_potency":[],"species_and_systems":"Primary human endothelial and smooth muscle cells [PMID:12958167]. Mouse pair ortholog-inferred.","localisation_and_range":"Secreted/transmembrane flags [flag]; paracrine from endothelium to smooth muscle in this study [PMID:12958167].","caveats":"Abstract only; phosphorylation readout cannot separate direct ErbB2 binding from transactivation via ErbB1. One further judged row is pending.","key_references":[{"PMID":"12958167","why":"HB-EGF drives ErbB1/ErbB2 phosphorylation in SMC"}],"covers":["LR000737","LR004219"]},"LR000745":{"pair":"HGF -> SDC1","headline":"Syndecan-1 binds HGF through heparan sulfate and presents it to Met; a co-receptor, supported by one abstract-level paper.","interaction_type":"direct binding","direction_and_effect":"Syndecan-1 binds HGF via its heparan sulfate moieties, and this promotes HGF-mediated Met activation and downstream PI3K/PKB and RAS/MAPK signalling in multiple myeloma cells [PMID:11830493]. It acts as a co-receptor presenting HGF to Met, not as an independent signalling receptor [PMID:11830493].","molecular_requirements":"Heparan sulfate chains on syndecan-1 mediate HGF binding; Met is needed for signalling [PMID:11830493].","affinity_potency":[],"species_and_systems":"Human multiple myeloma cells [PMID:11830493]. The mouse pair is ortholog-inferred, not experimentally tested in our evidence.","localisation_and_range":"SDC1 is annotated as a transmembrane receptor, and HGF as secreted [flag].","caveats":"One paper, read as an abstract. BioGRID lists a reconstituted-complex record from the same paper [DB:BioGRID]. Binding is glycan-mediated, so it may be shared with other heparan sulfate proteoglycans.","key_references":[{"PMID":"11830493","why":"Syndecan-1 binds HGF and enhances Met signalling in myeloma"}],"covers":["LR000745","LR004226"]},"LR002716":{"pair":"HLA-A -> CD8A","headline":"Well-supported direct binding: crystal structure and SPR of CD8alphaalpha with class I HLA; CD8 acts as a T-cell co-receptor.","interaction_type":"direct binding","direction_and_effect":"CD8alphaalpha binds HLA-A*2402 in a crystal structure with two opposite alpha3 CD-loop shifts [PMID:21645925]. UniProt reports one HLA-A molecule binds one CD8A homodimer through its alpha-3 domain [DB:UniProt]. The effect is co-receptor function in T cells [PMID:21645925].","molecular_requirements":"A CD8A homodimer (CD8alphaalpha) was used; binding is via the nonpolymorphic alpha-3 domain of HLA-A [PMID:21645925][DB:UniProt]. Mutagenesis localised variation to the alpha3 domain [PMID:10809759].","affinity_potency":[{"value":"Kd 90-220 microM","assay":"surface plasmon resonance, CD8alphaalpha binding to classical class I MHC alleles","system":"human recombinant proteins","cite":"PMID:10809759"}],"species_and_systems":"Human proteins in both papers [PMID:21645925][PMID:10809759].","localisation_and_range":"Both are annotated as transmembrane [flag]; contact-dependent interaction between cells.","caveats":"Affinity is very weak (micromolar), as expected for a co-receptor; the Kd range is for class I MHC alleles in general, not HLA-A alone [PMID:10809759]. Both papers were read as abstracts.","key_references":[{"PMID":"21645925","why":"CD8alphaalpha-HLA-A*2402 crystal structure"},{"PMID":"10809759","why":"SPR affinities of CD8alphaalpha for class I MHC"}],"covers":["LR002716"]},"LR000754":{"pair":"HLA-B -> LILRB2","headline":"HLA-B class I binds inhibitory LILRB2 (ILT4) directly in human systems, with Kd in the tens of micromolar.","interaction_type":"direct binding","direction_and_effect":"ILT4 binds classical class I molecules and transduces negative signals that inhibit early signalling triggered by stimulatory receptors [PMID:9531263]. HLA-B acts as ligand and LILRB2 as inhibitory receptor.","molecular_requirements":"LILRB2 bound both folded and free heavy chain forms of class I, unlike LILRB1 [PMID:21270408]. Soluble ILT4 D1D2 was sufficient for SPR binding [PMID:12853576].","affinity_potency":[{"value":"Kd \u224814 to \u224845 \u03bcM","assay":"surface plasmon resonance, soluble ILT4 D1D2 over HLA-A*1101, -B*3501, -Cw*0401, -Cw*0702","system":"recombinant human proteins","cite":"PMID:12853576"}],"species_and_systems":"Human proteins and cells throughout [PMID:12853576][PMID:9531263][PMID:21270408].","localisation_and_range":"Both are annotated transmembrane [flag]; contact-dependent.","caveats":"All three papers were read as abstracts only. The Kd range covers several classical alleles, not HLA-B alone. LILRB2 showed the weakest binding to HLA-B*2705 [PMID:21270408]. UniProt records broad HLA recognition [DB:UniProt]. One further paper was judged a different entity.","key_references":[{"PMID":"12853576","why":"SPR affinity for HLA-B*3501 and other class I"},{"PMID":"21270408","why":"Binding across >90 HLA alleles; folded and free heavy chain"},{"PMID":"9531263","why":"ILT4 binds classical class I and signals negatively"}],"covers":["LR000754"]},"LR002725":{"pair":"HLA-C -> LILRA1","headline":"Single abstract-level report that activating LILRA1 prefers HLA-C free heavy chain; thinly supported.","interaction_type":"direct binding","direction_and_effect":"LILRA1, an activating receptor, preferentially binds HLA-C free heavy chain [PMID:21270408].","molecular_requirements":"Prefers beta2-microglobulin-free (unfolded) heavy chain over folded class I [PMID:21270408]. Co-receptors: not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human; LILR binding to more than 90 HLA class I alleles assessed; assay format not given in the abstract [PMID:21270408].","localisation_and_range":"HLA-C is flagged transmembrane, not secreted [flag]; free heavy chain form implies a non-canonical, possibly shed or unfolded ligand (not shown in our evidence).","caveats":"Abstract only; no affinity. Support is one paper. The curator effect label is 'antagonist' although the paper calls LILRA1 activating.","key_references":[{"PMID":"21270408","why":"LILR survey of >90 HLA class I alleles; LILRA1 prefers HLA-C free heavy chain"}],"covers":["LR002725"]},"LR008341":{"pair":"HLA-DQA1 -> LAG3","headline":"No verified primary paper; only a generic Reactome record that LAG3 binds MHC class II.","interaction_type":"database-asserted only","direction_and_effect":"Reactome records 'LAG3 (CD233) binds MHC II' [DB:Reactome R-HSA-8856157]. Effect: not reported in our evidence.","molecular_requirements":"Chain requirement for DQ: not reported in our evidence; the record is generic class II.","affinity_potency":[],"species_and_systems":"Not reported in our evidence (pair is human).","localisation_and_range":"Not reported in our evidence.","caveats":"Two review-only and two abstract-insufficient papers; none verified. Support is a database assertion for MHC II in general, not DQA1 specifically.","key_references":[],"covers":["LR008341"]},"LR007252":{"pair":"HLA-E -> KLRC2:KLRD1","headline":"Direct low-affinity binding of HLA-E to the activating CD94/NKG2C heterodimer.","interaction_type":"direct binding","direction_and_effect":"NKG2C/CD94, an activating receptor, bound HLA-E at significantly lower affinity than inhibitory NKG2A/CD94 [PMID:15728498]. HLA-E tetramer bound CD94/NKG2C transfectants [PMID:9486650].","molecular_requirements":"Requires KLRC2 (NKG2C) with KLRD1 (CD94) [PMID:15728498]. HLA-E presents leader peptides; peptide changed affinity [PMID:15728498]. Reactome lists CD94:NKG2C:HLA-E [DB:Reactome R-HSA-2326867]; BioGRID lists KLRD1-HLA-E [DB:BioGRID 283051].","affinity_potency":[],"species_and_systems":"Human; purified proteins, transfectants [PMID:15728498][PMID:9486650].","localisation_and_range":"HLA-E secreted and transmembrane per flags; receptor transmembrane [flag].","caveats":"No numeric affinity in our evidence; abstract-only papers; three papers review-only.","key_references":[{"PMID":"15728498","why":"Lower affinity of NKG2C/CD94 for HLA-E"},{"PMID":"9486650","why":"HLA-E tetramer binds CD94/NKG2C"}],"covers":["LR007252"]},"LR000763":{"pair":"HLA-G -> KIR2DL4","headline":"Soluble KIR2DL4 binds HLA-G-expressing cells; direct binding with an inhibitory outcome, from one abstract plus databases.","interaction_type":"direct binding","direction_and_effect":"Recombinant soluble KIR2DL4 bound cells expressing HLA-G but not other HLA class I molecules; KIR2DL4 transferred into NK-92 inhibited lysis [PMID:10190900]. Curators describe it as inhibitory.","molecular_requirements":"Not reported in our evidence beyond KIR2DL4 alone.","affinity_potency":[],"species_and_systems":"Human proteins and heterologous cells [PMID:10190900].","localisation_and_range":"HLA-G flagged secreted and transmembrane [flag].","caveats":"Abstract only. Reactome and BioGRID also assert this [DB:Reactome, DB:BioGRID]. Interaction labelled Stimulatory, while the paper shows inhibited lysis in its abstract-level note; two rows pending.","key_references":[{"PMID":"10190900","why":"soluble KIR2DL4 binds HLA-G cells"}],"covers":["LR000763"]},"LR002734":{"pair":"HMGB1 -> CXCR4","headline":"HMGB1 acts through CXCR4 only as a heterocomplex with CXCL12; one full-text paper, no affinity.","interaction_type":"functional only","direction_and_effect":"HMGB1 and CXCL12 form a heterocomplex (NMR, SPR) that acts exclusively through CXCR4 and not through other HMGB1 receptors, and promotes different CXCR4 conformational rearrangements than CXCL12 alone by FRET. Cell recruitment in vivo is inhibited by AMD3100 and glycyrrhizin [PMID:22370717]. UniProt notes the CXCL12:HMGB1 complex triggers CXCR4 homodimerization [DB:UniProt].","molecular_requirements":"CXCL12 is required: HMGB1-induced recruitment depends on CXCL12 [PMID:22370717].","affinity_potency":[],"species_and_systems":"Curated as human ligand and receptor; experiments also used murine NIH/3T3 cells, human monocytes and mouse air pouches [PMID:22370717]. The mouse pair is ortholog-inferred.","localisation_and_range":"HMGB1 is flagged secreted [flag]; it acts as a chemoattractant for recruited cells [PMID:22370717].","caveats":"HMGB1 is not shown here as an independent CXCR4 ligand. BioGRID lists an affinity-capture record [DB:BioGRID]. The curated assay class is direct binding, but the strongest binding data are for the HMGB1-CXCL12 interaction.","key_references":[{"PMID":"22370717","why":"HMGB1-CXCL12 heterocomplex signals via CXCR4"}],"covers":["LR002734","LR005982"]},"LR001843":{"pair":"HMGB1 -> HAVCR2","headline":"TIM-3 binds HMGB1 and sequesters it in tumour dendritic cells; one full-text mouse-based paper, functional rather than structural.","interaction_type":"functional only","direction_and_effect":"TIM-3 interacted with HMGB1 and interfered with recruitment of nucleic acids into dendritic-cell endosomes, reducing the efficacy of DNA vaccination and chemotherapy [PMID:22842346]. This is an inhibitory, sequestering role, not activating signalling.","molecular_requirements":"The Q62A substitution near the FG loop largely abrogated HMGB1 binding, so the metal-ion-dependent ligand-binding site of TIM-3 is needed. Binding was partly suppressed by RAGE-Fc or galectin-9 and blocked by anti-TIM-3 mAb [PMID:22842346].","affinity_potency":[],"species_and_systems":"Mouse tumours and tumour-associated dendritic cells, with TIM-3 expression also seen in patients with cancer [PMID:22842346]. The curated receptor species is mouse; the human pair is ortholog-inferred.","localisation_and_range":"HMGB1 is flagged secreted [flag]; it is released from dying tumour cells [PMID:22842346].","caveats":"TIM-3 bound HMGB1 with an affinity said to be similar to RAGE, but no value is given in our evidence. Single paper; one more row was review-only.","key_references":[{"PMID":"22842346","why":"TIM-3 binds HMGB1 and blunts nucleic-acid immunity"}],"covers":["LR001843","LR005192"]},"LR002743":{"pair":"HMGB2 -> LRP1","headline":"HMGB2 is reported to bind purified LRP1 directly in a chondrocyte ligandome study; only one abstract-level paper.","interaction_type":"direct binding","direction_and_effect":"Direct LRP1 binding was confirmed for HMGB2 (together with nine other ligands) using purified LRP1; the study links affinity for LRP1 with endocytosis rate [PMID:36028175]. Inhibiting LRP1-ligand interaction caused chondrocyte cell death and altered the secretome [PMID:36028175].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human chondrocytes, LRP1-deficient fibroblasts and a conditional Lrp1 knockout mouse; HMGB2-specific work is curated as human [PMID:36028175]. The mouse pair is ortholog-inferred.","localisation_and_range":"HMGB2 is flagged as secreted [flag]; the receptor mediates endocytosis in cartilage [PMID:36028175].","caveats":"Abstract-only reading; the HMGB2 affinity value is not given. No database records.","key_references":[{"PMID":"36028175","why":"LRP1 cartilage ligandome; direct binding of HMGB2 to LRP1"}],"covers":["LR002743","LR005991"]},"LR004228":{"pair":"HP -> ITGAM","headline":"Haptoglobin binds the CD11b/CD18 integrin on monocytic cells; evidence is chain-level for ITGAM (CD11b) from one 1996 paper.","interaction_type":"direct binding","direction_and_effect":"Haptoglobin binds purified CD11b/CD18, indicating direct binding; anti-CD11b mAb44 inhibits haptoglobin binding to THP1/U937 cells, and an anti-CD18 mAb partly inhibits it [PMID:8786317]. Binding was increased by Ca2+/ADP and inhibited by fibrinogen [PMID:8786317].","molecular_requirements":"The functional receptor is the CD11b/CD18 heterodimer; CD11b antibody blocking is the stronger evidence, with CD18 involvement only partial [PMID:8786317]. No interference from anti-CD11a or anti-CD11c mAbs [PMID:8786317].","affinity_potency":[{"value":"Kd 6.5 x 10(-6)","assay":"radioiodinated haptoglobin binding, one receptor class, 1.7 x 10(5) sites per cell (low affinity)","system":"human THP1 cells","cite":"PMID:8786317"}],"species_and_systems":"Human haptoglobin and human monocytic cell lines (THP1, U937), monocytes and granulocytes [PMID:8786317]. The mouse pair is ortholog-inferred.","localisation_and_range":"HP is flagged as secreted [flag].","caveats":"Abstract-only reading. The affinity was measured on whole cells, not on the single chain. One further row is pending.","key_references":[{"PMID":"8786317","why":"Haptoglobin binds CD11b/CD18 on THP1 cells and purified integrin"}],"covers":["LR000769","LR004228"]},"LR000772":{"pair":"HSP90B1 -> LRP1","headline":"gp96 (HSP90B1) binds CD91/LRP1 directly in antigen-presenting cells; consistent evidence across papers.","interaction_type":"direct binding","direction_and_effect":"CD91 binds gp96 directly, and alpha2-macroglobulin or anti-CD91 antibodies inhibit re-presentation of gp96-chaperoned peptides by macrophages [PMID:11248808]. The 2001 paper restates direct binding as the result of earlier work and extends CD91 as receptor to other heat shock proteins [PMID:11290339]. The annotated modulatory effect is stimulatory [flag].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Antigen-presenting cells and macrophages; species is recorded as human in this dossier, but the same 2001 paper is curated as mouse (RAW264.7 cells) elsewhere [PMID:11290339]. Human pair is ortholog-inferred.","localisation_and_range":"HSP90B1 carries no secreted flag [flag]; the papers treat gp96 as an external chaperone taken up by APCs [PMID:11248808].","caveats":"Direct-binding sentence in the 2001 paper cites earlier work, so the primary evidence is [PMID:11248808] (abstract only). No Kd reported.","key_references":[{"PMID":"11248808","why":"gp96 binds CD91 directly; alpha2-macroglobulin and anti-CD91 block"},{"PMID":"11290339","why":"CD91 as common receptor for gp96, hsp90, hsp70, calreticulin"}],"covers":["LR000772","LR004231"]},"LR002752":{"pair":"HSPA1A -> TLR2","headline":"HspA1A from ovarian cancer cells activates neutrophils through TLR2 (and TLR4) in vitro; functional only.","interaction_type":"functional only","direction_and_effect":"Neutrophil activation and increased reactive-oxygen-species production by ovarian cancer cells involve interaction of HspA1A with TLR2 and TLR4 on the neutrophil surface; anti-TLR2 and anti-TLR4 antibodies were used to test this [PMID:22528050].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human neutrophils from cancer patients and healthy donors, with human ovarian cancer cells [PMID:22528050].","localisation_and_range":"HSPA1A is flagged as secreted [flag]; the paper describes membrane-bound HspA1A on cancer cells in direct cell contact with neutrophils [PMID:22528050].","caveats":"Abstract and excerpts only; no direct binding or affinity, and TLR2 and TLR4 effects are not separated.","key_references":[{"PMID":"22528050","why":"HspA1A on ovarian cancer cells acts via TLR2/4 on neutrophils"}],"covers":["LR002752"]},"LR004237":{"pair":"IAPP -> CALCR","headline":"Amylin acts on CALCR alone and, more potently, with RAMPs; nine confirmed papers in human cell systems, so well supported though RAMP-dependent.","interaction_type":"direct binding","direction_and_effect":"Amylin binds and activates the calcitonin receptor: human and rat amylin activated CALCR alone and all three CALCR+RAMP complexes in cAMP assays [PMID:24169554]; GtoPdb lists full agonist action [DB:GtoPdb]. In breast cancer cells, amylin stimulated cAMP with EC50 1.4 nM [PMID:9487987]. A tumour study reports amylin signalling through CalcR and RAMP3 to inhibit glycolysis [PMID:25409149].","molecular_requirements":"RAMPs change the pharmacology: RAMP1 and -3 increased [125I]amylin binding to hCTR2 by 262 and 338% [PMID:10342886]; the RAMP N-terminal domain dictates competition specificity [PMID:16531504]. CALCR alone also responds [PMID:24169554]. Structures with a CALCR chain exist [DB:PDB 8F0J].","affinity_potency":[{"value":"IC50 3.6 nM","assay":"inhibition of [125I]amylin binding by human amylin","system":"MCF-7 human breast carcinoma cells","cite":"PMID:9487987"},{"value":"IC50 3.1 nM","assay":"inhibition of [125I]amylin binding by human amylin","system":"RAEC cells with hCTR2 + RAMP1","cite":"PMID:10342886"},{"value":"IC50 4.0 nM","assay":"inhibition of [125I]amylin binding by human amylin","system":"RAEC cells with hCTR2 + RAMP3","cite":"PMID:10342886"},{"value":"EC50 1.4 nM","assay":"cAMP accumulation by human amylin","system":"MCF-7 cells","cite":"PMID:9487987"}],"species_and_systems":"Human CALCR (hCTR2, CTRa) in transfected rabbit endothelial, COS-7 and HEK293S cells, and MCF-7 cells, with rat or human amylin; one tumour paper in vivo [PMID:10342886] [PMID:16531504] [PMID:24169554] [PMID:9487987] [PMID:25409149]. Mouse pair is ortholog-inferred.","localisation_and_range":"IAPP is flagged secreted and CALCR transmembrane [flag]; amylin is a circulating or local peptide acting on cell-surface receptors.","caveats":"Without RAMP, amylin binding to CALCR is weak (0.9 fmol per 50,000 cells) [PMID:10342886]. Authors of PMID:9487987 argue the MCF-7 amylin site may be distinct from CALCR. Papers read as abstracts only; one review-only row excluded.","key_references":[{"PMID":"10342886","why":"[125I]amylin binding and IC50 values with CTR2 plus RAMP1/2/3"},{"PMID":"24169554","why":"cAMP responses of CALCR alone and AMY1-3 to amylin"},{"PMID":"16531504","why":"RAMP domain contributions to amylin receptor binding and signalling"}],"covers":["LR000779","LR004237"]},"LR007090":{"pair":"IAPP -> CALCR:RAMP1","headline":"Amylin acts through the CALCR:RAMP1 (AMY1) complex per UniProt and PDB records; one abstract-only in vivo paper supports it.","interaction_type":"functional only","direction_and_effect":"Microinjecting amylin into the rodent locus coeruleus induced anorexia without nausea, and locus coeruleus calcitonin receptors co-express RAMP1 by RNAscope; curators label it agonist [PMID:42521122]. UniProt describes CALCR with RAMP1 as the AMYR1 receptor for amylin [DB:UniProt]. GtoPdb has agonist records for IAPP-CALCR [DB:GtoPdb].","molecular_requirements":"Requires both CALCR and RAMP1 (AMYR1) [DB:UniProt]. Co-expression, not binding, is shown in the paper [PMID:42521122].","affinity_potency":[],"species_and_systems":"Rats and mice in vivo per the abstract, although curators record human [PMID:42521122].","localisation_and_range":"IAPP flagged secreted; the complex is flagged transmembrane [flag]. Amylin acts on neurons in the locus coeruleus [PMID:42521122].","caveats":"Abstract only; in vivo pharmacology does not prove binding to the RAMP1 complex specifically, since CGRP also acts. Two other papers were abstract_insufficient. PDB structures list a CALCR chain with IAPP, not the RAMP1 complex specifically [DB:PDB 8F0J].","key_references":[{"PMID":"42521122","why":"Amylin microinjection in locus coeruleus; CTR neurons co-express RAMP1"}],"covers":["LR007090"]},"LR000781":{"pair":"IAPP -> RAMP3","headline":"Amylin signals through CALCR with RAMP3 (AMY3); supported by cAMP pharmacology and a tumour study, with RAMP3 not shown to act alone.","interaction_type":"functional only","direction_and_effect":"Amylin and pramlintide activated all three AMY receptors in a cAMP response [PMID:24169554]. In a cancer paper, amylin acted through CalcR and RAMP3 to inhibit glycolysis and induce reactive oxygen species and apoptosis; knockdown of CALCR or RAMP3 prevented these effects [PMID:25409149]. GtoPdb lists a full agonist (pEC50 8.6 to 10.8) [DB:GtoPdb].","molecular_requirements":"Both CALCR and RAMP3 were needed in the knockdown experiments [PMID:25409149]. UniProt says RAMP3 with CALCR acts as the amylin receptor [DB:UniProt]. Structures of the human Amylin3 receptor with Gs exist [DB:PDB 8F0K].","affinity_potency":[{"value":"pEC50 8.6 to 10.8","assay":"GtoPdb agonist record","system":"not reported in our evidence","cite":"DB:GtoPdb"}],"species_and_systems":"HEK293S and COS-7 cells [PMID:24169554]; human H1299 cells and p53-null mice [PMID:25409149]. Mouse pair is ortholog-inferred.","localisation_and_range":"Paper text states IAPP is a secreted protein [PMID:25409149]; RAMP3 is flagged transmembrane [flag].","caveats":"Both abstracts were read for the cAMP paper; the tumour paper had full text. The tumour paper's effect is on downstream cell behaviour in a mixed knockdown setting, and curators labelled the effect as antagonist, which refers to tumour inhibition, not receptor antagonism.","key_references":[{"PMID":"24169554","why":"cAMP activation at AMY1-3 receptors"},{"PMID":"25409149","why":"Amylin needs CALCR and RAMP3 for anti-tumour effects"}],"covers":["LR000781","LR004239"]},"LR004246":{"pair":"ICAM2 -> ITGAL","headline":"ICAM-2 binds the LFA-1 alpha chain (CD11a) I domain with structural and binding support; ranked below ICAM-1 in affinity.","interaction_type":"direct binding","direction_and_effect":"ICAM-2 is an LFA-1 ligand with affinity order ICAM-1 > ICAM-2 > ICAM-3 for a locked-open alphaL I domain [PMID:11353828]; off-rates differ among ICAM-1, -2 and -3 and relate to residues around a metal coordination bond in the alphaLbeta2 interface [PMID:15728350]. Pig ICAM-2 supported firm adhesion of human LFA-1 cells [PMID:15023143].","molecular_requirements":"The binding data use the isolated alphaL I domain, so the alpha chain alone is sufficient for binding in those assays [PMID:11353828]; UniProt describes the receptor as ITGAL:ITGB2 [DB:UniProt].","affinity_potency":[],"species_and_systems":"Human proteins [PMID:11353828][PMID:15728350]; the adhesion study used pig ICAM-2 with human LFA-1 [PMID:15023143]. Mouse pair is ortholog-inferred.","localisation_and_range":"Membrane-bound adhesion molecule, contact-dependent; UniProt: leukocyte cell-cell adhesion on resting cells [DB:UniProt].","caveats":"All three papers are abstract-only. The adhesion paper uses pig ICAM-2 [PMID:15023143]. No numeric affinities in our evidence.","key_references":[{"PMID":"11353828","why":"Affinity ranking ICAM-1 > ICAM-2 > ICAM-3 for alphaL I domain"},{"PMID":"15728350","why":"Crystal structure and kinetics for ICAM-1/2/3 with alphaL"}],"covers":["LR000788","LR004246"]},"LR000790":{"pair":"ICAM2 -> ITGB2","headline":"ICAM-2 acts on beta2 integrins mainly through LFA-1; support is abstract-level mutagenesis and an adhesion study.","interaction_type":"functional only","direction_and_effect":"LFA-1 alpha-chain (CD11a) I-domain mutations defined a binding surface for ICAM-1 and ICAM-2; Lys-263-to-alanine preferentially abolished ICAM-2 binding, and Thr-175-to-alanine reduced ICAM-2 binding ~70% [PMID:9786897]. Pig ICAM-2 supported firm adhesion of human LFA-1 cells [PMID:15023143].","molecular_requirements":"ITGB2 is the shared beta chain; the mutational evidence maps to the alpha chain (CD11a) I-domain [PMID:9786897]. UniProt describes ITGAL:ITGB2 as the receptor [DB:UniProt].","affinity_potency":[],"species_and_systems":"Human LFA-1 mutants [PMID:9786897]; pig ICAM-2 with human LFA-1 in transfectants [PMID:15023143]. Mouse pair is ortholog-inferred.","localisation_and_range":"Membrane-bound; contact-dependent adhesion.","caveats":"Both abstract-only; the beta chain itself is not shown to bind ICAM-2 alone. Four abstract_insufficient and one pending row not shown.","key_references":[{"PMID":"9786897","why":"Mutagenesis mapping of the LFA-1 I-domain surface for ICAM-2"}],"covers":["LR000790","LR004248"]},"LR004255":{"pair":"ICAM4 -> ITGB2","headline":"Well supported: three human studies show beta2 integrins (LFA-1, Mac-1, CD11c/CD18) binding ICAM-4.","interaction_type":"direct binding","direction_and_effect":"alphaLbeta2 and alphaMbeta2 bind ICAM-4-Fc specifically and dose dependently [PMID:15355350]; CD11c/CD18 binds ICAM-4, curated as agonist, and antibodies inhibit erythrophagocytosis [PMID:16985175]; antibodies to CD11a, CD11b or CD18 block L-cell adhesion to ICAM-4-Fc [PMID:10846180].","molecular_requirements":"beta2 pairs with different alpha chains (alphaL, alphaM, alphaX), each with partly different ICAM-4 binding sites: LFA-1 uses domain 1, Mac-1 domains 1 and 2, CD11c/CD18 both domains [PMID:10846180, PMID:16985175]. Evidence is for heterodimers, not beta2 alone.","affinity_potency":[],"species_and_systems":"Human proteins and cells [PMID:15355350, PMID:16985175, PMID:10846180]; mouse pair ortholog-inferred.","localisation_and_range":"ICAM4 carries both secreted and transmembrane flags [flag], so range is unclear; the papers used recombinant ICAM-4-Fc and cell-surface ICAM-4, consistent with contact-dependent adhesion.","caveats":"All three papers abstract only; seven rows judged, one abstract-insufficient. Affinity not reported.","key_references":[{"PMID":"15355350","why":"alphaLbeta2 and alphaMbeta2 binding to ICAM-4-Fc"},{"PMID":"16985175","why":"CD11c/CD18 as ICAM-4 receptor"},{"PMID":"10846180","why":"LFA-1 and Mac-1 binding sites"}],"covers":["LR000801","LR004255"]},"LR002761":{"pair":"ICAM4 -> ITGB5","headline":"Weak support: alphaVbeta5 is suggested by antibody inhibition of cell adhesion to ICAM-4-Fc in one abstract-only paper.","interaction_type":"functional only","direction_and_effect":"Adhesion of alpha4beta1-negative non-haemopoietic cells to ICAM-4-Fc was RGD-inhibitable and, by antibody inhibition, mediated by alphaV integrins, notably alphaVbeta1 and alphaVbeta5 [PMID:11435317]. UniProt lists ITGA5:ITGB5 among ICAM4 partners in vitro [DB:UniProt].","molecular_requirements":"beta5 would act with alphaV; no beta5-alone evidence. Neither the LETS nor LDV motif in domain 1 was critical [PMID:11435317].","affinity_potency":[],"species_and_systems":"Human cell lines with an ICAM-4-Fc construct [PMID:11435317]; mouse pair ortholog-inferred.","localisation_and_range":"ICAM4 carries both secreted and transmembrane flags [flag], so range is unclear; the papers used recombinant ICAM-4-Fc and cell-surface ICAM-4, consistent with contact-dependent adhesion.","caveats":"One paper, abstract only; beta5 is named only as one of two notable alphaV partners. Affinity not reported.","key_references":[{"PMID":"11435317","why":"alphaV-family integrins including alphaVbeta5 mediate adhesion to ICAM-4-Fc"}],"covers":["LR002761","LR006007"]},"LR004264":{"pair":"IFNA13 -> IFNAR2","headline":"Chain-level nanomolar binding of alpha-IFNs to IFNAR2, applied to IFNA13 by a class statement.","interaction_type":"direct binding","direction_and_effect":"IFNA13 is a stimulatory agonist at IFNAR2 [DB:GtoPdb]; binding to the isolated chain is reported for alpha-IFNs [PMID:21856167].","molecular_requirements":"Chain-only evidence [PMID:21856167].","affinity_potency":[{"value":"0.4-5 nM","assay":"binding to isolated receptor chain","system":"12 human alpha-IFN subtypes","cite":"PMID:21856167"}],"species_and_systems":"Human isolated chains.","localisation_and_range":"Not reported in our evidence.","caveats":"Abstract only; IFNA13 not named. Mouse pair is ortholog-inferred.","key_references":[{"PMID":"21856167","why":"Chain affinities of alpha-IFN subtypes"}],"covers":["LR008444","LR004264"]},"LR007270":{"pair":"IFNA14 -> IFNAR1:IFNAR2","headline":"Heterodimer pair supported only by a class-wide chain-binding abstract and GtoPdb chain entries.","interaction_type":"direct binding","direction_and_effect":"Alpha-IFNs bind each isolated chain [PMID:21856167]; GtoPdb lists IFNA14 as agonist of each chain [DB:GtoPdb].","molecular_requirements":"Isolated chains were tested, not the assembled complex [PMID:21856167].","affinity_potency":[{"value":"0.5-5 \u03bcM (IFNAR1) and 0.4-5 nM (IFNAR2)","assay":"binding to isolated chains","system":"12 human alpha-IFN subtypes","cite":"PMID:21856167"}],"species_and_systems":"Human isolated chains.","localisation_and_range":"IFNA14 flagged secreted; complex flagged transmembrane [flag].","caveats":"Abstract only; IFNA14 not named.","key_references":[{"PMID":"21856167","why":"Chain affinities of alpha-IFN subtypes"}],"covers":["LR007270"]},"LR000808":{"pair":"IFNA14 -> IFNAR2","headline":"Chain-level nanomolar binding of alpha-IFNs to IFNAR2, applied to IFNA14 by a class statement.","interaction_type":"direct binding","direction_and_effect":"IFNA14 is a stimulatory agonist at IFNAR2 [PMID:21856167] [DB:GtoPdb].","molecular_requirements":"Chain-only evidence [PMID:21856167].","affinity_potency":[{"value":"0.4-5 nM","assay":"binding to isolated receptor chain","system":"12 human alpha-IFN subtypes","cite":"PMID:21856167"}],"species_and_systems":"Human isolated chains.","localisation_and_range":"IFNA14 flagged secreted [flag].","caveats":"Abstract only; IFNA14 not named in the abstract.","key_references":[{"PMID":"21856167","why":"Chain affinities of alpha-IFN subtypes"}],"covers":["LR000808"]},"LR011716":{"pair":"IFNA2 -> IFNA2:IFNAR1:IFNAR2","headline":"IFNA2 to the IFNA2:IFNAR1:IFNAR2 entry is supported only by database records; no verified paper.","interaction_type":"database-asserted only","direction_and_effect":"GtoPdb lists IFNA2 as agonist at IFNAR1 and IFNAR2 [DB:GtoPdb]. BioGRID records IFNAR2-IFNA2 reconstituted complex and co-purification [DB:BioGRID, PMID:10339405], and IntAct records IFNA2 with IFNAR1 and IFNAR2 by x-ray crystallography [DB:IntAct, PMID:21854986]. Several PDB entries are listed (e.g. [DB:PDB 2HYM]); UniProt notes IFNA2 interacts with IFNAR2 [DB:UniProt].","molecular_requirements":"The receptor entry lists IFNA2, IFNAR1 and IFNAR2 together; requirements not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human pair. Species and system of the database experiments are not reported in our evidence.","localisation_and_range":"Ligand carries a secreted flag [flag]; range otherwise not reported in our evidence.","caveats":"No paper row was verified for this complex (two pending). The evidence is database records, mostly for the individual chains. Whether all three listed members act together is not reported in our evidence.","key_references":[{"PMID":"10339405","why":"BioGRID-recorded IFNAR2 binding to IFNA2."},{"PMID":"21854986","why":"IntAct-recorded crystal structure of the IFNA2 receptor complex."}],"covers":["LR011716"]},"LR000817":{"pair":"IFNA2 -> IFNAR1","headline":"IFNA2 binds the IFNAR1 chain directly but weakly; confirmed by several binding studies and a crystal structure.","interaction_type":"direct binding","direction_and_effect":"IFNalpha2 binds ifnar1-EC and ifnar2-EC, with competitive 1:1 interaction for all IFNs tested [PMID:17174979]. GtoPdb lists it as an agonist [DB:GtoPdb]. A 1991 study showed Hu-IFN-alpha A competes for binding to human cells with IFN-beta and -omega but not IFN-gamma [PMID:1834641].","molecular_requirements":"IFNAR1 binds IFNs more weakly than IFNAR2 [PMID:21856167]; signalling complexes of IFNs have very similar ternary architecture on ifnar1-EC and ifnar2-EC [PMID:17174979]. A crystal structure (PDB 3SE3) with IFNA2 and IFNAR1 chains is recorded [DB:PDB 3SE3, DB:IntAct, PMID:21854986].","affinity_potency":[{"value":"0.5-5 \u03bcM","assay":"IFNAR1 chain affinity for human alpha-IFN subtypes (class-wide; subtype not individually named in abstract)","system":"isolated human receptor chains","cite":"PMID:21856167"}],"species_and_systems":"Human ligands and receptor chains; recombinant extracellular domains on solid supports [PMID:17174979] and human cells [PMID:1834641].","localisation_and_range":"Ligand carries a secreted flag [flag]; range otherwise not reported in our evidence.","caveats":"Papers were read as abstracts only. PMID:21856167 gives class-wide values, with IFNA2 named only as a comparison subtype. PMID:1834641 predates separation of the two chains and cannot assign binding to IFNAR1 specifically.","key_references":[{"PMID":"17174979","why":"Real-time binding of IFNalpha2 to ifnar1-EC and ifnar2-EC."},{"PMID":"21856167","why":"Class-wide affinities of 12 human alpha-IFN subtypes for IFNAR1 and IFNAR2 (abstract only)."},{"PMID":"1834641","why":"Competition binding on human cells; receptor chain unresolved."}],"covers":["LR000817"]},"LR000826":{"pair":"IFNA7 -> IFNAR2","headline":"IFNA7 binds IFNAR2 as a type I interferon agonist; support is a class-wide binding study plus GtoPdb.","interaction_type":"direct binding","direction_and_effect":"IFNA7 acts as an agonist on the type I interferon receptor; the curator-verified study reports binding of human alpha-IFN subtypes to isolated receptor chains [PMID:21856167]. GtoPdb lists this as an agonist interaction with no affinity units [DB:GtoPdb].","molecular_requirements":"IFNAR2 is the tight-binding chain (0.4-5 nM) and IFNAR1 the weak one (0.5-5 \u03bcM) for alpha-IFNs [PMID:21856167]. Whether the pair needs both chains for signalling is not reported in our evidence beyond this binding comparison.","affinity_potency":[{"value":"0.4-5 nM","assay":"affinity and rate-constant determination, 12 human alpha-IFN subtypes collectively, isolated IFNAR2 chain","system":"human proteins","cite":"PMID:21856167"}],"species_and_systems":"Human ligand and human receptor chains, isolated recombinant chains (abstract-level reading) [PMID:21856167].","localisation_and_range":"Ligand is flagged secreted and not transmembrane [flag], so it acts as a diffusible paracrine or endocrine signal.","caveats":"The affinity range is stated for 'Alpha-IFNs' as a class, not IFNA7 individually; only IFN-alpha1 (220 nM) is singled out as weaker, and the paper was read as an abstract only [PMID:21856167].","key_references":[{"PMID":"21856167","why":"binding of 12 human alpha-IFN subtypes to isolated IFNAR1 and IFNAR2"}],"covers":["LR000826"]},"LR001852":{"pair":"IFNE -> IFNAR2","headline":"IFNE signals through IFNAR2 in mouse, shown functionally; human pair is projected. No database records.","interaction_type":"functional only","direction_and_effect":"IFN-\u03b5 signalled via the Ifnar1 and Ifnar2 receptors to induce IFN-regulated genes, so it acts as a type I IFN agonist [PMID:23449591]. Ifn-\u03b5-deficient mice were more susceptible to HSV-2 and Chlamydia muridarum infection of the female reproductive tract [PMID:23449591].","molecular_requirements":"Both Ifnar1 and Ifnar2 are named as the signalling receptors [PMID:23449591]; whether one chain suffices is not reported in our evidence.","affinity_potency":[],"species_and_systems":"Mouse experiments; the human pair is ortholog-inferred, the mouse pair is not [PMID:23449591].","localisation_and_range":"Ligand is flagged secreted and not transmembrane [flag], so it acts as a diffusible paracrine or endocrine signal. The paper reports IFN-\u03b5 constitutively expressed by female reproductive tract epithelium and hormonally regulated [PMID:23449591].","caveats":"Evidence is functional (gene induction), not binding, and abstract-only. No direct binding or affinity data and no database records in our evidence.","key_references":[{"PMID":"23449591","why":"IFN-\u03b5 signals via Ifnar1/Ifnar2; knockout mice more infection-prone"}],"covers":["LR001852","LR005200"]},"LR011725":{"pair":"IFNG -> IFNG:IFNGR1","headline":"IFNG binds IFNGR1 in crystal structures and databases; no verified paper, three pending.","interaction_type":"database-asserted only","direction_and_effect":"GtoPdb lists IFNG at IFNGR1 as agonist [DB:GtoPdb]. UniProt says IFNG signals via JAK-STAT after interaction with IFNGR1 [DB:UniProt]. Reactome has the binding reaction IFNG dimer binds IFNGR [DB:Reactome].","molecular_requirements":"IFNGR1 forms a heterodimer with IFNGR2 as the IFNG receptor complex per UniProt [DB:UniProt]. Co-crystal structures are recorded [DB:PDB 1FG9][DB:PDB 1FYH][DB:BioGRID]. The entity IFNG:IFNGR1 also contains IFNG itself, which suggests the ligand dimer [flag].","affinity_potency":[],"species_and_systems":"Human; no verified papers in our evidence; structural records only [DB:PDB 1FG9].","localisation_and_range":"IFNG flagged secreted, IFNGR1 flagged transmembrane receptor [flag].","caveats":"No curator-verified paper; three papers pending. Support is databases only, though structural and co-crystal records are direct physical evidence.","key_references":[],"covers":["LR011725"]},"LR000835":{"pair":"IFNL2 -> IL10RB","headline":"IFN-lambda2 and IL10RB: shared second chain of the IFN-lambda receptor; one abstract.","interaction_type":"functional only","direction_and_effect":"IL-28 and IL-29 interacted with a heterodimeric receptor of IL-10Rbeta and IL-28Ralpha [PMID:12469119]; GtoPdb lists Agonist [DB:GtoPdb].","molecular_requirements":"IL10RB works with IFNLR1; standalone binding to IL10RB is not shown in our evidence [PMID:12469119].","affinity_potency":[],"species_and_systems":"Human, human cells [PMID:12469119].","localisation_and_range":"IFNL2 is flagged secreted and non-transmembrane [flag].","caveats":"Abstract-only; heterodimer evidence rather than chain-only; the abstract names IL-28, not IL-28A specifically.","key_references":[{"PMID":"12469119","why":"heterodimeric receptor with IL-10Rbeta"}],"covers":["LR000835"]},"LR004273":{"pair":"IGF2 -> IGF1R","headline":"IGF2 is a recorded IGF1R agonist with structures; our one verified paper uses the interaction only as an assay.","interaction_type":"direct binding","direction_and_effect":"GtoPdb lists IGF2 as an agonist of IGF1R [DB:GtoPdb]; the interaction is annotated stimulatory. The verified paper describes IGF-II binding IGF-1R with high affinity and used it in binding assays of Q18 mutants [PMID:35304516].","molecular_requirements":"Structures contain chains of IGF2 and IGF1R [DB:PDB 6VWG]. Subunit requirements are not reported in our evidence.","affinity_potency":[],"species_and_systems":"Immunocaptured IGF-1R in competition binding with europium-labelled IGF-II; the IGF-II analogues were made in E. coli [PMID:35304516].","localisation_and_range":"IGF2 is flagged secreted and IGF1R transmembrane [flag].","caveats":"The quoted evidence is a background statement; the paper's own measurements are for IGF-II Q18 analogues (for example Q18I IC50 0.45 nM), not wild-type affinity, so none is given here. Abstract read, with excerpts. Three review-only rows were excluded.","key_references":[{"PMID":"35304516","why":"IGF-II analogue binding to IGF-1R"}],"covers":["LR000841","LR004273"]},"LR002770":{"pair":"IGF2 -> ITGAV","headline":"Integrin alphavbeta3 binds IGF2 in one verified study; ITGAV is the alpha chain.","interaction_type":"direct binding","direction_and_effect":"IGF2 specifically bound integrins alphavbeta3 and alpha6beta4 and induced proliferation of IGF1R-positive CHO cells expressing either integrin [PMID:28873464]. Integrin-binding-defective IGF2 mutants (Arg to Glu at 24, 34, 37 and/or 38) suppressed wild-type IGF2 proliferation, suggesting dominant-negative IGF1R antagonism [PMID:28873464]. UniProt agrees [DB:UniProt].","molecular_requirements":"The alphavbeta3 heterodimer was tested; ITGAV alone is not shown. Blocking antibody 7E3 (anti-beta3) and cyclic RGDfV reduced cell adhesion to IGF2 [PMID:28873464].","affinity_potency":[],"species_and_systems":"CHO cells expressing recombinant integrins, ELISA-type binding with soluble alphavbeta3, and adhesion assays; anchorage-independent conditions [PMID:28873464]. Mouse pair is ortholog-inferred.","localisation_and_range":"IGF2 is flagged secreted [flag].","caveats":"The single supporting paper is the same for several integrin chain rows; evidence concerns the heterodimer. No affinity is reported in our evidence.","key_references":[{"PMID":"28873464","why":"IGF2 binds alphavbeta3 and alpha6beta4; C-domain Arg mutants"}],"covers":["LR002770","LR006016"]},"LR010951":{"pair":"IGFBP1 -> IGF1","headline":"Database-supported IGFBP1-IGF1 binding, including a crystal structure; no curated paper in the dossier.","interaction_type":"database-asserted only","direction_and_effect":"IGFBP1 binds IGF1 to form an IGF:IGFBP1 complex [DB:Reactome]; UniProt states IGFBP1 binds IGF1 and IGF2 equally well [DB:UniProt]. Direction (binding protein sequestering the growth factor) is implied by the records; no effect label is recorded for this pair.","molecular_requirements":"Complex of IGFBP1 with IGF1 [DB:Reactome]; a structure with a chain of each protein is deposited [DB:PDB 2DSQ].","affinity_potency":[],"species_and_systems":"Human only; assays listed are bio-layer interferometry and X-ray crystallography [DB:IntAct][DB:PDB 2DSQ].","localisation_and_range":"IGF1 is annotated as secreted [flag]; IGFBP1 has no localisation flag in the dossier.","caveats":"No curator-verified paper: four candidate papers were judged as a different entity. Support rests on IntAct, PDB, Reactome and UniProt records alone. This is a binding-protein/ligand pair, not a signalling receptor.","key_references":[],"covers":["LR010951"]},"LR011176":{"pair":"IGFBP2 -> IGF2","headline":"Database-supported IGFBP2-IGF2 binding with inhibitory label; no curated paper in the dossier.","interaction_type":"database-asserted only","direction_and_effect":"Annotated as inhibitory; IGFBP2 binds IGF forming IGF:IGFBP2 [DB:Reactome]; UniProt records that IGFBP2 interacts with IGF2 [DB:UniProt].","molecular_requirements":"No subunit requirements reported.","affinity_potency":[],"species_and_systems":"Human only; the only interaction assay listed is anti-tag co-immunoprecipitation [DB:IntAct].","localisation_and_range":"IGF2 is annotated as secreted [flag]; IGFBP2 has no localisation flag.","caveats":"No curator-verified paper (three candidates judged as a different entity). Database records only; no affinity.","key_references":[],"covers":["LR011176"]},"LR000844":{"pair":"IGFBP4 -> FZD8","headline":"One abstract-level study: IGFBP-4 co-immunoprecipitates with Frizzled 8 and blocks Wnt3A binding; inhibitory.","interaction_type":"direct binding","direction_and_effect":"IGFBP-4 physically interacted with Frizzled 8 and inhibited binding of Wnt3A to it, inhibiting canonical Wnt signalling [PMID:18528331]. Curator effect: antagonist.","molecular_requirements":"The same study reports interaction with the co-receptor LRP6 too [PMID:18528331]; whether Frizzled 8 alone is sufficient is not reported in our evidence.","affinity_potency":[],"species_and_systems":"Curator note describes a mouse model (Igfbp4 knockdown, cardiomyogenesis); the dossier lists a mouse pair and a human pair projected from it [PMID:18528331]. Assays: co-immunoprecipitation and Wnt3A competition.","localisation_and_range":"IGFBP4 is annotated as secreted and FZD8 as a receptor [flag].","caveats":"Abstract-only read; the interaction assay is co-immunoprecipitation, not a quantified binding measurement. No affinity reported. Cardiogenic effect was independent of IGF binding but attenuated by IGFs through IGFBP-4 sequestration [PMID:18528331].","key_references":[{"PMID":"18528331","why":"IGFBP-4 binds Frizzled 8 and LRP6, blocks Wnt3A binding"}],"covers":["LR000844","LR004276"]},"LR008008":{"pair":"IGHG1:IGLC1 -> FCGR3B","headline":"One abstract-level crystal structure of the IgG1 Fc fragment with soluble FcgammaRIII supports binding.","interaction_type":"direct binding","direction_and_effect":"A 3.2 A crystal structure of human IgG1 Fc with soluble FcgammaRIII (CD16) shows a 1:1 complex [PMID:10917521]. Effect direction is not reported in our evidence.","molecular_requirements":"The receptor contacts both halves of the Fc at the C gamma2 domains and hinge; the Fc opens asymmetrically [PMID:10917521]. Only the Fc fragment is in the structure; the light chain IGLC1 is not shown to be required not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human Fc fragment and human soluble receptor, X-ray crystallography [PMID:10917521]. PDB 1E4K, 1T83, 1T89 list IgG1 (P01857) with O75015 [DB:PDB 1E4K].","localisation_and_range":"IGHG1 is flagged secreted and FCGR3B a receptor [flag]; range from annotation only.","caveats":"Abstract only. The abstract names FcgammaRIII (CD16) without separating FCGR3A from FCGR3B; the curator assigned it to FCGR3B on inference. The complex ligand includes IGLC1, but the structure uses an Fc fragment.","key_references":[{"PMID":"10917521","why":"3.2 A structure of IgG1 Fc with soluble FcgammaRIII"}],"covers":["LR008008"]},"LR004282":{"pair":"IHH -> PTCH2","headline":"PTCH2 binds all hedgehog family members with similar affinity in one abstract-level paper.","interaction_type":"direct binding","direction_and_effect":"Biochemical analysis shows PTCH and PTCH2 both bind all hedgehog family members with similar affinity and form a complex with SMO [PMID:9811851]. UniProt describes PTCH2 as a negative regulator of smoothened signalling and a receptor for SHH, IHH and DHH [DB:UniProt]. The authors suggest PTCH2 mediates Desert Hedgehog activity in vivo [PMID:9811851].","molecular_requirements":"PTCH2 can form a complex with SMO [PMID:9811851].","affinity_potency":[],"species_and_systems":"Binding assay species is not reported in our evidence. Both human and mouse pairs are ortholog-inferred.","localisation_and_range":"IHH is flagged secreted and transmembrane [flag]; range from annotation only.","caveats":"Abstract only. IHH is covered by the general statement about all family members. No numeric affinity is given.","key_references":[{"PMID":"9811851","why":"PTCH2 binds all hedgehog family members"}],"covers":["LR000852","LR004282"]},"LR000853":{"pair":"IL10 -> IL10RA","headline":"IL-10 binds IL10RA (IL-10R1) with sub-nanomolar affinity, shown by crystal structure and binding assays.","interaction_type":"direct binding","direction_and_effect":"A 2.9 A crystal structure shows IL-10 bound to soluble IL-10R1 [PMID:11485736]. Soluble human IL-10 receptor inhibits 125I-hIL-10 binding and antagonises hIL-10 effects on proliferation and cytokine synthesis [PMID:7759550]. Mouse IL-10R expressed in Ba/F3 cells binds IL-10 and the cells proliferate [PMID:8248239]. GtoPdb lists IL-10 as an agonist [DB:GtoPdb].","molecular_requirements":"The complex has two IL-10s and four sIL-10R1 molecules [PMID:11485736]; IL-10R1 is the high-affinity chain and must recruit the low-affinity IL-10R2 chain before signalling [PMID:11485736]. Soluble receptor is monomeric [PMID:7759550].","affinity_potency":[{"value":"Kd 563 +/- 59 pM","assay":"soluble receptor binding","system":"human IL-10 and soluble receptor from myeloma cells","cite":"PMID:7759550"},{"value":"approximately 70 pM","assay":"binding on Ba/F3 transfectants","system":"mouse IL-10R in Ba/F3 cells","cite":"PMID:8248239"},{"value":"pEC50 9.699999809265137 to 10.300000190734863","assay":"GtoPdb affinity","system":"not stated","cite":"PMID:19161426"}],"species_and_systems":"Human proteins in the structure and Kd [PMID:11485736] [PMID:7759550]; mouse cells for the 70 pM value [PMID:8248239].","localisation_and_range":"IL10 is flagged secreted [flag]; paracrine or endocrine range from annotation only.","caveats":"All papers are abstract only. A 2001 crystallisation paper adds no new structure [PMID:11717514]. IL10RA alone binds IL-10 but does not signal without IL10RB [PMID:11485736].","key_references":[{"PMID":"11485736","why":"2.9 A structure of IL-10 with IL-10R1"},{"PMID":"7759550","why":"Kd 563 pM and 2:4 stoichiometry"},{"PMID":"8248239","why":"Mouse IL-10R binds IL-10 at about 70 pM"}],"covers":["LR000853","LR004283"]},"LR004291":{"pair":"IL13 -> IL13RA1","headline":"IL13 binds IL13RA1 directly by structure and biophysical assays in databases; no curator-verified paper yet.","interaction_type":"database-asserted only","direction_and_effect":"IL13 signals through IL13RA1 with IL4R, activating JAK1 and TYK2 and then STAT6 [DB:UniProt]. GtoPdb lists agonist [DB:GtoPdb]. Reactome records IL13 binding IL13RA:TYK2 and phosphorylated complex [DB:Reactome].","molecular_requirements":"IL4R chain is also part of the signalling receptor per UniProt [DB:UniProt]. IL13RA2 is a separate high-affinity decoy [DB:UniProt].","affinity_potency":[],"species_and_systems":"Human records; mouse pair is projected from human by orthology, not tested [DB:UniProt]. Binding assays in IntAct are ITC and SPR [DB:IntAct]; crystal structures [DB:PDB 3BPO] [DB:PDB 5E4E]; BioGRID reconstituted complex [DB:BioGRID].","localisation_and_range":"IL13 flagged secreted [flag]; receptor flagged as receptor [flag].","caveats":"No judged paper: 3 abstracts were insufficient, 1 review-only, 1 pending. Evidence is database-only; affinity not reported in our evidence.","key_references":[],"covers":["LR000861","LR004291"]},"LR000862":{"pair":"IL13 -> IL13RA2","headline":"IL13 binds IL13RA2 with very high affinity, shown by crystal structure and ITC/SPR; functions as a decoy.","interaction_type":"direct binding","direction_and_effect":"IL-13Ralpha2 lacks canonical Jak/STAT signaling and the abstract indicates a decoy function [PMID:20223216]. UniProt: IL13RA2 is a decoy that inhibits IL-13 and IL-4 signalling and internalises IL13, though it can also signal via AP-1 leading to TGFB1 [DB:UniProt].","molecular_requirements":"IL13RA2 alone binds IL13; it uses the same two-site binding mode as IL13RA1 with extra peripheral residues [PMID:20223216]. It binds IL-13 but not IL-4 and does not pair with IL4R in COS-7 beyond a small number of receptors [PMID:8663118] [DB:UniProt].","affinity_potency":[{"value":"4.7 pM","assay":"displacement isothermal titration calorimetry","system":"soluble IL-13 and IL-13R alpha2 extracellular domains, human","cite":"PMID:20223216"},{"value":"over 5,000-fold higher affinity than IL-13R alpha1","assay":"ITC","system":"soluble human proteins","cite":"PMID:20223216"}],"species_and_systems":"Human recombinant proteins (insect cell expressed) [PMID:20223216]; COS-7 cells transfected with receptor cDNA [PMID:8663118]. Mouse pair inferred from human.","localisation_and_range":"Receptor flagged transmembrane; ligand secreted [flag].","caveats":"The femtomolar statement in the abstract differs from the 4.7 pM measured by ITC in the full text; both are as reported [PMID:20223216]. Signalling role conflicts between sources (decoy vs AP-1 signalling) [DB:UniProt]. 8663118 read as abstract only.","key_references":[{"PMID":"20223216","why":"Crystal structure and affinity of IL-13/IL-13Ralpha2"},{"PMID":"8663118","why":"Cloning; IL-13 binding to COS-7 cells, not IL-4"}],"covers":["LR000862","LR004292"]},"LR006028":{"pair":"IL16 -> CD9","headline":"IL-16 is reported to signal through CD9 as an alternative receptor, with binding to CD9-expressing CHO cells and CD9-dependent responses; abstracts only.","interaction_type":"direct binding","direction_and_effect":"Agonist. Anti-CD9 antibodies blocked IL-16-driven chemotaxis and Ca2+ mobilisation in CD4-negative HMC-1 mast cells, and inhibited activation of cord-blood-derived human and mouse bone-marrow-derived mast cells by 50% to 60% [PMID:16144798]. CD9 knockdown in A549 cells reduced migration towards IL-16 [PMID:29884309].","molecular_requirements":"CD9 acts as an alternative to CD4, which HMC-1 cells lack [PMID:16144798]. Whether other co-receptors are needed is not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human cell lines (HMC-1, A549, CHO transfectants) and primary human and mouse mast cells [PMID:16144798]; A549 CRISPR knockdown clones [PMID:29884309]. The mouse pair is ortholog-inferred, not directly tested here.","localisation_and_range":"IL-16 is annotated as secreted [flag]; CD9 is annotated as a receptor [flag]. Range from papers is not described.","caveats":"Both papers were read as abstracts only. Evidence for the CHO binding is a single statement without affinity. The A549 study is a functional migration readout and only supports the hypothesis.","key_references":[{"PMID":"16144798","why":"Antibody block, antisense and CHO transfectant binding for IL-16 and CD9"},{"PMID":"29884309","why":"CRISPR CD9 knockdown reduces IL-16-directed migration"}],"covers":["LR002785","LR006028"]},"LR000871":{"pair":"IL17B -> IL17RB","headline":"IL-17B binds IL-17RB (SPR, flow cytometry, co-IP) in one human-protein study, read from the abstract only.","interaction_type":"direct binding","direction_and_effect":"Direction: IL-17B binds IL-17RB [PMID:10749887]. IL-17B injected in mice caused neutrophil migration in a dose-dependent manner, suggesting a proinflammatory cytokine [PMID:10749887]. GtoPdb lists an agonist interaction [DB:GtoPdb].","molecular_requirements":"Not reported in our evidence beyond single IL-17RB, a type I transmembrane protein [PMID:10749887]. BioGRID lists a reconstituted complex [DB:BioGRID].","affinity_potency":[],"species_and_systems":"Human protein binding; neutrophil migration was in mice with CHO-derived IL-17B [PMID:10749887]. Mouse pair is ortholog-inferred.","localisation_and_range":"IL-17RB described as a type I transmembrane protein [PMID:10749887]; IL-17B annotated as secreted [flag].","caveats":"Single study, abstract only, with no affinity. IL-17B in vivo effect was not shown to be via IL-17RB.","key_references":[{"PMID":"10749887","why":"SPR, flow cytometry and co-IP binding of IL-17B to IL-17BR"}],"covers":["LR000871","LR004301"]},"LR000880":{"pair":"IL1A -> IL1RAP","headline":"IL1RAP is an essential co-receptor for IL-1 signalling; direct IL-1alpha-IL1RAP binding is not shown, only a mouse knockout effect on affinity.","interaction_type":"functional only","direction_and_effect":"IL-1 agonists bound AcP-deficient cells through IL1R1 but failed to signal [PMID:9820540]; GtoPdb lists IL1A-IL1RAP as agonist [DB:GtoPdb].","molecular_requirements":"IL1RAP acts with IL1R1 and the pair is required for signalling by all IL-1 agonists [PMID:9820540]. Lack of AcP only moderately reduced murine IL-1alpha affinity, so IL1RAP is a minor contributor to IL-1alpha binding [PMID:9820540].","affinity_potency":[],"species_and_systems":"Mouse (AcP-deficient mice and fibroblasts, murine IL-1alpha) [PMID:9820540]. The mouse pair is the directly evidenced one; the human pair is ortholog-inferred.","localisation_and_range":"Ligand carries the secreted annotation flag [flag], which implies paracrine/endocrine range; receptor localisation beyond the receptor flag is not reported in our evidence.","caveats":"Abstract only. The paper does not show direct IL-1alpha-IL1RAP binding; IL1R1 is also needed. Co-receptor evidence only.","key_references":[{"PMID":"9820540","why":"IL1RAP-deficient mice and fibroblasts"}],"covers":["LR000880","LR004310"]},"LR011734":{"pair":"IL1B -> IL1B:IL1R1:IL1RAP","headline":"Database-asserted only, with structures of related complexes; no verified paper, and the complex lists IL1B as a receptor member.","interaction_type":"database-asserted only","direction_and_effect":"GtoPdb lists IL1B-IL1R1 and IL1B-IL1RAP as agonist [DB:GtoPdb]; PDB 4DEP shows the IL-1b signaling complex [DB:PDB 4DEP].","molecular_requirements":"IL1RAP associates with IL1R1 bound to IL1B to form the high affinity receptor complex per UniProt [DB:UniProt]; PDB 3O4O and 4DEP are structures of the complex [DB:PDB 3O4O, DB:PDB 4DEP].","affinity_potency":[],"species_and_systems":"No experiments from curated papers in our evidence.","localisation_and_range":"Ligand carries the secreted annotation flag [flag], which implies paracrine/endocrine range; receptor localisation beyond the receptor flag is not reported in our evidence.","caveats":"No curator-verified paper in our evidence; support rests on database records only. Two papers are pending. Affinity not reported.","key_references":[],"covers":["LR011734"]},"LR007306":{"pair":"IL1F10 -> IL1RAP:IL1RL2","headline":"Complex pair rests on a single UniProt annotation; no paper evidence.","interaction_type":"database-asserted only","direction_and_effect":"UniProt states IL1F10 is a ligand for IL-36R/IL1RL2 [DB:UniProt]; effect direction is not reported in our evidence.","molecular_requirements":"Complex of IL1RAP and IL1RL2; whether IL1RAP is needed for IL1F10 is not reported in our evidence.","affinity_potency":[],"species_and_systems":"Species and system not reported in our evidence (human only).","localisation_and_range":"IL1RAP and the complex are flagged transmembrane [flag].","caveats":"No papers were confirmed; the one paper judged was abstract_insufficient. The UniProt record concerns IL1RL2 alone, not the complex.","key_references":[],"covers":["LR007306"]},"LR006037":{"pair":"IL1F10 -> IL1RL2","headline":"IL-38 binds the IL-36 receptor (IL1RL2) specifically among the IL-1 receptor family and acts like an antagonist; two confirming papers.","interaction_type":"direct binding","direction_and_effect":"In a screen of immobilised receptor extracellular domains IL-38 bound only the IL-36 receptor, as did IL-36Ra [PMID:22315422]. Recombinant IL-38 reduced IL-22 (37% decrease), IL-17 (39% decrease) and IL-36gamma-induced IL-8 (42% decrease); in dendritic cells IL-38 increased LPS-induced IL-6 twofold [PMID:22315422]. A second paper reports IL-38 binding IL1R6 (alias of IL1RL2) [PMID:26892022].","molecular_requirements":"Receptor extracellular domain alone was tested; accessory chain requirement is not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human recombinant IL-38 (152 amino acids), human PBMC and monocyte-derived dendritic cells, immobilised receptor domains [PMID:22315422]; mouse pair inferred.","localisation_and_range":"IL1F10 is flagged secreted [flag].","caveats":"Both papers abstract-only in the dossier; the 2016 binding statement was browser-read and its spot-check is pending [PMID:26892022]. Dose-response is biphasic, unlike classical antagonist anakinra, so antagonism is not clean [PMID:22315422]. No affinity reported.","key_references":[{"PMID":"22315422","why":"Receptor-specific binding screen and functional effects"},{"PMID":"26892022","why":"Independent binding of IL-38 to IL1R6"}],"covers":["LR002794","LR006037"]},"LR004318":{"pair":"IL20 -> IL20RB","headline":"IL-20 binds IL20RB first with high affinity, then recruits IL20RA; well supported as a chain of the IL-20 receptor.","interaction_type":"direct binding","direction_and_effect":"IL-20 forms a stable high-affinity binary complex with sIL-20R2 (IL20RB), which creates the binding site for receptor I [PMID:14580208]. IL-20 signals through both IL-20RA/IL-20RB and IL-22R/IL-20RB [PMID:12351624] [PMID:11564763]. GtoPdb: Agonist [DB:GtoPdb].","molecular_requirements":"IL20RB is the shared chain of both type I and type II complexes [PMID:11564763] [PMID:12351624]; signalling needs a partner chain, IL20RA or IL22RA1.","affinity_potency":[],"species_and_systems":"Recombinant human soluble ectodomains from S2 cells [PMID:14580208]; transfected cell lines [PMID:12351624]. Mouse pair projected.","localisation_and_range":"IL-20 flagged secreted [flag].","caveats":"All papers abstract only; no numeric affinity reported in our evidence. Two other papers were abstract_insufficient.","key_references":[{"PMID":"14580208","why":"IL-20 binds receptor II (IL20RB) first with high affinity"},{"PMID":"11564763","why":"IL20RB shared by type I and II IL-20R"},{"PMID":"12351624","why":"Receptor sharing among IL-19, IL-20, IL-24"}],"covers":["LR000888","LR004318"]},"LR007315":{"pair":"IL22 -> IL10RB:IL22RA1","headline":"IL-22 binds both IL22RA1 and IL10RB chains, with the two-chain complex binding best; supported by two papers and structures.","interaction_type":"direct binding","direction_and_effect":"Each chain binds IL-TIF (IL-22) independently by cross-linking, and binding to the complex is greater than to either chain alone [PMID:11035029]. IL22RA1 with CRF2-4 enables IL-22 signalling [PMID:10875937]. GtoPdb lists agonists [DB:GtoPdb].","molecular_requirements":"Both IL22RA1 (CRF2-9) and IL10RB (IL-10R2) are needed for a functional receptor in hamster cells; in monkey COS cells CRF2-9 alone confers sensitivity. CRF2-9 recruits STATs [PMID:11035029]. Structures of the two partners exist [DB:PDB 3DGC][DB:PDB 3DLQ].","affinity_potency":[],"species_and_systems":"Human ligand and receptor; COS, hamster and other responsive cell lines [PMID:11035029][PMID:10875937].","localisation_and_range":"IL-22 is flagged secreted and the complex transmembrane [flag].","caveats":"Both papers read as abstracts only. One further paper was unresolvable and one abstract_insufficient.","key_references":[{"PMID":"11035029","why":"each chain binds IL-22; complex binds better"},{"PMID":"10875937","why":"IL-22 signals via CRF2-4 and IL-22R"}],"covers":["LR007315"]},"LR004327":{"pair":"IL24 -> IL20RA","headline":"IL-24 signals through IL20RA paired with IL20RB; multiple papers agree, though all were read as abstracts.","interaction_type":"direct binding","direction_and_effect":"IL-24 is a ligand for IL-20R1/IL-20R2 and IL-22R1/IL-20R2, and COS cells with either heterodimer bind it with similar saturation kinetics [PMID:11706020]; mda-7 binds the type I IL-20R complex with STAT3 phosphorylation [PMID:11564763]. Agonist per GtoPdb [DB:GtoPdb].","molecular_requirements":"IL20RA acts only with IL20RB; IL-24 can alternatively use IL22RA1 with IL20RB [PMID:12351624][PMID:20061404]. A soluble homodimeric IL-20R2 blocks IL-24 [PMID:20061404].","affinity_potency":[],"species_and_systems":"Human receptors in COS, BHK cells and keratinocytes [PMID:11706020]; IL-24 transgenic mice show epidermal phenotypes that appear IL-22R1 dependent [PMID:20061404].","localisation_and_range":"IL-24 is flagged secreted [flag].","caveats":"All abstract-only. Binding is to heterodimers, so the IL20RA row inherits complex evidence. In vivo phenotype is described as IL-22R1 dependent, not IL20RA dependent [PMID:20061404].","key_references":[{"PMID":"11706020","why":"IL-24 binds IL-20R1/IL-20R2 and IL-22R1/IL-20R2"},{"PMID":"11564763","why":"mda-7 binds type I IL-20R"},{"PMID":"20061404","why":"IL-24 transgenic mice; soluble IL-20R2 blocks IL-24"}],"covers":["LR000897","LR004327"]},"LR000907":{"pair":"IL31 -> OSMR","headline":"OSMR is the second chain of the IL-31 receptor; evidence is functional and abstract-only.","interaction_type":"functional only","direction_and_effect":"IL-31 signals through a receptor composed of IL-31 receptor A and oncostatin M receptor [PMID:15184896]. The second signal transducing receptor for IL-31 'seems to be' OSMRbeta [PMID:15194700]. GtoPdb: agonist [DB:GtoPdb].","molecular_requirements":"OSMR works with IL31RA, which UniProt calls the IL31-binding subunit [DB:UniProt Q6EBC2]. Jak1 is activated in complexes of the IL31RA chain (GPL) with OSMRbeta, and also in a homomeric IL31RA complex, so OSMR may not be required for all signalling [PMID:15194700].","affinity_potency":[],"species_and_systems":"Experiment species unspecified in the curator record [PMID:15184896]; the mouse pair is ortholog-inferred.","localisation_and_range":"IL-31 is flagged secreted [flag].","caveats":"Both papers are abstract only. The OSMR assignment is hedged ('seems to be') [PMID:15194700]. No binding assay or affinity in our evidence; whether IL-31 contacts OSMR directly is not shown.","key_references":[{"PMID":"15184896","why":"IL-31 signals through IL31RA and OSMR."},{"PMID":"15194700","why":"Signalling of IL31RA with OSMRbeta; OSMR assignment hedged."}],"covers":["LR000907","LR004336"]},"LR004336":{"pair":"IL31 -> OSMR","headline":"OSMR is the second chain of the IL-31 receptor; evidence is functional and abstract-only.","interaction_type":"functional only","direction_and_effect":"IL-31 signals through a receptor composed of IL-31 receptor A and oncostatin M receptor [PMID:15184896]. The second signal transducing receptor for IL-31 'seems to be' OSMRbeta [PMID:15194700]. GtoPdb: agonist [DB:GtoPdb].","molecular_requirements":"OSMR works with IL31RA, which UniProt calls the IL31-binding subunit [DB:UniProt Q6EBC2]. Jak1 is activated in complexes of the IL31RA chain (GPL) with OSMRbeta, and also in a homomeric IL31RA complex, so OSMR may not be required for all signalling [PMID:15194700].","affinity_potency":[],"species_and_systems":"Experiment species unspecified in the curator record [PMID:15184896]; the mouse pair is ortholog-inferred.","localisation_and_range":"IL-31 is flagged secreted [flag].","caveats":"Both papers are abstract only. The OSMR assignment is hedged ('seems to be') [PMID:15194700]. No binding assay or affinity in our evidence; whether IL-31 contacts OSMR directly is not shown.","key_references":[{"PMID":"15184896","why":"IL-31 signals through IL31RA and OSMR."},{"PMID":"15194700","why":"Signalling of IL31RA with OSMRbeta; OSMR assignment hedged."}],"covers":["LR000907","LR004336"]},"LR001861":{"pair":"IL32 -> ITGB3","headline":"IL-32 binds integrin beta3 through its RGD motif in one abstract-level cancer paper.","interaction_type":"direct binding","direction_and_effect":"CAF-derived IL32 specifically bound integrin \u03b23 through the RGD motif and activated p38 MAPK signalling in breast cancer cells (agonist), increasing fibronectin, N-cadherin and vimentin expression and tumour cell invasion [PMID:30391782]. Knockdown of IL32 or integrin \u03b23 inactivated p38 MAPK [PMID:30391782].","molecular_requirements":"Integrin \u03b23 alone is named; the alpha partner is not reported in our evidence. The RGD motif of IL32 is needed for binding [PMID:30391782].","affinity_potency":[],"species_and_systems":"Human cancer-associated fibroblasts and breast cancer cells [PMID:30391782].","localisation_and_range":"IL32 is flagged secreted; ITGB3 is flagged not secreted [flag]. The paper describes paracrine CAF-to-tumour-cell signalling [PMID:30391782].","caveats":"Single paper read as abstract only; no affinity or binding assay detail reported in our evidence. No database records support this pair. Integrin \u03b23 is a chain of heterodimeric integrins, so alpha-partner expression matters for complex-aware scoring.","key_references":[{"PMID":"30391782","why":"IL32 binds integrin \u03b23 via RGD and drives p38 MAPK signalling and invasion."}],"covers":["LR001861"]},"LR005209":{"pair":"IL36A -> IL1RL2","headline":"IL36A activates IL1RL2 (IL-36R) in functional assays; supported by two abstract-only papers.","interaction_type":"functional only","direction_and_effect":"IL-1F6/F8/F9 activate NF-kappaB in an IL-1Rrp2 (IL1RL2)-dependent manner and anti-IL-1Rrp2 antibodies block it [PMID:14734551]. IL36R activation of mouse and human fibroblasts induced fibrosis-related genes including collagen type VI [PMID:30452921]. GtoPdb: Agonist [DB:GtoPdb].","molecular_requirements":"Signalling needs IL-1RAcP as well as IL1RL2 per the companion evidence; single IL1RL2 rows inherit complex-level evidence [PMID:14734551].","affinity_potency":[],"species_and_systems":"Human and mouse cell lines [PMID:14734551]; mouse and human fibroblasts and human intestinal tissue [PMID:30452921].","localisation_and_range":"Ligand annotated as secreted [flag]; receptor-side localisation not otherwise reported.","caveats":"Both papers abstract-only. No binding measurement or affinity. 14734551 names IL-1F6/F8/F9 rather than IL36A.","key_references":[{"PMID":"14734551","why":"IL-1Rrp2-dependent NF-kappaB activation"},{"PMID":"30452921","why":"IL36R activation in fibroblasts"}],"covers":["LR001864","LR005209"]},"LR006046":{"pair":"IL36G -> IL1RAP","headline":"IL1RAP is a co-receptor in IL-36 signalling (one functional paper); a PDB structure is also listed.","interaction_type":"functional only","direction_and_effect":"IL-1RAcP antibodies and a cytoplasmically deleted IL-1RAcP blocked NF-kappaB activation by IL-1F6/F8/F9 [PMID:14734551]. GtoPdb: Agonist [DB:GtoPdb].","molecular_requirements":"IL1RAP acts as an obligate co-receptor with IL-1Rrp2 [PMID:14734551]. PDB 9I7X contains chains of Q9NZH8 and Q9NPH3 [DB:PDB 9I7X].","affinity_potency":[],"species_and_systems":"Human cell lines [PMID:14734551].","localisation_and_range":"Ligand annotated as secreted [flag]; receptor-side localisation not otherwise reported.","caveats":"One abstract-only paper that names IL-1F6/F8/F9. No affinity reported.","key_references":[{"PMID":"14734551","why":"IL-1RAcP required for signalling"}],"covers":["LR002804","LR006046"]},"LR007324":{"pair":"IL36G -> IL1RAP:IL1RL2","headline":"IL-36 acting on the IL1RAP:IL1RL2 complex rests on database records only; no judged papers.","interaction_type":"database-asserted only","direction_and_effect":"GtoPdb lists agonist records for both IL1RAP and IL1RL2 [DB:GtoPdb]; Reactome has a binding reaction IL36:IL1RL2 with IL1RAP [DB:Reactome]. UniProt and a PDB structure (9I7X, chains Q9NZH8 and Q9NPH3) are listed [DB:UniProt][DB:PDB 9I7X].","molecular_requirements":"Complex of IL1RAP and IL1RL2 (listed members); which subunit binds the ligand is not reported in these records.","affinity_potency":[],"species_and_systems":"Human only; no experimental paper in our evidence.","localisation_and_range":"Ligand annotated as secreted [flag]; receptor complex annotated transmembrane [flag].","caveats":"No papers (three review-only rows). Support is database assertion only.","key_references":[],"covers":["LR007324"]},"LR002806":{"pair":"IL37 -> IL18R1","headline":"IL-37 binds IL-18Ralpha in one abstract-level paper plus database records; effect is anti-inflammatory.","interaction_type":"direct binding","direction_and_effect":"IL-37 bound IL-18Ralpha and used IL-1R8 to activate an anti-inflammatory program [PMID:25729923]. GtoPdb lists Agonist [DB:GtoPdb]; Reactome and BioGRID record binding [DB:Reactome][DB:BioGRID].","molecular_requirements":"Function needs IL-1R8 as well; silencing IL-18Ralpha impaired IL-37 activity [PMID:25729923].","affinity_potency":[],"species_and_systems":"Human PBMC and IL-37 transgenic mice [PMID:25729923]; reconstituted complex in BioGRID [DB:BioGRID].","localisation_and_range":"Ligand annotated as secreted [flag]; receptor-side localisation not otherwise reported.","caveats":"Abstract only; binding method not stated and no affinity. Experiment species fields are blank.","key_references":[{"PMID":"25729923","why":"IL-37-IL-1R8-IL-18Ralpha complex"}],"covers":["LR002806"]},"LR000916":{"pair":"IL5 -> IL5RA","headline":"IL5 binds IL5RA directly with nM to sub-nM affinity; well supported by binding and structure data.","interaction_type":"direct binding","direction_and_effect":"IL5 is an agonist at IL5RA [DB:GtoPdb]. The human alpha chain binds IL-5 with high affinity by itself [PMID:1732409]; hIL5 forms a 1:1 complex with soluble receptor alpha [PMID:7721873].","molecular_requirements":"IL5RA alone suffices for binding in human COS7 cells [PMID:1732409]; signalling uses IL5RA with the common beta chain CSF2RB [DB:UniProt]. Binding determinants lie in FnIII domains 1-3 [PMID:10880230].","affinity_potency":[{"value":"Kd 250-590 pM","assay":"IL-5 binding","system":"COS7 cells transfected with human IL-5 receptor cDNA","cite":"PMID:1732409"},{"value":"Kd 3.1 nM","assay":"titration microcalorimetry","system":"human IL5 with soluble IL5R alpha, Drosophila-expressed","cite":"PMID:7721873"},{"value":"Kd 2.0 nM","assay":"titration microcalorimetry","system":"shIL5R alpha-Fc chimera","cite":"PMID:7721873"}],"species_and_systems":"Human proteins; the mouse alpha chain binds IL-5 with low affinity (Kd approximately 10 nM) [PMID:1732409]; ovine IL-5 activates human but not mouse alpha [PMID:10880230].","localisation_and_range":"IL4 is flagged secreted and non-transmembrane [flag], so it acts as a diffusible ligand on receptor-bearing cells; the receptor is flagged as a transmembrane receptor [flag].","caveats":"Abstracts only. Mouse pair is listed directly, but no mouse-specific binding data are shown beyond the low-affinity statement.","key_references":[{"PMID":"7721873","why":"Calorimetry and structure, Kd 3.1 nM"},{"PMID":"1732409","why":"Cloning and high-affinity binding"},{"PMID":"10880230","why":"Epitope mapping by chimeras"}],"covers":["LR000916","LR004344"]},"LR004345":{"pair":"Il6 -> Il6ra","headline":"Mouse Il6 to Il6ra projected from human structural evidence; no mouse experiments in our evidence.","interaction_type":"direct binding","direction_and_effect":"IL-6 is engaged by IL-6Ralpha before gp130 [PMID:12829785]; the D3 domain of IL6R carries more than 90% of binding energy to IL-6 [PMID:14557255].","molecular_requirements":"Il6ra is the ligand-binding chain; gp130 is recruited afterwards [PMID:12829785].","affinity_potency":[],"species_and_systems":"Both papers used human proteins by NMR or crystallography; the mouse pair is ortholog-inferred [PMID:12829785][PMID:14557255].","localisation_and_range":"Secreted ligand [flag]; receptor not annotated as transmembrane in this dossier.","caveats":"Evidence is human, projected to mouse; abstracts only. One further paper was abstract_insufficient.","key_references":[{"PMID":"12829785","why":"Hexameric complex structure (human)"},{"PMID":"14557255","why":"NMR epitope mapping (human)"}],"covers":["LR004345"]},"LR004354":{"pair":"INHBA -> ACVR1","headline":"Activin A binds ACVR1 to form a non-signaling complex; one verified paper (full text) supports binding with an antagonist-like sequestering effect.","interaction_type":"direct binding","direction_and_effect":"Activin A binds ACVR1 to form a non-signaling complex (NSC) rather than activating Smad1/5/8; the curator labels the effect antagonist [PMID:32515349]. The ACVR1-Activin A-type II receptor complex did not induce phosphorylation of the proteins on a phosphokinase array [PMID:32515349]. UniProt describes an apparent inhibition of ACVR1-mediated BMP signalling [DB:UniProt].","molecular_requirements":"The complex includes a type II receptor (ACVR1-Activin A-type II receptor) [PMID:32515349]. The finger 2 tip loop of activin A is required: muteins that lost it could not form the NSC [PMID:32515349].","affinity_potency":[],"species_and_systems":"Human ACVR1 overexpressed in HEK293 cells and mouse embryonic stem cells with Acvr1b knockout; mouse pair is projected from human [PMID:32515349].","localisation_and_range":"Ligand carries a secreted flag [flag]; the receptor is a membrane receptor, with range otherwise not reported in our evidence.","caveats":"Effect is non-signaling sequestration, not activation, even though the interaction record is labelled Stimulatory. Binding was inferred from signalling and dimerization readouts; affinity not reported. Curated from abstract level, with full text supporting.","key_references":[{"PMID":"32515349","why":"Shows activin A forms a non-signaling complex with ACVR1 and type II receptors."}],"covers":["LR000931","LR004354"]},"LR000934":{"pair":"INHBA -> ACVR2B","headline":"Binding of activin A to ACVR2B is supported by a verified competition study and a structure.","interaction_type":"direct binding","direction_and_effect":"Labelled activin was displaced by inhibin from the activin type II receptors, especially type IIB [PMID:9202237]. GtoPdb lists agonist [DB:GtoPdb].","molecular_requirements":"Type II receptor binds activin directly; UniProt says type-2 receptors act as primary activin receptors [DB:UniProt]. PDB 7OLY holds activin A with an ActRIIB-Alk4 fusion [DB:PDB 7OLY].","affinity_potency":[],"species_and_systems":"Chinese hamster ovary cells; species of ligand and receptor not stated in our evidence [PMID:9202237].","localisation_and_range":"Ligand secreted flag, receptor transmembrane flag [flag].","caveats":"The paper concerns inhibin displacing activin, so it supports ACVR2B binding of activin only indirectly; abstract only; no affinity.","key_references":[{"PMID":"9202237","why":"Competition binding shows activin and inhibin use type II receptors, especially IIB."}],"covers":["LR000934","LR004357"]},"LR007261":{"pair":"INHBA:INHBB -> ACVR1B:ACVR2B","headline":"Activin A/B ligand complex to ACVR1B:ACVR2B; supported by database records only.","interaction_type":"database-asserted only","direction_and_effect":"GtoPdb lists each activin subunit with each receptor chain as agonist interactions [DB:GtoPdb]. Reactome describes activin A, AB and B binding an ACVR2A,B:ACVR1B receptor [DB:Reactome].","molecular_requirements":"BioGRID records ACVR2A and ACVR2B with INHBA and INHBB [PMID:9202237]; structures cover activin A with an ActRIIB-Alk4 fusion [DB:PDB 7OLY] and with ACVR2A [DB:PDB 7U5P]. Both type II chains appear, so which is required is not reported.","affinity_potency":[],"species_and_systems":"Not reported in our evidence beyond human database records.","localisation_and_range":"Ligand is flagged secreted [flag], so likely paracrine/endocrine; receptor is flagged transmembrane [flag].","caveats":"No paper-level evidence is held for this pair (only review-only or abstract-insufficient rows), so it rests on database records alone.","key_references":[],"covers":["LR007261"]},"LR008260":{"pair":"INHBB -> ACVR1C:ACVR2B","headline":"Activin B to ACVR1C:ACVR2B; supported by database records only.","interaction_type":"database-asserted only","direction_and_effect":"GtoPdb lists INHBB with each receptor chain as agonist [DB:GtoPdb]. UniProt: ACVR1C is a receptor for activin AB, activin B, activin E and NODAL [DB:UniProt].","molecular_requirements":"Chain-level records; BioGRID covers the type II chain with INHBB [PMID:9202237]. Complex requirements not reported in our evidence.","affinity_potency":[],"species_and_systems":"Not reported in our evidence beyond human database records.","localisation_and_range":"Ligand is flagged secreted [flag], so likely paracrine/endocrine; receptor is flagged transmembrane [flag].","caveats":"Only abstract-insufficient rows exist; no curator-verified paper supports the assembled complex.","key_references":[],"covers":["LR008260"]},"LR004363":{"pair":"INHBB -> ACVR2A","headline":"Activin B binds ACVR2A: crystal-structure-level evidence for the activin/ACVR2A mode, plus ALK4/ALK7 context; mouse pair ortholog-inferred.","interaction_type":"direct binding","direction_and_effect":"ACVR2A high-affinity growth factors include activin A and activin B; effect recorded as agonist [PMID:35643319]. A second paper shows activin B signalling via ActRIIA/ALK7 [PMID:15196700].","molecular_requirements":"Structures were solved for BMPR2 with activin B and ACVR2A with activin A, not activin B with ACVR2A itself [PMID:35643319]. Signalling needs a type I partner (ALK7 or ALK4) [PMID:15196700].","affinity_potency":[],"species_and_systems":"Human ligand and receptor per curator fields [PMID:35643319]; the second paper used mouse reconstitution [PMID:15196700]. Mouse pair is ortholog-inferred.","localisation_and_range":"Ligand flagged secreted and receptor transmembrane [flag].","caveats":"Both papers read as abstract only. The binding spectrum claim for activin B/ACVR2A is stated at group level in the abstract [PMID:35643319]. No affinity values reported in our evidence.","key_references":[{"PMID":"35643319","why":"Structures and binding spectrum of ACVR2A/BMPR2"},{"PMID":"15196700","why":"Activin B receptor combinations"}],"covers":["LR000940","LR004363"]},"LR002815":{"pair":"INHBC -> ACVR1C","headline":"Activin C (INHBC) signals through ACVR1C (ALK7) in reporter assays and human adipocytes; two abstract-level papers.","interaction_type":"functional only","direction_and_effect":"Activin C activated SMAD2/3 signalling via ALK7 and suppressed lipolysis in human adipocytes [PMID:39283655]. Using an ALK7-dependent HEK293T reporter, an anti-ALK7 antibody nearly abrogated activin C signalling [PMID:35736809].","molecular_requirements":"Activin C signals exclusively through ALK7 among SMAD2/3 type I receptors; it has low affinity for type II receptors, and did not form a stable complex with ActRIIA or ActRIIB [PMID:35736809].","affinity_potency":[],"species_and_systems":"Human immortalized adipocytes [PMID:39283655]; HEK293T reporter cells and mature murine adipocytes [PMID:35736809].","localisation_and_range":"Ligand flagged secreted [flag]; liver-adipose endocrine axis proposed [PMID:39283655].","caveats":"Abstracts read, with excerpts for one paper. No numerical affinity in our evidence. Two further confirmed rows are not shown.","key_references":[{"PMID":"35736809","why":"ALK7 specificity and type II receptor binding of activin C"},{"PMID":"39283655","why":"Activin C activates ALK7 in human adipocytes"}],"covers":["LR002815","LR006055"]},"LR006055":{"pair":"INHBC -> ACVR1C","headline":"Activin C (INHBC) signals through ACVR1C (ALK7) in reporter assays and human adipocytes; two abstract-level papers.","interaction_type":"functional only","direction_and_effect":"Activin C activated SMAD2/3 signalling via ALK7 and suppressed lipolysis in human adipocytes [PMID:39283655]. Using an ALK7-dependent HEK293T reporter, an anti-ALK7 antibody nearly abrogated activin C signalling [PMID:35736809].","molecular_requirements":"Activin C signals exclusively through ALK7 among SMAD2/3 type I receptors; it has low affinity for type II receptors, and did not form a stable complex with ActRIIA or ActRIIB [PMID:35736809].","affinity_potency":[],"species_and_systems":"Human immortalized adipocytes [PMID:39283655]; HEK293T reporter cells and mature murine adipocytes [PMID:35736809].","localisation_and_range":"Ligand flagged secreted [flag]; liver-adipose endocrine axis proposed [PMID:39283655].","caveats":"Abstracts read, with excerpts for one paper. No numerical affinity in our evidence. Two further confirmed rows are not shown.","key_references":[{"PMID":"35736809","why":"ALK7 specificity and type II receptor binding of activin C"},{"PMID":"39283655","why":"Activin C activates ALK7 in human adipocytes"}],"covers":["LR002815","LR006055"]},"LR000943":{"pair":"INHBC -> ACVR2B","headline":"Activin C reported to bind ACVR2B and antagonise activin A signalling; one abstract-level paper.","interaction_type":"direct binding","direction_and_effect":"Activin-C acts as an activin-A antagonist by binding activin receptor subunits IIA and IIB and modulating canonical Smad signalling [PMID:25180271]. The database-style effect label is Stimulatory, which differs from this antagonist reading.","molecular_requirements":"Type II receptor subunit binding only; a type I partner is not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human granulosa cell line and human gonadal/adrenal cancer tissue [PMID:25180271]. Mouse pair is projected from human evidence (ortholog inferred).","localisation_and_range":"Ligand is flagged secreted [flag].","caveats":"Single paper, read as abstract only; binding method not stated in the abstract. Two confirmed rows are counted but one paper is shown; one other row was review-only and one abstract-insufficient.","key_references":[{"PMID":"25180271","why":"Activin-C binds ActRIIA/IIB and antagonises activin A in human gonadal/adrenal cancer settings"}],"covers":["LR000943","LR004366"]},"LR002824":{"pair":"ITGAM -> CD209","headline":"Mac-1 on neutrophils is reported to bind DC-SIGN (CD209), but only as background in one abstract.","interaction_type":"functional only","direction_and_effect":"DC maturation by neutrophils needs binding of DC-SIGN to Mac-1 on the neutrophil [PMID:16246332].","molecular_requirements":"The evidence concerns the Mac-1 heterodimer, not ITGAM alone; CEACAM1 binding is also required for DC-neutrophil contact [PMID:16246332].","affinity_potency":[],"species_and_systems":"Human neutrophils and dendritic cells [PMID:16246332].","localisation_and_range":"Membrane proteins acting in cell-cell contact [PMID:16246332].","caveats":"The Mac-1 binding is stated as prior work; the paper's own finding is CEACAM1. Abstract only. No direct binding data in our evidence.","key_references":[{"PMID":"16246332","why":"DC-SIGN engages Mac-1 and CEACAM1 on neutrophils"}],"covers":["LR002824"]},"LR006064":{"pair":"ITGB1 -> ADGRE5","headline":"Integrin alpha5beta1 is reported as a high-affinity counterreceptor for CD97; the ITGB1 row inherits this abstract-level evidence.","interaction_type":"direct binding","direction_and_effect":"Soluble CD97 drives integrin-dependent HUVEC migration [PMID:15576472].","molecular_requirements":"Evidence is for the alpha5beta1 heterodimer, not ITGB1 alone [PMID:15576472].","affinity_potency":[],"species_and_systems":"Human HUVEC and in vivo angiogenesis assay [PMID:15576472]; mouse pair is orthology-projected.","localisation_and_range":"ADGRE5 flagged secreted [flag].","caveats":"Abstract only; no affinity values; chain-only attribution.","key_references":[{"PMID":"15576472","why":"Alpha5beta1 as counterreceptor for CD97"}],"covers":["LR002826","LR006064"]},"LR000952":{"pair":"JAG1 -> NOTCH1","headline":"Canonical Notch ligand-receptor pair with direct binding and functional support, plus extensive database records.","interaction_type":"direct binding","direction_and_effect":"Soluble Notch1 extracellular protein bound JAG1 directly in solid-phase assays, Ca2+-dependent [PMID:11006133]. In cell-based assays JAG1 activated NOTCH1 [PMID:32820046]. Blocking Jagged1 or Notch1 with antibodies inhibited Treg suppressor function in vitro [PMID:18292500]. The interaction is annotated as stimulatory.","molecular_requirements":"Binding required Ca2+ [PMID:11006133]. Fringe enzymes modulate activity in a ligand- and receptor-specific way, though the abstract does not give JAG1-NOTCH1 specifics [PMID:32820046]. UniProt also notes interaction with NOTCH1 in the presence of calcium ions [DB:UniProt].","affinity_potency":[],"species_and_systems":"Human proteins in the binding and signalling papers [PMID:11006133][PMID:32820046]; species unspecified for the Treg study [PMID:18292500]. The mouse pair is a separate record, and the human pair is ortholog-inferred.","localisation_and_range":"JAG1 is flagged as transmembrane [flag], so signalling is likely contact-dependent; the papers do not state this.","caveats":"All three papers were read as abstracts only. The Treg paper is indirect (antibody blockade) [PMID:18292500]. Affinities were said to differ between DSL proteins but are not given in our evidence [PMID:11006133]. Database support includes BioGRID, IntAct, Reactome [DB:BioGRID][DB:IntAct][DB:Reactome].","key_references":[{"PMID":"11006133","why":"Direct solid-phase binding"},{"PMID":"32820046","why":"Cell-based NOTCH1 activation by JAG1"},{"PMID":"18292500","why":"Blocking antibodies in Treg function"}],"covers":["LR000952","LR004375"]},"LR004381":{"pair":"JAG2 -> NOTCH3","headline":"Jagged2 binds Notch3 directly in vitro; one paper plus database records.","interaction_type":"direct binding","direction_and_effect":"Soluble Notch3 bound Jagged2 on cells and in solid-phase assays, Ca2+-dependent [PMID:11006133]. Annotation: stimulatory.","molecular_requirements":"Ca2+ required [PMID:11006133].","affinity_potency":[],"species_and_systems":"Human proteins [PMID:11006133].","localisation_and_range":"JAG2 flagged as not secreted [flag].","caveats":"Abstract-only; no affinity in our evidence. BioGRID and Reactome records exist [DB:BioGRID][DB:Reactome].","key_references":[{"PMID":"11006133","why":"Direct binding"}],"covers":["LR000958","LR004381"]},"LR007045":{"pair":"JAM2 -> ITGA4:ITGB1","headline":"JAM2 engages alpha4beta1 integrin in T cells, conditional on JAM3; functional evidence only.","interaction_type":"functional only","direction_and_effect":"Using neutralizing integrin antibodies, an interaction between JAM2 and alpha4beta1 was defined in T cells; TBC 772 blocked it [PMID:12070135].","molecular_requirements":"Both subunits form the complex; engagement required prior JAM2-JAM3 adhesion [PMID:12070135]. The first Ig-like fold binds both counter-receptors [PMID:12070135].","affinity_potency":[],"species_and_systems":"Human T cells [PMID:12070135].","localisation_and_range":"JAM2 flagged as not secreted [flag]; interaction class is Adhesion-Adhesion [flag].","caveats":"Abstract-only; no direct binding; conditional on JAM3. Reactome records the complex [DB:Reactome].","key_references":[{"PMID":"12070135","why":"Adhesion assays"}],"covers":["LR007045"]},"LR002833":{"pair":"JAM2 -> ITGB1","headline":"JAM2 engages alpha4beta1 in T cells; evidence concerns the heterodimer, not beta1 alone.","interaction_type":"functional only","direction_and_effect":"Neutralizing integrin antibodies defined a JAM2-alpha4beta1 interaction in T cells [PMID:12070135]. Reactome records it [DB:Reactome].","molecular_requirements":"The partner subunit alpha4 is required; engagement occurred only after JAM2-JAM3 adhesion [PMID:12070135].","affinity_potency":[],"species_and_systems":"Human T cell line [PMID:12070135].","localisation_and_range":"JAM2 flagged as not secreted [flag].","caveats":"Chain-only: beta1 alone was not tested. Abstract-only; no direct binding.","key_references":[{"PMID":"12070135","why":"JAM2-alpha4beta1 in T cells"}],"covers":["LR002833","LR006070"]},"LR001870":{"pair":"JAM3 -> JAM2","headline":"JAM-B/JAM-C heterophilic interaction supported by one in vivo and human-cell functional paper plus UniProt, Reactome and IntAct records.","interaction_type":"functional only","direction_and_effect":"JAM-B/JAM-C engagement is required for hematopoietic stem and progenitor cell homing and reconstitution: a blocking anti-Jam-c antibody inhibited reconstitution and homing and induced mobilisation in a Jam-b-dependent manner [PMID:24357068]. UniProt describes JAM2 and JAM3 as mediating heterotypic cell-cell interactions with each other [DB:UniProt].","molecular_requirements":"Single chains on each side; no co-receptor requirement reported in our evidence.","affinity_potency":[],"species_and_systems":"Mouse in vivo (antibody treatment, reconstitution, homing), translated to human cells where an adhesive JAM-B/JAM-C interaction was found between human HSPC and mesenchymal stem cells, but not with endothelial cells or osteoblasts [PMID:24357068].","localisation_and_range":"Cell-cell adhesion between neighbouring cells (juxtacrine); JAM2 is flagged transmembrane [flag]. JAM3 also carries a secreted flag [flag].","caveats":"Abstract-only read. Evidence is antibody blockade rather than direct binding; IntAct protein array and solid phase assay and Reactome binding records add database support [DB:IntAct, DB:Reactome]. The interaction was cell-type restricted in human cells [PMID:24357068].","key_references":[{"PMID":"24357068","why":"Jam-b/Jam-c in HSPC homing and mobilisation, mouse and human"}],"covers":["LR001870","LR005215"]},"LR006073":{"pair":"JAM3 -> JAM3","headline":"JAM-C homophilic binding shown with purified protein and adhesion assays in human cells; mapped to the D1 Ig domain.","interaction_type":"direct binding","direction_and_effect":"Soluble JAM-C bound immobilised JAM-C in a purified system, JAM-C-transfected CHO cells adhered to immobilised JAM-C, and this mediated lung carcinoma NCI-H522 cell adhesion to JAM-C and to endothelial cells, blocked by soluble JAM-C or isolated D1 [PMID:16118203].","molecular_requirements":"Homophilic binding is mediated by the amino-terminal Ig domain D1, not D2; the E66R mutation in the Arg64-Ile65-Glu66 motif abolished it [PMID:16118203].","affinity_potency":[],"species_and_systems":"Human JAM-C; purified proteins, CHO transfectants, NCI-H522 cells and endothelial cells; abstract-only read. The mouse entry is ortholog-inferred.","localisation_and_range":"Contact-dependent between adjacent cells (tumour-endothelial); the entity flag marks JAM3 secreted [flag], not supported by the paper.","caveats":"Single paper, read as abstract. IntAct (protein array, solid phase assay) and Reactome (JAM3 dimerises) records agree [DB:IntAct, DB:Reactome]. A homodimer means ligand and receptor are the same chain. No affinity reported.","key_references":[{"PMID":"16118203","why":"Homophilic JAM-C binding and D1/E66 mapping"}],"covers":["LR002836","LR006073"]},"LR000961":{"pair":"KITLG -> KIT","headline":"Human SCF binds KIT with high-affinity direct evidence, crystal structures and many database records.","interaction_type":"direct binding","direction_and_effect":"SCF is the KIT ligand, shown by direct binding and cross-linking [PMID:1375232, PMID:7680037]; the crystal structure shows SCF dimers symmetrically contacting D1-D3 of two KIT ectodomains, with KIT D4 and D5 forming lateral homotypic contacts [PMID:17662946]. GtoPdb lists an agonist interaction [DB:GtoPdb].","molecular_requirements":"SCF dimer to two KIT chains forming a 2:2 complex [PMID:17662946]; the ectodomain alone binds ligand [PMID:1375232]; the third Ig-like domain contributes to affinity [PMID:7680037].","affinity_potency":[{"value":"approximately 200 to 300 pmol/L","assay":"125I-SCF binding, soluble c-kit from human serum or OCIM1 cells","system":"human soluble receptor","cite":"PMID:7536489"},{"value":"approximately 1.5 nmol/L","assay":"125I-SCF binding, recombinant soluble c-kit","system":"CHO-expressed","cite":"PMID:7536489"}],"species_and_systems":"Human KIT ectodomain crystal structure [PMID:17662946]; soluble receptors from human serum and OCIM1 cells [PMID:7536489]; a mouse SCF paper is also included [PMID:1698556]. Rodent SCF has reduced affinity toward human KIT according to the structural paper [PMID:17662946].","localisation_and_range":"SCF is flagged secreted and transmembrane [flag]; soluble KIT forms exist in human serum and can bind SCF [PMID:7536489].","caveats":"Most papers were abstract reads. One pending paper is not shown. The rodent SCF reduced-affinity point suggests species matters in cross-species work [PMID:17662946]. Affinities are for soluble receptors, not full-length KIT on cells.","key_references":[{"PMID":"17662946","why":"Crystal structure of KIT ectodomain with SCF, 2:2 complex"},{"PMID":"7536489","why":"Affinity of soluble c-kit for SCF"},{"PMID":"7680037","why":"Maps SCF binding site on KIT ectodomain"}],"covers":["LR000961"]},"LR010942":{"pair":"KLB -> FGFR1","headline":"betaKlotho binds FGFR1 and is needed for FGF19/FGF21 activity; abstract-level binding plus database records.","interaction_type":"direct binding","direction_and_effect":"betaKlotho binds FGFRs and is required for FGF21 activity; FGF19 and FGF21 can signal through FGFR1-3 bound by betaKlotho and increase glucose uptake in adipocytes expressing FGFR1 [PMID:17623664]. The curated modulatory effect is Stimulatory [flag].","molecular_requirements":"betaKlotho acts as a co-receptor together with FGFR isoforms; the FGF19 subfamily ligand is required for the metabolic signal [PMID:17623664].","affinity_potency":[],"species_and_systems":"Human according to the curator fields; target tissues and receptor co-expression [PMID:17623664]. BioGRID lists affinity capture-western and FRET, and IntAct lists surface plasmon resonance [DB:BioGRID][DB:IntAct].","localisation_and_range":"Not reported in our evidence; KLB is flagged as a receptor [flag].","caveats":"One paper, read as an abstract only. Three further papers were judged abstract_insufficient. Direct KLB-FGFR1 binding is stated only in passing in the abstract; no affinity reported. Signalling needs FGF19 or FGF21, which are not part of this pair.","key_references":[{"PMID":"17623664","why":"betaKlotho with FGFR isoforms sets FGF19/FGF21 tissue specificity"}],"covers":["LR010942"]},"LR012427":{"pair":"KLB -> FGFR4","headline":"betaKlotho-FGFR4 supported by database records, including a Reactome FGFR4:HS:KLB:FGF19 complex; no curated paper confirmation.","interaction_type":"database-asserted only","direction_and_effect":"Not reported in our evidence beyond the curated Stimulatory annotation [flag]. Reactome describes FGFR4 binding to HS:KLB:FGF19 [DB:Reactome].","molecular_requirements":"Reactome lists a complex of FGFR4, heparan sulfate (HS), KLB and FGF19 [DB:Reactome].","affinity_potency":[],"species_and_systems":"BioGRID affinity capture-western [DB:BioGRID]; UniProt states FGFR4 interacts with KLB [DB:UniProt]. Species and system not reported in our evidence.","localisation_and_range":"Not reported in our evidence.","caveats":"Two papers are pending and none confirmed; support is from databases only, and no experimental detail is available here.","key_references":[],"covers":["LR012427"]},"LR002842":{"pair":"KLRG1 -> CDH2","headline":"KLRG1 binds N-cadherin per one abstract-level statement; direct binding, no detail on N-cadherin.","interaction_type":"direct binding","direction_and_effect":"KLRG1 is an inhibitory receptor and binds N-cadherin; inhibition of killing was shown for E-cadherin, not N-cadherin [PMID:16461340].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Identified by expression cloning with a mouse KLRG1 tetramer; the paper's mouse-specific finding is for E-cadherin, so N-cadherin binding is not resolved to mouse [PMID:16461340]. Human pair is ortholog-inferred [flag].","localisation_and_range":"Both membrane proteins [flag].","caveats":"One paper; the N-cadherin statement is a single sentence and the functional effect is shown only for E-cadherin. Two further papers were abstract_insufficient. No affinity reported.","key_references":[{"PMID":"16461340","why":"KLRG1 binds E-, N- and R-cadherins"}],"covers":["LR002842","LR006077"]},"LR004390":{"pair":"KNG1 -> RXFP4","headline":"A single report of bradykinin and kallidin activating GPR100 (RXFP4) in CHO cells; not replicated in our evidence and the active ligands are kinins.","interaction_type":"functional only","direction_and_effect":"Bradykinin and kallidin elicited a calcium response in CHO cells stably expressing GPR100, with EC50 in the low nanomolar range, whereas des-Arg analogues were inactive [PMID:14530218].","molecular_requirements":"Signalling was through Galphaq rather than Galphai/o, using Galpha16 and aequorin as readout; the ligands are kinin peptides, not intact KNG1 [PMID:14530218].","affinity_potency":[],"species_and_systems":"Human GPR100 expressed in CHO cells with aequorin and Galpha16 [PMID:14530218].","localisation_and_range":"KNG1 is secreted [flag]; peripheral hormone-like action suggested by the paper's expression data [PMID:14530218].","caveats":"One paper only, abstract read; no replication in our evidence. The curator note says the claim was not independently replicated and GPR100 is regarded as RXFP4 whose replicated ligand is relaxin-3, so treat as doubtful. The EC50 is not given as a number.","key_references":[{"PMID":"14530218","why":"GPR100 calcium response to bradykinin and kallidin"}],"covers":["LR000968","LR004390"]},"LR000970":{"pair":"L1CAM -> EGFR","headline":"Co-IP in transfected HEK293 cells and Drosophila S2 evidence for L1CAM-EGFR association and EGFR activation; not seen in brain.","interaction_type":"direct binding","direction_and_effect":"Reciprocal co-IP in HEK293 cells (human L1CAM and human EGFR) showed physical interaction [PMID:22815787]. L1CAM-mediated adhesion between Drosophila S2 cells activated human EGF kinase at contact sites, and EGFR physically interacted with L1-CAM [PMID:14718570]. L1CAM binding to erbB enhances the response to neuregulins [PMID:22815787]; effect labelled agonist.","molecular_requirements":"Different Ig-like domains of L1CAM can support erbB binding [PMID:22815787]. Reactome describes an L1-EGFR trans-heterodimer [DB:Reactome R-HSA-445016]; the PLoS One paper reports a cis interaction for erbB3.","affinity_potency":[],"species_and_systems":"Human proteins in HEK293 and Drosophila S2 cells [PMID:22815787][PMID:14718570]; Drosophila genetics also used [PMID:14718570]. Mouse pair is ortholog-inferred.","localisation_and_range":"Membrane proteins acting at cell contact sites (homophilic L1 adhesion triggers activation) [PMID:14718570]; L1CAM also flagged secreted [flag].","caveats":"The 2012 study could not detect L1CAM-EGFR co-IP from brain extracts ('not shown'), while erbB2 and erbB3 were detected [PMID:22815787]. 2004 paper read as abstract only; the 2012 paper's text is partly excerpted. Non-quantitative assay; no affinity.","key_references":[{"PMID":"22815787","why":"Co-IP of L1CAM with erbB receptors, human proteins"},{"PMID":"14718570","why":"L1 adhesion activates EGFR kinase in S2 cells"}],"covers":["LR000970","LR004392"]},"LR009115":{"pair":"L1CAM -> EPHB2","headline":"Co-IP in HEK293 cells links EphB2 and L1, direct or indirect; EphB2 phosphorylates L1.","interaction_type":"direct binding","direction_and_effect":"Each EphB, including EphB2, coimmunoprecipitated with L1, 'indicating a direct or indirect molecular association' [PMID:22579729]. EphB2 kinase activity, not a kinase-dead mutant, induced L1 phosphorylation at FIGQY(1229) via Src family kinases [PMID:22579729].","molecular_requirements":"EphB2 kinase activity and Src family kinases are needed for L1 phosphorylation [PMID:22579729]; requirement for binding itself not reported. Reactome lists p-Y-L1:EPHB2 complex [DB:Reactome R-HSA-443816].","affinity_potency":[],"species_and_systems":"Transfected HEK293 cells with chick and mouse EphB2; mouse retinocollicular mapping context [PMID:22579729]. Experiments used chick and mouse proteins, not human.","localisation_and_range":"Membrane receptor-receptor interaction in retinal ganglion cell axons; EPHB2 not flagged secreted [flag].","caveats":"Co-IP cannot separate direct from indirect association; the assay_class direct_binding label is stronger than the paper's own wording.","key_references":[{"PMID":"22579729","why":"EphB-L1 co-IP and L1 phosphorylation by EphB2"}],"covers":["LR009115"]},"LR006082":{"pair":"L1CAM -> ITGB1","headline":"VLA-5 (alpha5beta1) binds murine L1 and L1-Ig6 supports beta1 integrin adhesion; ITGB1 is the shared beta chain.","interaction_type":"direct binding","direction_and_effect":"VLA-5 bound murine L1 in cell aggregation, platelet and bead binding assays, blocked by anti-L1 and anti-VLA-5 mAbs and an L1 RGD peptide [PMID:8557754]. L1-Ig6 is a heterophilic ligand for alpha5beta1 and alphavbeta1 [PMID:9396761].","molecular_requirements":"Beta1 integrins bind in Mn2+ only, inhibited by Ca2+; RGD-dependent [PMID:9396761]. ITGB1 pairs with alpha5 or alphav; chain-level evidence.","affinity_potency":[],"species_and_systems":"Mouse cells, platelets and thymocytes plus human Nalm-6 [PMID:8557754]; human L1-Ig6 [PMID:9396761].","localisation_and_range":"Cell-contact adhesion [PMID:8557754].","caveats":"Both papers abstract only; no affinity; beta1 binding weaker than beta3 per hierarchy.","key_references":[{"PMID":"8557754","why":"VLA-5 binds murine L1"},{"PMID":"9396761","why":"L1-Ig6 beta1 integrin binding"}],"covers":["LR002847","LR006082"]},"LR002851":{"pair":"LAIR1 -> LILRB4","headline":"Only very weak LAIR1-LILRB4 binding seen (Kd > 200 uM), of doubtful significance; curators judged the abstract as pair absent.","interaction_type":"conflicting","direction_and_effect":"Weak binding between LAIR-1 and Lilrb4 was detected by SPR in human and mouse, but the authors say its significance is difficult to evaluate because Lilrb4 tended to bind itself [PMID:19283782]. Effect not reported.","molecular_requirements":"Not reported in our evidence.","affinity_potency":[{"value":"Kd > 200 uM","assay":"SPR, monomeric hLAIR-1 over immobilised hLilrb4","system":"recombinant human proteins","cite":"PMID:19283782"}],"species_and_systems":"Recombinant human and mouse proteins in a bead/SPR assay [PMID:19283782].","localisation_and_range":"Both are flagged transmembrane [flag].","caveats":"The curator verdict was pair_absent from the abstract, which describes both receptors binding collagen, yet the full text reports weak LAIR-1/Lilrb4 binding at the limit of the assay. An IntAct solid-phase record also exists [DB:IntAct Q8NHJ6-Q6GTX8].","key_references":[{"PMID":"19283782","why":"Weak binding detected, Kd > 200 uM"}],"covers":["LR002851"]},"LR006091":{"pair":"LAMA3 -> ITGB4","headline":"Laminin-332 (with LAMA3) binds recombinant integrin alpha6beta4 directly; one full-text study, assembled trimer.","interaction_type":"direct binding","direction_and_effect":"Laminin-332 bound recombinant alpha6beta4 in solid-phase saturation binding [PMID:16413178]. Interaction record lists a Stimulatory effect [flag].","molecular_requirements":"Receptor tested is the alpha6beta4 heterodimer; ITGB4 alone is not shown to suffice. Ligand is the laminin-332 trimer, not LAMA3 alone [PMID:16413178].","affinity_potency":[{"value":"Kd 12 nM","assay":"solid-phase saturation binding, laminin-332 vs recombinant alpha6beta4","system":"human recombinant","cite":"PMID:16413178"}],"species_and_systems":"Human recombinant integrin and purified laminin [PMID:16413178].","localisation_and_range":"LAMA3 is flagged secreted and not transmembrane [flag]; laminin acts as a basement-membrane matrix ligand (not stated in the paper text we hold).","caveats":"Single paper; no cellular or in vivo data. Three other papers were abstract-insufficient.","key_references":[{"PMID":"16413178","why":"Kd of alpha6beta4 for laminin-332"}],"covers":["LR002857","LR006091"]},"LR004408":{"pair":"LAMA3 -> SDC2","headline":"Binding of the laminin alpha3 LG4 module to syndecan-2 shown by affinity chromatography and solid-phase assay; abstract-level read.","interaction_type":"direct binding","direction_and_effect":"Syndecan-2 from fibroblasts bound the LG4 module of laminin alpha3 by affinity chromatography, and solid-phase assays showed syndecan-2 interacting with the A3G75aR peptide (NSFMALYLSKGR) within LG4 [PMID:11373281]. Cell adhesion to LG4 depended on cell-surface heparan sulfate proteoglycans [PMID:11373281].","molecular_requirements":"The binding site is a LG4 peptide, so a LG4 fragment, not full chain, was tested; coreceptor needs not reported in our evidence.","affinity_potency":[],"species_and_systems":"Syndecan-2 from fibroblasts and recombinant fragments or peptides; species not stated in our evidence [PMID:11373281].","localisation_and_range":"LAMA3 flagged secreted; SDC2 flagged transmembrane [flag].","caveats":"Read from abstract only. BioGRID lists Affinity Capture-Western and Reconstituted Complex records from the same paper [DB:BioGRID], so these are not independent.","key_references":[{"PMID":"11373281","why":"LG4/A3G75aR binds syndecan-2"}],"covers":["LR000989","LR004408"]},"LR002860":{"pair":"LAMA4 -> ITGB3","headline":"Recombinant laminin alpha4 G domain binds integrin alphavbeta3 with high affinity; one abstract-level paper.","interaction_type":"direct binding","direction_and_effect":"alphavbeta3 integrin bound with high affinity to G(919-1207) of laminin alpha4, and function-blocking antibodies to alphavbeta3 reduced endothelial attachment [PMID:12454288].","molecular_requirements":"Receptor tested is the alphavbeta3 heterodimer, so ITGB3 alone is not shown to suffice; ligand is a G-domain fragment [PMID:12454288].","affinity_potency":[{"value":"half-maximal at 1.4 nM","assay":"endothelial cell adhesion to G(919-1207) (adhesion, not Kd)","system":"endothelial cells","cite":"PMID:12454288"}],"species_and_systems":"Endothelial cells and recombinant protein [PMID:12454288].","localisation_and_range":"LAMA4 flagged secreted; ITGB3 not secreted [flag].","caveats":"Abstract only; no binding Kd quoted.","key_references":[{"PMID":"12454288","why":"alphavbeta3 binds alpha4 G domain"}],"covers":["LR002860","LR006094"]},"LR011392":{"pair":"LAMA5 -> ITGA7:ITGB1","headline":"Complex row for laminin alpha5 and integrin alpha7beta1; only a PDB record.","interaction_type":"database-asserted only","direction_and_effect":"Direction and effect not reported in our evidence. A PDB entry has a chain of O15230 and a chain of P05556 [DB:PDB 7CEC].","molecular_requirements":"Receptor is the ITGA7:ITGB1 heterodimer per the entity record.","affinity_potency":[],"species_and_systems":"Species and system not reported in our evidence.","localisation_and_range":"LAMA5 is flagged secreted [flag]; the receptor complex is flagged transmembrane, not as a receptor [flag]. Range otherwise not reported in our evidence.","caveats":"No papers judged (one abstract_insufficient). The PDB chains listed are LAMA5 and ITGB1, not ITGA7 [DB:PDB 7CEC].","key_references":[],"covers":["LR011392"]},"LR004417":{"pair":"LAMA5 -> ITGB4","headline":"Laminin alpha5 (as laminin-511/521) binds integrin alpha6beta4 with Kd 25 nM; a single binding paper.","interaction_type":"direct binding","direction_and_effect":"Laminin-511/521 bound recombinant integrin alpha6beta4 [PMID:16413178]. Annotated stimulatory.","molecular_requirements":"The binder is the alpha6beta4 heterodimer; ITGB4 alone and single laminin chains were not tested [PMID:16413178].","affinity_potency":[{"value":"Kd 25 nM","assay":"solid-phase saturation binding, recombinant integrin ectodomain to purified laminin isoforms (laminin-511/521 vs alpha6beta4)","system":"human recombinant proteins","cite":"PMID:16413178"}],"species_and_systems":"Human recombinant proteins [PMID:16413178]; mouse pair ortholog-inferred.","localisation_and_range":"LAMA5 is flagged secreted [flag] and ITGB4 is flagged as a receptor [flag]; beyond these annotation flags, range is not reported in our evidence.","caveats":"One paper only; this is the weakest Kd among the laminin-511/521 integrin pairings in that paper (compared with 0.73 nM and 3.4 nM) [PMID:16413178].","key_references":[{"PMID":"16413178","why":"Recombinant alpha6beta4 binding to laminin-511/521"}],"covers":["LR000998","LR004417"]},"LR011383":{"pair":"LAMB3 -> ITGA3:ITGB1","headline":"LAMB3 with ITGA3:ITGB1 has no verified paper; the only database record concerns alpha2beta1.","interaction_type":"database-asserted only","direction_and_effect":"The only record is Reactome integrin alpha2beta1 binding laminin-332 [DB:Reactome R-HSA-349626]; it does not name alpha3beta1.","molecular_requirements":"Subunit requirements for this complex are not reported in our evidence.","affinity_potency":[],"species_and_systems":"Species and experimental system are not reported in our evidence.","localisation_and_range":"Ligand is annotated as secreted [flag]; the receptor is annotated as a receptor [flag]. Matrix versus soluble range is not reported in our evidence.","caveats":"No paper in our evidence verifies this pair as listed; support rests on the database record alone. Four papers were abstract_insufficient. Related chain-level LAMB3-ITGA3 row has recombinant alpha3beta1 evidence, but it is not credited to this complex row.","key_references":[],"covers":["LR011383"]},"LR004426":{"pair":"LAMB3 -> ITGB4","headline":"LAMB3 (in laminin-332) binds integrin alpha6beta4 at Kd 12 nM; assembled-laminin evidence.","interaction_type":"direct binding","direction_and_effect":"Laminin-332, which contains LAMB3, bound recombinant alpha6beta4 in solid-phase assays [PMID:16413178]. Annotated effect is Stimulatory [flag]. Direction: laminin to integrin.","molecular_requirements":"Binder tested is the alpha6beta4 heterodimer, ligand the assembled heterotrimer; ITGB4 alone and LAMB3 alone were not tested [PMID:16413178].","affinity_potency":[{"value":"Kd 12 nM","assay":"solid-phase saturation binding, recombinant integrin ectodomain to purified laminin isoform; alpha6beta4 vs laminin-332","system":"recombinant human integrin, purified laminin","cite":"PMID:16413178"}],"species_and_systems":"Recombinant human proteins [PMID:16413178]; mouse pair is projected from human.","localisation_and_range":"Ligand is annotated as secreted [flag]; the receptor is annotated as a receptor [flag]. Matrix versus soluble range is not reported in our evidence.","caveats":"Kd values are for the whole laminin heterotrimer, not the single chain. One abstract_insufficient paper is not shown.","key_references":[{"PMID":"16413178","why":"Kd of alpha6beta4 for laminin-332"}],"covers":["LR001008","LR004426"]},"LR011374":{"pair":"LAMC2 -> ITGA2:ITGB1","headline":"Weak support: an abstract-level LAMC2-ITGB1 proximity signal and a Reactome binding record for alpha2beta1 and laminin-332.","interaction_type":"direct binding","direction_and_effect":"A Duolink proximity assay showed more LAMC2-ITGB1 interaction signals in alcohol-fed colorectal cancer rats and in patient samples [PMID:36188720]. Reactome lists integrin alpha2beta1 binding laminin-332 [DB:Reactome R-HSA-349626].","molecular_requirements":"The paper concerns ITGB1 only; ITGA2 involvement is not shown by it [PMID:36188720]. Reactome supports the alpha2beta1 heterodimer [DB:Reactome R-HSA-349626].","affinity_potency":[],"species_and_systems":"Rat colorectal cancer model and clinical colorectal cancer samples [PMID:36188720].","localisation_and_range":"Not reported in our evidence.","caveats":"Curated from the abstract; the paper measures proximity in tissue under alcohol exposure, not binding. Does not address the alpha2 chain. Interaction-class label of direct binding is generous.","key_references":[{"PMID":"36188720","why":"LAMC2-ITGB1 proximity signal in CRC tissue"}],"covers":["LR011374"]},"LR004435":{"pair":"LAMC2 -> ITGB4","headline":"Recombinant alpha6beta4 binds laminin-332 (contains LAMC2) with Kd 12 nM; ITGB4 is a chain-level proxy.","interaction_type":"direct binding","direction_and_effect":"Recombinant alpha6beta4 showed clear specificity for laminin-332 [PMID:16413178]. Recorded effect: stimulatory [flag].","molecular_requirements":"The assembled laminin-332 heterotrimer and the alpha6beta4 heterodimer were tested; individual chains were not [PMID:16413178].","affinity_potency":[{"value":"Kd 12 nM","assay":"solid-phase saturation binding of recombinant integrin to laminin-332","system":"human recombinant alpha6beta4","cite":"PMID:16413178"}],"species_and_systems":"Human recombinant proteins [PMID:16413178]. Mouse pair is ortholog-projected.","localisation_and_range":"LAMC2 flagged secreted [flag].","caveats":"Chain-level assignment inferred; one paper in the dossier.","key_references":[{"PMID":"16413178","why":"Recombinant alpha6beta4 binding to laminin-332"}],"covers":["LR001017","LR004435"]},"LR005218":{"pair":"LEAP2 -> GHSR","headline":"LEAP2 is an endogenous GHSR antagonist that fully inhibits ghrelin activation and blocks ghrelin effects in vivo.","interaction_type":"direct binding","direction_and_effect":"LEAP2 fully inhibits GHSR activation by ghrelin and blocks ghrelin effects on food intake, GH release and glucose maintenance in vivo; neutralizing antibodies against LEAP2 enhance ghrelin action [PMID:29233536]. GtoPdb lists it as an antagonist [DB:GtoPdb].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[{"value":"pIC50 8.22","assay":"inhibition of GHSR activation (as recorded by curators)","system":"human ligand and receptor","cite":"PMID:29233536"}],"species_and_systems":"Human ligand and receptor in vitro; in vivo effects in the paper, species not detailed in our evidence [PMID:29233536]. Mouse pair listed too.","localisation_and_range":"LEAP2 is a secreted hormone from liver and small intestine whose secretion is suppressed by fasting [PMID:29233536]; flagged secreted [flag].","caveats":"Abstract only; BioGRID lists a reconstituted complex [DB:BioGRID 3496523]. Whether LEAP2 binds the orthosteric site is not reported in our evidence.","key_references":[{"PMID":"29233536","why":"LEAP2 as an endogenous GHSR antagonist"}],"covers":["LR001876","LR005218"]},"LR006109":{"pair":"LECT2 -> TIE1","headline":"LECT2 is reported as a functional ligand of orphan receptor Tie1; evidence is one abstract-level paper.","interaction_type":"functional only","direction_and_effect":"LECT2 binding to Tie1 interrupts Tie1/Tie2 heterodimerization, facilitates Tie2/Tie2 homodimerization, activates PPAR signaling and inhibits endothelial migration and tube formation; curated as agonist [PMID:31474362].","molecular_requirements":"Acts through the Tie1/Tie2 receptor complex balance; Tie2 is involved [PMID:31474362].","affinity_potency":[],"species_and_systems":"In vivo mice with LECT2 overexpression and Lect2-knockout, endothelial cells in vitro, and human liver fibrosis samples [PMID:31474362]. Mouse pair is ortholog-projected.","localisation_and_range":"LECT2 is flagged secreted [flag].","caveats":"Abstract only; no affinity or direct binding data in the dossier; single paper.","key_references":[{"PMID":"31474362","why":"LECT2 as a functional Tie1 ligand in liver fibrosis"}],"covers":["LR002875","LR006109"]},"LR006118":{"pair":"LGALS3 -> ITGB3","headline":"Galectin-3 binds integrin alphavbeta3, enabling KRAS dependence in cancer cells; direct binding claimed in an abstract.","interaction_type":"direct binding","direction_and_effect":"Galectin-3 directly binds cell-surface integrin alphavbeta3 and enables KRAS functions, including macropinocytosis; a drug disrupting alphavbeta3/galectin-3 binding suppressed tumours [PMID:28893801].","molecular_requirements":"The receptor is the alphavbeta3 heterodimer, so ITGB3 pairs with ITGAV [PMID:28893801].","affinity_potency":[],"species_and_systems":"Cancer cells with patient-derived xenografts and spontaneous tumours in mice [PMID:28893801]. Species of reagents not reported in our evidence.","localisation_and_range":"Galectin-3 flagged secreted; ITGB3 flagged receptor, not secreted [flag].","caveats":"Read depth is abstract only; direct binding is asserted in the abstract and no assay details or affinity are given. No database records.","key_references":[{"PMID":"28893801","why":"Galectin-3 binds alphavbeta3, driving KRAS addiction"}],"covers":["LR002884","LR006118"]},"LR006127":{"pair":"LGALS8 -> ALCAM","headline":"ALCAM (CD166) was identified as a Gal-8 binding partner in vascular endothelial cells; abstract-level evidence, with proangiogenic effects of Gal-8.","interaction_type":"direct binding","direction_and_effect":"CD166/ALCAM was identified as a specific Gal-8-binding partner in normal vascular ECs; Gal-8 promoted capillary-tube formation and EC migration and induced angiogenesis in vivo in mice (agonist-like) [PMID:20876211].","molecular_requirements":"Gal-8 is a bivalent tandem-repeat galectin with two CRDs; whether ALCAM alone mediates the angiogenic effect is not reported in our evidence [PMID:20876211].","affinity_potency":[],"species_and_systems":"Human endothelial cells for binding; Matrigel plug angiogenesis in mice. Mouse pair is ortholog-inferred [PMID:20876211].","localisation_and_range":"Both partners carry secreted flags [flag]; ALCAM also a transmembrane flag [flag].","caveats":"Abstract only; the binding assay is not described and no affinity is given. The angiogenic readouts are not shown to depend on ALCAM.","key_references":[{"PMID":"20876211","why":"ALCAM identified as Gal-8 binding partner in vascular endothelial cells"}],"covers":["LR002897","LR006127"]},"LR002905":{"pair":"LGALS9 -> CD40","headline":"Galectin-9 interacts with CD40 on mouse CD4 T cells, blocking CD40-induced proliferation at higher doses; one paper.","interaction_type":"direct binding","direction_and_effect":"Galectin-9 prevented CD40-induced proliferation of CD4loCD40+ T cells in a dose-dependent manner and induced necrotic cell death through a Tim-3-independent mechanism (antagonist) [PMID:22685601].","molecular_requirements":"CD40 occurs as differentially glycosylated forms; not further resolved here [PMID:22685601].","affinity_potency":[],"species_and_systems":"Autoimmune-prone NOD mouse and BALB/c mouse CD4 T cells; the dossier pair is human, ortholog-inferred [PMID:22685601].","localisation_and_range":"CD40 is a transmembrane receptor [flag]; galectin-9 secreted [flag].","caveats":"Abstract and excerpts show functional effects; the binding claim is a single abstract statement. At 2.5 ug/ml galectin-9 did not prevent CD40-induced survival, so action is concentration-dependent [PMID:22685601]. At lower concentrations it altered CD3, CD4 and TCR surface expression instead. No affinity reported.","key_references":[{"PMID":"22685601","why":"Galectin-9 interacts with CD40 and limits CD40-driven T cell proliferation"}],"covers":["LR002905"]},"LR006136":{"pair":"LGALS9 -> TLR4","headline":"Galectin-9 binds TLR4 on mouse B-1 cells in a bead pulldown; one full-text paper.","interaction_type":"direct binding","direction_and_effect":"Gal9 binds TLR4 and CD180 on B-1 cells, and less on B-2 cells, by recombinant Gal9-coated bead pulldown of mouse B cell lysates and flow cytometry [PMID:34369876]. The paper concludes Gal9 directly regulates distinct TLRs, dampening signal transduction by altering nano-scale co-distribution [PMID:34369876].","molecular_requirements":"Gal9 also binds CD180, IgM-BCR and CD5; whether TLR4 requires other chains is not reported in our evidence [PMID:34369876].","affinity_potency":[],"species_and_systems":"Mouse primary B-1 and B-2 cells; the human pair is ortholog-inferred [PMID:34369876].","localisation_and_range":"Galectin-9 flagged secreted [flag]; acts at the B-cell surface [PMID:34369876].","caveats":"Single paper; a pulldown does not show a direct purified-protein interaction or the glycan dependence. Two other rows were abstract_insufficient.","key_references":[{"PMID":"34369876","why":"Gal9 pulldown binds TLR4 and CD180 on B-1 cells"}],"covers":["LR002909","LR006136"]},"LR005227":{"pair":"LGI1 -> ADAM23","headline":"LGI1 binds ADAM23 with significant ability in one study, secondary to ADAM22; Reactome and IntAct support.","interaction_type":"direct binding","direction_and_effect":"ADAM23 had a significant binding ability to LGI1 or LGI4, indicating ADAM22 is not the sole receptor [PMID:18974846]. Reactome lists LGI1 binds ADAM22 and ADAM23 [DB:Reactome]; IntAct lists an anti-tag coimmunoprecipitation [DB:IntAct]. Effect direction not reported.","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Mouse proteins per excerpts (curator labels human) [PMID:18974846].","localisation_and_range":"LGI1 secreted; ADAM23 flagged secreted and receptor [flag].","caveats":"Abstract does not say which of LGI1 or LGI4 bound ADAM23; no affinity; abstract only [PMID:18974846].","key_references":[{"PMID":"18974846","why":"LGI-ADAM binding specificity incl. ADAM23"}],"covers":["LR001885","LR005227"]},"LR004444":{"pair":"LIPC -> LRP1","headline":"Hepatic lipase binds purified LRP with Kd 52 nM and is internalised by LRP; one abstract-read paper.","interaction_type":"direct binding","direction_and_effect":"Hepatic lipase binds purified LRP, and this binding is inhibited by RAP and heparin; 125I-HL internalisation and degradation by HepG2 cells is largely blocked by RAP or anti-LRP IgG [PMID:7721852]. The dossier lists agonist, but the result concerns endocytic clearance.","molecular_requirements":"Cell-surface proteoglycans are required for efficient internalisation (curator note and title) [PMID:7721852].","affinity_potency":[{"value":"Kd 52 nM","assay":"in vitro binding to purified LRP","system":"purified LRP","cite":"PMID:7721852"}],"species_and_systems":"Human proteins; HepG2 cells and LRP-deficient mouse fibroblasts [PMID:7721852]. Human and mouse pairs are ortholog-inferred. BioGRID lists a reconstituted complex [DB:BioGRID].","localisation_and_range":"LIPC is flagged secreted [flag]; endocytic receptor action at the cell surface, requiring proteoglycans.","caveats":"One paper, abstract only (1995). Two further papers were review-only or abstract-insufficient.","key_references":[{"PMID":"7721852","why":"HL binds purified LRP, Kd 52 nM, and is internalised via LRP"}],"covers":["LR001027","LR004444"]},"LR002914":{"pair":"LRFN4 -> PTPRD","headline":"LRFN4 (SALM3) binds LAR-family RPTPs including PTPRD in a splice-dependent trans-synaptic interaction; one paper, plus Reactome.","interaction_type":"direct binding","direction_and_effect":"SALM3 interacts with and requires all three LAR-RPTPs (LAR, PTP-sigma, PTP-delta) for presynaptic differentiation [PMID:26321637]. The interaction needs the mini-exon B insert in the LAR-RPTP [PMID:26321637]. Reactome lists SALM3 binding LAR-RPTP [DB:Reactome].","molecular_requirements":"LAR-RPTPs containing meB alone bound SALM3, those with only meA or neither did not; adding meA to meB increased binding. Ig1-3 domains of PTP-delta were sufficient [PMID:26321637].","affinity_potency":[],"species_and_systems":"Paper reports mouse SALM3 and mouse PTP-delta in its assays; dossier species fields say human and the mouse pair is ortholog-inferred [PMID:26321637]. Cell-binding and co-culture assays, plus Salm3 knockout mice [PMID:26321637].","localisation_and_range":"Both flagged transmembrane for the pair, so contact-dependent trans-synaptic adhesion [flag][PMID:26321637].","caveats":"Evidence is family-level for all LAR-RPTPs; pair-specific data for PTPRD are not separated in our evidence. Evidence names PTP-delta explicitly in the notes and excerpts. Affinity not reported in our evidence.","key_references":[{"PMID":"26321637","why":"SALM3 binds LAR-RPTPs in a meB-dependent manner"}],"covers":["LR002914","LR006139"]},"LR006145":{"pair":"LRIG1 -> EGFR","headline":"LRIG1 binds EGFR and a soluble LRIG1 ectodomain inhibits EGFR activity; the primary paper is abstract-only, with multiple interaction-database records.","interaction_type":"direct binding","direction_and_effect":"A soluble LRIG1 ectodomain of the LRRs inhibited ligand-independent EGFR activation and growth of A431, HeLa and MDA-468 cells; EGFR-negative cells were unresponsive until EGFR was reintroduced [PMID:16847455]. Excess EGF displaced up to 75% of LRIG1 binding on A431 cells, suggesting an overlapping binding region [PMID:16847455]. Effect is antagonist/inhibitory.","molecular_requirements":"UniProt says LRIG1 interacts via extracellular LRR and Ig-like domains with EGFR, ERBB2, ERBB3 and ERBB4 [DB:UniProt]. The soluble ectodomain with only the LRRs was active [PMID:16847455].","affinity_potency":[{"value":"Kd 10 nM","assay":"LRIG1 binding sites on A431 cells","system":"human A431 cells","cite":"PMID:16847455"}],"species_and_systems":"Human carcinoma cell lines [PMID:16847455]; mouse pair is ortholog-inferred.","localisation_and_range":"LRIG1 not flagged secreted or transmembrane in our entity flags [flag]; the active form tested was a soluble ectodomain [PMID:16847455].","caveats":"UniProt also notes LRIG1 may have low affinity for EGFR and interaction may occur only when both are at high levels [DB:UniProt]. Primary paper abstract only. BioGRID and IntAct list co-IP and affinity capture records [DB:BioGRID][DB:IntAct].","key_references":[{"PMID":"16847455","why":"Soluble LRIG1 ectodomain binds A431 cells (Kd 10 nM) and inhibits EGFR"}],"covers":["LR002920","LR006145"]},"LR002923":{"pair":"LRIG2 -> PDGFRB","headline":"LRIG2 co-immunoprecipitates with PDGFR-beta and enhances its signalling in glioblastoma cells; a single paper plus one IntAct record.","interaction_type":"direct binding","direction_and_effect":"LRIG2 physically interacts with PDGFR-beta, promoting its total expression and activation and enhancing Akt and STAT3 signalling and cell-cycle effectors [PMID:30015847]. Curators label the effect agonist [PMID:30015847].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human glioblastoma cells, in vitro and in vivo, with PDGF-BB stimulation [PMID:30015847]. IntAct lists an anti-bait co-IP from the same paper [DB:IntAct]. The mouse pair is ortholog-inferred.","localisation_and_range":"LRIG2 is annotated non-secreted [flag]; PDGFR-beta is annotated transmembrane [flag]. Range is not discussed in our excerpts.","caveats":"The paper itself notes that Lrig2 had no effect on PDGFR levels or phosphorylation in mouse embryonic fibroblasts, so the effect may be tumour-cell specific [PMID:30015847]. Evidence is co-IP in cells, not purified-protein binding, and the sole IntAct record cites the same paper.","key_references":[{"PMID":"30015847","why":"LRIG2-PDGFR-beta interaction and enhanced signalling in GBM cells"}],"covers":["LR002923","LR006148"]},"LR006154":{"pair":"LRRTM1 -> NRXN3","headline":"LRRTM1 is reported to share the S4-lacking neurexin binding code that covers neurexins 1, 2 and 3; support is one abstract-level paper.","interaction_type":"direct binding","direction_and_effect":"The neurexin binding code of LRRTM2, which binds neurexins 1, 2 and 3 alpha and beta variants lacking an insert at splice site 4, is conserved in LRRTM1 and functional in a coculture hemisynapse formation assay [PMID:20519524].","molecular_requirements":"Neurexin variants must lack the splice site 4 insert [PMID:20519524].","affinity_potency":[],"species_and_systems":"One paper, read as abstract only; species not specified. Both human and mouse pairs are projected from other evidence (ortholog inferred) [PMID:20519524]. No database records.","localisation_and_range":"Both partners are flagged transmembrane [flag]; localisation is not discussed in our evidence for this pair.","caveats":"The paper's text does not specifically name NRXN3 for LRRTM1; the pair is inferred from the general statement that the code is conserved, and the curator note itself says it covers NRXN1-3. Single paper, abstract read, no affinity reported.","key_references":[{"PMID":"20519524","why":"conserved neurexin binding code in LRRTM1"}],"covers":["LR002929","LR006154"]},"LR002932":{"pair":"LRRTM2 -> NRXN3","headline":"LRRTM2 is reported to bind neurexin-3 lacking the S4 insert; support is one abstract-level paper's general statement.","interaction_type":"direct binding","direction_and_effect":"LRRTM2 binds neurexins 1, 2 and 3 alpha and beta variants specifically lacking an insert at splice site 4 [PMID:20519524].","molecular_requirements":"Neurexin must lack the S4 insert [PMID:20519524].","affinity_potency":[],"species_and_systems":"One paper, abstract only; species not specified. Orthology-projected mouse pair. No database records.","localisation_and_range":"Both partners flagged transmembrane [flag].","caveats":"The paper's evidence sentence names neurexin-1beta; NRXN3 rests on a general statement. Single abstract-read paper, no affinity reported.","key_references":[{"PMID":"20519524","why":"LRRTM2 binds neurexins 1-3 lacking S4"}],"covers":["LR002932","LR006157"]},"LR006163":{"pair":"LRRTM4 -> GPC6","headline":"LRRTM4 binds glypicans in a heparan sulfate-dependent manner; GPC6 is not singled out, so support for GPC6 specifically is indirect.","interaction_type":"direct binding","direction_and_effect":"Glypican is identified as a receptor for LRRTM4, with binding in an HS-dependent manner [PMID:23911103]. Glypican 4 and LRRTM4 localize to pre- and postsynaptic membranes, and the paper concludes a trans-synaptic glypican-LRRTM4 interaction regulates excitatory synapse development [PMID:23911103].","molecular_requirements":"Binding depends on heparan sulfate. Glypican binds LRRTM4 but not LRRTM2 [PMID:23911103]. LRRTM4-Fc bound strongly to all glypican isoforms tested, and five glypicans (GPC1, GPC3-6) were detected in the LRRTM4-Fc pulldown [PMID:23911103].","affinity_potency":[],"species_and_systems":"Mass spectrometry used rat brain homogenate; binding assays used HA-tagged mouse glypican cDNAs in HEK293T cells [PMID:23911103]. Curated species labels say human, but these were not the experimental species.","localisation_and_range":"LRRTM4 is flagged membrane-bound and GPC6 secreted [flag]; the paper describes glypican as a GPI-anchored HSPG and the interaction as trans-synaptic [PMID:23911103].","caveats":"The abstract speaks of glypican as a class; follow-up experiments focused on GPC4, and GPC4 but not GPC6 is strongly expressed in developing cortex and hippocampus (Fig. S1B) [PMID:23911103]. Whether GPC6 was among the isoforms tested in cell-surface binding is not stated explicitly in our excerpts.","key_references":[{"PMID":"23911103","why":"Identifies glypican as an LRRTM4 receptor; five glypicans including GPC6 seen in the LRRTM4 pulldown"}],"covers":["LR002938","LR006163"]},"LR002941":{"pair":"LSR -> ACE2","headline":"LSR interacts with ACE2 in cis and trans and blocks Spike binding; one paper, functional and co-IP evidence.","interaction_type":"functional only","direction_and_effect":"LSR interacts with ACE2 in cis and in trans, preventing its binding to S protein and inhibiting viral entry and S protein-mediated cell-cell fusion; this makes it an antagonist of Spike-ACE2 binding rather than an activator [PMID:39443717]. Loss of LSR enhanced infection and exogenous LSR protected [PMID:39443717].","molecular_requirements":"Six LSR variants, CRD mutants and N- and C-terminal deletions were co-expressed with ACE2 in co-IP assays; which of them bind is not reported in our excerpts [PMID:39443717]. A small LSR-derived peptide blocked S-ACE2 binding in vitro [PMID:39443717].","affinity_potency":[],"species_and_systems":"Human cell lines (HEK293, Caco-2), intestinal organoids, ex vivo tissue and a humanized ACE2 mouse model [PMID:39443717]. BioGRID lists affinity capture-western [DB:BioGRID].","localisation_and_range":"Both flagged without a secretion flag [flag]; trans interaction was tested by co-culturing LSR and ACE2 cells, so cell-contact binding is supported [PMID:39443717].","caveats":"Direct binding between purified proteins is not reported; evidence is co-IP and pulldown in cells. Only one paper; the abstract was the curated read.","key_references":[{"PMID":"39443717","why":"LSR-ACE2 cis/trans interaction blocking Spike binding"}],"covers":["LR002941","LR006166"]},"LR004453":{"pair":"LTA -> TNFRSF1A","headline":"Well supported direct binding: crystal structure of the TNFR1:LT-beta (LTA) complex plus binding evidence and several databases.","interaction_type":"direct binding","direction_and_effect":"Curator labels agonist. The crystal structure shows three receptor molecules bound symmetrically to one TNF beta trimer, with the receptor in the groove between adjacent subunits, giving a model for receptor activation [PMID:8387891]. LT alpha2/beta1 surface complex is recognised by the p55-TNF receptor [PMID:7995952].","molecular_requirements":"The LT alpha trimer binds three TNFR1 molecules [PMID:8387891]. UniProt says LTA in its homotrimeric form binds TNFR1 [DB:UniProt]. Reactome lists LTA trimer binding TNFRSF1A,1B,14 [DB:Reactome]; structure [DB:PDB 1TNR].","affinity_potency":[],"species_and_systems":"Human proteins; structure used the extracellular domain of human 55 kd TNF receptor and human TNF beta at 2.85 A resolution [PMID:8387891]. Surface-complex work used PMA-activated II-23 human T cell hybridoma [PMID:7995952].","localisation_and_range":"LT alpha is flagged secreted and the receptor transmembrane [flag]. Surface LT alpha2/beta1 is a minor membrane form that p55 recognises [PMID:7995952].","caveats":"Both papers read as abstracts only. The surface-form paper concerns a heteromer and does not isolate LT alpha. No affinity in our evidence. BioGRID lists co-crystal and reconstituted complexes [DB:BioGRID].","key_references":[{"PMID":"8387891","why":"Crystal structure of TNFR1 with LT alpha (TNF beta)"},{"PMID":"7995952","why":"Minor LT-alpha2/beta1 surface form recognised by p55 receptor"}],"covers":["LR001040","LR004453"]},"LR004462":{"pair":"MADCAM1 -> ITGA4","headline":"MADCAM1 is a ligand of integrin alpha4beta7; evidence is for the heterodimer, and ITGA4 alone is a subunit-level entry.","interaction_type":"direct binding","direction_and_effect":"MADCAM1 binds integrin alpha4beta7 and mediates lymphocyte adhesion; stimulatory effect per the interaction annotation. The paper-level evidence shows alpha4beta7 is a receptor for MAdCAM-1 [PMID:7687523]. Chemokines tune this: CCL25 raised alpha4beta7-MAdCAM-1 adhesion frequency from 31% to 55%, while CXCL10 lowered it to 25% [PMID:29789438].","molecular_requirements":"Needs the alpha4/beta7 pair. Alpha4beta1 does not support efficient binding to MAdCAM-1 [PMID:7687523]; beta7 residues 46-386 account for MAdCAM-1 specificity [PMID:9233649]. Alpha4 Tyr(187) is key for adhesion to soluble MAdCAM-1-Ig [PMID:10702270]. ITGB7 must be co-expressed when scoring.","affinity_potency":[],"species_and_systems":"Human cells in most assays (RPMI 8866-CXCR3 lymphocyte line, K562 transfectants) [PMID:29789438][PMID:10702270]; one paper does not state species [PMID:7687523]. Mouse pair is ortholog-inferred.","localisation_and_range":"MADCAM1 is flagged transmembrane, not secreted [flag]; contact-dependent adhesion (juxtacrine).","caveats":"Four of the confirmed papers were read as abstracts only except PMID:29789438, which has full-text excerpts. Activity depends on integrin conformation: Mn2+ opens alpha4beta7 for both MAdCAM-1 and VCAM-1 [PMID:29789438]. Reactome, IntAct and PDB records describe the alpha4beta7 complex, not ITGA4 alone [DB:Reactome][DB:PDB 9P95].","key_references":[{"PMID":"7687523","why":"alpha4beta7 identified as receptor for MAdCAM-1; alpha4beta1 does not bind"},{"PMID":"29789438","why":"conformer-dependent ligand switching with single-cell force data"},{"PMID":"9233649","why":"beta7 region specifying MAdCAM-1 binding"}],"covers":["LR001049","LR004462"]},"LR006172":{"pair":"MBL2 -> LRP1","headline":"MBL binds CD91 (LRP1) directly in vitro in one paper; a second paper places CD91 downstream of calreticulin.","interaction_type":"direct binding","direction_and_effect":"MBL binds CD91 in a time- and concentration-dependent manner, inhibited by known CD91 ligands [PMID:21054788]. MBL with C1q stimulates apoptotic cell ingestion via calreticulin bound to CD91 [PMID:11560994].","molecular_requirements":"MASP-3 inhibits MBL-CD91 binding and MASP-binding-deficient MBL mutants cannot interact with CD91, so the site is at or near the MASP-binding site [PMID:21054788]. Calreticulin may be a co-partner [PMID:11560994].","affinity_potency":[],"species_and_systems":"Human proteins and human macrophages (HMDM) and Jurkat targets [PMID:11560994]; PMID:21054788 labelled human. Mouse pair is ortholog-inferred.","localisation_and_range":"MBL2 is flagged secreted [flag]; soluble pattern-recognition molecule acting on phagocyte surface CD91 (paracrine/local).","caveats":"Both papers read as abstracts (PMID:11560994 with full-text excerpts). In PMID:11560994 CD91 is a partner of calreticulin rather than a proven direct MBL binder. IntAct lists surface plasmon resonance for PMID:21054788 [DB:IntAct].","key_references":[{"PMID":"21054788","why":"MBL-CD91 binding and MASP-site dependence"},{"PMID":"11560994","why":"MBL/C1q uptake via calreticulin-CD91"}],"covers":["LR002947","LR006172"]},"LR004471":{"pair":"MDK -> ITGB1","headline":"Midkine binds integrin alpha4beta1 and alpha6beta1 in mouse embryo and cell assays; evidence is for heterodimers, from one abstract-only paper.","interaction_type":"direct binding","direction_and_effect":"Midkine binds these integrins; alpha4beta1 and alpha6beta1 are concluded to be functional midkine receptors. Anti-alpha4 antibody inhibited midkine-dependent migration of osteoblastic cells and anti-alpha6 inhibited neurite outgrowth of embryonic neurons; midkine raised paxillin tyrosine phosphorylation [PMID:15466886].","molecular_requirements":"Beta1 integrin bound a midkine-agarose column and was eluted mostly with EDTA; alpha4 and alpha6 were the binding alpha-subunits [PMID:15466886].","affinity_potency":[],"species_and_systems":"Mouse embryo (13-day) extracts and cell assays; curated as human/human, but the experiments used mouse material [PMID:15466886]. Mouse pair is ortholog-inferred.","localisation_and_range":"MDK is flagged secreted, not transmembrane [flag]; paracrine growth factor.","caveats":"Single paper, abstract only. The integrins may cooperate with other midkine receptors (PTPRZ, LRP, ALK) [PMID:15466886]. UniProt records the interaction [DB:UniProt]. ITGB1 is the shared chain; the alpha partner matters for scoring.","key_references":[{"PMID":"15466886","why":"midkine-integrin binding and function"}],"covers":["LR001058","LR004471"]},"LR004480":{"pair":"MFAP5 -> NOTCH1","headline":"Paper supports MAGP-2 (MFAP5) interacting with Notch1 EGF-like repeats and activating it; one abstract-only paper.","interaction_type":"direct binding","direction_and_effect":"MAGP-2 interacted with Notch1 EGF-like repeats; co-expression released the Notch1 ectodomain and activated Notch signalling, as an agonist [PMID:16492672].","molecular_requirements":"The C-terminal domain of MAGP-2 is required for binding and activation; release requires furin-like heterodimer formation but not ADAM cleavage [PMID:16492672].","affinity_potency":[],"species_and_systems":"Human proteins, cell co-expression assays [PMID:16492672]. Both species pairs are ortholog-inferred.","localisation_and_range":"MFAP5 is flagged secreted [flag]; described as a microfibril-associated protein [PMID:16492672].","caveats":"Abstract only; the abstract does not use the MFAP5 name, so mapping MAGP-2 to MFAP5 is a curator assumption. No affinity reported.","key_references":[{"PMID":"16492672","why":"MAGP-2 binds Notch1 EGF repeats and induces activation"}],"covers":["LR001067","LR004480"]},"LR002950":{"pair":"MFAP5 -> NOTCH2","headline":"Bladder cancer paper reports CAF-derived MFAP5 directly interacting with NOTCH2 and activating it; abstract only.","interaction_type":"direct binding","direction_and_effect":"CAF-derived MFAP5 activated NOTCH2/HEY1 signalling through direct interaction with NOTCH2, stimulating N2ICD release; NOTCH2 knockdown or inactivating antibody NRR2Mab reversed MFAP5 effects in vitro and in vivo [PMID:32293074].","molecular_requirements":"Not reported beyond NOTCH2; MFAP5-mediated PI3K-AKT signalling activated a DLL4/NOTCH2 axis [PMID:32293074].","affinity_potency":[],"species_and_systems":"Human bladder cancer cells and cancer-associated fibroblasts, with in vivo tests [PMID:32293074]. Mouse pair is ortholog-inferred.","localisation_and_range":"MFAP5 is secreted by CAFs, paracrine to tumour cells [PMID:32293074].","caveats":"The abstract states 'direct interaction' without naming the assay; abstract only, no affinity. Possible involvement of DLL4 confounds ligand attribution.","key_references":[{"PMID":"32293074","why":"CAF-derived MFAP5 activates NOTCH2 via direct interaction"}],"covers":["LR002950","LR006175"]},"LR006181":{"pair":"MIA -> ITGB1","headline":"MIA binds integrin beta1 (as alpha4beta1 and alpha5beta1) in melanoma cells by far-Western and co-IP and reduces integrin activity; abstract only.","interaction_type":"direct binding","direction_and_effect":"MIA interacts with integrin alpha4beta1 and alpha5beta1, down-regulating integrin activity and MAPK signalling, an antagonist-type effect [PMID:16517605].","molecular_requirements":"The paper identifies alpha4beta1 and alpha5beta1 heterodimers, so both subunits belong to the complex [PMID:16517605]. MIA also binds fibronectin [PMID:16517605]. beta1 is the shared chain of both integrins.","affinity_potency":[],"species_and_systems":"Human malignant melanoma cells [PMID:16517605]. Mouse pair is ortholog-inferred.","localisation_and_range":"MIA is flagged secreted [flag].","caveats":"Abstract only; no affinity. Evidence is for the integrin heterodimers, not a single chain; the abstract does not say which assay showed which integrin.","key_references":[{"PMID":"16517605","why":"MIA binds alpha4beta1/alpha5beta1 integrins and reduces MAPK signalling"}],"covers":["LR002956","LR006181"]},"LR005245":{"pair":"MIF -> CXCR2","headline":"MIF directly binds CXCR2 and activates it as a noncognate chemokine-like agonist; one paper plus an IntAct pull-down.","interaction_type":"direct binding","direction_and_effect":"MIF triggers Galphai- and integrin-dependent arrest and chemotaxis, integrin activation and calcium influx through CXCR2; it competes with cognate ligands and directly bound CXCR2. Il8rb (Cxcr2) deficiency abolished MIF-induced leukocyte recruitment [PMID:17435771].","molecular_requirements":"CXCR2 and CD74 formed a receptor complex, and monocyte arrest by MIF in inflamed or atherosclerotic arteries involved both CXCR2 and CD74 [PMID:17435771].","affinity_potency":[],"species_and_systems":"Human ligand and receptor labelled; in vivo work in mice (Mif deficiency, Il8rb deficiency, atherosclerosis-prone mice). Mouse pair is ortholog-inferred [PMID:17435771].","localisation_and_range":"MIF carries a secreted flag [flag]; acts as a soluble ligand [PMID:17435771].","caveats":"Abstract-only reading; no affinity reported. An IntAct pull-down record exists [DB:IntAct].","key_references":[{"PMID":"17435771","why":"MIF is a noncognate ligand of CXCR2 and CXCR4"}],"covers":["LR001905","LR005245"]},"LR001906":{"pair":"MIF -> CXCR4","headline":"MIF activates CXCR4 functionally and competes with cognate ligands, but direct binding is shown only for CXCR2.","interaction_type":"functional only","direction_and_effect":"MIF triggers arrest, chemotaxis, integrin activation and calcium influx through CXCR4 (agonist) and competed with cognate ligands for CXCR4 binding [PMID:17435771].","molecular_requirements":"Not reported in our evidence for CXCR4 specifically; CXCR2 and CD74 form a complex in the same paper [PMID:17435771].","affinity_potency":[],"species_and_systems":"Human monocytes and T cells; mouse in vivo work. Mouse pair is ortholog-inferred [PMID:17435771].","localisation_and_range":"MIF carries a secreted flag [flag]; soluble ligand [PMID:17435771].","caveats":"The abstract states MIF directly bound CXCR2, not CXCR4; here support is competition and signalling. Abstract only, one paper, no affinity [PMID:17435771].","key_references":[{"PMID":"17435771","why":"MIF competes at and signals through CXCR4"}],"covers":["LR001906","LR005246"]},"LR001078":{"pair":"MMP9 -> LRP1","headline":"MMP-9 (as the MMP-9/TIMP-1 complex) binds LRP, which internalises and degrades it; one abstract-level paper.","interaction_type":"direct binding","direction_and_effect":"In vitro, the MMP-9.TIMP-1 complex bound LRP with high affinity and the binding determinant appears to reside on MMP-9 [PMID:11279011]. LRP-expressing cells internalised 125I-MMP-9.TIMP-1, while LRP-deficient lines did so poorly, so LRP is a clearance receptor [PMID:11279011].","molecular_requirements":"The species bound was the MMP-9.TIMP-1 complex [PMID:11279011]. Whether free MMP-9 binds is not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human MMP-9 with mouse embryonic fibroblasts (mouse LRP) [PMID:11279011]. The mouse pair is not ortholog-inferred in the dossier.","localisation_and_range":"MMP9 is flagged as secreted [flag]; LRP mediates uptake from the extracellular space [PMID:11279011].","caveats":"The affinity is called high but no value is given in the abstract. Abstract only. LRP1 is a scavenger, not a signalling receptor.","key_references":[{"PMID":"11279011","why":"MMP-9/TIMP-1 binding to LRP and LRP-mediated catabolism"}],"covers":["LR001078","LR004490"]},"LR006190":{"pair":"MMP9 -> TLR4","headline":"A Neu1-MMP9 complex is bound to TLR4 on macrophages and is needed for LPS-induced signalling; abstract only.","interaction_type":"functional only","direction_and_effect":"A Neu1-MMP9 complex is bound to TLR4 on the cell surface of naive macrophages; MMP9 inhibition, knockdown or knockout reduced LPS-induced Neu1 activity and NF\u03baB activation (agonist-type support) [PMID:21873432].","molecular_requirements":"MMP9 acts in a complex with Neu1 and G\u03b1(i) signalling; the alpha-2,3-sialyl residue of TLR is the Neu1 target [PMID:21873432].","affinity_potency":[],"species_and_systems":"Macrophage cells, including MMP9-knockout primary macrophages [PMID:21873432]. The human pair is ortholog-inferred; the mouse row is not.","localisation_and_range":"MMP9 is flagged as secreted [flag]; the paper places the complex on the macrophage cell surface [PMID:21873432].","caveats":"MMP9 is a TLR4-associated component rather than a ligand activating TLR4 itself; direct MMP9-TLR4 binding is not shown in the abstract. Abstract only; the curated experiment species is human while the abstract mentions knockout macrophages.","key_references":[{"PMID":"21873432","why":"Neu1-MMP9 complex bound to TLR4 and required for LPS signalling"}],"covers":["LR002965","LR006190"]},"LR010843":{"pair":"MSTN -> ACVR1B:ACVR2A","headline":"Weak support: one in vivo paper on ALK4 knockdown, no direct evidence for the ACVR2A chain.","interaction_type":"functional only","direction_and_effect":"Antisense knockdown of ALK4 in mdx and wild-type mice inhibited myostatin activity and decreased muscle mass [PMID:27733450].","molecular_requirements":"ALK4 (ACVR1B) is named as a key receptor for the myostatin/activin pathway; the type II chain ACVR2A is not named in the abstract [PMID:27733450].","affinity_potency":[],"species_and_systems":"Mouse (mdx and wild-type) and in vitro myoblasts [PMID:27733450].","localisation_and_range":"Myostatin is secreted [flag].","caveats":"Abstract only; the paper does not test this complex or binding. The curator note says the ACVR2A side is not covered.","key_references":[{"PMID":"27733450","why":"ALK4 as myostatin/activin type I receptor in mouse muscle"}],"covers":["LR010843"]},"LR006802":{"pair":"MT-RNR2 -> FPR3","headline":"Humanin is an agonist for FPR3 (FPRL2) in transfected cells; one abstract-only paper.","interaction_type":"functional only","direction_and_effect":"Humanin suppressed forskolin-induced cAMP in CHO-hFPRL2 cells and showed chemotactic activity [PMID:15465011]; GtoPdb lists a full agonist [DB:GtoPdb] and UniProt calls FPR3 a receptor for humanin [DB:UniProt].","molecular_requirements":"Single receptor transfectant is sufficient [PMID:15465011].","affinity_potency":[{"value":"pEC50 8.95","assay":"cAMP suppression","system":"CHO-hFPRL2","cite":"PMID:15465011"}],"species_and_systems":"Human proteins in CHO transfectants [PMID:15465011].","localisation_and_range":"Humanin is annotated secreted [flag].","caveats":"Abstract only. Direct binding was shown for FPRL1 in the abstract, not FPRL2.","key_references":[{"PMID":"15465011","why":"Humanin as FPRL1/FPRL2 ligand"}],"covers":["LR006802"]},"LR008422":{"pair":"MTNR1A -> GNAI2","headline":"Database-only receptor-G protein association; not a ligand-receptor pair.","interaction_type":"database-asserted only","direction_and_effect":"Direction and effect not reported in our evidence.","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"BioGRID Affinity Capture-Western and Affinity Capture-MS, IntAct tandem affinity purification records [DB:BioGRID 280095][DB:IntAct].","localisation_and_range":"Not reported in our evidence.","caveats":"No verified papers (different_entity, review_only). Support is co-purification records only.","key_references":[],"covers":["LR008422"]},"LR001087":{"pair":"NCAM1 -> FGFR1","headline":"Direct NCAM-FGFR1 binding shown by SPR and immunoprecipitation across several papers.","interaction_type":"direct binding","direction_and_effect":"CD56/NCAM on NK-92 cells ligated FGFR1 beta on Jurkat T cells and costimulated TCR/CD3-triggered IL-2 production, inhibited 50-75% by CD56 mAbs [PMID:12121226]. Curator labels effect as agonist/stimulatory.","molecular_requirements":"NCAM F3 modules 1 and 2 bound FGFR1 Ig modules 2 and 3 by SPR; individual F3 modules did not bind detectably, so both are needed [PMID:12791257]. A later paper reports the second FGFR Ig module is also involved [PMID:18593816].","affinity_potency":[{"value":"10 uM Kd","assay":"surface plasmon resonance","system":"purified recombinant NCAM F3 modules 1+2 with FGFR modules","cite":"PMID:12791257"}],"species_and_systems":"Human proteins and cells in the SPR and Jurkat/NK-92 work; species unspecified for [PMID:18593816]. Mouse pair is ortholog-inferred.","localisation_and_range":"NCAM is flagged secreted/transmembrane [flag]; the Jurkat/NK-92 result is trans cell-cell contact [PMID:12121226].","caveats":"Two papers were abstract-only. The IL-2 conclusion is hedged by the authors. A 10 uM Kd is low affinity, which the authors argue suffices physiologically [PMID:12791257].","key_references":[{"PMID":"12791257","why":"SPR direct interaction of NCAM F3 modules with FGFR1, Kd 10 uM"},{"PMID":"12121226","why":"CD56 engages FGFR1 and costimulates IL-2 in Jurkat T cells"},{"PMID":"18593816","why":"SPR/NMR: FGFR Ig module 2 also binds NCAM"}],"covers":["LR001087","LR004498"]},"LR001915":{"pair":"NECTIN1 -> CADM3","headline":"Single abstract-only cell-aggregation paper shows nectin-1 heterophilic adhesion with Necl-1 (CADM3).","interaction_type":"functional only","direction_and_effect":"Necl-1 (CADM3) showed Ca2+-independent heterophilic cell-cell adhesion with nectin-1 and nectin-3, but not with Necl-5 or nectin-2 [PMID:15741237]. Reactome lists a Necl-1:Nectin-1 trans heterodimer [DB:Reactome].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Cell adhesion assays; the species is not stated in our evidence [PMID:15741237].","localisation_and_range":"Both are membrane adhesion molecules acting in trans at cell-cell contacts; Necl-1 localised at contact sites among axons, terminals and glia [PMID:15741237]. The ligand/receptor direction is arbitrary for this symmetric pair.","caveats":"Evidence is cell aggregation, not purified-protein binding; abstract only; no affinity.","key_references":[{"PMID":"15741237","why":"Necl-1 heterophilic adhesion with nectin-1"}],"covers":["LR001915","LR005254"]},"LR005254":{"pair":"NECTIN1 -> CADM3","headline":"Single abstract-only cell-aggregation paper shows nectin-1 heterophilic adhesion with Necl-1 (CADM3).","interaction_type":"functional only","direction_and_effect":"Necl-1 (CADM3) showed Ca2+-independent heterophilic cell-cell adhesion with nectin-1 and nectin-3, but not with Necl-5 or nectin-2 [PMID:15741237]. Reactome lists a Necl-1:Nectin-1 trans heterodimer [DB:Reactome].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Cell adhesion assays; the species is not stated in our evidence [PMID:15741237].","localisation_and_range":"Both are membrane adhesion molecules acting in trans at cell-cell contacts; Necl-1 localised at contact sites among axons, terminals and glia [PMID:15741237]. The ligand/receptor direction is arbitrary for this symmetric pair.","caveats":"Evidence is cell aggregation, not purified-protein binding; abstract only; no affinity.","key_references":[{"PMID":"15741237","why":"Necl-1 heterophilic adhesion with nectin-1"}],"covers":["LR001915","LR005254"]},"LR006208":{"pair":"NECTIN1 -> FGFR1","headline":"One abstract-only paper: the nectin-1 Ig3 module binds FGFR isoforms by SPR and induces FGFR1c phosphorylation.","interaction_type":"direct binding","direction_and_effect":"Recombinant nectin-1 Ig3 induced neurite outgrowth, abolished by SU5402 or dominant-negative FGFR1, and induced FGFR1c phosphorylation like the whole ectodomain [PMID:22955284]. Agonist of FGFR signalling.","molecular_requirements":"Only the third, membrane-proximal Ig module (Ig3) was tested; the full-length protein is not reported to bind in our evidence [PMID:22955284]. SPR showed direct interaction with various FGFR isoforms [PMID:22955284].","affinity_potency":[],"species_and_systems":"Mouse nectin-1 Ig3, primary hippocampal and cerebellar granule neurons [PMID:22955284]. The human row is ortholog-inferred. BioGRID lists a reconstituted complex [DB:BioGRID].","localisation_and_range":"Nectin-1 is a flagged secreted and transmembrane protein [flag]; the tested form was a soluble recombinant fragment.","caveats":"Single paper read as abstract; no SPR affinity in our evidence.","key_references":[{"PMID":"22955284","why":"SPR and functional data for nectin-1 Ig3 with FGFR"}],"covers":["LR002983","LR006208"]},"LR001924":{"pair":"NECTIN3 -> CADM3","headline":"Heterophilic adhesion between nectin-3 and Necl-1 (CADM3) shown in cell aggregation assays; one abstract-only paper.","interaction_type":"direct binding","direction_and_effect":"Necl-1 showed Ca2+-independent heterophilic cell-cell adhesion with Necl-2, nectin-1 and nectin-3, but not Necl-5 or nectin-2 [PMID:15741237]. Direction and activating or inhibitory effect are not reported in our evidence.","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Cell aggregation assays; species not stated in the abstract, curator recorded human [PMID:15741237]. Mouse pair is the non-projected one.","localisation_and_range":"Membrane-bound by flags [flag]; adhesion at the cell junction, juxtacrine [DB:Reactome].","caveats":"Abstract only. Adhesion assays do not give affinity. Necl-1 also binds homophilically [PMID:15741237]. Reactome has a Necl-1:Nectin-3 trans heterodimer [DB:Reactome].","key_references":[{"PMID":"15741237","why":"Necl-1 binds nectin-3 but not nectin-2 in aggregation assays"}],"covers":["LR001924","LR005263"]},"LR005263":{"pair":"NECTIN3 -> CADM3","headline":"Heterophilic adhesion between nectin-3 and Necl-1 (CADM3) shown in cell aggregation assays; one abstract-only paper.","interaction_type":"direct binding","direction_and_effect":"Necl-1 showed Ca2+-independent heterophilic cell-cell adhesion with Necl-2, nectin-1 and nectin-3, but not Necl-5 or nectin-2 [PMID:15741237]. Direction and activating or inhibitory effect are not reported in our evidence.","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Cell aggregation assays; species not stated in the abstract, curator recorded human [PMID:15741237]. Mouse pair is the non-projected one.","localisation_and_range":"Membrane-bound by flags [flag]; adhesion at the cell junction, juxtacrine [DB:Reactome].","caveats":"Abstract only. Adhesion assays do not give affinity. Necl-1 also binds homophilically [PMID:15741237]. Reactome has a Necl-1:Nectin-3 trans heterodimer [DB:Reactome].","key_references":[{"PMID":"15741237","why":"Necl-1 binds nectin-3 but not nectin-2 in aggregation assays"}],"covers":["LR001924","LR005263"]},"LR001096":{"pair":"NID1 -> ITGA3","headline":"Integrin alpha3beta1 isolated as the entactin receptor from human prostate carcinoma cells; the integrin chain named is alpha3.","interaction_type":"direct binding","direction_and_effect":"The entactin receptor from PC-3 cells was identified as integrin alpha 3 beta 1; an anti-alpha 3 antibody inhibited PC-3 attachment to entactin but not to laminin [PMID:1527019].","molecular_requirements":"The receptor is the alpha3beta1 heterodimer; purified alpha 3 beta 1 bound entactin-Sepharose in a divalent cation-dependent manner, and alpha 2 beta 1 liposomes did not bind [PMID:1527019]. Binding required cations and was not eluted by RGD peptides [PMID:1527019].","affinity_potency":[],"species_and_systems":"Human PC-3 cells with mouse recombinant entactin; abstract only [PMID:1527019]. Human and mouse pairs are both ortholog-inferred.","localisation_and_range":"Entactin is an extracellular matrix protein; NID1 is annotated secreted [flag].","caveats":"Abstract-only evidence. One judged paper was review only.","key_references":[{"PMID":"1527019","why":"Alpha3beta1 isolated as the entactin receptor from PC-3 cells"}],"covers":["LR001096","LR004507"]},"LR004507":{"pair":"NID1 -> ITGA3","headline":"Integrin alpha3beta1 isolated as the entactin receptor from human prostate carcinoma cells; the integrin chain named is alpha3.","interaction_type":"direct binding","direction_and_effect":"The entactin receptor from PC-3 cells was identified as integrin alpha 3 beta 1; an anti-alpha 3 antibody inhibited PC-3 attachment to entactin but not to laminin [PMID:1527019].","molecular_requirements":"The receptor is the alpha3beta1 heterodimer; purified alpha 3 beta 1 bound entactin-Sepharose in a divalent cation-dependent manner, and alpha 2 beta 1 liposomes did not bind [PMID:1527019]. Binding required cations and was not eluted by RGD peptides [PMID:1527019].","affinity_potency":[],"species_and_systems":"Human PC-3 cells with mouse recombinant entactin; abstract only [PMID:1527019]. Human and mouse pairs are both ortholog-inferred.","localisation_and_range":"Entactin is an extracellular matrix protein; NID1 is annotated secreted [flag].","caveats":"Abstract-only evidence. One judged paper was review only.","key_references":[{"PMID":"1527019","why":"Alpha3beta1 isolated as the entactin receptor from PC-3 cells"}],"covers":["LR001096","LR004507"]},"LR004516":{"pair":"NLGN2 -> NRXN1","headline":"Supported mainly by a general neurexin-binding paper and a mutation study; no NLGN2-specific affinity.","interaction_type":"direct binding","direction_and_effect":"All three neuroligins bind beta-neurexins in native and recombinant form [PMID:8576240]. Truncated NRXN1 and NRXN2 proteins failed to bind NLGN2 in cell binding assays and failed to promote synaptic differentiation [PMID:21424692].","molecular_requirements":"Tight binding needs beta-neurexins lacking a splice site 4 insert [PMID:8576240].","affinity_potency":[],"species_and_systems":"Human cell binding assays and neuron coculture (curator: human) [PMID:21424692]; species unspecified for 8576240. Mouse and human pairs are ortholog-projected.","localisation_and_range":"Neither partner is secreted; both carry transmembrane flags [flag], so this is a membrane-bound, contact-dependent (trans-synaptic) pair. BioGRID lists a reconstituted complex [DB:BioGRID].","caveats":"Both papers abstract-only. The mutation paper shows loss of binding by truncated NRXN1, with NLGN2 binding by the wild type described only as 'established' [PMID:21424692]. The 8576240 sentence refers to beta-neurexins as a class. Further papers were abstract-insufficient or pending.","key_references":[{"PMID":"8576240","why":"Neuroligin binding to beta-neurexins"},{"PMID":"21424692","why":"Truncated NRXN1 fails to bind NLGN2"}],"covers":["LR001105","LR004516"]},"LR006217":{"pair":"NLGN3 -> PTPRD","headline":"Experimentally shown non-canonical NLGN3-PTPdelta interaction (splice-dependent) that competes with neurexin binding; mouse-based single paper.","interaction_type":"direct binding","direction_and_effect":"NLGN3 binds PTPdelta splice variants lacking the meB peptide in cell surface binding, cell aggregation and coimmunoprecipitation from mouse brain; PTPdelta-meB(-) beads need NLGN3 to induce excitatory and inhibitory postsynaptic differentiation in neurons [PMID:33758193].","molecular_requirements":"Only PTPdelta variants lacking meB bind; meB(+) variants do not. LAR and PTPsigma variants lacking meB interact much more weakly. Among murine NLGN1-4, NLGN3 alone showed significant binding [PMID:33758193].","affinity_potency":[],"species_and_systems":"Mouse cortical/striatal neurons, mouse brain co-IP and HEK293T cells; curator lists human; the mouse pair is not ortholog-inferred [PMID:33758193].","localisation_and_range":"Both partners are transmembrane [flag]; HEK293T aggregation indicates trans, contact-mediated binding [PMID:33758193].","caveats":"PTPdelta and NRXN1beta compete for NLGN3 binding in a competitive binding assay [PMID:33758193]. ITC was performed but values are not in our evidence. Abstract plus excerpts only.","key_references":[{"PMID":"33758193","why":"NLGN3-PTPdelta binding, competition with NRXN1beta"}],"covers":["LR002993","LR006217"]},"LR004525":{"pair":"NMS -> NMUR2","headline":"Functionally supported agonist pair from one abstract-level rat paper, with a Reactome binding reaction and GtoPdb and UniProt records.","interaction_type":"functional only","direction_and_effect":"NMS is an agonist: it was purified from rat brain as an endogenous ligand of FM-4/TGR-1 (NMU receptors), and ICV NMS activates SCN neurons and shifts circadian phase in rats [PMID:15635449]. GtoPdb lists it as an agonist [DB:GtoPdb]; Reactome has 'NMUR2 binds neuromedin-S' [DB:Reactome R-HSA-981832].","molecular_requirements":"Not reported in our evidence beyond the receptor chain; a PDB structure with these chains exists [DB:PDB 7W57].","affinity_potency":[{"value":"pIC50 9.199999809265137","assay":"as recorded for the paper's curated affinity field","system":"rat","cite":"PMID:15635449"}],"species_and_systems":"Rat peptide and rat receptor [PMID:15635449]; human and mouse not directly tested in our evidence.","localisation_and_range":"NMS flagged secreted [flag]; the paper proposes autocrine and/or paracrine action [PMID:15635449].","caveats":"One paper, abstract only, naming the receptor only as FM-4/TGR-1 (NMU receptors); NMUR2-specific evidence otherwise rests on databases.","key_references":[{"PMID":"15635449","why":"Identification of NMS as endogenous NMU-receptor ligand"}],"covers":["LR001114","LR004525"]},"LR011752":{"pair":"NODAL -> ACVR1C:ACVR2B:CRIPTO","headline":"Nodal with ACVR1C, ACVR2B and CRIPTO as a complex; supported only by database records, no curated paper.","interaction_type":"database-asserted only","direction_and_effect":"UniProt states that cell-associated CRIPTO acts as a Nodal coreceptor in cis [DB:UniProt], and that ACVR2B is a receptor for NODAL [DB:UniProt]. Effect direction is not reported in our evidence beyond this.","molecular_requirements":"Complex of type I (ACVR1C), type II (ACVR2B) and CRIPTO co-receptor. BioGRID lists reconstituted complexes for TDGF1-NODAL and ACVR2B-NODAL [DB:BioGRID, PMID:28126904]; no record covers the full three-part complex or ACVR1C-NODAL.","affinity_potency":[],"species_and_systems":"Species of the experiments is not reported in our evidence; the pair is human.","localisation_and_range":"NODAL is flagged secreted [flag]; CRIPTO is flagged secreted and ACVR2B transmembrane [flag], so range is not settled by our evidence. UniProt describes CRIPTO as acting in cis [DB:UniProt].","caveats":"No papers were judged for this pair. Support is only BioGRID and UniProt records; the CRIPTO/TDGF1 naming may be an alias issue and was not checked.","key_references":[{"PMID":"28126904","why":"BioGRID reconstituted-complex records (database only, not read)"}],"covers":["LR011752"]},"LR008413":{"pair":"NOTCH1 -> JAG2","headline":"JAG2 binds NOTCH1 directly in a Ca2+-dependent manner in human proteins; one paper, abstract only, row reversed.","interaction_type":"direct binding","direction_and_effect":"Soluble Notch1 bound Jagged2 on the cell surface, and Jagged2 directly bound immobilised soluble Notch1; authors conclude Jagged2 is a Notch1 ligand [PMID:11006133].","molecular_requirements":"Ca2+-dependent [PMID:11006133].","affinity_potency":[],"species_and_systems":"Human receptor-ectodomain fusion proteins; abstract only [PMID:11006133].","localisation_and_range":"JAG2 flagged transmembrane and non-secreted [flag], so contact-dependent.","caveats":"Affinities were not quantified; single paper. Reactome and BioGRID records agree [DB:BioGRID, DB:Reactome R-HSA-157140].","key_references":[{"PMID":"11006133","why":"Direct physical binding of Jagged2 to Notch1"}],"covers":["LR008413"]},"LR008431":{"pair":"NOTCH3 -> JAG2","headline":"Jagged2 binds Notch3 directly and Ca2+-dependently; one abstract-only paper, row reversed.","interaction_type":"direct binding","direction_and_effect":"Jagged2 on the cell surface bound soluble Notch3 and directly bound immobilised soluble Notch3; authors conclude DSL proteins are ligands for Notch1 and Notch3 [PMID:11006133].","molecular_requirements":"Ca2+-dependent [PMID:11006133].","affinity_potency":[],"species_and_systems":"Human receptor-ectodomain fusion proteins; abstract only [PMID:11006133].","localisation_and_range":"JAG2 flagged transmembrane and non-secreted [flag].","caveats":"No affinity numbers. Reactome records exist [DB:Reactome R-HSA-157066]. Two other papers were review only.","key_references":[{"PMID":"11006133","why":"Physical binding of Jagged2 to Notch3"}],"covers":["LR008431"]},"LR004534":{"pair":"NPFF -> NPFFR1","headline":"NPFF binds NPFFR1 with nanomolar affinity and acts as a full agonist; four confirming papers and GtoPdb.","interaction_type":"direct binding","direction_and_effect":"NPFF specifically bound NPFF1, and both receptors were activated by NPFF [PMID:11024015]. In human NPFF1 CHO cells it inhibits forskolin-induced cAMP [PMID:12242085], and GTPgammaS assays showed agonist behaviour [PMID:17011599]. GtoPdb lists a full agonist [DB:GtoPdb].","molecular_requirements":"Receptor alone sufficient in CHO cells. Galpha(i3) and Galpha(s) are the main transducers of NPFF1 [PMID:17011599].","affinity_potency":[{"value":"Kd 1.13 nM","assay":"radioligand binding","system":"heterologous expression, human and rat clones","cite":"PMID:11024015"},{"value":"pKi 8.5 to 9.899999618530273","assay":"GtoPdb affinity range","system":"not specified in dossier","cite":"DB:GtoPdb"}],"species_and_systems":"Human and rat receptor clones in heterologous systems [PMID:11024015]; human NPFF1 in CHO cells [PMID:12242085, PMID:17011599]. Abstracts only. Mouse pair ortholog-inferred.","localisation_and_range":"NPFF is flagged secreted [flag].","caveats":"Peptides from both precursors bind both receptors; NPFF2 is also bound with high affinity, so NPFF is not selective [PMID:11024015, PMID:12242085]. The PMID:11481330 result compares NPVF peptides against NPFF peptides and gives no NPFF number.","key_references":[{"PMID":"11024015","why":"Kd 1.13 nM binding of NPFF to NPFF1"},{"PMID":"12242085","why":"Peptide affinities at human NPFF1 and NPFF2"},{"PMID":"17011599","why":"GTPgammaS agonist activity at NPFF1"}],"covers":["LR001124","LR004534"]},"LR004543":{"pair":"NPPC -> NPR2","headline":"CNP is the canonical, selective agonist of NPR2 (GC-B), supported by binding, functional and in vivo papers.","interaction_type":"direct binding","direction_and_effect":"CNP potently and selectively activated human ANPR-B guanylyl cyclase and did not raise cGMP in ANPR-A cells [PMID:1672777]; CNP was most potent at GC-B [PMID:1309330]. In mice CNP induces cGMP signalling via Npr2 needed for sensory axon bifurcation [PMID:19805384].","molecular_requirements":"Receptor-only guanylate cyclase; a splice variant NPR-Bi lacking a functional cyclase domain mediates a tyrosine-kinase-dependent K+ channel inhibition in IHKE-1 cells [PMID:12709393].","affinity_potency":[{"value":"50-fold higher than ANP","assay":"affinity of CNP for ANPR-B","system":"human ANPR-B","cite":"PMID:1672777"},{"value":"500-fold higher than BNP","assay":"affinity of CNP for ANPR-B","system":"human ANPR-B","cite":"PMID:1672777"}],"species_and_systems":"Human cells [PMID:1672777][PMID:12709393]; mouse in vivo genetics [PMID:19805384]. Both species are directly supported. GtoPdb lists agonist [DB:GtoPdb].","localisation_and_range":"CNP is annotated secreted [flag]; paper calls it a secreted molecule acting on sensory axons [PMID:19805384].","caveats":"All four papers read as abstracts. PMID:12709393 concerns a non-canonical variant, not canonical signalling.","key_references":[{"PMID":"1672777","why":"CNP selectively activates human ANPR-B"},{"PMID":"1309330","why":"Rank order at GC-B"},{"PMID":"19805384","why":"CNP/Npr2 in sensory axon bifurcation in mice"}],"covers":["LR001133","LR004543"]},"LR004552":{"pair":"NPY -> NPY4R","headline":"NPY binds NPY4R with nanomolar affinity but lower than PP, the preferred ligand; abstract-level cloning papers.","interaction_type":"direct binding","direction_and_effect":"NPY is an agonist of Y4/PP1 but a weaker one than PP. NPY pKi 8.68 against PP pKi 10.25 [PMID:7592911]; Ki 9.9 nM for NPY versus 13.8 pM for PP [PMID:7493937]. GtoPdb lists a full agonist [DB:GtoPdb].","molecular_requirements":"Single receptor chain; no co-receptor reported.","affinity_potency":[{"value":"pKi 8.68","assay":"125I-PYY displacement by NPY","system":"transiently expressed human Y4","cite":"PMID:7592911"},{"value":"Ki 9.9 nM","assay":"binding","system":"cloned human PP1 (Y4) in CHO cells","cite":"PMID:7493937"}],"species_and_systems":"Human receptor; human ligands [PMID:7592911][PMID:7493937]. Mouse pair is projected from human.","localisation_and_range":"NPY is flagged secreted, NPY4R transmembrane [flag].","caveats":"All papers read as abstracts only. Y4 is described as primarily a PP receptor [PMID:7493937], and the chimera paper calls PP highly selective for Y4 [PMID:15966750]. NPY is a lower-affinity, likely secondary ligand. One different_entity row was excluded.","key_references":[{"PMID":"7592911","why":"NPY pKi 8.68 at human Y4, compared with PP"},{"PMID":"7493937","why":"NPY Ki 9.9 nM at PP1/Y4 receptor"}],"covers":["LR001143","LR004552"]},"LR006226":{"pair":"NRCAM -> CNTN2","headline":"NRCAM-CNTN2 is supported by two database records only; no curator-verified paper.","interaction_type":"database-asserted only","direction_and_effect":"No paper confirms this pair. BioGRID lists a reconstituted complex [PMID:12139915][DB:BioGRID] and Reactome lists an NrCAM:Axonin-1 complex [DB:Reactome R-HSA-445006].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Species of the database experiments not reported in our evidence; human and mouse pairs are ortholog-inferred.","localisation_and_range":"Both entities carry secreted, receptor and transmembrane-type annotation flags [flag]; these look conflicting for a cell adhesion pair and do not define range. Contact-mediated binding is not shown here.","caveats":"No verified paper: outcomes are two different_entity and six abstract_insufficient. Support is database-only and the direction (ligand versus receptor) is not established.","key_references":[],"covers":["LR003002","LR006226"]},"LR010717":{"pair":"NRG2 -> ERBB2:ERBB3","headline":"NRG2 binds ErbB3 directly; ERBB2 as co-receptor is inferred, not shown.","interaction_type":"direct binding","direction_and_effect":"The NRG-2 EGF-like domain binds ErbB3 and ErbB4 [PMID:9168115]. Neuregulin-2 is an ErbB-family ligand [PMID:9168114].","molecular_requirements":"The ErbB3 chain is directly evidenced; the curator notes that ERBB2 is inferred as the standard partner [PMID:9168115]. Reactome lists NRG1/2:ERBB3:ERBB2 complexes [DB:Reactome].","affinity_potency":[],"species_and_systems":"Human ligand and receptor in receptor binding assays [PMID:9168115]; no affinity in our evidence.","localisation_and_range":"NRG2 is flagged secreted and transmembrane [flag].","caveats":"Both papers are abstract only; PMID 9168114 names ErbB2, ErbB3 and ErbB4 as the ErbB family generally. ERBB2 contribution is not tested.","key_references":[{"PMID":"9168115","why":"NRG-2 EGF domain binds ErbB3 and ErbB4"},{"PMID":"9168114","why":"NRG2 cloning, ErbB ligand"}],"covers":["LR010717"]},"LR004561":{"pair":"NRG4 -> ERBB4","headline":"NRG4 is a selective ERBB4 ligand: it displaces NRG-1 from ErbB-4 and activates its signalling.","interaction_type":"direct binding","direction_and_effect":"NRG-4 displaces ErbB-4-bound NRG-1 and activates signalling downstream of this receptor; an EGF-like peptide drove growth of ErbB-4 cells only [PMID:10348342].","molecular_requirements":"ErbB-4 alone suffices; other ErbB proteins or their combinations did not respond [PMID:10348342].","affinity_potency":[],"species_and_systems":"Species not clearly reported in this row; ErbB receptors ectopically expressed in interleukin-dependent cells, synthetic peptide [PMID:10348342]. Mouse pair is projected.","localisation_and_range":"Pro-NRG-4 is a transmembrane protein with a short cytoplasmic domain [PMID:10348342]; flags mark secreted and transmembrane [flag]. mRNA in adult pancreas, weakly muscle [PMID:10348342].","caveats":"Single paper, abstract only; no affinity. GtoPdb has no action or affinity [DB:GtoPdb]. Reactome records are generic NRG ligand entries [DB:Reactome].","key_references":[{"PMID":"10348342","why":"NRG-4 specificity for ErbB-4 and displacement of NRG-1"}],"covers":["LR001152","LR004561"]},"LR006235":{"pair":"NRN1 -> CD36","headline":"NRN1 binds CD36 in a CRISPRa screen follow-up by cell staining; one full-text paper.","interaction_type":"direct binding","direction_and_effect":"Fluorescent tetramers of NRN1 bound 293F cells expressing full-length CD36 by flow cytometry, and CD36 was a top hit in the NRN1 screen [PMID:36178190]. Effect on CD36 is not reported.","molecular_requirements":"Full-length CD36 on the cell surface; NRN1 was used as a tetramer, which can favour low-affinity interactions [PMID:36178190]. Other subunits not reported.","affinity_potency":[],"species_and_systems":"Human NRN1 and CD36; CRISPR activation screen and 293F cells, recombinant [PMID:36178190].","localisation_and_range":"NRN1 annotated as secreted [flag]; CD36 is a multi-pass transmembrane scavenger receptor [PMID:36178190].","caveats":"Tested by cell surface staining only (no SPR for this pair in the paper table) [PMID:36178190]. No affinity. CD36 also bound other secreted ligands (LY6H, VWC2L, SCRG1), so it may be promiscuous. In vivo relevance not reported.","key_references":[{"PMID":"36178190","why":"CRISPRa screen identifies CD36 as NRN1 receptor, confirmed by staining"}],"covers":["LR003011","LR006235"]},"LR006244":{"pair":"NRXN1 -> LRRTM3","headline":"In vitro pull-down shows LRRTM3 interacts with neurexin-1beta lacking SS4; one confirmed paper, mouse.","interaction_type":"direct binding","direction_and_effect":"Ig-neurexin-1b lacking an insert at SS4 pulled down LRRTM3 in vitro; LRRTM3 required only specific neurexin splice variants for synaptogenic activity [PMID:26776509].","molecular_requirements":"Pull-down used SS4-lacking neurexin-1beta; the abstract states LRRTM3 needs specific splice variants of presynaptic neurexins [PMID:26776509].","affinity_potency":[],"species_and_systems":"Mouse study (Lrrtm3 knockout and knockdown in dentate gyrus neurons) [PMID:26776509]. Human pair is ortholog-inferred. UniProt notes NRXN1 interacts with LRRTM1-4 by similarity [DB:UniProt].","localisation_and_range":"Both transmembrane [flag]; trans-synaptic.","caveats":"The paper itself says the interaction was shown at least in vitro; the binding is a supplementary figure result, not the main finding. One further paper was abstract_insufficient.","key_references":[{"PMID":"26776509","why":"Ig-neurexin-1b pull-down of LRRTM3; splice-variant-dependent synaptogenesis"}],"covers":["LR003020","LR006244"]},"LR006253":{"pair":"NRXN3 -> CLSTN3","headline":"Beta-neurexins bind Clstn3 directly according to one abstract-only paper; NRXN3 specifically is not named.","interaction_type":"direct binding","direction_and_effect":"Beta-Nrxns directly interact via their LNS domain with Clstn3 and its cadherin domains [PMID:32434929]. Clstn3 synaptogenic activity depended on SS4-positive beta-Nrxn variants [PMID:32434929].","molecular_requirements":"SS4 insert-positive Nrxns are required; insert-negative variants do not rescue [PMID:32434929].","affinity_potency":[],"species_and_systems":"Experiment species unspecified; neuron cultures, conditional knockout mice and hippocampal slices described in abstract [PMID:32434929]. Mouse pair is non-inferred.","localisation_and_range":"Both flagged transmembrane, non-secreted [flag]; Clstn3 is described as a postsynaptic adhesion molecule acting via presynaptic neurexins [PMID:32434929].","caveats":"Abstract only; Nrxn paralogue (NRXN3) is not named. The abstract notes that direct binding had been a matter of debate [PMID:32434929].","key_references":[{"PMID":"32434929","why":"Beta-Nrxn LNS domain directly binds Clstn3, SS4-dependent"}],"covers":["LR003029","LR006253"]},"LR008503":{"pair":"NRXN3 -> NLGN1","headline":"Supported only by database records (BioGRID, UniProt); no curator-verified paper.","interaction_type":"database-asserted only","direction_and_effect":"Direction and effect are not reported in our evidence.","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"BioGRID lists a reconstituted complex [DB:BioGRID]; UniProt states NLGN1 interacts with neurexins NRXN1, NRXN2 and NRXN3 (by similarity) [DB:UniProt].","localisation_and_range":"Both flagged transmembrane, non-secreted [flag].","caveats":"Three papers pending, none judged; the UniProt statement is by similarity [DB:UniProt].","key_references":[],"covers":["LR008503"]},"LR001159":{"pair":"NTF3 -> NTRK3","headline":"NT-3 is the cognate TrkC ligand, supported by binding, structural mapping and signalling papers, though all read as abstracts.","interaction_type":"direct binding","direction_and_effect":"gp145trkC is a functional receptor for NT-3 and does not bind NGF or BDNF [PMID:1653651]. NT-3 signalling through TrkC promotes apoptosis in medulloblastoma cells [PMID:9973222]. Curator labels it agonist [PMID:9488719].","molecular_requirements":"TrkC primarily uses loop EF for binding [PMID:9488719]. Reactome lists NTF3:NTRK3 homodimer complexes [DB:Reactome].","affinity_potency":[],"species_and_systems":"Human receptor models and mutational analysis [PMID:9488719]; neuronal cells expressing defined Trk receptors [PMID:7679912]; medulloblastoma cells and nude mouse xenografts [PMID:9973222]. Mouse pair is ortholog-inferred.","localisation_and_range":"NTF3 flagged secreted, NTRK3 transmembrane [flag].","caveats":"All papers read as abstracts only; one review-only row is not shown. GtoPdb record has no action or affinity [DB:GtoPdb].","key_references":[{"PMID":"1653651","why":"trkC identified as NT-3 receptor"},{"PMID":"9488719","why":"Loop EF of TrkC as NT-3 binding determinant"},{"PMID":"7679912","why":"NT-3 preferred for TrkC in neuronal and non-neuronal cells"}],"covers":["LR001159","LR004568"]},"LR004570":{"pair":"Ntf5 -> Ntrk2","headline":"Mouse pair supported by human TrkB subnanomolar binding and canonical specificity papers.","interaction_type":"direct binding","direction_and_effect":"The human TrkB Ig2 domain binds BDNF and NT-4 with subnanomolar affinity [PMID:11855816]. NT-4/5 is a preferred ligand for TrkB [PMID:7679912].","molecular_requirements":"TrkB Ig2 domain sufficient [PMID:11855816].","affinity_potency":[{"value":"subnanomolar","assay":"surface plasmon resonance","system":"isolated human TrkB Ig2 domain","cite":"PMID:11855816"}],"species_and_systems":"Binding data are human [PMID:11855816]; curator assigns mouse to the second paper [PMID:7679912]. BioGRID and PDB 1HCF records are for the human pair [DB:BioGRID][DB:PDB 1HCF].","localisation_and_range":"NT-4 flagged secreted [flag].","caveats":"Affinity qualitative only; abstracts only; the mouse row rests largely on human data.","key_references":[{"PMID":"11855816","why":"SPR of NT-4 binding to TrkB Ig2"},{"PMID":"7679912","why":"NT-4/5 preferred TrkB ligand"}],"covers":["LR004570"]},"LR001168":{"pair":"NTN1 -> UNC5D","headline":"Netrin-1 to UNC5D rests on a general family statement; no UNC5D-specific netrin evidence in our dossier.","interaction_type":"functional only","direction_and_effect":"The cited paper states in background that netrin-1 induces repulsive axon guidance by binding the Unc5 receptor family (Unc5A-Unc5D) [PMID:21673655]. Its own finding is that Unc5D binds FLRT2 [PMID:21673655].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Background statement in a paper using mouse neocortex development; Reactome lists UNC-5 binding netrin-1 in general [DB:Reactome]. The human pair is ortholog-inferred.","localisation_and_range":"Netrin-1 is secreted and UNC5D is transmembrane [flag].","caveats":"The paper does not test netrin-1 with UNC5D and notes Unc5 functions independent of netrin-1 [PMID:21673655]. Abstract only. Treat this as weakly supported.","key_references":[{"PMID":"21673655","why":"Background statement on netrin-1/Unc5 family; main finding concerns FLRT2"}],"covers":["LR001168","LR004577"]},"LR006262":{"pair":"NTN3 -> UNC5C","headline":"Murine netrin-3 binds the UNC5 family in one abstract-only paper; UNC5C is not named individually.","interaction_type":"direct binding","direction_and_effect":"Murine netrin-3 binds the UNC5 family (UNC5H1, UNC5H2 and UNC5H3) with higher affinity than it binds DCC [PMID:10366627].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Murine netrin-3 protein; human pair is ortholog-inferred [PMID:10366627].","localisation_and_range":"Netrin-3 is flagged secreted and the receptor transmembrane [flag].","caveats":"Abstract only. The evidence sentence names UNC5H1-3, and the mapping to this specific receptor is not stated in the abstract. No numbers are reported.","key_references":[{"PMID":"10366627","why":"Murine netrin-3 binds UNC5 family receptors"}],"covers":["LR003038","LR006262"]},"LR001177":{"pair":"NXPH1 -> NRXN2","headline":"Neurexophilin-1 binds the LNS2 domain of neurexin-2 with nanomolar affinity, shown by a 2019 full-text study and earlier abstract data.","interaction_type":"direct binding","direction_and_effect":"Nxph1 binds the LNS2SS2- domains of Nrxn1, Nrxn2 and Nrxn3 with similar nanomolar affinities [PMID:31566781]. Neurexophilins 1 and 3 bind the second LNS domain in all three alpha-neurexins [PMID:9856994].","molecular_requirements":"LNS2 domain is required; all splice variants bind in the 1998 study [PMID:9856994]. The I401Q mutation in Nrxn2 LNS2SS2- decreases Nxph1 affinity from the nanomolar to the micromolar range [PMID:31566781].","affinity_potency":[],"species_and_systems":"Mouse Nrxn2 was assessed in the 2019 study [PMID:31566781]; recombinant mouse proteins in [PMID:9856994]. Both species pairs are ortholog-inferred.","localisation_and_range":"Secreted ligand [flag] and membrane neurexin [flag].","caveats":"Exact affinity values sit in a table not shown in our excerpts. The 1998 paper was read as an abstract only. The 2019 evidence sentence is a section-lead sentence rather than a result.","key_references":[{"PMID":"31566781","why":"Structures of Nxph1 with Nrxn LNS2 and isoform specificity"},{"PMID":"9856994","why":"NXPH1 and NXPH3 bind LNS2 of all three alpha-neurexins"}],"covers":["LR001177","LR004586"]},"LR006271":{"pair":"OMG -> PTPRU","headline":"OMG binds PTPRU with a KD of ~70 nM by SPR; PTPRU was the top hit of the OMG CRISPRa screen.","interaction_type":"direct binding","direction_and_effect":"OMG is the ligand and PTPRU the receptor. In the paper's OMG CRISPRa screen PTPRU was the top-ranking hit with a positive enrichment trajectory over all three selection rounds, and binding was confirmed by SPR [PMID:36178190]. Effect on PTPRU activity is not reported in our evidence.","molecular_requirements":"PTPRU ectodomain alone was sufficient for SPR binding; among R2B RPTPs only PTPRU bound OMG [PMID:36178190].","affinity_potency":[{"value":"KD ~70 nM","assay":"SPR, 1:1 binding model","system":"recombinant human PTPRU-ECD and human OMG","cite":"PMID:36178190"}],"species_and_systems":"Human proteins, cell-based CRISPRa screen plus SPR [PMID:36178190]. Mouse pair is projected from human.","localisation_and_range":"OMG is flagged non-secreted [flag]; the paper treats it as a secreted ligand used as a multimerised bait, so range (contact versus diffusible) is not settled in our evidence. The PTPRU entity has a receptor flag only, no transmembrane or secreted flag [flag].","caveats":"Single paper, no independent confirmation, no database records. Quoted KD is approximate.","key_references":[{"PMID":"36178190","why":"Screen hit and SPR KD for OMG-PTPRU"}],"covers":["LR003047","LR006271"]},"LR001186":{"pair":"OSM -> IL6ST","headline":"OSM engages gp130 (IL6ST) as the shared signalling chain; supported by structure, functional papers and databases, but not alone.","interaction_type":"direct binding","direction_and_effect":"OSM binds gp130 through its site 2 epitope centred on Gly120 [PMID:10997905], and in rat hepatoma cells human and mouse OSM engaged gp130 together with their OSMRbeta subunits [PMID:10854424]. Both LIF and OSM activate gp130.LIFR, whereas gp130.OSMRbeta is activated by OSM only [PMID:8999038]. GtoPdb lists OSM as an agonist of IL6ST [DB:GtoPdb].","molecular_requirements":"gp130 works with a second chain, either LIFR or OSMR [PMID:8999038][PMID:10854424]. UniProt says low-affinity binding to IL6ST induces heterodimerisation with LIFR or OSMR [DB:UniProt]. Our evidence does not show gp130 alone signalling for OSM.","affinity_potency":[],"species_and_systems":"Human OSM structure and mutagenesis [PMID:10997905]; human/mouse OSM in rat hepatoma cells [PMID:10854424]; human cell systems [PMID:8999038][PMID:16051226]. Mouse pair is projected from human.","localisation_and_range":"OSM is a flagged secreted, non-transmembrane ligand; IL6ST is a flagged transmembrane receptor [flag]. Paracrine/endocrine range follows from the secreted flag.","caveats":"All four papers shown were read as abstracts only. The structure is of OSM alone, not a complex [PMID:10997905]. The IL6ST entity name in the dossier is 'Interleukin-27 receptor', which looks like a label mismatch for gp130. PDB 8V29 and 8V2A are listed with chains of P13725 and P40189 [DB:PDB 8V29]. Reactome and IntAct records exist [DB:Reactome].","key_references":[{"PMID":"10997905","why":"Crystal structure; gp130 site 2 epitope"},{"PMID":"8999038","why":"OSM acts via gp130-LIFR and gp130-OSMRbeta"},{"PMID":"10854424","why":"Human and mouse OSM engage gp130 with OSMRbeta"}],"covers":["LR001186","LR004595"]},"LR003049":{"pair":"PCDHA7 -> PCDHA7","headline":"PCDHA7 binds itself homophilically in trans by SPR with interface mutagenesis; mouse data, human by orthology.","interaction_type":"direct binding","direction_and_effect":"Mutations designed to disrupt the alpha7 trans interface inhibited homophilic binding, showing binding occurs via the trans interface [PMID:35253643]. Self-binding, so no distinct ligand and receptor.","molecular_requirements":"Clustered protocadherin trans interaction is homophilic and isoform-specific; cis multimers with other isoforms may form the actual cell-surface unit, so one isoform alone may not reproduce the interface.","affinity_potency":[],"species_and_systems":"Mouse clustered protocadherin EC1-4 fragments by SPR [PMID:35253643]; the human pair is ortholog-inferred.","localisation_and_range":"Membrane-bound cell-adhesion molecule; trans homophilic contact between cells (juxtacrine), not secreted [flag].","caveats":"Heterophilic binding of close paralogs was not detected, with an estimated lower limit KD of ~200 \u03bcM [PMID:35253643]. Only mouse fragments were tested; alpha isoforms need cis partners for surface delivery in cells, per a curator note.","key_references":[{"PMID":"35253643","why":"SPR plus trans-interface mutagenesis"}],"covers":["LR003049","LR006273"]},"LR006307":{"pair":"PCSK1N -> GPR171","headline":"The proSAAS-derived peptide BigLEN activates mouse GPR171; evidence is one abstract-only paper.","interaction_type":"functional only","direction_and_effect":"BigLEN (not LittleLEN) activates the Galphai/o-coupled GPR171 (agonist); knockdown of hypothalamic GPR171 reduced BigLEN signalling and changed food intake [PMID:24043826].","molecular_requirements":"The bioactive ligand is the processed peptide BigLEN rather than full-length PCSK1N; its four C-terminal amino acids suffice to bind and activate GPR171 [PMID:24043826].","affinity_potency":[],"species_and_systems":"Mouse hypothalamus, Neuro2A cells and mice [PMID:24043826]; human pair ortholog-inferred.","localisation_and_range":"PCSK1N is annotated secreted [flag]; the peptide acts as a secreted neuropeptide (annotation only).","caveats":"Abstract only, and binding assays are described only as ligand-binding/receptor-activity assays [PMID:24043826]. Human data not reported in our evidence.","key_references":[{"PMID":"24043826","why":"Deorphanises GPR171 as BigLEN receptor with genetic and antibody loss-of-function."}],"covers":["LR003084","LR006307"]},"LR003085":{"pair":"PCSK1N -> GPR83","headline":"proSAAS-derived PEN peptides activate GPR83 with length-dependent G protein bias; abstract-only paper plus UniProt.","interaction_type":"functional only","direction_and_effect":"PEN activates GPR83 (agonist); PEN22 and PEN20 favour Galphai coupling, while PEN18 and PEN19 favour Galphas coupling, consistent with biased ligands [PMID:35605991]. UniProt also lists PEN peptides as GPR83 activators via Gi and Gs [DB:UniProt].","molecular_requirements":"The active species are processed PEN peptides from proSAAS (PCSK1N), not the full precursor; the length of PEN determines the G protein coupling [PMID:35605991].","affinity_potency":[],"species_and_systems":"Human receptor/ligand labelled in the curated row [PMID:35605991]; mouse pair is ortholog-inferred.","localisation_and_range":"PCSK1N is annotated secreted [flag]; PEN is described as a neuropeptide [PMID:35605991].","caveats":"Abstract only; no affinity for PEN reported in our evidence (high-affinity binding in the abstract concerns proCCK peptides) [PMID:35605991].","key_references":[{"PMID":"35605991","why":"PEN lengths bias GPR83 coupling to Galphai vs Galphas."}],"covers":["LR003085","LR006308"]},"LR001933":{"pair":"PDCD1LG2 -> RGMB","headline":"PD-L2 binds RGMb directly (Kd 48.5 nM) in mouse and human proteins; blocking it impairs respiratory tolerance.","interaction_type":"direct binding","direction_and_effect":"PD-L2 binds RGMb, a second receptor besides PD-1; blocking the RGMb-PD-L2 interaction impaired respiratory tolerance development by interfering with initial T-cell expansion [PMID:24752301].","molecular_requirements":"PD-L2 and BMP-2/4 bind distinct sites on RGMb; PD-L2 does not bind RGMa or RGMc, and RGMb did not bind PD-L1 [PMID:24752301].","affinity_potency":[{"value":"Kd = 48.5 nM","assay":"Biacore, RGMb with PD-L2","system":"recombinant proteins (Fig. 1e)","cite":"PMID:24752301"}],"species_and_systems":"Mouse and human proteins bind each other by ELISA, plus mouse cell conjugation assays and mouse tolerance models [PMID:24752301]; the human pair is ortholog-inferred.","localisation_and_range":"PD-L2 annotated secreted [flag]; RGMs are GPI-anchored membrane proteins and cells conjugated by surface-to-surface binding [PMID:24752301].","caveats":"Abstract-level curation with full-text excerpts. For comparison, PD-1 bound PD-L2 with Kd = 58.8 nM in the same experiment [PMID:24752301].","key_references":[{"PMID":"24752301","why":"Identifies RGMb as PD-L2 receptor with binding and functional blockade."}],"covers":["LR001933","LR005271"]},"LR001195":{"pair":"PDGFB -> LRP1","headline":"PDGF-BB binds purified LRP1 by SPR; LRP1 acts as a co-receptor rather than the main PDGF receptor.","interaction_type":"direct binding","direction_and_effect":"Only PDGF, not bFGF, EGF or IGF-1, bound purified LRP on a sensor chip; PDGF-BB induced transient Src-dependent phosphorylation of the LRP cytoplasmic domain at the second NPXY motif and recruited Shc [PMID:11854294]. UniProt lists the PDGFB-LRP1 interaction [DB:UniProt].","molecular_requirements":"LRP1 modulates PDGF receptor signalling as a co-receptor, so it likely functions alongside PDGF receptors [PMID:11854294].","affinity_potency":[],"species_and_systems":"Human proteins, SPR with purified LRP [PMID:11854294]; mouse pair ortholog-inferred.","localisation_and_range":"PDGFB annotated secreted [flag].","caveats":"Abstract only; no affinity reported in our evidence. BioGRID records the same paper [DB:BioGRID].","key_references":[{"PMID":"11854294","why":"SPR of PDGF binding to purified LRP with negative controls."}],"covers":["LR001195","LR004604"]},"LR004606":{"pair":"PDGFB -> PDGFRB","headline":"PDGFB binds and activates PDGFRB; supported by human receptor binding data and database structure and binding records.","interaction_type":"direct binding","direction_and_effect":"PDGF receptor cloned from human cDNA bound PDGF-BB and, less, PDGF-AB, but not PDGF-AA [PMID:2850496]. A soluble PDGFRB decoy reduced PDGF-BB-induced glycosaminoglycan synthesis in fetal lung fibroblasts, consistent with receptor-mediated stimulation [PMID:11903042]. UniProt: PDGFB homodimer interacts with PDGFRB homodimers [DB:UniProt].","molecular_requirements":"The ligand acts as a dimer (PDGFB homodimer; PDGFA:PDGFB heterodimers also bind PDGFRB) [DB:UniProt]. Single receptor chain suffices in the CHO expression assay [PMID:2850496].","affinity_potency":[],"species_and_systems":"Human receptor expressed in CHO cells [PMID:2850496]; human fetal lung fibroblasts [PMID:11903042]. Both papers read as abstracts only. A PDB structure (3MJG) and IntAct and BioGRID binding records exist [DB:PDB 3MJG][DB:IntAct].","localisation_and_range":"PDGFB flagged secreted, PDGFRB transmembrane [flag]; soluble paracrine ligand acting on a cell-surface receptor.","caveats":"Both papers read as abstracts only. The second paper is an indirect functional (decoy) readout. The mouse pair is ortholog-inferred from human evidence. No affinity reported in our evidence.","key_references":[{"PMID":"2850496","why":"Receptor cloned and shown to bind PDGF-BB, not PDGF-AA"},{"PMID":"11903042","why":"Soluble PDGFRB decoy blocks PDGF-BB response in fibroblasts"}],"covers":["LR001197","LR004606"]},"LR005272":{"pair":"PDPN -> CLEC1B","headline":"PDPN binds CLEC1B (CLEC-2); crystal structure and mouse lung development data support it.","interaction_type":"direct binding","direction_and_effect":"Podoplanin binds CLEC-2, and crystal structures of the complex show binding at the noncanonical side face of CLEC-2 via sialic acid on O-glycan [PMID:25458834]. UniProt: PDPN binding to CLEC1B triggers platelet activation or aggregation [DB:UniProt]. Platelet Clec-2 and podoplanin interaction regulates lung development in mice [PMID:29853539].","molecular_requirements":"Binding depends on O-glycosylation (sialic acid) of podoplanin [PMID:25458834]. CLEC1B acts as a dimer in Reactome complexes [DB:Reactome].","affinity_potency":[],"species_and_systems":"Structure: PDB 3WSR [DB:PDB 3WSR]. In vivo: murine lung development [PMID:29853539]. Both papers read as abstracts only.","localisation_and_range":"PDPN is flagged non-secreted [flag]; contact between platelet and podoplanin-expressing cell. The CLEC1B secreted flag is an annotation flag [flag].","caveats":"Abstracts only; the lung development abstract is truncated. No affinity in our evidence. Curated experiment species for the mouse paper is recorded as human.","key_references":[{"PMID":"25458834","why":"Crystal structure of CLEC-2 with podoplanin"},{"PMID":"29853539","why":"Platelet Clec-2/podoplanin interaction needed for mouse lung development"}],"covers":["LR001934","LR005272"]},"LR006316":{"pair":"PECAM1 -> PECAM1","headline":"Homophilic PECAM1 self-binding mapped to Ig domains 1-2 in one abstract-only aggregation study; databases add reconstituted-complex records.","interaction_type":"direct binding","direction_and_effect":"PECAM1 binds itself (homophilic adhesion); the curator labels the effect agonist [PMID:8702505].","molecular_requirements":"Homophilic binding involves the first two extracellular Ig-like domains; the cytoplasmic domain (exons 9-10 for minimal length) and surface expression level shift aggregation between homophilic and heterophilic modes [PMID:8702505].","affinity_potency":[],"species_and_systems":"Cell aggregation assay in L-cells expressing human, murine and chimeric PECAM-1; experiments were in vitro [PMID:8702505]. Mouse pair is ortholog-inferred.","localisation_and_range":"Membrane-bound receptor, not secreted [flag]; homophilic contact between cells is implied by the aggregation assay [PMID:8702505].","caveats":"Single paper, read as abstract only. The same abstract reports heterophilic, calcium-dependent aggregation under some conditions. BioGRID, IntAct and Reactome records exist (reconstituted complex, solid phase assay, trans-homophilic interaction) [DB:BioGRID] [DB:IntAct] [DB:Reactome].","key_references":[{"PMID":"8702505","why":"Domain mapping of homophilic PECAM-1 binding"}],"covers":["LR003093","LR006316"]},"LR004615":{"pair":"PENK -> OPRD1","headline":"Weak support: the one verified paper is a biosensor tool paper whose cited sentence does not address PENK or OPRD1; GtoPdb lists an agonist.","interaction_type":"database-asserted only","direction_and_effect":"GtoPdb lists a full agonist for PENK at OPRD1 [DB:GtoPdb]. The paper's evidence sentence concerns kappaLight and dynorphin release, not this pair [PMID:39009835].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Biosensors built on human OPRK1, OPRD1 and OPRM1; mouse brain slices and in vivo photometry in mice [PMID:39009835].","localisation_and_range":"PENK is flagged secreted [flag]. Range not reported in our evidence.","caveats":"The paper was read as abstract plus excerpts; the excerpts only describe cloning. Direct PENK-OPRD1 evidence is not shown. GtoPdb lists pKi without a value in the dossier [DB:GtoPdb].","key_references":[{"PMID":"39009835","why":"Opioid receptor-based biosensors (indirect)"}],"covers":["LR001206","LR004615"]},"LR003094":{"pair":"PF4 -> CCR1","headline":"CXCL4/PF4 acts as a CCR1 agonist for migration and endocytosis; one full-text paper, but CXCL4 did not compete for CCL3 binding.","interaction_type":"functional only","direction_and_effect":"CXCL4 induced migration of CCR1-expressing L1.2 transfectants and THP-1 cells, CCR1 endocytosis, and CCR1 antagonist-sensitive monocyte chemotaxis; it appears a partial agonist in transfectants [PMID:29930254].","molecular_requirements":"Migration to CXCL4 was ablated by chondroitinase, suggesting cell-surface glycosaminoglycan presentation is required [PMID:29930254].","affinity_potency":[],"species_and_systems":"Human THP-1 cells, human primary monocytes, mouse L1.2 transfectants [PMID:29930254]. Human and mouse pairs are ortholog-inferred.","localisation_and_range":"PF4 is flagged secreted [flag]; deposition on endothelium is described in the abstract [PMID:29930254].","caveats":"Binding was not shown: unlabeled CXCL4 failed to compete with radiolabelled CCL3 for CCR1 [PMID:29930254]. Assay_class says direct_binding but the data are functional. UniProt cites the interaction [DB:UniProt]. Effect needs micromolar CXCL4 (1 uM used) [PMID:29930254].","key_references":[{"PMID":"29930254","why":"CXCL4 as CCR1 agonist in monocytes"}],"covers":["LR003094","LR006317"]},"LR006325":{"pair":"PLA2G2A -> EGFR","headline":"sPLA2-IIa co-immunoprecipitates with EGFR in human cancer cells; one abstract-only paper plus BioGRID.","interaction_type":"direct binding","direction_and_effect":"sPLA2-IIa binds EGFR and HER3 by co-immunoprecipitation, and the authors suggest it acts as a ligand for both [PMID:28440478]. Curated direction: agonist; sPLA2-IIa activates EGFR-family signalling in a positive feedback loop with HER/ERBB-PI3K-Akt-NF-kB signalling [PMID:28440478]. BioGRID lists affinity capture-Western [DB:BioGRID 2524052].","molecular_requirements":"Not reported in our evidence; HER2 interaction is indirect [PMID:28440478].","affinity_potency":[],"species_and_systems":"Human lung (A549, H1975) and prostate (22Rv1) cancer cells; xenografts in nude mice [PMID:28440478]. Mouse pair is ortholog-inferred.","localisation_and_range":"Secreted and raised in tumour interstitial fluid and blood [PMID:28440478]; secreted flag on PLA2G2A [flag].","caveats":"Abstract only; co-IP in cells does not prove direct binding or exclude intermediaries, and no affinity is reported.","key_references":[{"PMID":"28440478","why":"sPLA2-IIa binds EGFR and HER3 by co-IP and supports cancer stem cell phenotype"}],"covers":["LR003104","LR006325"]},"LR001942":{"pair":"PLA2G2A -> ITGB3","headline":"sPLA2-IIA binds and activates alphavbeta3; beta3 is one chain of the heterodimer.","interaction_type":"direct binding","direction_and_effect":"sPLA2-IIA bound integrin alphavbeta3 with high affinity [PMID:18635536]. It directly activated purified soluble and cell-surface alphavbeta3 and enhanced ligand binding in ELISA and flow cytometry [PMID:25398877]. BioGRID lists a reconstituted complex [DB:BioGRID 1528284]. Agonist.","molecular_requirements":"alphavbeta3 heterodimer; Arg-74 and Arg-100 of sPLA2-IIA are needed [PMID:18635536]. Beta3 alone: not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human ligand and human receptor; integrin binding and cell assays [PMID:18635536][PMID:25398877]. Mouse pair is ortholog-inferred.","localisation_and_range":"Secreted, from the PLA2G2A secreted flag [flag].","caveats":"The 18635536 evidence sentence is background text. Affinity (KD 2 x 10(-7) M) is for alphavbeta3 in the same paper [PMID:18635536]. 25398877 full-text read is marked unverified.","key_references":[{"PMID":"18635536","why":"alphavbeta3 binding and mutagenesis"},{"PMID":"25398877","why":"Direct activation of alphavbeta3 via site 2"}],"covers":["LR001942","LR005279"]},"LR004624":{"pair":"PLAT -> LRP1","headline":"tPA bound to PAI-1 binds LRP1 for clearance, and LRP1 binds tPA on neurons; two abstract-only papers.","interaction_type":"direct binding","direction_and_effect":"tPA-inhibitor complexes bound LRP in solution, and their endocytosis and degradation in cells was reduced by anti-LRP antibodies and RAP [PMID:1502153]. In hippocampal neurons LRP was the major cell-surface receptor that bound tPA, and tPA binding enhanced cyclic AMP-dependent protein kinase activity [PMID:10632583]. UniProt says LRP1 interacts with tPA alone or in complex with SERPINE1 [DB:UniProt Q07954].","molecular_requirements":"The species bound in [PMID:1502153] is the tPA-PAI-1 complex, not free tPA. LRP is a heterodimeric receptor [PMID:1502153].","affinity_potency":[],"species_and_systems":"Human ligand and receptor labels for the 1992 paper; [PMID:10632583] used mouse hippocampal slices with tPA knockout mice (ligand species unspecified). Mouse pair is ortholog-inferred.","localisation_and_range":"Secreted tPA per flag [flag]; LRP1 is described as a ubiquitous membrane receptor [PMID:1502153].","caveats":"Abstract only. Free tPA binding is shown only in neurons [PMID:10632583]; clearance function is for the complex [PMID:1502153]. Numeric affinity not reported in our evidence.","key_references":[{"PMID":"1502153","why":"tPA-PAI-1 complexes bind LRP and are cleared"},{"PMID":"10632583","why":"LRP is the major tPA-binding receptor on hippocampal neurons"}],"covers":["LR001221","LR004624"]},"LR006334":{"pair":"PLAUR -> ITGAV","headline":"Direct cell-based binding of soluble uPAR to alphaV (ITGAV) integrin chain in one paper; no affinity.","interaction_type":"direct binding","direction_and_effect":"Soluble uPAR (suPAR D2D3) bound integrin-transfected CHO cells in a cation-dependent manner, blocked by anti-integrin and anti-uPAR antibodies [PMID:11053440]. It acts as a ligand, signalling consequence not reported in our evidence.","molecular_requirements":"Evidence is for the heterodimer; the integrin chain alone was not tested separately [PMID:11053440]. Paired with beta3 in the paper [PMID:11053440].","affinity_potency":[],"species_and_systems":"Human uPAR on hamster (CHO) cells [PMID:11053440].","localisation_and_range":"uPAR is described as a GPI-anchored protein lacking a transmembrane structure that acts as an integrin ligand, in trans between apposed cells, as well as an associated protein in cis [PMID:11053440]. Cell-cell contact range.","caveats":"Single paper (abstract only); no affinity.","key_references":[{"PMID":"11053440","why":"uPAR binds integrins alpha4beta1, alpha6beta1, alpha9beta1, alphavbeta3 on CHO cells"}],"covers":["LR003113","LR006334"]},"LR004633":{"pair":"PLG -> ITGA9","headline":"Plasmin(ogen) kringles bind integrin alpha9beta1 in CHO cells; chain-level row for ITGA9.","interaction_type":"direct binding","direction_and_effect":"Plasmin specifically interacts with alpha9beta1 and induced migration of alpha9-CHO cells; migration needed kringle binding, plasmin catalytic activity and simultaneous PAR-1 activation [PMID:15247268]. Angiostatin alone did not induce migration [PMID:15247268].","molecular_requirements":"Needs kringle binding plus catalytic activity and PAR-1; alpha9 is tested as the alpha9beta1 heterodimer [PMID:15247268].","affinity_potency":[],"species_and_systems":"Human proteins on recombinant CHO cells; abstract only [PMID:15247268].","localisation_and_range":"Ligand flagged secreted.","caveats":"The active species is plasmin, the cleaved form, not intact plasminogen; angiostatin is described as a ligand and antagonist of alpha9beta1 [PMID:15247268]. One further row abstract-insufficient.","key_references":[{"PMID":"15247268","why":"plasmin binds alpha9beta1 and needs PAR-1 for migration"}],"covers":["LR001230","LR004633"]},"LR006343":{"pair":"PODXL2 -> SELE","headline":"Endoglycan (PODXL2) from B cells binds E-selectin in a sialylation-dependent way and supports rolling; a single paper.","interaction_type":"direct binding","direction_and_effect":"Immunopurified endoglycan from a B-cell line, a monocyte line and human tonsils bound P-selectin and, where tested, E-selectin; an endoglycan construct supported slow rolling of E- and P-selectin bearing cells [PMID:18606703].","molecular_requirements":"Binding was divalent cation-dependent and required sialylation of endoglycan; rolling depended on sialic acid and fucose [PMID:18606703]. Blocking antibodies or EDTA reduced rolling by 90-100% [PMID:18606703].","affinity_potency":[],"species_and_systems":"Human cells and tonsil-derived protein [PMID:18606703]; mouse pair is ortholog-inferred.","localisation_and_range":"Endoglycan flagged transmembrane, not secreted [flag]; contact-dependent (rolling) adhesion.","caveats":"One paper only. E-selectin was tested in fewer assays than P-selectin ('where tested'). No affinity reported. No database records.","key_references":[{"PMID":"18606703","why":"endoglycan binds E- and P-selectin; supports rolling"}],"covers":["LR003122","LR006343"]},"LR004642":{"pair":"POMC -> MC2R","headline":"POMC-derived ACTH activates MC2R in cell assays; evidence is abstract-level functional work, with the POMC gene standing in for its cleavage product.","interaction_type":"functional only","direction_and_effect":"ACTH, a POMC cleavage product, activates human MC2R and raises a cAMP-reporter signal [PMID:12213892]; ACTH[1-39] and ACTH[1-24] are full agonists at the mouse receptor [PMID:8754753]. Recombinant ASIP inhibits ACTH-stimulated cAMP at hMC2R, nonsurmountably [PMID:9058374]. UniProt lists MC2R as a POMC ligand target [DB:UniProt].","molecular_requirements":"Not reported in our evidence; no accessory subunit is discussed in the dossier.","affinity_potency":[{"value":"EC50 5.5 nM","assay":"cAMP-responsive luciferase reporter","system":"OS-3 cells with human MC2R","cite":"PMID:12213892"},{"value":"KD 0.84 x 10(-9) M","assay":"Scatchard analysis, 125I-ACTH binding (ACTH[1-39])","system":"HeLa cells with mouse ACTH receptor","cite":"PMID:8754753"},{"value":"EC50 57 x 10(-12) M","assay":"cAMP stimulation (ACTH[1-39])","system":"HeLa cells with mouse ACTH receptor","cite":"PMID:8754753"}],"species_and_systems":"Human receptor in OS-3 and OS3 cells [PMID:12213892][PMID:9058374]; mouse receptor in stably transfected HeLa cells [PMID:8754753]. The mouse pair is ortholog-inferred. All three papers were read as abstracts only.","localisation_and_range":"POMC is flagged secreted and MC2R transmembrane [flag]; this implies paracrine or endocrine signalling, but no paper here tests range.","caveats":"The ligand actually tested is ACTH, not full-length POMC. Abstract notes all five melanocortin receptors bind ACTH to some degree, though MC2R is ACTH-selective [PMID:12213892]. No primary direct-binding data with human MC2R in this dossier. Entity name shown for POMC is beta-endorphin, which is not the ligand tested [flag].","key_references":[{"PMID":"12213892","why":"Human MC2R activated by ACTH with EC50 5.5 nM; FGD mutants validate assay"},{"PMID":"8754753","why":"Mouse ACTH receptor binding and agonism, KD and EC50 values"},{"PMID":"9058374","why":"ASIP antagonism of ACTH at hMC2R"}],"covers":["LR001240","LR004642"]},"LR001249":{"pair":"PPY -> NPY1R","headline":"Weak, indirect support: one abstract-only paper uses PP as a Y1 reference; UniProt says Y1 has virtually no affinity for PP.","interaction_type":"conflicting","direction_and_effect":"The one confirmed paper states PP is highly selective for Y4 while NPY has highest affinities for Y1, Y2 and Y5; no PP effect at Y1 is described [PMID:15966750]. UniProt states Y1 has virtually no affinity for PP at physiological concentrations [DB:UniProt].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human peptides and receptors per the curator; the work is chimeric-peptide structure-affinity studies [PMID:15966750]. Mouse pair is projected from human.","localisation_and_range":"PPY is flagged secreted and NPY1R transmembrane [flag].","caveats":"Abstract-only evidence, and it is a selectivity statement rather than a measured PP-Y1 interaction. The paper's PP-segment chimeras show PP is a poor Y1 ligand [PMID:15966750]. Reactome only records a generic reaction that NPY receptors bind NPY-related peptides [DB:Reactome]. Treat as likely a negligible PP-Y1 interaction.","key_references":[{"PMID":"15966750","why":"PP/NPY chimera affinity study; PP selective for Y4"}],"covers":["LR001249","LR004650"]},"LR004651":{"pair":"PPY -> NPY2R","headline":"Weak support: one abstract-only paper uses PP as a Y2 reference; UniProt says Y2 binds PP with lower affinity.","interaction_type":"conflicting","direction_and_effect":"The confirmed paper says PP is highly selective for Y4 while NPY has highest affinities at Y1, Y2 and Y5; no PP effect at Y2 is described [PMID:15966750]. UniProt says Y2 can also bind PP with lower affinity [DB:UniProt].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human peptides and receptors per the curator; chimeric-peptide affinity studies [PMID:15966750]. Mouse pair is projected from human.","localisation_and_range":"PPY is flagged secreted and NPY2R transmembrane [flag].","caveats":"Abstract-only and indirect: the sentence is a selectivity statement, not a PP-Y2 measurement [PMID:15966750]. No affinity value reported in our evidence. Reactome only records a generic reaction that NPY receptors bind NPY-related peptides [DB:Reactome].","key_references":[{"PMID":"15966750","why":"PP/NPY chimera affinity study; PP selective for Y4"}],"covers":["LR001250","LR004651"]},"LR005281":{"pair":"PRG4 -> TLR4","headline":"Direct binding of PRG4 to TLR4 by ELISA with inhibitory effect on TLR4 activation; one paper, human recombinant system.","interaction_type":"direct binding","direction_and_effect":"Recombinant and native human PRG4 showed concentration-dependent binding to TLR4 by ELISA, and nhPRG4 inhibited TLR4 activation by its agonist and by OA and RA synovial fluid; the paper classes PRG4 as an antagonist [PMID:26643105]. Depleting PRG4 from synovial fluid did not significantly change TLR4 activation [PMID:26643105].","molecular_requirements":"Not reported in our evidence; binding used immobilised receptor protein, and activity was read in receptor-expressing HEK cells [PMID:26643105].","affinity_potency":[],"species_and_systems":"Human recombinant and native PRG4, TLR-overexpressing HEK cells and patient OA/RA synovial fluid [PMID:26643105]. Mouse pair is projected.","localisation_and_range":"PRG4 is flagged secreted [flag] and described as secreted by synovial fibroblasts and chondrocytes [PMID:26643105].","caveats":"One paper only; no affinity value reported in our evidence. The TLR4 binding is shown, but endogenous PRG4 depletion had no significant effect on TLR4 in synovial fluid, so physiological relevance is weaker than for TLR2 [PMID:26643105].","key_references":[{"PMID":"26643105","why":"PRG4 binds TLR2 and TLR4 and reduces their activation"}],"covers":["LR001944","LR005281"]},"LR006352":{"pair":"PRLH -> NPFFR1","headline":"Weak support: a full-text RF-amide panel reports NPFF1R binding the peptide set at 0.1-10 nM, with no PrRP-specific value in our evidence.","interaction_type":"direct binding","direction_and_effect":"In a binding panel, NPFF1R bound the whole set of RF-amide peptides with affinity constants in the 0.1-10 nM range [PMID:23911743]; the curator marks this as agonist.","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human peptides and receptor, membranes from receptor-expressing cells with [3H]-FFRF-NH2 radioligand [PMID:23911743]. Mouse pair is projected.","localisation_and_range":"PRLH is flagged secreted and NPFFR1 transmembrane [flag].","caveats":"The quoted sentence is a group statement; the PRLH (PrRP) value is not given in our evidence, and the paper says RF-amide peptide selectivity is low [PMID:23911743]. NPFFR1 is not PrRP's canonical receptor in the paper's list [PMID:23911743].","key_references":[{"PMID":"23911743","why":"RF-amide peptide binding profile at five receptors"}],"covers":["LR003131","LR006352"]},"LR001258":{"pair":"PROK1 -> PROKR2","headline":"Well supported agonist-receptor pair: PROK1 binds and activates PROKR2 in transfected cells; evidence from abstracts only.","interaction_type":"direct binding","direction_and_effect":"PROK1 and PROK2 induced nanomolar calcium responses in CHO cells expressing PK-R2 and bound with high affinity [PMID:12054613]. Recombinant prokineticins activated both receptors, with calcium, phosphoinositide and MAPK signalling [PMID:11886876]. GtoPdb lists full agonist [DB:GtoPdb]. PK1 also stimulated Ca2+ responses in PKR2-expressing cells [PMID:15772293].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human protein experiments in CHO and other heterologous systems; bovine adrenal capillary endothelial cells showed MAPK phosphorylation and DNA synthesis [PMID:12054613]. Mouse pair is ortholog-inferred.","localisation_and_range":"Both PROK1 and the receptor are annotated secreted and transmembrane respectively [flag], so paracrine signalling onto membrane receptors.","caveats":"Abstract-only reading for all papers. Selectivity between PKR1 and PKR2 is stated but not quantified [PMID:12054613]. GtoPdb gives pIC50 ranges only [DB:GtoPdb].","key_references":[{"PMID":"12054613","why":"Deorphanisation of PK-R2 by EG-VEGF/prokineticins."},{"PMID":"11886876","why":"Cloning and activation of both receptors by nanomolar prokineticins."}],"covers":["LR001258","LR004658"]},"LR004660":{"pair":"PROK2 -> PROKR2","headline":"Well supported agonist-receptor pair: PROK2 activates PROKR2; in vitro human data plus rat in vivo behavioural data; abstracts only.","interaction_type":"direct binding","direction_and_effect":"PK2 is a cognate ligand of PK-R2 (I5E), binding with high affinity and inducing calcium flux in CHO cells [PMID:12054613]. In rats, intracerebroventricular PK2 inhibited nocturnal locomotor activity, and PK2 positively fed back on its own transcription through PKR2 [PMID:12024206]. GtoPdb lists full agonist [DB:GtoPdb].","molecular_requirements":"Not reported in our evidence. PK2beta is about 10-fold less potent than PK1 or PK2 at PKR2 [PMID:15772293].","affinity_potency":[{"value":"pIC50 6.0","assay":"intracellular Ca2+ response benchmark","system":"human PK2 in PKR2-expressing cells","cite":"PMID:15772293"}],"species_and_systems":"Human proteins in CHO cells [PMID:12054613][PMID:15772293]; rat in vivo experiments for the behavioural paper [PMID:12024206]. Mouse pair is ortholog-inferred.","localisation_and_range":"Both PROK2 and the receptor are annotated secreted and transmembrane respectively [flag], so paracrine signalling onto membrane receptors.","caveats":"All abstract-only. The rat paper takes the PK2/PKR2 pairing as established and uses expression plus ICV PK2 without a receptor-selective antagonist or knockout, so it is weak for the pair itself [PMID:12024206]. GtoPdb pIC50 values for the pair are ranges without stated assay [DB:GtoPdb].","key_references":[{"PMID":"12054613","why":"Deorphanisation of PK-R2 by PK2."},{"PMID":"12024206","why":"Rat in vivo PK2 effect with PKR2 expression in SCN."},{"PMID":"15772293","why":"PK2 Ca2+ potency at PKR2, pIC50 6.0."}],"covers":["LR001260","LR004660"]},"LR006361":{"pair":"PRTN3 -> CD177","headline":"PRTN3 (PR3) is displayed on neutrophils via CD177 per database records and a mouse paper that treats this as background.","interaction_type":"database-asserted only","direction_and_effect":"CD177 acts as a receptor for membrane-bound PR3 in a neutrophil subset, which the paper cites from earlier work rather than testing [PMID:30236159]. UniProt says CD177 receptors display mature PRTN3 on the neutrophil surface [DB:UniProt]; Reactome lists a PRTN3:CD177 plasma membrane complex [DB:Reactome R-HSA-5610107].","molecular_requirements":"CD177 binds the mature form of PRTN3 [DB:UniProt].","affinity_potency":[],"species_and_systems":"The curated paper used mouse neutrophils; databases are human [PMID:30236159][DB:UniProt]. A PDB structure 9IGO contains a chain of each partner [DB:PDB 9IGO].","localisation_and_range":"CD177 is flagged secreted and transmembrane [flag]; UniProt describes membrane display of PRTN3 on neutrophils [DB:UniProt]; the dossier does not give soluble versus membrane PR3 binding detail.","caveats":"The paper does not test PR3-CD177 binding; its own results concern PECAM-1 acting through CD177 [PMID:30236159]. One further abstract was insufficient. Direction (CD177 as presenter rather than signalling receptor) is not established.","key_references":[{"PMID":"30236159","why":"Context: CD177 as mPR3 receptor; PECAM-1/CD177 effect on neutrophils."}],"covers":["LR003140","LR006361"]},"LR001267":{"pair":"PSPN -> GFRA4","headline":"GFRalpha4 is the ligand-binding subunit for persephin; supported by two binding papers and databases.","interaction_type":"direct binding","direction_and_effect":"Persephin binds GFRalpha4, and with RET promotes Ret autophosphorylation and neuronal survival, acting as an agonist [PMID:11116144][PMID:9740802]. Persephin binds efficiently only to GFR alpha-4 [PMID:9740802].","molecular_requirements":"GFRalpha4 is the ligand-binding subunit and RET is also required for signalling [PMID:9740802][PMID:11116144]. UniProt says PSPN acts via its coreceptor GFRA4 [DB:UniProt].","affinity_potency":[],"species_and_systems":"Human proteins in GFRA4-transfected cells with endogenous Ret [PMID:11116144]; mouse persephin binding chicken GFR alpha-4 and mouse sympathetic neurons by microinjection [PMID:9740802].","localisation_and_range":"Ligand flagged secreted [flag]; GFRalpha4 is GPI-linked [PMID:11116144].","caveats":"Both papers read as abstracts, one with full-text excerpts. The 1998 study notes persephin's lower affinity for GFR alpha-4 may reflect testing mouse persephin on chicken receptor [PMID:9740802]. Alone, GFRA4 is insufficient for signalling.","key_references":[{"PMID":"9740802","why":"Persephin binds GFR alpha-4 and needs Ret for survival response."},{"PMID":"11116144","why":"Human GFRalpha4 characterised as PSPN ligand-binding subunit."}],"covers":["LR001267","LR004667"]},"LR003148":{"pair":"PTN -> ITGB3","headline":"PTN directly binds integrin alphavbeta3 in an RGD-independent manner, supported by one paper and database records.","interaction_type":"direct binding","direction_and_effect":"alphavbeta3 directly interacts with PTN, and a beta3 specificity-loop peptide inhibited the interaction and abolished PTN-induced endothelial cell migration [PMID:19141530]. UniProt records ITGAV:ITGB3 interacting with PTN [DB:UniProt].","molecular_requirements":"Binding is RGD-independent and maps to the beta3 specificity loop, residues 177-184 [PMID:19141530]. The partner alphaV chain is part of the receptor [DB:UniProt]; PTN-induced Tyr773 phosphorylation of beta3 needs RPTPbeta/zeta and c-Src [PMID:19141530].","affinity_potency":[],"species_and_systems":"Human endothelial and glioma cells [PMID:19141530]. Mouse pair is ortholog-inferred.","localisation_and_range":"PTN is flagged as secreted [flag], so signalling would be paracrine.","caveats":"Abstract only; no affinity reported. BioGRID lists an affinity capture-Western record [DB:BioGRID]. The effect depends on cell context: PTN decreased migration in alphavbeta3-negative glioma cells [PMID:19141530].","key_references":[{"PMID":"19141530","why":"Direct PTN-alphavbeta3 interaction via beta3 loop"}],"covers":["LR003148","LR006369"]},"LR006370":{"pair":"PTN -> KDR","headline":"PTN binds VEGFR2 with a reported Kd of 11.6 nM and inhibits VEGFR2 phosphorylation; the effect looks inhibitory.","interaction_type":"direct binding","direction_and_effect":"PTN binds VEGFR2 and inhibits its Tyr1175 phosphorylation; in cells lacking alphavbeta3, PTN decreased VEGFR2 phosphorylation and migration in a VEGFR2-dependent manner [PMID:32681389]. PTN also decreased the stimulatory effect of VEGFA [PMID:32681389]. The curator labels the effect antagonist.","molecular_requirements":"Molecular dynamics suggest PTN binds the same VEGFR2 region as VEGFA, via PTN's N-terminal domain [PMID:32681389]. Interplay with alphavbeta3 determines the cellular outcome [PMID:32681389].","affinity_potency":[{"value":"Kd 11.6 nM","assay":"binding of PTN to VEGFR2 (experimental approaches not detailed in dossier)","system":"human","cite":"PMID:32681389"}],"species_and_systems":"Human ligand and receptor, endothelial cells [PMID:32681389]. Mouse pair is ortholog-inferred.","localisation_and_range":"PTN is flagged as secreted [flag], so signalling would be paracrine. KDR is flagged as transmembrane [flag].","caveats":"Abstract only. Single paper. The dossier modulatory annotation for other PTN pairs says stimulatory, but here PTN inhibits VEGFR2 signalling while still stimulating migration through alphavbeta3 [PMID:32681389].","key_references":[{"PMID":"32681389","why":"PTN binds VEGFR2 (Kd 11.6 nM) and inhibits its signalling"}],"covers":["LR003149","LR006370"]},"LR001276":{"pair":"PTN -> PTPRB","headline":"No supporting evidence in our dossier beyond a BioGRID co-localisation record; papers were rejected or insufficient.","interaction_type":"database-asserted only","direction_and_effect":"Not reported in our evidence.","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Not reported in our evidence; human and mouse (ortholog-inferred) pair.","localisation_and_range":"PTN is flagged as secreted [flag], so signalling would be paracrine.","caveats":"Judged rows were different_entity (3), abstract_insufficient (2) and review_only (1); BioGRID holds only a co-localisation record [DB:BioGRID], which is not binding evidence.","key_references":[],"covers":["LR001276","LR004676"]},"LR003157":{"pair":"PTPRD -> IL1RAPL1","headline":"Well supported by crystal structure, binding Kd and synaptic assays; splice-dependent trans-synaptic adhesion.","interaction_type":"direct binding","direction_and_effect":"IL1RAPL1 ectodomains induce excitatory presynapse formation by interacting with PTPdelta [PMID:21926414]. PTPdelta induces pre- and postsynaptic differentiation via binding IL1RAPL1 [PMID:25908590].","molecular_requirements":"The PTPdelta Ig1-Ig2 domains retain IL1RAPL1 binding; ratio 1:1; affinity depends on splice inserts meA9 and meB [PMID:25908590].","affinity_potency":[{"value":"Kd 0.15 uM","assay":"binding measurement, PTPdelta isoform with meA9 and meB (highest of all variants)","system":"PTPdelta ECD with IL1RAPL1 ECD","cite":"PMID:25908590"}],"species_and_systems":"Crystallography and neurons [PMID:25908590]; neurons with IL1RAPL1 ectodomains [PMID:21926414]; species not specified for the latter.","localisation_and_range":"Both flagged transmembrane [flag]; trans-synaptic. PDB 5WY8 holds the complex [DB:PDB 5WY8].","caveats":"Abstract-level evidence for curated rows, with full-text excerpts for the Kd; affinity applies to one isoform only.","key_references":[{"PMID":"25908590","why":"crystal structure and Kd of PTPdelta-IL1RAPL1"},{"PMID":"21926414","why":"IL1RAPL1 ectodomain induces presynapse via PTPdelta"}],"covers":["LR003157","LR006378"]},"LR003166":{"pair":"PTPRG -> CNTN5","headline":"PTPRG carbonic-anhydrase-like domain binds CNTN5 Ig repeats 2-3 by crystallography; one primary paper.","interaction_type":"direct binding","direction_and_effect":"PTPRG interacts with CNTN3, 4, 5 and 6, whereas PTPRZ binds only CNTN1 [PMID:20133774]. Effect direction is not reported in our evidence.","molecular_requirements":"Crystal structures show the carbonic anhydrase-like domains of PTPRZ/PTPRG interact directly with the second and third Ig repeats of contactins; the CNTN4 complex used mouse CNTN4 with mouse PTPRG's carbonic-anhydrase-like domain [PMID:20133774].","affinity_potency":[],"species_and_systems":"Curated as human proteins; the co-crystal used mouse CNTN4 and mouse PTPRG domains [PMID:20133774]. Human pair is ortholog-inferred; mouse pair is not.","localisation_and_range":"Not stated in the paper text shown; entity flags: CNTN5 flagged secreted, PTPRG not secreted [flag].","caveats":"Structure paper was read only as abstract; the abstract-level result shows PTPRG binds CNTN3, 4, 5 and 6 and no affinity is reported in our evidence. Curator note says this pair is stored four times (both directions, human and mouse) for one interaction. The CNTN5 evidence is the family-level statement, not a CNTN5-specific structure.","key_references":[{"PMID":"20133774","why":"Crystal structures of PTPRG/PTPRZ with contactins; CNTN specificity"}],"covers":["LR003166","LR006387"]},"LR001951":{"pair":"PVR -> CD226","headline":"PVR (CD155) is a ligand of CD226 (DNAM-1) in Fc-staining and NK killing assays; activating; structure and UniProt support.","interaction_type":"direct binding","direction_and_effect":"PVR-Fc stained DNAM-1-expressing COS-7 cells and DNAM-1-Fc stained PVR-expressing CHO-K cells, and the DNAM-1/PVR interaction enhanced NK-mediated tumour lysis, reversed by masking either partner [PMID:15607800]. CD226 activates NK cytotoxicity on CD155 engagement and is opposed by CD96 [PMID:24658051]. UniProt says CD226 binding of PVR/NECTIN2 promotes NK and CTL cytotoxicity [DB:UniProt].","molecular_requirements":"The ligand is shared: NECTIN2 also binds DNAM-1 [PMID:15607800], and CD96 competes with CD226 for CD155 [PMID:24658051]. DNAM-1 stimulation is associated with beta(2) integrin [PMID:15034010]; that is background in that paper.","affinity_potency":[],"species_and_systems":"Human NK cells and cell lines in the curated rows; antibodies came from mouse immunisation [PMID:15607800]. Both human and mouse pairs are direct.","localisation_and_range":"Both membrane proteins; the NK-to-target contact is a juxtacrine interaction [PMID:15607800].","caveats":"Competing receptors (CD96, TIGIT) share PVR and give opposing outcomes [PMID:24658051], which matters when scoring PVR signalling. All papers were abstract-only. No affinity in our evidence. Structure [DB:PDB 6O3O] and BioGRID/IntAct/Reactome records exist.","key_references":[{"PMID":"15607800","why":"Reciprocal Fc staining identifies PVR as a DNAM-1 ligand"},{"PMID":"24658051","why":"CD96 competes with CD226 for CD155; CD226 activates NK cells"}],"covers":["LR001951","LR005287"]},"LR003175":{"pair":"PVR -> KIR2DL5B","headline":"PVR binds KIR2DL5 directly in two human studies; KIR2DL5 engagement inhibits NK cells, but binding depends on KIR2DL5 allele.","interaction_type":"direct binding","direction_and_effect":"PVR binding to KIR2DL5 on NK cells induced inhibitory synapse formation, and blocking antibodies raised NK cytotoxicity against PVR+ tumours; deleting PVR in tumour cells removed the KIR2DL5 suppression [PMID:36377656]. The effect is inhibitory (KIR2DL5 signals through ITIM/ITSM and SHP-1/SHP-2) [PMID:36377656].","molecular_requirements":"PVR bound KIR2DL5 without competition from DNAM-1, TIGIT or CD96, so it uses a different site; both D0 and D2 domains of KIR2DL5 were needed for binding [PMID:36377656]. PVR did not bind KIR2DL4 or KIR2DL1 [PMID:32822567]. Allele matters: PVR weakly bound 2DL5B*00602 and did not bind 2DL5A*005 or 2DL5B*003 [PMID:36377656].","affinity_potency":[],"species_and_systems":"Human proteins and human cells; binding by recombinant PVR-Ig/Fc on transfected 3T3 cells, ELISA-based screen, SPR (PVR analyte 156-10,000 nM, no Kd given in our excerpts), flow cytometry [PMID:36377656][PMID:32822567].","localisation_and_range":"PVR is flagged as secreted and transmembrane [flag]; the papers used membrane-expressed PVR on target cells for NK inhibition, so contact-dependent signalling is the demonstrated mode [PMID:36377656].","caveats":"The dossier lists KIR2DL5B, but the papers tested KIR2DL5 generally and alleles differ in binding. PMID:36377656 was read as abstract in the dossier row although excerpts are present. No affinity value is reported in our evidence.","key_references":[{"PMID":"36377656","why":"Binding, non-competition with other PVR receptors, NK inhibition and tumour models"},{"PMID":"32822567","why":"Independent binding validation by ELISA, SPR and cell staining; specific among KIRs"}],"covers":["LR003175"]},"LR005290":{"pair":"PVR -> TIGIT","headline":"PVR binds TIGIT, which inhibits human NK cytotoxicity; two papers read as abstracts, plus SPR and structure records.","interaction_type":"direct binding","direction_and_effect":"TIGIT binds PVR and PVRL2 but not PVRL3, and inhibits NK cytotoxicity directly through its ITIM; it protects normal cells from NK killing [PMID:19815499]. TIGIT is described as counterbalancing CD226, with CD96 also sharing PVR (CD155) [PMID:24658051]. Effect on the receptor-bearing cell is inhibitory.","molecular_requirements":"Not reported in our evidence beyond TIGIT's own ITIM being needed for inhibition [PMID:19815499]. PVR is shared with CD226 and CD96, which compete for it [PMID:24658051].","affinity_potency":[],"species_and_systems":"Human NK cells and human proteins [PMID:19815499]. The other paper used mouse knockouts for CD96 but the TIGIT statement is background there [PMID:24658051]. IntAct records include SPR and solid phase assay; a PDB structure with PVR and TIGIT chains exists [DB:IntAct][DB:PDB 3UDW].","localisation_and_range":"TIGIT is flagged as not secreted and PVR as secreted and transmembrane [flag]; NK inhibition shown with PVR on target cells [PMID:19815499].","caveats":"Both papers were judged on abstracts only. PMID:24658051 mainly concerns CD96 vs CD226; TIGIT-PVR is background there. No affinity value in our evidence. The entry's modulatory effect is labelled Stimulatory while the papers describe inhibition of NK cells.","key_references":[{"PMID":"19815499","why":"TIGIT binds PVR and PVRL2 and inhibits NK cells via its ITIM"},{"PMID":"24658051","why":"Places TIGIT with CD226 and CD96 competing for PVR"}],"covers":["LR001954","LR005290"]},"LR007333":{"pair":"RAET1E -> HCST:KLRK1","headline":"ULBP4 (RAET1E) binds recombinant NKG2D and raises human NK killing, consistent with the NKG2D/DAP10 complex; abstract only.","interaction_type":"functional only","direction_and_effect":"ULBP4 transduced into EL4 cells gained binding to recombinant NKG2D and increased cytotoxicity by human NK cells, consistent with ULBPs being NKG2D/DAP10 ligands [PMID:12732206]. Activating.","molecular_requirements":"The paper's abstract names the NKG2D/DAP10 complex generally; DAP10 requirement for ULBP4 itself was not tested in our evidence [PMID:12732206].","affinity_potency":[],"species_and_systems":"EL4 transductants with human NK cells and recombinant NKG2D [PMID:12732206]. IntAct records, mainly by flow cytometry (one SPR), for the NKG2D-ULBP4 pair [DB:IntAct].","localisation_and_range":"ULBP4 has a predicted transmembrane domain, unlike GPI-linked ULBP1-3, and is flagged secreted and transmembrane [PMID:12732206][flag]; skin-predominant.","caveats":"One abstract-only paper; complex row inherited from the KLRK1 chain. Two other papers were review only and one abstract insufficient. No affinity reported.","key_references":[{"PMID":"12732206","why":"ULBP4 binds NKG2D and triggers NK killing"}],"covers":["LR007333"]},"LR001285":{"pair":"RAET1E -> KLRK1","headline":"ULBP4/RAET1E binds NKG2D and activates NK and CD8+ T cells in abstract-level evidence.","interaction_type":"functional only","direction_and_effect":"ULBP4 confers recombinant NKG2D binding and human NK cytotoxicity [PMID:12732206]. Letal engagement with TCR stimulation increased CD8+ proliferation and IL-2 and IFN-gamma secretion [PMID:14508119].","molecular_requirements":"NKG2D acts with DAP10 in the paper's description [PMID:12732206].","affinity_potency":[],"species_and_systems":"Human NK/CD8+ cells; EL4 transductants [PMID:12732206][PMID:14508119]. IntAct FACS and SPR records exist [DB:IntAct].","localisation_and_range":"ULBP4/Letal is a transmembrane NKG2D ligand lacking an alpha-3 domain, skin-predominant [PMID:12732206][PMID:14508119]; flagged secreted [flag].","caveats":"Both papers abstract only. PMID:14508119 calls the ligand Letal without equating it to RAET1E in the abstract. No affinity reported.","key_references":[{"PMID":"12732206","why":"ULBP4 binds NKG2D, increases NK killing"},{"PMID":"14508119","why":"Letal engagement gives T-cell costimulation"}],"covers":["LR001285"]},"LR003184":{"pair":"RELN -> STAB2","headline":"Reelin was reported as a circulating Stabilin-2 ligand in one mouse atherosclerosis study; single-source.","interaction_type":"direct binding","direction_and_effect":"Reelin was among ligands independently confirmed for Stab1/Stab2 by GST-pulldown and endocytosis assays; clearance by the scavenger receptors is linked to reduced monocyte activation [PMID:36325910]. Curated as agonist, but the receptor is a clearance (scavenger) receptor, so effect is uptake rather than signalling per the abstract [PMID:36325910].","molecular_requirements":"Not reported in our evidence beyond Stab2 being a single-chain receptor.","affinity_potency":[],"species_and_systems":"Mouse knockout and antibody studies; ligand-binding assays species not stated in the abstract (curator lists human) [PMID:36325910]. The mouse pair is ortholog-inferred.","localisation_and_range":"Reelin is described as a circulating plasma ligand cleared by liver sinusoidal endothelium [PMID:36325910]; RELN is flagged secreted [flag].","caveats":"Only an abstract was read, and it is truncated; the binding evidence is a pulldown, with no affinity reported. Reelin is one of several ligands confirmed in a screen focused on atherosclerosis [PMID:36325910].","key_references":[{"PMID":"36325910","why":"Stab1/2 targeting in atherosclerosis; Reelin as novel circulating ligand"}],"covers":["LR003184","LR006404"]},"LR001294":{"pair":"REN -> ATP6AP2","headline":"Renin and prorenin bind the (pro)renin receptor ATP6AP2 in the original cloning paper; one primary paper plus database records.","interaction_type":"direct binding","direction_and_effect":"Cells stably expressing the receptor showed renin- and prorenin-specific binding; renin binding raised catalytic efficiency of angiotensinogen conversion fourfold and triggered ERK1/ERK2 activation [PMID:12045255]. BioGRID and Reactome record the complex [DB:BioGRID][DB:Reactome R-HSA-2022360].","molecular_requirements":"A single-transmembrane protein of 350 aa; no co-receptor reported [PMID:12045255].","affinity_potency":[],"species_and_systems":"Human renin receptor cDNA in transfected cells, with confocal localisation in glomerular mesangium and arterial subendothelium [PMID:12045255].","localisation_and_range":"REN is flagged secreted and ATP6AP2 transmembrane [flag]; the receptor sits on the plasma membrane [DB:Reactome R-HSA-2022360].","caveats":"One abstract-level source. The curator notes ATP6AP2 also acts as a V-ATPase accessory subunit, a separate role [PMID:12045255]. One more paper is pending.","key_references":[{"PMID":"12045255","why":"Cloning of the human renin receptor with renin and prorenin binding"}],"covers":["LR001294"]},"LR006406":{"pair":"RGMA -> TFR2","headline":"Evidence is that RGMA can substitute for HJV in the HFE-TfR2 complex; direct RGMA-TFR2 binding is not shown.","interaction_type":"functional only","direction_and_effect":"RGMA, a CNS HJV homolog, can substitute for HJV within the HFE-TfR2-HJV complex and promote hepcidin transcription [PMID:22728873].","molecular_requirements":"The same TfR2 residues (120-139) that matter for HFE/HJV binding are implicated; the complex includes HFE and HJV architecture [PMID:22728873].","affinity_potency":[],"species_and_systems":"Species not stated beyond the curator's human entry; the mouse pair is ortholog-inferred [PMID:22728873].","localisation_and_range":"RGMA is flagged secreted and TFR2 transmembrane [flag]; a membrane complex is described [PMID:22728873].","caveats":"Abstract-only; the sentence concerns functional substitution, not binding to TFR2 itself; single paper.","key_references":[{"PMID":"22728873","why":"RGMA substitutes for HJV in the HFE-TfR2 complex"}],"covers":["LR003186","LR006406"]},"LR012391":{"pair":"RNF43 -> FZD8:LRP6","headline":"RNF43 -> FZD8:LRP6 is supported only by database records; no paper confirmed it.","interaction_type":"database-asserted only","direction_and_effect":"Reactome lists a binding reaction in which ZNRF3 and RNF43 bind the FZD:LRP5/6 receptor complex [DB:Reactome]; BioGRID lists RNF43-FZD8 affinity-capture or PCA records [DB:BioGRID]. Direction and effect are not reported in our evidence.","molecular_requirements":"Receptor is a FZD plus LRP complex; the Reactome record is generic for the FZD:LRP5/6 complex, not specific to this paralog combination, and which subunit RNF43 contacts is not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human; experimental systems not reported in our evidence.","localisation_and_range":"Not reported in our evidence (no secreted or membrane flag given).","caveats":"No paper confirmed this pair (outcomes: different_entity 2, abstract_insufficient 2). Some judged rows were a different entity.","key_references":[],"covers":["LR012391"]},"LR003193":{"pair":"ROBO3 -> NCAM1","headline":"ROBO3 binds NCAM1 heterophilically in one abstract-only paper; no database support.","interaction_type":"direct binding","direction_and_effect":"Robo3 can bind heterophilically to NCAM [PMID:16226035]; no agonist or antagonist effect is reported for this pair.","molecular_requirements":"Robo3A and Robo3B isoforms differ by a 26-residue N-terminal insertion; which isoform binds NCAM is not reported in our evidence [PMID:16226035].","affinity_potency":[],"species_and_systems":"Human Robo3 isoforms; mouse pair projected from human [PMID:16226035].","localisation_and_range":"Robo3 membrane flag; NCAM1 is flagged both secreted and transmembrane [flag].","caveats":"Abstract only, one sentence of evidence, assay not detailed. No database records. NCAM isoform is not specified.","key_references":[{"PMID":"16226035","why":"Robo3 heterophilic binding to Robo1 and NCAM"}],"covers":["LR003193","LR006413"]},"LR006415":{"pair":"ROBO3 -> ROBO3","headline":"ROBO3 homophilic binding from an abstract-only paper; UniProt notes oligomerization linked to midline axon repulsion.","interaction_type":"direct binding","direction_and_effect":"Robo3 can bind homophilically [PMID:16226035]. UniProt says this interaction promotes oligomerization of ROBO3, resulting in repulsion of commissural axons at the midline [DB:UniProt].","molecular_requirements":"Robo3A/Robo3B isoforms differ by a 26-residue N-terminal insertion; which one self-associates is not reported in our evidence [PMID:16226035].","affinity_potency":[],"species_and_systems":"Human Robo3 isoforms [PMID:16226035]; the UniProt statement cites PMID 32198364, which is not among our judged papers [DB:UniProt].","localisation_and_range":"Membrane-bound per flag [flag]; midline repulsion implies contact-dependent action [DB:UniProt].","caveats":"Abstract only for the primary paper. Self-pair, so ligand and receptor roles are indistinguishable.","key_references":[{"PMID":"16226035","why":"Robo3 homophilic binding"}],"covers":["LR003195","LR006415"]},"LR010933":{"pair":"RPSA -> PRND","headline":"Doppel binds laminin receptor precursor (RPSA) by yeast two-hybrid and co-IP; one abstract-only paper.","interaction_type":"direct binding","direction_and_effect":"Dpl binds the full-length 37-kDa laminin receptor precursor protein, shown by yeast two-hybrid and validated by immunoprecipitation in transfected cell lines and in vivo tissues [PMID:15246873]. Effect direction not reported.","molecular_requirements":"Residues 100-220 of LRP interact with Dpl, but deleting the N-terminal domain of full-length LRP abolished the interaction [PMID:15246873].","affinity_potency":[],"species_and_systems":"Yeast two-hybrid, transfected cell lines, in vivo tissues; species not stated in our evidence [PMID:15246873].","localisation_and_range":"PRND carries a non-secreted flag [flag].","caveats":"Abstract only. In the dossier RPSA is the ligand and PRND the receptor, but the paper treats Dpl as the binder of LRP; direction is arbitrary. One abstract-insufficient row and one different-entity row exist.","key_references":[{"PMID":"15246873","why":"Dpl-LRP two-hybrid and co-IP"}],"covers":["LR010933"]},"LR004705":{"pair":"RSPO1 -> LGR5","headline":"RSPO1 is an agonist ligand of LGR5, with binding, functional and structural support.","interaction_type":"direct binding","direction_and_effect":"R-spondins function as ligands of LGR4 and LGR5 and enhance Wnt/beta-catenin signalling [PMID:21693646]. All four R-spondins bind LGR5 and RSPO1 enhances WNT3A signalling [PMID:21727895]. GtoPdb: full agonist [DB:GtoPdb].","molecular_requirements":"LGR5 associates with the Frizzled/Lrp complex; LGR4, -5 or -6 can rescue RSPO1 enhancement [PMID:21727895]. Neither receptor couples to G proteins or beta-arrestin [PMID:21693646].","affinity_potency":[{"value":"pEC50 11.1","assay":"Wnt reporter assay","system":"intestinal crypts / reporter assays","cite":"PMID:21693646"}],"species_and_systems":"Human proteins; intestinal crypts and Wnt reporter assays [PMID:21693646]; mouse gut and HEK293 [PMID:21727895]. Mouse pair is ortholog-inferred.","localisation_and_range":"RSPO1 secreted per flag [flag].","caveats":"Both papers abstract only. RSPO1 modulates Wnt rather than signalling alone [PMID:21693646]. IntAct has SPR and co-IP records and PDB lists structures 4BSR-4BSU [DB:IntAct][DB:PDB 4BSR].","key_references":[{"PMID":"21693646","why":"RSPOs as LGR4/5 ligands, pEC50"},{"PMID":"21727895","why":"R-spondin binding to LGR4/5/6"}],"covers":["LR001308","LR004705"]},"LR001960":{"pair":"RSPO2 -> ZNRF3","headline":"RSPO2 is reported as a direct antagonistic ligand of ZNRF3, independent of LGR4/5/6; evidence is one abstract-only paper plus database records.","interaction_type":"direct binding","direction_and_effect":"RSPO2 acts as an antagonist of ZNRF3 (with RNF43); the authors state RSPO2, without LGR4/5/6, serves as a direct antagonistic ligand to RNF43 and ZNRF3 [PMID:29769720]. Reduced WNT potentiation correlated with RSPO2 mutant allele severity [PMID:29769720].","molecular_requirements":"No LGR4/5/6 needed for this action according to the paper [PMID:29769720]. Co-receptor or subunit requirements for ZNRF3 binding are not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human RSPO2 mutations (tetra-amelia), triple Lgr4/5/6 knockout mice and cells, and rnf43/znrf3 deletion in Xenopus embryos [PMID:29769720]. Curators recorded human ligand and receptor.","localisation_and_range":"RSPO2 is flagged secreted and ZNRF3 is flagged as a receptor [flag]; BioGRID lists ZNRF3-RSPO2 FRET, reconstituted complex and affinity capture-Western records [DB:BioGRID], and PDB lists structures containing both chains [DB:PDB 8XFP].","caveats":"The paper was read as an abstract only, so binding details are not available. The abstract describes impaired binding of mutant RSPO2 to ZNRF3 rather than reporting a measured affinity [PMID:29769720]. Dossier covers human and mouse pairs, both with direct evidence.","key_references":[{"PMID":"29769720","why":"RSPO2 as LGR-independent direct antagonistic ligand of RNF43/ZNRF3"}],"covers":["LR001960","LR005293"]},"LR004714":{"pair":"RSPO3 -> LGR5","headline":"RSPO3 acting through LGR5 is supported by family-level abstracts and databases; LGR5 enhances Wnt signalling as a facultative component.","interaction_type":"direct binding","direction_and_effect":"RSPO3 acts as an agonist at LGR5, potentiating Wnt/beta-catenin signalling [PMID:21693646]; GtoPdb records a full agonist [DB:GtoPdb].","molecular_requirements":"LGR4 and LGR5 enhance Wnt-induced LRP6 phosphorylation [PMID:21693646]. Lgr5 homologues are described as facultative Wnt receptor components associating with the Frizzled/Lrp complex; removing LGR4 abrogates RSPO1-driven enhancement, rescued by LGR4, -5 or -6 [PMID:21727895].","affinity_potency":[{"value":"pEC50 11.0","assay":"Wnt reporter assay, as recorded by curators","system":"intestinal crypts; Wnt reporter assays","cite":"PMID:21693646"}],"species_and_systems":"Curators record human ligand and receptor; the underlying work used mouse gut conditional knockouts and HEK293 cells with RSPO1 [PMID:21727895].","localisation_and_range":"RSPO3 is flagged secreted and LGR5 transmembrane [flag].","caveats":"All three papers were read as abstracts only and name R-spondins generally. PMID 29769720 is an RSPO2 paper reporting impaired LGR4/5/6 binding of mutants. No RSPO3-specific measurement is reported in our evidence beyond database records [DB:UniProt] [DB:Reactome].","key_references":[{"PMID":"21693646","why":"R-spondins as LGR4/5 ligands"},{"PMID":"21727895","why":"Lgr4/5 mediate R-spondin signalling"}],"covers":["LR001317","LR004714"]},"LR004723":{"pair":"RTN4 -> RTN4R","headline":"Nogo-66 binds NgR1 (RTN4R) with high affinity and inhibits axon regeneration; the canonical, well supported Nogo receptor pair.","interaction_type":"direct binding","direction_and_effect":"Nogo-66 binds NgR1 and inhibits axonal extension; receptor expression is sufficient to confer Nogo-66 inhibition on unresponsive neurons [PMID:11201742]. The NgR1 complex with p75 and LINGO-1 represses axon regeneration on binding myelin components [PMID:15694322]; UniProt lists NgR1 as receptor for RTN4, OMG and MAG [DB:UniProt].","molecular_requirements":"The signalling complex comprises NgR1, p75 and LINGO-1; TAJ can replace p75 and activate RhoA [PMID:15694322].","affinity_potency":[],"species_and_systems":"Curators record human ligand and receptor; the 2001 paper used neurons and cells, the 2005 paper mouse neurons [PMID:11201742] [PMID:15694322].","localisation_and_range":"RTN4 is flagged non-secreted and RTN4R transmembrane [flag]; Nogo-66 is the extracellular domain acting on GPI-linked NgR1 [PMID:11201742].","caveats":"Both papers abstract-only; \"high affinity\" is stated without a number. The second paper treats the pair as background.","key_references":[{"PMID":"11201742","why":"Identification of NgR as Nogo-66 receptor"},{"PMID":"15694322","why":"NgR1/p75/LINGO-1 complex; TAJ substitutes for p75"}],"covers":["LR001326","LR004723"]},"LR006424":{"pair":"RTN4RL2 -> ADGRB3","headline":"RTN4RL2 binds BAI3 per a family-wide nanomolar-binding statement in one paper; the human pair is projected.","interaction_type":"direct binding","direction_and_effect":"A single TSR domain of BAIs binds all three RTN4-receptor isoforms with nanomolar affinity [PMID:34758294]. BAI3-expressing cells aggregated specifically with RTN4R-expressing cells [PMID:34758294]. Signalling effect not reported for this pair.","molecular_requirements":"The single TSR2 domain of BAI3 binds RTN4Rs [PMID:34758294]. Co-receptors not reported.","affinity_potency":[],"species_and_systems":"Recombinant ectodomains and HEK 293F cells [PMID:34758294]. The human pair is ortholog-inferred; a mouse pair is not.","localisation_and_range":"Trans-cellular adhesion, so contact-dependent [PMID:34758294]. RTN4RL2 carries a secreted flag [flag].","caveats":"Evidence for this pair is a general statement covering all family members, recorded from the abstract; the Kd values in the paper (1.9 nM, 30.0 nM) are for other pairs (BAI3-RTN4R and BAI1-RTN4RL2) and none is reported for RTN4RL2-BAI3.","key_references":[{"PMID":"34758294","why":"family-wide binding to BAI1 and BAI3"}],"covers":["LR003204","LR006424"]},"LR006433":{"pair":"S100A4 -> CCR5","headline":"S100A4 alone binds the CCR5 extracellular domain but is not sufficient for migration; the Tag7-Mts1 complex is needed.","interaction_type":"direct binding","direction_and_effect":"Only Mts1 (S100A4) binds the CCR5 extracellular domain, but this binding is not enough to induce cell movement; the Tag7-Mts1 complex induces PBMC migration via CCR5 and CXCR3 [PMID:30713770]. UniProt records the same function [DB:UniProt].","molecular_requirements":"The intact S100A4-PGLYRP1 (Tag7) complex is required for chemotaxis; Tag7 alone does not bind CCR5 per curator notes [PMID:30713770].","affinity_potency":[],"species_and_systems":"Human PBMC from healthy donors [PMID:30713770].","localisation_and_range":"S100A4 is flagged secreted and CCR5 transmembrane [flag].","caveats":"Abstract only; affinity not reported. S100A4 alone is not functionally sufficient, so scoring S100A4 alone for CCR5 may overstate signalling.","key_references":[{"PMID":"30713770","why":"S100A4 binds CCR5; complex drives migration"}],"covers":["LR003215","LR006433"]},"LR006442":{"pair":"S100A8 -> CD36","headline":"S100A8/A9 carrying arachidonic acid interacts with CD36 as a fatty acid transporter, not a signalling receptor.","interaction_type":"direct binding","direction_and_effect":"Arachidonate uptake by HUVEC, mediated mostly by FAT/CD36, was inhibited by sulfo-N-succinimidyl oleate and doubled in CD36-transfected COS-7 cells; an in vitro assay confirmed interaction of CD36 with the S100A8/A9-AA complex [PMID:11141076].","molecular_requirements":"The interacting species is the S100A8/A9 heterodimer with arachidonic acid [PMID:11141076].","affinity_potency":[],"species_and_systems":"Human endothelial cells (HUVEC) and COS-7 cells [PMID:11141076].","localisation_and_range":"S100A8 is flagged secreted and CD36 transmembrane [flag].","caveats":"Abstract only. Cargo transport, not receptor signalling. Complex-level evidence inherited by the S100A8 subunit.","key_references":[{"PMID":"11141076","why":"CD36-dependent uptake of S100A8/A9-arachidonate"}],"covers":["LR003225","LR006442"]},"LR003229":{"pair":"S100A8 -> MCAM","headline":"MCAM reported as an S100A8/A9 receptor in melanoma cells; abstract-only, no affinity.","interaction_type":"functional only","direction_and_effect":"MCAM functions as an S100A8/A9 receptor, activating NF-kappaB (more prominently than ALCAM or RAGE) and ROS formation and promoting malignant melanoma progression [PMID:27151304]. Agonist-like.","molecular_requirements":"The ligand tested is the S100A8/A9 complex; S100A8 alone is not separated in our evidence [PMID:27151304].","affinity_potency":[],"species_and_systems":"Human melanoma cells per the abstract; mouse pair is ortholog-inferred.","localisation_and_range":"Ligand secreted by flag [flag]; MCAM is flagged as a receptor but not transmembrane [flag], which looks inconsistent with a membrane receptor.","caveats":"Abstract only; the curator row is labelled direct_binding but the evidence sentence describes receptor function, not binding measurement. No Kd. No database support.","key_references":[{"PMID":"27151304","why":"MCAM as S100A8/A9 receptor driving NF-kB and ROS in melanoma"}],"covers":["LR003229","LR006446"]},"LR006451":{"pair":"S100A9 -> BSG","headline":"EMMPRIN/BSG is described as an S100A9 receptor, but only as background citing prior work.","interaction_type":"functional only","direction_and_effect":"The abstract states that a positive feedback loop between S100A8/A9 and proinflammatory cytokines is mediated by EMMPRIN, an S100A9 receptor; this is cited as the group's earlier finding, not shown here [PMID:27388991]. EMMPRIN and neuroplastin-beta form a heterodimer on keratinocytes, proposed as a functional receptor for the S100A8/A9 heterodimer [PMID:27388991].","molecular_requirements":"Possible heterodimer with neuroplastin-beta; knockdown of both receptors suppressed proliferation and cytokine induction [PMID:27388991].","affinity_potency":[],"species_and_systems":"Cultured normal human keratinocytes [PMID:27388991].","localisation_and_range":"Ligand secreted [flag]; BSG flagged transmembrane [flag].","caveats":"The S100A9-BSG result is background from earlier work, not tested in this paper; abstract only; no binding data or affinity in our evidence.","key_references":[{"PMID":"27388991","why":"Describes EMMPRIN/BSG as S100A9 receptor (background) and its heterodimer"}],"covers":["LR003234","LR006451"]},"LR003238":{"pair":"S100A9 -> CD68","headline":"Recombinant rat S100A9 binds rat CD68 by ELISA and affinity chromatography; human and mouse pairs are ortholog-inferred.","interaction_type":"direct binding","direction_and_effect":"Recombinant rat S100A8 and S100A9 bound r-CD68 but not r-CD14 by ELISA and affinity chromatography, supported by flow cytometry; deglycosylation reduced binding and CD68 siRNA suppressed macrophage activation by r-S100A9 [PMID:27312849]. Agonist-like.","molecular_requirements":"Glycosylation of macrophages was needed for full binding; anti-TLR4 or anti-RAGE antibodies suppressed r-S100A9-stimulated IL-1beta mRNA, so CD68 may act with other receptors [PMID:27312849].","affinity_potency":[],"species_and_systems":"Rat recombinant proteins and rat macrophages; both the human and mouse pairs are projected by orthology, not tested [PMID:27312849].","localisation_and_range":"Ligand flagged as secreted [flag]; secreted, so paracrine/endocrine range is plausible. CD68 colocalized with S100A8/S100A9 in LPS-stimulated macrophages [PMID:27312849].","caveats":"Abstract only; rat-only evidence. Some cytokine regulation was not statistically significant. No affinity.","key_references":[{"PMID":"27312849","why":"Rat S100A9 binds CD68, glycosylation-dependent"}],"covers":["LR003238","LR006454"]},"LR006460":{"pair":"SAA1 -> TLR4","headline":"SAA1 is reported to bind TLR4/MD2 and activate NF-kappaB in hepatocytes; one in vivo-heavy study.","interaction_type":"direct binding","direction_and_effect":"SAA1 directly bound TLR4/MD2, induced TLR4 internalization and activated NF-kappaB, raising SAA1, IL-6 and CCL2 in hepatocytes [PMID:35247611]. Hepatic SAA1 overexpression worsened metabolic disease in mice, and this was markedly alleviated by TLR4 knockout [PMID:35247611].","molecular_requirements":"Binding was with the TLR4/MD2 complex; the methods describe SPR of mouse SAA1 with MD2 or TLR4, but the per-partner result is not shown in our excerpts [PMID:35247611].","affinity_potency":[],"species_and_systems":"Mouse in vivo (AAV8, knockout mice) and mouse recombinant TLR4/MD2 for binding; human NAFLD livers showed raised SAA1 [PMID:35247611]. The human pair is ortholog-inferred.","localisation_and_range":"Secreted ligand, membrane receptor; hepatocyte autocrine/paracrine loop [flag][PMID:35247611].","caveats":"Abstract-level support for binding; the curated species labels (human) differ from the mouse experiments. No affinity reported in our evidence. A second confirmed paper is not shown.","key_references":[{"PMID":"35247611","why":"SAA1 binds TLR4/MD2 and drives hepatic inflammation"}],"covers":["LR003244","LR006460"]},"LR003247":{"pair":"SCGB3A2 -> SDC1","headline":"SCGB3A2 binds syndecan-1 on cells and delivers LPS into the cytosol; moderately supported by one study.","interaction_type":"direct binding","direction_and_effect":"SCGB3A2 chaperones LPS to the cytosol through cell surface syndecan-1, driving caspase-11 pyroptosis [PMID:30526845]. SDC1 knockdown in LLC cells reduced SCGB3A2 binding, and ARH-77 cells expressing mouse SDC1 showed enhanced binding [PMID:30526845].","molecular_requirements":"Heparin inhibited binding, suggesting heparan sulfate chains on SDC1 contribute [PMID:30526845]. Effect is as LPS carrier rather than classical signalling.","affinity_potency":[],"species_and_systems":"Cell binding in mouse LLC, human ARH-77 (with mouse SDC1) and RAW264.7 cells, plus mouse xenografts [PMID:30526845].","localisation_and_range":"SCGB3A2 is flagged secreted; SDC1 is flagged transmembrane (and secreted) [flag].","caveats":"Binding was shown on cells, not with purified proteins, in our excerpts. Species labels in the dossier (human) differ from the mouse cell experiments. A second confirmed paper is not shown.","key_references":[{"PMID":"30526845","why":"SCGB3A2 binds SDC1 and delivers LPS to cytosol"}],"covers":["LR003247","LR006463"]},"LR004732":{"pair":"SCT -> VIPR1","headline":"Secretin acts at VPAC1 only with very low affinity; evidence is analogue binding and selectivity studies, so the pair is weak.","interaction_type":"conflicting","direction_and_effect":"Wild-type human VPAC1 displays very low affinity for secretin; secretin stimulates cAMP but the S/V ratio (EC50 secretin/EC50 VIP) is 300 [PMID:12133828]. GtoPdb records secretin as agonist [DB:GtoPdb].","molecular_requirements":"Selectivity is set by the N-terminal ectodomain: swapping it for the secretin receptor's gives S/V = 1.2, and the Gln135/Thr136 and Gly140/Ser141 pairs restrict secretin access [PMID:12133828].","affinity_potency":[{"value":"IC50 60 nM","assay":"binding of [R16]chicken secretin, a secretin-derived analogue","system":"human VIP1 receptor","cite":"PMID:9437714"},{"value":"IC50 1 nM","assay":"binding of the same analogue","system":"rat VIP1 receptor","cite":"PMID:9437714"}],"species_and_systems":"Human VPAC1-secretin chimeras in COS-7 cells [PMID:12133828]; binding on rat and human receptors with an analogue [PMID:9437714].","localisation_and_range":"Secretin is flagged secreted [flag].","caveats":"The affinity figures are for a modified chicken secretin analogue, not native secretin [PMID:9437714]. The main paper is about how VPAC1 excludes secretin, so this looks like low-affinity cross-reactivity [PMID:12133828]. Both papers were read as abstracts only.","key_references":[{"PMID":"12133828","why":"Shows VPAC1 has very low affinity for secretin and maps the filter"},{"PMID":"9437714","why":"Secretin-derived analogue binding at VIP1 receptors"}],"covers":["LR001336","LR004732"]},"LR003256":{"pair":"SELE -> GLG1","headline":"Direct SPR binding of monomeric E-selectin to ESL-1 (GLG1), very low affinity; one abstract-only paper in mouse material plus database records.","interaction_type":"direct binding","direction_and_effect":"E-selectin binds ESL-1 (GLG1) as a ligand; surface plasmon resonance gave a fast dissociation rate (koff 4.6 s-1) and association rate (kon 7.4e4 M-1 s-1) [PMID:11404363]. Effect on signalling not reported in our evidence.","molecular_requirements":"Monomeric E-selectin was used. ESL-1 from mouse bone marrow cells and recombinant ESL-1 from alpha1,3-fucosyltransferase IV CHO cells both bound, so the fucosyltransferase appears sufficient for functional recombinant ESL-1 [PMID:11404363].","affinity_potency":[{"value":"Kd 62 uM","assay":"surface plasmon resonance, monomeric E-selectin","system":"ESL-1 from mouse bone marrow cells","cite":"PMID:11404363"},{"value":"Kd 66 uM","assay":"surface plasmon resonance","system":"recombinant ESL-1 from alpha1,3-fucosyltransferase IV CHO cells","cite":"PMID:11404363"}],"species_and_systems":"Both partners were mouse in the experiment (native mouse ESL-1, plus CHO-derived recombinant ESL-1); the human pair is ortholog-inferred and the mouse pair is not [PMID:11404363].","localisation_and_range":"Both are annotated as transmembrane [flag], so contact-dependent adhesion is implied; the paper describes tethering and rolling on endothelium [PMID:11404363].","caveats":"Affinity is very low with a fast off-rate, characteristic of rolling adhesion rather than stable binding. Paper read as abstract only. BioGRID lists the same paper as reconstituted complex [DB:BioGRID]; IntAct and Reactome also hold records [DB:IntAct] [DB:Reactome].","key_references":[{"PMID":"11404363","why":"SPR kinetics and Kd of E-selectin binding ESL-1"}],"covers":["LR003256","LR006472"]},"LR001339":{"pair":"SELPLG -> SELP","headline":"PSGL-1 binding to P-selectin is directly demonstrated, with an SPR affinity, structure and several database records.","interaction_type":"direct binding","direction_and_effect":"P-selectin binds PSGL-1; a sulfated, anionic amino-terminal segment of PSGL-1 is necessary for PSGL-1-mediated attachment to P- but not E-selectin [PMID:9128259]. In myeloma, blocking antibodies or PSGL-1 knockdown repressed macrophage-mediated drug resistance, and E-selectin-Fc was described as agonistic on PSGL-1, with Src/Erk1/2/c-myc activation [PMID:22996336].","molecular_requirements":"The first 19 amino acids of PSGL-1 suffice for attachment and rolling on P- and E-selectin, with a sialyl Lewis x glycan at Thr-16 important [PMID:9128259]. Covalent dimerisation of PSGL-1 is not required: monomeric Cys mutants bound P-selectin similarly, and a soluble approximately 25-kDa N-terminal fragment bound immobilized P-selectin [PMID:10713099]. Binding needed Ca2+ and sialidase-sensitive PSGL-1 [PMID:9829984].","affinity_potency":[{"value":"Kd 320 +/- 20 nM","assay":"surface plasmon resonance, soluble monomeric P-selectin to immobilized PSGL-1","system":"human P-selectin, PSGL-1 from human neutrophils","cite":"PMID:9829984"},{"value":"koff 1.4 +/- 0.1 s-1","assay":"surface plasmon resonance","system":"human","cite":"PMID:9829984"}],"species_and_systems":"Binding studies used human proteins and cells [PMID:9829984][PMID:10713099][PMID:9128259]. The myeloma study used human cells and a human myeloma-SCID mouse model [PMID:22996336]. The mouse pair is inferred from human evidence.","localisation_and_range":"Both partners are flagged membrane-bound [flag]; rolling and cell-contact adhesion between cells [PMID:9128259].","caveats":"Three of four shown papers were read as abstracts only. The myeloma paper concerns PSGL-1/selectins together, not P-selectin alone [PMID:22996336]. GtoPdb lists the affinity as pKd [DB:GtoPdb]. Structure and records available [DB:PDB 1G1S] [DB:BioGRID] [DB:IntAct] [DB:Reactome R-HSA-202724].","key_references":[{"PMID":"9829984","why":"SPR affinity and kinetics of P-selectin to PSGL-1"},{"PMID":"9128259","why":"Minimal PSGL-1 N-terminal determinants for P-selectin binding"},{"PMID":"10713099","why":"Monomeric PSGL-1 binds P-selectin"}],"covers":["LR001339","LR004735"]},"LR004741":{"pair":"SEMA3A -> PLXNA4","headline":"Direct binding screen plus functional and genetic data support SEMA3A signalling via PLXNA4, with NRP1 normally involved.","interaction_type":"direct binding","direction_and_effect":"A pairwise ectodomain screen detected direct Sema3A-PlxnA4 binding in the absence of Nrp1 [PMID:26633812]. PLXNA4 is upregulated in cortical interneurons and conveys SEMA3A repulsion [PMID:33503438]. In endothelial/glioblastoma cells Sema3A signalling depended on neuropilin-1, plexin-A1 and plexin-A4 [PMID:25335892]. Interaction class is stimulatory [flag].","molecular_requirements":"Sema3A may bind PlxnA4 directly without Nrp1 [PMID:26633812], yet functional work finds NRP1 required [PMID:25335892]; in mice Neuropilin-1 signalling is mediated principally by Plexin-A4 [PMID:15721238].","affinity_potency":[],"species_and_systems":"Screen with purified ectodomains (labelled human in dossier) [PMID:26633812]; mouse cortex [PMID:33503438]; human-labelled cells [PMID:25335892]; Plexin-A3/A4 double-mutant mouse neurons [PMID:15721238].","localisation_and_range":"SEMA3A is flagged as secreted and not transmembrane [flag], so it acts as a diffusible paracrine cue on membrane receptors. PLXNA4 is flagged transmembrane [flag].","caveats":"Functional papers [PMID:25335892][PMID:15721238] were read as abstracts only and concern the co-receptor complex. No affinity reported in our evidence.","key_references":[{"PMID":"26633812","why":"Direct Sema3A-PlxnA4 binding in a pairwise screen"},{"PMID":"33503438","why":"SEMA3A as PLXNA4 ligand in cortical interneurons"},{"PMID":"15721238","why":"Plexin-A4 mediates Neuropilin-1 Sema3A signalling in vivo"}],"covers":["LR001345","LR004741"]},"LR003265":{"pair":"SEMA3B -> PLXNA4","headline":"Plexin-A4 is required, with plexin-A2 and a neuropilin, for Sema3B signalling (abstract only).","interaction_type":"functional only","direction_and_effect":"Sema3B signalling completely abolished by plexin-A2 silencing also required plexin-A4 and one of the two neuropilins [PMID:25335892]. Effect agonist.","molecular_requirements":"Part of a multi-component requirement: plexin-A2, plexin-A4 and NRP1 or NRP2 [PMID:25335892].","affinity_potency":[],"species_and_systems":"Endothelial and glioblastoma cells (labelled human) [PMID:25335892]; mouse pair is ortholog-inferred [flag].","localisation_and_range":"Sema3B is flagged secreted [flag].","caveats":"Single abstract-only paper; plexin-A4 requirement is stated in one sentence and no direct binding is shown.","key_references":[{"PMID":"25335892","why":"Sema3B signalling requires plexin-A4, plexin-A2 and a neuropilin"}],"covers":["LR003265","LR006481"]},"LR001348":{"pair":"SEMA3C -> NRP1","headline":"Several papers show SEMA3C (Sema E) acting through NRP1 in binding and functional work, mostly in mouse and mostly abstract-read.","interaction_type":"direct binding","direction_and_effect":"Neuropilin-1 binds Sema III, Sema E and Sema IV with high affinity [PMID:9331348]. Sympathetic axon responses to Sema E are mediated by neuropilin-1 and -2 as homo- or hetero-oligomers [PMID:9883722]. Sema3C signalled through Neuropilin-1 and PlexinD1 to inhibit retinal angiogenesis, abrogating VEGF-induced AKT, FAK and p38MAPK activation [PMID:26194913]. Neural crest SEMA3C activates NRP1 in outflow-tract endothelium [PMID:26053665].","molecular_requirements":"PlexinD1 is a co-receptor in the angiogenesis context [PMID:26194913]; NRP1 can act alone or with NRP2 in axons [PMID:9883722].","affinity_potency":[],"species_and_systems":"Dossier labels species as human for binding and angiogenesis papers [PMID:9331348][PMID:26194913], though the retina and sympathetic work involve mouse or neuron systems; mouse genetics for outflow tract [PMID:26053665].","localisation_and_range":"SEMA3C is flagged as secreted and not transmembrane [flag], so it acts as a diffusible paracrine cue on membrane receptors.","caveats":"All four shown papers were read as abstracts only. Effect is context dependent: antagonist of pathological angiogenesis [PMID:26194913] versus agonist in outflow-tract septation [PMID:26053665]. No affinity values reported in our evidence.","key_references":[{"PMID":"9331348","why":"NRP1 binds Sema III, Sema E and Sema IV with high affinity"},{"PMID":"26194913","why":"Sema3C via NRP1/PlexinD1 inhibits retinal angiogenesis"},{"PMID":"26053665","why":"Neural crest SEMA3C activates NRP1 in outflow tract"}],"covers":["LR001348","LR004744"]},"LR004750":{"pair":"SEMA3F -> NRP2","headline":"SEMA3F binds NRP2, with direct binding and functional papers in neurons, T-cell precursors and tumour cells; well supported.","interaction_type":"direct binding","direction_and_effect":"NRP2 is reported as a high-affinity receptor for Sema IV (SEMA3F) but not Sema III, and mediates repulsive guidance [PMID:9331348][PMID:9856463]. SEMA3F-NRP2 signalling inhibits PI3K/Akt and mTOR/rictor assembly [PMID:26156437]. Anti-NRP2 antibody reversed SEMA3F inhibition of CXCL12-driven thymocyte migration [PMID:25068647].","molecular_requirements":"Plexin partners are needed for signalling: SEMA3F's effect on Akt/mTOR required NRP2/Plexin A1 complexes, since knockdown of either removed it [PMID:26156437]. Plexin-A3 is the principal plexin for NRP2-mediated signalling in mouse neurons [PMID:15721238]. NRP2 CUB/coagulation-factor domains confer Sema IV specificity [PMID:9856463].","affinity_potency":[],"species_and_systems":"Binding papers used human-labelled partners [PMID:9331348][PMID:9856463]; signalling work used human endothelial, T-cell and tumour cells plus xenografts [PMID:26156437] and human thymocytes [PMID:25068647]; plexin genetics used mouse neurons [PMID:15721238].","localisation_and_range":"SEMA3F is flagged secreted and NRP2 transmembrane [flag], so paracrine signalling to NRP2-expressing cells is implied. BioGRID lists a reconstituted complex [DB:BioGRID].","caveats":"Three of the key papers were read as abstracts only [PMID:9331348][PMID:9856463][PMID:26156437]. The 1997 paper is mostly about Sema IV naming, so SEMA3F identity rests on curator mapping. No affinity values are reported in our evidence.","key_references":[{"PMID":"9331348","why":"first report of high-affinity NRP2 binding to Sema IV, not Sema III"},{"PMID":"26156437","why":"SEMA3F-NRP2 signalling requires NRP2/Plexin A1; inhibits Akt/mTOR"},{"PMID":"25068647","why":"anti-NRP2 blocks SEMA3F effect on human thymocyte migration"}],"covers":["LR001354","LR004750"]},"LR001357":{"pair":"SEMA3G -> NRP2","headline":"SEMA3G binds NRP2 (not NRP1) in two direct-binding papers; supported in mouse and human-labelled systems.","interaction_type":"direct binding","direction_and_effect":"Sema3G binds Neuropilin-2 but not Neuropilin-1 and repels sympathetic but not dorsal root ganglion axons [PMID:16098142]. Sema3G binds Nrp2, which forms a complex with PlexinD1, and induces cell collapse [PMID:27880905].","molecular_requirements":"NRP2 partners with PlexinD1 for the collapse response [PMID:27880905]. Sema3G-AP bound Nrp2-expressing cells but not PlexinD1-expressing cells in the excerpts [PMID:27880905].","affinity_potency":[],"species_and_systems":"Murine Sema3G in the first paper [PMID:16098142]; the second paper is tagged human but uses mouse embryos and lymphatic endothelial cells [PMID:27880905]. Human pair is ortholog-inferred.","localisation_and_range":"SEMA3G is flagged secreted [flag].","caveats":"The 2005 paper was read as abstract only [PMID:16098142]. No affinity values reported.","key_references":[{"PMID":"16098142","why":"Sema3G binds NRP2 not NRP1; repels sympathetic axons"},{"PMID":"27880905","why":"Sema3G-AP binds Nrp2; NRP2/PlexinD1 complex needed for collapse"}],"covers":["LR001357","LR004753"]},"LR008026":{"pair":"SEMA3G -> NRP2:PLXND1","headline":"Complex-level evidence from one paper: Sema3G binds Nrp2, which forms a receptor complex with PlexinD1.","interaction_type":"direct binding","direction_and_effect":"Sema3G binds Nrp2, which forms a receptor complex with PlexinD1, and induces cell collapse in an Nrp2/PlexinD1-dependent manner [PMID:27880905]. It repels lymphatic endothelial cells away from arteries [PMID:27880905].","molecular_requirements":"Both NRP2 and PLXND1 are needed for collapse [PMID:27880905]. Binding was seen to Nrp2-expressing cells, not to PlexinD1-expressing cells alone [PMID:27880905].","affinity_potency":[],"species_and_systems":"Full text read; mouse embryonic skin and lymphatic endothelial cells, though curator tagged human [PMID:27880905].","localisation_and_range":"SEMA3G is flagged secreted [flag], consistent with an artery-derived paracrine cue [PMID:27880905].","caveats":"Single paper; direct binding is to NRP2 only, so PLXND1 role is as complex partner. No affinity reported.","key_references":[{"PMID":"27880905","why":"Sema3G-Nrp2/PlexinD1 repulsion of lymphatic endothelial cells"}],"covers":["LR008026"]},"LR001366":{"pair":"SEMA6A -> PLXNA2","headline":"Plexin-A2 is supported as a Sema6A receptor by mouse binding and genetic evidence, plus a knockdown-rescue study in a glioblastoma line.","interaction_type":"direct binding","direction_and_effect":"A plexin-A2 semaphorin-domain point mutation abolished Sema6A binding to plexin-A2, and Plxna2-/- mice phenocopied Sema6a mutants in cerebellar granule cell migration; chimeras indicate cell-autonomous action [PMID:18327254]. In U87MG cells the contractile response to Sema6A (and Sema3B) was rescued by re-expressing plexin-A2 after silencing [PMID:25335892].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Mouse in vivo and binding data [PMID:18327254]; U87MG glioblastoma cells (species not stated in our evidence) [PMID:25335892]. Human and mouse pairs are both listed.","localisation_and_range":"Ligand is flagged membrane-bound [flag]; Reactome lists a SEMA6A:PLXNA2,PLXNA4 plasma-membrane complex [DB:Reactome].","caveats":"The first paper was read as an abstract only. The second is knockdown-based and its Sema6A sentence comes from a browser-read quote whose spot-check is pending.","key_references":[{"PMID":"18327254","why":"Plexin-A2 mutation abolishes Sema6A binding; mouse genetics"},{"PMID":"25335892","why":"Plexin-A2 rescue restores Sema6A response (knockdown-based)"}],"covers":["LR001366","LR004762"]},"LR003283":{"pair":"SEMA6C -> NRCAM","headline":"One full-text paper shows by AP-ligand binding that Nr-CAM interacts with Sema6C but not Sema6A.","interaction_type":"direct binding","direction_and_effect":"In an AP-tagged ligand binding assay in HEK293 cells, Nr-CAM interacted with Sema6C but not Sema6A [PMID:22632726]. No effect direction is reported for Sema6C.","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"HEK293 cells; species of the constructs not stated in our evidence. The human pair is ortholog-inferred.","localisation_and_range":"Ligand flagged membrane-bound only by absence of a secreted flag; receptor carries both secreted and transmembrane flags [flag].","caveats":"The paper is about Sema6D; Sema6C binding is a specificity control shown in a supplementary figure (S5A) and there is no functional test for Sema6C [PMID:22632726].","key_references":[{"PMID":"22632726","why":"AP-Sema6C binds Nr-CAM; Sema6A does not"}],"covers":["LR003283"]},"LR010654":{"pair":"SEMA6D -> TYROBP","headline":"Functional support only: DAP12 phosphorylation after Sema6D in cells expressing plexin-A1, Trem-2 and DAP12; DAP12 is a complex component.","interaction_type":"functional only","direction_and_effect":"RAW264.7 cells expressing plexin-A1, Trem-2 and DAP12 showed DAP12 tyrosine phosphorylation when stimulated with recombinant soluble Sema6D [PMID:16715077].","molecular_requirements":"Plexin-A1 and Trem-2 were present with DAP12 in this experiment; DAP12 alone is not shown to bind Sema6D [PMID:16715077].","affinity_potency":[],"species_and_systems":"RAW264.7 cells (species not stated in our evidence); the paper also generated plexin-A1-deficient mice [PMID:16715077].","localisation_and_range":"Soluble recombinant Sema6D was used, though the ligand is flagged membrane-bound [flag]; Reactome lists the plasma-membrane complex [DB:Reactome].","caveats":"Browser-read quote with spot-check pending; two other rows were abstract_insufficient. Class is Receptor-Receptor.","key_references":[{"PMID":"16715077","why":"DAP12 phosphorylation after Sema6D via plexin-A1/Trem-2"}],"covers":["LR010654"]},"LR006505":{"pair":"SERPINE1 -> LRP1B","headline":"Evidence concerns uPA:PAI-1 complexes with uPAR on LRP1B, not free PAI-1; indirect and weak for a direct pair.","interaction_type":"functional only","direction_and_effect":"An LRP1B minireceptor formed immunoprecipitable cell-surface complexes with uPAR in the presence of uPA:PAI-1 complexes, but internalised them far more slowly than the LRP minireceptor, impairing uPAR regeneration and cell migration [PMID:12194987]. This indicates a negative regulatory, not activating, effect.","molecular_requirements":"Requires uPA:PAI-1 complex and uPAR for complex formation [PMID:12194987].","affinity_potency":[],"species_and_systems":"Cell-based work with an LRP1B minireceptor (mLRP1B4); species labelled human [PMID:12194987]. Mouse pair is ortholog-projected.","localisation_and_range":"Cell-surface complex; LRP1B is flagged as a receptor [flag].","caveats":"Free PAI-1 binding is not shown. One paper, abstract only.","key_references":[{"PMID":"12194987","why":"LRP1B with uPAR and uPA:PAI-1 impairs uPAR regeneration"}],"covers":["LR003289","LR006505"]},"LR001375":{"pair":"SERPINE1 -> LRP2","headline":"PAI-1 complexes bind and are endocytosed by LRP2 (gp330); binding measured for uPA:PAI-1, Kd about 0.8 nM.","interaction_type":"direct binding","direction_and_effect":"Affinity-purified gp330 from rabbit renal cortex bound uPA:PAI-1 complexes, and binding was inhibited by RAP [PMID:8344937]. Type II pneumocytes internalised and degraded PAI-1, pro-uPA and uPA:PAI-1, blocked by RAP and partly by anti-gp330 antibodies [PMID:7673355]. Thrombin-PAI-1 endocytosis was blocked by LRP-2 antibodies and RAP [PMID:8626514].","molecular_requirements":"The bound species is the uPA:PAI-1 complex; binding was calcium-dependent [PMID:8344937]. Vitronectin promotes thrombin-PAI-1 clearance [PMID:8626514].","affinity_potency":[{"value":"Kd about 0.8 nM","assay":"binding of uPA.PAI-1 complexes to affinity-purified gp330 at 4 degrees C","system":"rabbit renal cortex","cite":"PMID:8344937"}],"species_and_systems":"Rabbit renal gp330 and tubules [PMID:8344937]; rat type II pneumocytes [PMID:7673355]; dossier labels all as human. Mouse pair is ortholog-projected.","localisation_and_range":"Apical endocytosis in kidney proximal tubules [PMID:8344937]; LRP2 is flagged as a receptor [flag].","caveats":"All three papers abstract only. Partly shared with LRP1 in cell assays, so LRP2-specific contribution is not isolated [PMID:7673355, PMID:8626514].","key_references":[{"PMID":"8344937","why":"Direct binding of uPA:PAI-1 to gp330, Kd about 0.8 nM"},{"PMID":"7673355","why":"gp330-dependent endocytosis of PAI-1 and uPA:PAI-1"},{"PMID":"8626514","why":"LRP2 and LRP1 mediate thrombin-PAI-1 endocytosis"}],"covers":["LR001375","LR004770"]},"LR003292":{"pair":"SFTPA1 -> CKAP4","headline":"SP-A binds CKAP4 (p63) on type II pneumocytes by crosslinking and co-IP; one abstract-level paper plus Reactome.","interaction_type":"direct binding","direction_and_effect":"CKAP4/p63 was identified as an SP-A cell-surface binding protein; anti-p63 antibody blocked SP-A-mediated inhibition of ATP-stimulated phospholipid secretion [PMID:16556726]. The effect is inhibitory on secretion.","molecular_requirements":"not reported in our evidence.","affinity_potency":[],"species_and_systems":"Crosslinking on rat type II cell membranes and intact mouse type II cells with human SP-A as ligand; the human pair is ortholog-inferred, and so is the mouse pair [PMID:16556726].","localisation_and_range":"SFTPA1 is flagged secreted [flag]; CKAP4 is flagged a receptor [flag].","caveats":"One paper, abstract only. The paper refers to SP-A generally, not SFTPA1 specifically. Reactome has a PALM-C100-CKAP4 binding reaction [DB:Reactome].","key_references":[{"PMID":"16556726","why":"Identification of p63/CKAP4 as an SP-A binding protein"}],"covers":["LR003292","LR006508"]},"LR006514":{"pair":"SFTPD -> OSCAR","headline":"OSCAR-Fc binds the SP-D collagenous region and SP-D triggers TNF-alpha release in OSCAR-dependent fashion; one paper with full-text excerpts.","interaction_type":"direct binding","direction_and_effect":"Agonist: monocytes secrete TNF-alpha upon SP-D exposure in an OSCAR-dependent fashion [PMID:25716998].","molecular_requirements":"SP-D collagenous region carries a putative OSCAR-binding motif (SP-D residues 106-114 GPPGPPGVP) [PMID:25716998]. Reactome lists OSCAR with collagen/SP-D [DB:Reactome].","affinity_potency":[],"species_and_systems":"OSCAR-Fc fusion protein with recombinant SP-D and native SP-D from human bronchoalveolar lavage; human CCR2+ inflammatory monocytes; mouse pair is ortholog-inferred [PMID:25716998].","localisation_and_range":"SP-D is flagged secreted [flag].","caveats":"One paper; abstract-based read depth though excerpts are present. No affinity reported in the excerpts.","key_references":[{"PMID":"25716998","why":"OSCAR as receptor for SP-D, TNF-alpha release in monocytes"}],"covers":["LR003299","LR006514"]},"LR001384":{"pair":"SFTPD -> TLR4","headline":"SP-D binds the soluble TLR4 extracellular domain via its CRD; one abstract-level paper plus Reactome.","interaction_type":"direct binding","direction_and_effect":"Natural and recombinant SP-D showed specific binding to soluble TLR4 extracellular domain [PMID:16834340]; functional effect is not reported in our evidence.","molecular_requirements":"Binding is Ca2+-dependent, includes deglycosylated receptor, and is blocked by a CRD-epitope antibody [PMID:16834340]. Reactome lists TLR4:LY96 [DB:Reactome].","affinity_potency":[],"species_and_systems":"Recombinant soluble human TLR4 with human SP-D; mouse pair is ortholog-inferred [PMID:16834340].","localisation_and_range":"SP-D is flagged secreted [flag].","caveats":"One paper, abstract only; no affinity reported.","key_references":[{"PMID":"16834340","why":"SP-D binds sTLR2 and sTLR4 through the CRD"}],"covers":["LR001384","LR004779"]},"LR005308":{"pair":"SIRPA -> CD47","headline":"Well-supported SIRPA-CD47 interaction: one functional adhesion paper plus structures, IntAct, Reactome and UniProt records.","interaction_type":"direct binding","direction_and_effect":"CD47 was identified as the extracellular ligand for human SIRP, and SIRPalpha1/alpha2 extracellular domains supported cell adhesion that an anti-CD47 antibody (CC2C6) inhibited [PMID:10572074]. UniProt describes CD47 as receptor for SIRPA, preventing maturation of immature dendritic cells [DB:UniProt].","molecular_requirements":"SIRPalpha1 and SIRPalpha2 competed for the same cell binding site [PMID:10572074]. Further requirements are not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human recombinant SIRPalpha-Fc fusion proteins and human cell lines [PMID:10572074]. Mouse row is not ortholog-inferred in the dossier interaction list, but no mouse experiment is shown; the human row is ortholog-inferred.","localisation_and_range":"Both are annotated transmembrane [flag], so contact-dependent signalling.","caveats":"The paper was read as abstract only and shows binding indirectly through adhesion and antibody blocking. Structural records (PDB 2JJS, 2JJT, 4CMM, 7YGG) and IntAct ELISA/solid phase assays support direct binding [DB:PDB 2JJS] [DB:IntAct]. Reactome records the SIRPA:CD47 complex [DB:Reactome].","key_references":[{"PMID":"10572074","why":"CD47 identified as SIRP ligand; adhesion blocked by anti-CD47 mAb"}],"covers":["LR001978","LR005308"]},"LR006523":{"pair":"SLAMF8 -> SLAMF8","headline":"Mouse homophilic SLAMF8 binding shown in two papers; human row is ortholog-inferred.","interaction_type":"direct binding","direction_and_effect":"Slamf8-Fc bound Slamf8-transfected 293 cells but not Slamf1 transfectants [PMID:25799045]. A pulldown showed SLAMF8-Fc binds SLAMF8-His, and homophilic interaction promoted FDC-induced monocytic cell differentiation [PMID:35953458].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Mouse Slamf8 on HEK293 transfectants [PMID:25799045]; mouse FDC line FL-Y and recombinant proteins [PMID:35953458]. No human experiment shown.","localisation_and_range":"Not flagged secreted; surface receptor, but Fc fusion forms were used [PMID:25799045].","caveats":"Second paper abstract only. Two further rows were judged a different entity. IntAct holds a solid phase assay record [DB:IntAct]. No affinity.","key_references":[{"PMID":"25799045","why":"Slamf8-Fc binds Slamf8 cells, not Slamf1"},{"PMID":"35953458","why":"SLAMF8-Fc pulldown of SLAMF8-His"}],"covers":["LR003309","LR006523"]},"LR001393":{"pair":"SLIT1 -> ROBO1","headline":"Well-established SLIT1-ROBO1 guidance pair: direct binding of mouse SLIT1, functional and in vivo papers, and database records.","interaction_type":"direct binding","direction_and_effect":"Mouse SLIT1 binds ROBO1 [PMID:10433822]. Endogenous Robos mediate Slit growth-promoting effects on neurite length in Robo1;Robo2 deficient neurons [PMID:21600986]. In the presence of Slit1, both Robo1 and FLRT3 are needed to induce Netrin-1 attraction through PKA-dependent surface DCC upregulation [PMID:24560577].","molecular_requirements":"FLRT3 acts as a Robo1 coreceptor for the Netrin-1 response [PMID:24560577]. Robo1 and Robo2 act together in PMID:21600986, so single-receptor contribution is not separated there.","affinity_potency":[],"species_and_systems":"Mouse SLIT1 protein [PMID:10433822]; mouse cortical neurons [PMID:21600986]; thalamic axons [PMID:24560577], species recorded as human in the dossier but not stated in the abstract.","localisation_and_range":"SLIT1 is flagged secreted and ROBO1 transmembrane [flag]; Reactome and UniProt records agree [DB:Reactome] [DB:UniProt].","caveats":"All three papers were abstract-only. The assay format in PMID:10433822 is not named, and PMID:24560577 centres on FLRT3, with Slit1-Robo1 as background. One further row was abstract-insufficient and one pending. No affinity.","key_references":[{"PMID":"10433822","why":"Mouse SLIT1 binds ROBO1"},{"PMID":"21600986","why":"Robo-dependent Slit growth effects in neurons"},{"PMID":"24560577","why":"FLRT3 as Robo1 coreceptor with Slit1"}],"covers":["LR001393","LR004788"]},"LR005317":{"pair":"SLITRK1 -> PTPRD","headline":"SLITRK1 and PTPdelta show cell aggregation and a co-crystal structure record; family-level evidence.","interaction_type":"direct binding","direction_and_effect":"Slitrk1-, Slitrk2- or Slitrk3-expressing L cells aggregated with PTPdelta-expressing L cells [PMID:23345436]. PTPdelta was needed for inhibitory synapse differentiation by Slitrks [PMID:23345436].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Mouse L cells and rat neurons [PMID:23345436]. Mouse pair ortholog-inferred.","localisation_and_range":"Both partners are transmembrane [flag]; trans-synaptic contact (cell-adhesion assay) [PMID:23345436].","caveats":"The paper's evidence is a family-level aggregation assay (browser-read, spot-check pending), not SLITRK1-specific binding. Database records: BioGRID co-crystal structure and reconstituted complex [DB:BioGRID], PDB 4RCA [DB:PDB 4RCA]. Four review-only rows not shown.","key_references":[{"PMID":"23345436","why":"Slitrk1 L-cell aggregation with PTPdelta"}],"covers":["LR001988","LR005317"]},"LR005326":{"pair":"SLPI -> PLSCR4","headline":"SLPI binds PLSCR4 in a pull-down from transfected cells; evidence is a single paper and less detailed than for PLSCR1.","interaction_type":"direct binding","direction_and_effect":"The paper calls SLPI a ligand of PLSCR1 and PLSCR4 and the curated effect is antagonist; the competition with CD4 was tested on PLSCR1 [PMID:19333378].","molecular_requirements":"GFP-PLSCR4, but not GFP-PLSCR3, was pulled down on GST-SLPI beads [PMID:19333378]. Domain mapping was done for PLSCR1 only; not reported for PLSCR4 in our evidence.","affinity_potency":[],"species_and_systems":"Human proteins expressed as GFP fusions in transfected cells with Jurkat T cells [PMID:19333378]. Mouse pair is projected from human evidence.","localisation_and_range":"SLPI is flagged secreted [flag]. PLSCR4 was found primarily at the plasma membrane of T cells and the authors state SLPI must cross the membrane to bind its endofacial domain [PMID:19333378].","caveats":"Curator read abstract level only. The mapped binding region and the CD4 competition are described for PLSCR1, so the curated notes on PLSCR4 competition go beyond what the excerpts show. Direct (purified) binding is shown for PLSCR1; for PLSCR4 only the pull-down is shown in our excerpts [PMID:19333378].","key_references":[{"PMID":"19333378","why":"Pull-down showing SLPI binds PLSCR1 and PLSCR4 but not PLSCR3"}],"covers":["LR001997","LR005326"]},"LR003319":{"pair":"SLURP2 -> CHRNA3","headline":"SLURP-2 co-purifies the alpha3 nAChR subunit from cortical extracts and inhibits alpha3beta2 currents; one paper.","interaction_type":"direct binding","direction_and_effect":"SLURP-2 inhibits acetylcholine-evoked currents at alpha3beta2 nAChRs, a moderate effect [PMID:27485575]. In keratinocytes, interaction with alpha3beta2 promoted proliferation [PMID:27485575]. The paper also suggests another possible target, alpha3beta4 nAChR, in PC12 cells [PMID:27485575].","molecular_requirements":"Binding was shown for the alpha3 subunit by affinity purification; functional data are for the alpha3beta2 combination. Whether alpha3 alone suffices is not reported in our evidence [PMID:27485575].","affinity_potency":[{"value":"IC50 >3 \u03bcM","assay":"inhibition of ACh-evoked current, alpha3beta2 nAChR","system":"Xenopus oocytes, human receptor","cite":"PMID:27485575"}],"species_and_systems":"Recombinant human SLURP-2 (rSLURP-2); human receptors in Xenopus oocytes and CHO cells, affinity purification from cortical brain extracts, and human oral keratinocyte Het-1A cells [PMID:27485575]. Species of the brain extract is not reported in our evidence.","localisation_and_range":"SLURP2 is flagged as secreted [flag]; the receptor is flagged as a receptor [flag]. Range is not discussed in our evidence.","caveats":"Binding evidence is subunit-level, from tissue extract, so it does not prove a direct alpha3-only interaction. Potency is weak (IC50 above the tested range). Paper is a single source.","key_references":[{"PMID":"27485575","why":"Recombinant SLURP-2 pharmacology and binding to acetylcholine receptors"}],"covers":["LR003319"]},"LR006532":{"pair":"SMOC2 -> LRP6","headline":"One cancer-cell paper reports SMOC-2 co-immunoprecipitating with LRP6 and enhancing WNT signalling; support rests on a co-IP.","interaction_type":"direct binding","direction_and_effect":"By co-culture IP, SMOC-2 directly interacted with the WNT receptors Fzd6 and LRP6, enhanced ligand-receptor interaction with canonical WNT ligands (Wnt3a and Wnt10b) and activated the WNT/beta-catenin pathway in endometrial cancer [PMID:30594556]. This acts as a positive facilitator, not a classical WNT ligand, per the curator note.","molecular_requirements":"Fzd6 and LRP6 were both reported as interactors, so a FZD-LRP complex may be involved; whether LRP6 alone is sufficient is not reported [PMID:30594556].","affinity_potency":[],"species_and_systems":"Species: not stated for the co-culture IP in our excerpts; endometrial cancer cell lines (AN3CA, Ishikawa, HEC-1A, ECC-1) and mouse xenografts were used elsewhere in the paper [PMID:30594556]. The mouse pair is projected from human evidence.","localisation_and_range":"SMOC2 is flagged as secreted and as a receptor [flag]; LRP6 is flagged as a receptor [flag]. Paracrine or autocrine range is not tested in our evidence.","caveats":"Evidence is a co-culture IP in cancer cells; 'directly' is the authors' wording and affinity is not reported. The excerpts available to us are mostly general statements. Only one paper.","key_references":[{"PMID":"30594556","why":"Co-IP of SMOC-2 with Fzd6 and LRP6 and WNT pathway activation in endometrial cancer"}],"covers":["LR003325","LR006532"]},"LR003328":{"pair":"SPARC -> LRP1","headline":"SPARC is one of ten direct LRP1 ligands confirmed in human chondrocyte work; abstract only.","interaction_type":"direct binding","direction_and_effect":"Direct LRP1 binding of SPARC and nine other ligands was confirmed, and affinity for LRP1 correlated with endocytosis rate [PMID:36028175]. Direction: LRP1 mediates endocytosis of the ligand (clearance); curator label is agonist.","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human chondrocytes, direct binding assays with purified LRP1, LRP1-deficient fibroblasts, and a conditional Lrp1 knockout mouse [PMID:36028175]. Mouse pair ortholog-inferred.","localisation_and_range":"SPARC flagged secreted [flag]; LRP1 on the cell surface mediates uptake.","caveats":"Abstract only (the abstract is cut off). Per-ligand affinity for SPARC is not given in our evidence. No database records.","key_references":[{"PMID":"36028175","why":"LRP1 chondrocyte ligandome; direct binding of SPARC confirmed"}],"covers":["LR003328","LR006535"]},"LR009412":{"pair":"SPINT1 -> ST14","headline":"No judged paper supports a ligand-receptor role; only structural and proteomic database records exist for this protease-inhibitor pair.","interaction_type":"database-asserted only","direction_and_effect":"Not reported in our evidence. Structures show matriptase in complex with its inhibitor HAI-1 [DB:PDB 4ISL] [DB:PDB 4ISN].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Crystal structures from X-ray diffraction (PMID 23443661) and a BioGRID Affinity Capture-MS record [DB:BioGRID] [DB:PDB 4ISL]; species of the experiments not stated in our evidence.","localisation_and_range":"Not reported in our evidence; no entity flags shown.","caveats":"One judged paper was different_entity and none confirmed. The records describe an inhibitor-protease complex, not signalling through a receptor.","key_references":[],"covers":["LR009412"]},"LR005335":{"pair":"SPON2 -> ITGA5","headline":"Mindin acts through alpha5-containing integrins: antibody blocking in DCs and an inhibitory effect in HCC; abstract-level only.","interaction_type":"functional only","direction_and_effect":"DC adhesion to mindin matrix was blocked by alpha5 antibodies [PMID:16917498]. SPON2-alpha5beta1 signalling inactivated RhoA, prevented F-actin assembly and inhibited HCC cell migration [PMID:29440144]. Effect: antagonist in HCC.","molecular_requirements":"alpha5 partners with beta1 in the HCC report [PMID:29440144].","affinity_potency":[],"species_and_systems":"Mouse DCs [PMID:16917498]; human HCC context [PMID:29440144].","localisation_and_range":"Mindin is an extracellular matrix protein [flag]; alpha5beta1 on the cell surface.","caveats":"Abstracts only; antibody blocking is indirect. Four papers judged confirmed, two shown. No affinity.","key_references":[{"PMID":"16917498","why":"DC adhesion to mindin blocked by anti-alpha5"},{"PMID":"29440144","why":"SPON2-alpha5beta1 inhibits HCC migration"}],"covers":["LR002007","LR005335"]},"LR004804":{"pair":"SPP1 -> ITGB1","headline":"Osteopontin binds integrin beta1 partners (alpha9beta1, alpha4beta1, alphavbeta1, alpha5beta1); several papers, mostly read as abstracts.","interaction_type":"direct binding","direction_and_effect":"Osteopontin acts as an agonist/adhesion ligand: thrombin-cleaved OPN binds alpha9beta1 and alpha4beta1 and acts as a chemoattractant for haemopoietic stem and progenitor cells [PMID:19417209]. SPP1 is reported to activate alpha5beta1 on nucleus pulposus cells, inhibiting mitophagy [PMID:39721032]. Spp1 is proposed to signal fibroblast-to-smooth-muscle cell via Itga8/Itgb1 [PMID:35414038].","molecular_requirements":"ITGB1 is the shared beta chain; the binding unit is an alpha/beta heterodimer (alpha9, alpha4, alphav, alpha5 or alpha8 named across papers). The N-terminal thrombin-cleaved OPN fragment is the active form for alpha9beta1 [PMID:19417209]; the SVVYGLR sequence is the alpha9beta1 site [PMID:10593924]; thrombin cleavage makes the fragment a much better ligand than full-length OPN for alpha9beta1 and alpha5beta1 [PMID:16005200]. Our curators note the data are stored per subunit [PMID:7592829].","affinity_potency":[{"value":"affinity 18 nM (Mn2+, alphavbeta1)","assay":"cell adhesion to GST-osteopontin","system":"HEK293 cells","cite":"PMID:7592829"}],"species_and_systems":"Human (HEK293, alpha9-transfected SW480/CHO/L-cells, human and murine haemopoietic cells); rat nucleus pulposus cells and a mouse Marfan model for the functional papers [PMID:7592829][PMID:10593924][PMID:19417209][PMID:39721032][PMID:35414038].","localisation_and_range":"SPP1 is flagged secreted [flag]; OPN is described as an extracellular matrix protein acting on cell-surface integrins [PMID:7592829].","caveats":"Four of six papers were read as abstracts only. The integrin partner differs by paper, so beta1 alone does not define the complex. PMID:35414038 is a transcriptome/single-cell inference with limited direct testing. PMID:16005200 does not specify species. BioGRID lists a reconstituted complex [DB:BioGRID]; Reactome lists SPP1 with alpha5beta1, alpha9beta1 and alpha8beta1 [DB:Reactome].","key_references":[{"PMID":"7592829","why":"Adhesion via alphavbeta1 with 18 nM affinity"},{"PMID":"10593924","why":"Maps SVVYGLR recognition site for alpha9beta1"},{"PMID":"19417209","why":"Thrombin-cleaved OPN binds alpha9beta1/alpha4beta1"}],"covers":["LR001409","LR004804"]},"LR007414":{"pair":"SPX -> GALR3:GPR151","headline":"No verified paper evidence; support rests on GtoPdb and UniProt records for GALR3 alone.","interaction_type":"database-asserted only","direction_and_effect":"Database records list spexin as an agonist at GALR3 [DB:GtoPdb]; UniProt describes the GALR3 entry as a receptor for spexin-1 [DB:UniProt].","molecular_requirements":"Records refer to GALR3 only; a role for GPR151 is not reported in our evidence.","affinity_potency":[],"species_and_systems":"Not reported in our evidence beyond the cited database records (cited paper PMID:24517231).","localisation_and_range":"SPX flagged secreted [flag].","caveats":"Two papers were judged abstract-insufficient and none confirmed. The complex is assumed from the GALR3 record.","key_references":[],"covers":["LR007414"]},"LR003337":{"pair":"SVEP1 -> ITGB1","headline":"SVEP1 binds integrin beta1-containing heterodimers (alpha4beta1, alpha9beta1); beta1 evidence is indirect via alpha-chain studies.","interaction_type":"direct binding","direction_and_effect":"SVEP1 binding to integrin alpha9beta1 was confirmed and it also directly bound alpha4beta1 [PMID:35802072]. UniProt states ITGA9:ITGB1 and ITGA4:ITGB1 repress calcium influx and inhibit vasocontraction via SVEP1 [DB:UniProt].","molecular_requirements":"ITGB1 acts as the common beta subunit paired with alpha4 or alpha9; the alpha chain is needed for the complexes described [PMID:35802072][DB:UniProt]. Whether beta1 alone binds is not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human iPSC-derived VSMCs and Svep1+/- mouse myography [PMID:35802072]. Mouse pair is projected from human.","localisation_and_range":"SVEP1 is flagged secreted [flag].","caveats":"One paper, abstract only; evidence concerns heterodimers, not ITGB1 alone, and CCC tools should score this with the alpha partner. Second confirmed row not shown.","key_references":[{"PMID":"35802072","why":"SVEP1 binds alpha9beta1 and alpha4beta1"}],"covers":["LR003337","LR006544"]},"LR004813":{"pair":"Tac2 -> Tacr1","headline":"Mouse Tac2 to Tacr1 rests on database records only and is projected from human; no paper confirms it.","interaction_type":"database-asserted only","direction_and_effect":"GtoPdb lists a full agonist for the TAC2-TACR1 pair [DB:GtoPdb]. No paper in our evidence tests it.","molecular_requirements":"Not reported in our evidence.","affinity_potency":[{"value":"pKi 6.1-6.4","assay":"curated agonist affinity range","system":"GtoPdb record","cite":"DB:GtoPdb"}],"species_and_systems":"Not reported in our evidence; the mouse pair is ortholog-inferred.","localisation_and_range":"Tac2 is flagged secreted and Tacr1 as a receptor [flag].","caveats":"No confirmed paper; one paper was judged abstract_insufficient. The BioGRID, IntAct, PDB and Reactome records shown are labelled TAC1 or substance P with TACR1 [DB:BioGRID] [DB:PDB 2KS9] [DB:Reactome], so they do not directly describe the TAC2 ligand.","key_references":[],"covers":["LR004813"]},"LR006820":{"pair":"TAC3 -> TACR3","headline":"NKB (TAC3) is the natural agonist of NK3 (TACR3), supported by binding and functional papers on the human receptor.","interaction_type":"direct binding","direction_and_effect":"Agonist. NKB binds with Ki = 0.8 nM and induces Ca++ mobilisation in cells expressing human NK-3 [PMID:9190866]; the human NK-3 receptor expressed in Xenopus oocytes mediates conductance changes in response to NKB, and mammalian cells show NKB-stimulated calcium mobilisation and arachidonic acid release [PMID:1312036].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[{"value":"Ki 0.8 nM","assay":"NKB inhibition of [125I][MePhe7]NKB binding","system":"CHO cells expressing hNK-3","cite":"PMID:9190866"},{"value":"pEC50 8.4","assay":"functional agonist potency (as recorded by curators)","system":"human NK-3 receptor expression","cite":"PMID:1312036"},{"value":"Kd 39 nM","assay":"[3H]senktide binding","system":"CHO cells, NK-3 homolog","cite":"PMID:8990205"}],"species_and_systems":"Human receptor in CHO, HEK 293 cells and Xenopus oocytes [PMID:9190866] [PMID:1312036] [PMID:8990205]. A mouse interaction is listed but not described by an experiment here.","localisation_and_range":"TAC3 flagged secreted and TACR3 transmembrane [flag].","caveats":"All papers abstract only. The 39 nM Kd is for senktide, not NKB, and the homolog shows some pharmacological differences from canonical NK-3 [PMID:8990205]. Mouse support is not shown by these papers.","key_references":[{"PMID":"9190866","why":"NKB affinity and Ca2+ mobilisation at human NK-3"},{"PMID":"1312036","why":"Cloning of human NK-3 and NKB response"},{"PMID":"8990205","why":"NK-3 homolog binds [125I-MePhe7]NKB"}],"covers":["LR001420","LR006820"]},"LR006550":{"pair":"TAFA1 -> NRXN1","headline":"FAM19A1 (TAFA1) binds neurexins through a disulfide-linked complex with the cysteine-loop domain; full text read.","interaction_type":"direct binding","direction_and_effect":"Not a classical agonist. FAM19A1-A4 bind the cysteine-loop domain of neurexins and form intermolecular disulfide bonds during transport; FAM19A1 expression decreased neurexin O-glycosylation and heparan sulfate modification in hippocampal cultures [PMID:32706374].","molecular_requirements":"Binding needed the cysteines of the cysteine-loop domain and an adjacent sequence; deleting the cysteine-loop of Nrxn1beta abolished FAM19A binding; all neurexins except neurexin-1gamma interact [PMID:32706374].","affinity_potency":[],"species_and_systems":"Co-IP in HEK293T cells with recombinant FAM19A and Nrxn1beta-ECD; endogenous complexes purified from adult mouse brain; hippocampal cultures [PMID:32706374].","localisation_and_range":"TAFA1 flagged secreted and NRXN1 transmembrane [flag]; the complex forms in the secretory pathway, so the paper suggests regulation of neurexin modification, not canonical paracrine signalling [PMID:32706374].","caveats":"Covalent binding mechanism is unusual and may not behave like standard ligand-receptor signalling. Neurexin-1gamma does not bind [PMID:32706374]. No affinity reported; experiments were largely mouse and recombinant.","key_references":[{"PMID":"32706374","why":"FAM19A/TAFA proteins as neurexin-binding regulators"}],"covers":["LR003343","LR006550"]},"LR003346":{"pair":"TAFA2 -> KIR3DL1","headline":"TAFA2 binds KIR3DL1 by SPR and cell staining in a receptor deorphanisation screen.","interaction_type":"direct binding","direction_and_effect":"Direction and effect are not reported in our evidence; binding only [PMID:36178190].","molecular_requirements":"Flow cytometry showed concentration-dependent TAFA-2 binding to KIR3DL1 cells but not to KIR2DL1 cells [PMID:36178190].","affinity_potency":[],"species_and_systems":"Human TAFA2 over KIR3DL1-ECD by SPR, and tetramer staining of NKL and K562 cells expressing KIR3DL1 [PMID:36178190]. The SPR constants are not in the excerpts.","localisation_and_range":"TAFA2 flagged secreted; KIR3DL1 flagged transmembrane [flag].","caveats":"Single study; no affinity value in our excerpts. No functional effect shown.","key_references":[{"PMID":"36178190","why":"CRISPRa screen finds TAFA2-KIR3DL1 by SPR and staining"}],"covers":["LR003346"]},"LR003355":{"pair":"TAFA5 -> S1PR2","headline":"FAM19A5 is proposed to act through S1PR2 to limit neointima formation; evidence is a single abstract.","interaction_type":"functional only","direction_and_effect":"FAM19A5 overexpression markedly inhibited vascular smooth muscle cell proliferation and migration and neointima formation after injury, and the title says it acts through S1PR2 [PMID:29453251]. The abstract lists radioligand binding, receptor internalization and calcium mobilization assays to identify the receptor, but its results for them are not in our excerpt [PMID:29453251]. UniProt calls S1PR2 the receptor for FAM19A5 [DB:UniProt].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Rat carotid balloon injury and mouse femoral wire injury in vivo; cultured vascular smooth muscle cells [PMID:29453251].","localisation_and_range":"FAM19A5 is described as a secreted adipokine, with a 43-amino-acid signal peptide [PMID:29453251]; S1PR2 annotated transmembrane receptor [flag].","caveats":"Abstract only, and the visible text is truncated before the receptor results. The UniProt record rests on the same paper [DB:UniProt].","key_references":[{"PMID":"29453251","why":"FAM19A5 inhibits neointima formation via S1PR2"}],"covers":["LR003355","LR006558"]},"LR003364":{"pair":"TFF1 -> FCRL4","headline":"TFF1 bound FCRL4 in a high-throughput protein microarray screen, with an IntAct SPR record; no function reported.","interaction_type":"direct binding","direction_and_effect":"TFF1 bound five orphan Ig receptors including FCRL4 in the screen; effect and direction are not reported in our evidence [PMID:21982860].","molecular_requirements":"not reported in our evidence.","affinity_potency":[],"species_and_systems":"Secreted protein microarray screen of 89 Ig-type receptors against 686 genes; species not stated in the evidence sentence [PMID:21982860]. IntAct lists a direct interaction by surface plasmon resonance [DB:IntAct].","localisation_and_range":"TFF1 is annotated secreted [flag]; FCRL4 is annotated as a receptor [flag].","caveats":"Discovery-screen evidence with possible low-affinity binding; the paper reports a 70% true-positive to false-positive hit ratio for its platform [PMID:21982860]. Quote from a browser read is marked unverifiable (spot-check pending). No functional validation in our evidence.","key_references":[{"PMID":"21982860","why":"Microarray screen: TFF1 binds FCRL4"}],"covers":["LR003364"]},"LR005344":{"pair":"TFF3 -> ACKR3","headline":"Functional and modelling evidence only that CXCR7 (ACKR3) contributes to TFF3-induced migration; no binding data.","interaction_type":"functional only","direction_and_effect":"TFF3 stimulated cell migration in a conjunctival epithelial cell line, completely suppressed by blocking CXCR4 and/or CXCR7 [PMID:26780310]. The effect is agonist-like for migration; proliferation was unaffected by blocking either receptor, and ERK1/2 activation was independent of CXCR7 [PMID:26780310].","molecular_requirements":"X-ray structure-based modelling predicted CXCR4 and CXCR7 dimers as possible binding partners [PMID:26780310]. Whether CXCR7 acts alone is not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human ocular surface tissues and a conjunctival epithelial cell line; mouse pair is ortholog-inferred [PMID:26780310].","localisation_and_range":"TFF3 is annotated secreted [flag].","caveats":"Abstract only. Blocking was of CXCR4 and/or CXCR7 together, so the CXCR7 contribution is not separated. Binding is computational prediction only.","key_references":[{"PMID":"26780310","why":"TFF3 migration blocked by CXCR4/CXCR7 inhibition"}],"covers":["LR002016","LR005344"]},"LR004831":{"pair":"TGFA -> ERBB2","headline":"Co-IP of TGF-alpha precursor splice forms with ERBB2 in CHO cells; an intracellular, isoform-specific interaction, not classic extracellular signalling.","interaction_type":"conflicting","direction_and_effect":"Co-immunoprecipitation was seen for the VaI and VaII variants but not the others; precursor-ErbB signalling effect is not reported in our evidence [PMID:10918572].","molecular_requirements":"Interaction is mediated by the precursor's cytoplasmic C-terminal region, shown with chimeras and mutants [PMID:10918572].","affinity_potency":[],"species_and_systems":"CHO cells overexpressing human TGF-alpha precursors (WT, VaI, VaII); mouse pair is ortholog-inferred [PMID:10918572].","localisation_and_range":"Membrane-anchored precursor with intracellular C-terminal interaction [PMID:10918572]; ligand also annotated secreted [flag].","caveats":"The wild-type precursor did not co-immunoprecipitate with ErbB2, so the interaction is splice-variant specific. Co-IP cannot exclude a bridging partner. Abstract only.","key_references":[{"PMID":"10918572","why":"Co-IP of TGFalpha precursor forms with ErbBs"}],"covers":["LR001436","LR004831"]},"LR001438":{"pair":"TGFB1 -> ACVRL1","headline":"TGF-beta1 binds ALK1 (ACVRL1) in endothelial cells, with TbetaR-II; one abstract-only mouse paper.","interaction_type":"direct binding","direction_and_effect":"ALK1 binds TGF-beta1 and TbetaR-II in endothelial cells; ALK1 signalling can inhibit TGF-beta1 transcriptional activation mediated by ALK5 [PMID:10716993].","molecular_requirements":"Binds together with TbetaR-II [PMID:10716993]; other requirements not reported in our evidence.","affinity_potency":[],"species_and_systems":"Mouse experiments (ligand and receptor both mouse), endothelial cells and ALK1-knockout mice [PMID:10716993]. Human pair is ortholog-inferred.","localisation_and_range":"TGFB1 is flagged secreted [flag]. Receptor localisation not reported in our evidence.","caveats":"Single paper read as abstract only. The binding details (assay, affinity) are not reported in our evidence. No database records.","key_references":[{"PMID":"10716993","why":"ALK1 binds TGF-beta1 and TbetaR-II in endothelial cells; ALK1 null mice"}],"covers":["LR001438","LR004833"]},"LR004840":{"pair":"TGFB1 -> TGFBR3","headline":"TGF-beta1 binds the betaglycan (TGFBR3) ectodomain directly by SPR; betaglycan is a co-receptor, not a signalling receptor.","interaction_type":"direct binding","direction_and_effect":"Betaglycan is described as a coreceptor without kinase activity that presents ligand to the signalling receptors (curator note), so TGFB1 -> TGFBR3 is accessory rather than signal-transducing [PMID:19842711]. Annotated as stimulatory [flag].","molecular_requirements":"Two independent ligand-binding regions lie in the betaglycan ectodomain (membrane-distal and membrane-proximal halves); fragments bind TGF-beta but neutralise it poorly, and tethering the domains gives high affinity [PMID:19842711]. The type III ectodomain bound two TGF-beta molecules in SPR [PMID:11382746]. Reactome lists TGFB1,TGFB2:TGFBR3 and a TGFBR3:TGFBR2 complex [DB:Reactome].","affinity_potency":[{"value":"Kd in the low nanomolar range","assay":"SPR, soluble betaglycan, three TGF-beta isoforms","system":"recombinant soluble betaglycan","cite":"PMID:19842711"}],"species_and_systems":"Human ligand and receptor in the 2009 SPR work; the soluble betaglycan was a rat recombinant form made in insect cells [PMID:19842711]. Species in the 2001 BIAcore study were unspecified [PMID:11382746]. Mouse pair is ortholog-projected.","localisation_and_range":"Ligand secreted, betaglycan membrane-anchored [flag]; also a proteolytically released soluble form that can block TGF-beta [PMID:19842711].","caveats":"Both primary papers were abstract-judged by curators; the 2009 affinity is stated only qualitatively for TGF-beta isoforms in general. BioGRID, IntAct, GtoPdb, UniProt also assert the pair [DB:BioGRID].","key_references":[{"PMID":"11382746","why":"BIAcore kinetics of TGF-beta isoforms with type III ectodomain"},{"PMID":"19842711","why":"Two ligand-binding domains of betaglycan, SPR affinities"}],"covers":["LR001445","LR004840"]},"LR001447":{"pair":"TGFB2 -> TGFBR2","headline":"TGF-beta2 binds a TGFBR2 splice variant (TbetaRII-B) and signals through Smad in the absence of betaglycan.","interaction_type":"direct binding","direction_and_effect":"TbetaRII-B restores TGF-beta2 sensitivity in L6 cells lacking TbetaRIII and TbetaRII-B, signalling via the Smad pathway [PMID:11157754]. Annotated stimulatory [flag].","molecular_requirements":"Works without a type III receptor; the evidence concerns the TbetaRII-B isoform specifically [PMID:11157754].","affinity_potency":[],"species_and_systems":"L6 cells in a transfection rescue assay; the species of the cells and constructs is not reported in our evidence. Human pair, mouse ortholog-projected.","localisation_and_range":"Ligand secreted [flag]; BioGRID, GtoPdb, PDB and Reactome also hold records [DB:BioGRID][DB:GtoPdb][DB:PDB 5TX4].","caveats":"Abstract-only; evidence is for the alternatively spliced isoform, not necessarily the main TGFBR2 form.","key_references":[{"PMID":"11157754","why":"TbetaRII-B as a TGF-beta2 binding receptor"}],"covers":["LR001447","LR004842"]},"LR007432":{"pair":"TGFB3 -> ACVR1:TGFBR2","headline":"TGF-beta3 binds TGFBR2 (structure, binding assays), but nothing in our evidence supports ACVR1 within this complex row.","interaction_type":"database-asserted only","direction_and_effect":"TGFB3-TGFBR2 has BioGRID reconstituted complex and co-crystal records [DB:BioGRID], IntAct X-ray [DB:IntAct], GtoPdb agonist [DB:GtoPdb], and a human TGF-beta3 complex structure [DB:PDB 1KTZ].","molecular_requirements":"ACVR1 is not mentioned in these records; its requirement is not reported in our evidence.","affinity_potency":[],"species_and_systems":"No curator-verified paper; one review-only and one different-entity judgement.","localisation_and_range":"Ligand secreted, complex transmembrane [flag].","caveats":"Database support concerns TGFBR2 alone.","key_references":[],"covers":["LR007432"]},"LR003373":{"pair":"TGFB3 -> ITGAV","headline":"Integrin alphaV (as alphaVbeta6) binds latent TGF-beta3 by structure and binding assays; chain-only row.","interaction_type":"direct binding","direction_and_effect":"alphaVbeta6 binds the RGDLXXL/I motif in the TGF-beta1 and TGF-beta3 prodomains with high affinity (crystal structures, mutations, peptide affinity) [PMID:25383667]. alphaVbeta6 binds and activates latent TGFbeta3 [PMID:11821050].","molecular_requirements":"Binding requires the heterodimer; the LXXL/I helix sits in a hydrophobic pocket of the beta6 subunit, so alphaV alone is not shown to suffice [PMID:25383667].","affinity_potency":[],"species_and_systems":"Human proteins in the 2002 work [PMID:11821050]; the structure species is not stated in our evidence. Mouse pair is ortholog-projected.","localisation_and_range":"Ligand secreted, annotated transmembrane [flag]; contact with matrix-bound latent complex.","caveats":"The bound species is the latency-associated peptide (LAP) complex, not mature TGF-beta. Integrin acts to activate TGF-beta release rather than transduce a TGF-beta signal [PMID:11821050]. Abstract-only reading.","key_references":[{"PMID":"25383667","why":"Crystal structure of alphaVbeta6 with the RGDLXXL/I prodomain motif"},{"PMID":"11821050","why":"alphaVbeta6 binds and activates latent TGFbeta3"}],"covers":["LR003373","LR006574"]},"LR001456":{"pair":"TGM2 -> ITGA9","headline":"tTG is a ligand for integrin alpha9beta1 by cell adhesion in two cell systems; functional support from one paper.","interaction_type":"functional only","direction_and_effect":"G-361 cells use alpha(9)beta(1) to adhere to tTG, and SW480 cells transfected with alpha(9)beta(1), but not mock transfectants, adhered to tTG [PMID:10816592].","molecular_requirements":"Functional receptor is alpha9beta1, so ITGB1 is also required [PMID:10816592].","affinity_potency":[],"species_and_systems":"Human G-361 melanoma and SW480 colon cancer cells [PMID:10816592]. The mouse pair is ortholog-inferred.","localisation_and_range":"TGM2 is flagged secreted [flag]; adhesion to tTG as substrate [PMID:10816592].","caveats":"Adhesion assays only, no direct binding or affinity; abstract-level read; one paper.","key_references":[{"PMID":"10816592","why":"tTG, FXIII and pp-vWF as ligands for alpha9beta1"}],"covers":["LR001456","LR004851"]},"LR001465":{"pair":"THBS1 -> ITGA3","headline":"Functional evidence that alpha3beta1 mediates breast carcinoma cell adhesion and chemotaxis to THBS1; no direct binding data.","interaction_type":"functional only","direction_and_effect":"The integrin alpha3beta1 is the major mediator of breast carcinoma cell adhesion and chemotaxis to TSP1 (stimulatory). TSP1 binding activity of alpha3beta1 was not stimulated by CD47-binding peptides from TSP1 [PMID:10196234]. Reactome lists THBS1 binding integrin alpha3beta1, alpha4beta1 [DB:Reactome].","molecular_requirements":"Acts as the alpha3beta1 heterodimer; activation state matters, as the integrin is partially active in MDA-MB-435 but mostly inactive in MDA-MB-231 and MCF-7, which need beta1 activation to spread on TSP1 [PMID:10196234]. IGF-1 and CD98 ligation increase its activity [PMID:10196234].","affinity_potency":[],"species_and_systems":"Breast carcinoma cell lines (species recorded as unspecified in this row) [PMID:10196234]. Mouse pair is ortholog-inferred.","localisation_and_range":"THBS1 is flagged secreted [flag], so it likely acts as a soluble or matrix-associated ligand; range is not reported in our evidence beyond that.","caveats":"One paper, read as abstract only; the readout is cell adhesion and chemotaxis, not physical binding. No affinity reported.","key_references":[{"PMID":"10196234","why":"alpha3beta1 is the major mediator of breast carcinoma adhesion/chemotaxis to TSP1"}],"covers":["LR001465","LR004860"]},"LR003382":{"pair":"THBS1 -> ITGAV","headline":"Supported by a platelet affinity-chromatography study (alphaVbeta3) and a prostate cancer paper; moderate evidence.","interaction_type":"direct binding","direction_and_effect":"A second platelet integrin, with an alpha chain comigrating with alphaV, bound thrombospondin-Sepharose and was eluted with GRGDSP peptide; alphaVbeta3 appears to act as a THBS1 receptor on endothelial and smooth muscle cells [PMID:2478219]. In human prostate cancer cells, THBS1 mediated migration by interacting with ITGAV (agonist-like), with colocalisation of THBS1 and ITGAV on TGFbeta stimulation [PMID:39304722].","molecular_requirements":"The receptor is alphaVbeta3: it shares the beta3 chain with GPIIb-IIIa [PMID:2478219]. RGD-dependent elution suggests an RGD-site interaction [PMID:2478219]. BioGRID and Reactome records concern ITGB3 and alphaIIbbeta3 rather than alphaV [DB:BioGRID][DB:Reactome].","affinity_potency":[],"species_and_systems":"Human platelets (affinity chromatography) [PMID:2478219]; human prostate cancer cell lines and xenografts [PMID:39304722].","localisation_and_range":"THBS1 is flagged secreted [flag], so it likely acts as a soluble or matrix-associated ligand; range is not reported in our evidence beyond that.","caveats":"The 1989 paper was read as abstract only and identifies alphaV by comigration and antibody, not sequence. The cancer paper's evidence is colocalisation and migration. Database examples shown concern ITGB3, not ITGAV. No affinity reported.","key_references":[{"PMID":"2478219","why":"THBS1-Sepharose retains platelet alphaVbeta3"},{"PMID":"39304722","why":"THBS1 interacts with ITGAV in TGFbeta-driven prostate cancer migration (full text)"}],"covers":["LR003382","LR006583"]},"LR001474":{"pair":"THBS2 -> ITGA6","headline":"Alpha6beta1 mediates adhesion and chemotaxis of cells to the THBS2 N-terminal region; abstract only.","interaction_type":"functional only","direction_and_effect":"Alpha6beta1 mediates adhesion of human microvascular endothelial and HT-1080 cells to immobilised recombinant N-terminal regions of TSP-1 and TSP-2, and chemotaxis to them [PMID:12909644].","molecular_requirements":"The N-terminal pentraxin module carries the site; alpha6beta1 heterodimer [PMID:12909644].","affinity_potency":[],"species_and_systems":"Human microvascular endothelial cells and HT-1080 fibrosarcoma cells with recombinant protein [PMID:12909644].","localisation_and_range":"THBS2 flagged secreted; used as immobilised substrate [flag].","caveats":"Abstract only; adhesion assays rather than direct binding, despite the direct_binding label. Mouse pair is ortholog-inferred.","key_references":[{"PMID":"12909644","why":"alpha6beta1 recognises N-terminal modules of TSP-1 and TSP-2"}],"covers":["LR001474","LR004869"]},"LR003391":{"pair":"THY1 -> ADGRE5","headline":"THY1 binds CD97 (ADGRE5) in human cell and protein binding assays, via the CD97 stalk; single paper read as abstract.","interaction_type":"direct binding","direction_and_effect":"CD97-bearing cells adhere to Thy-1 and soluble CD97 binds immobilised Thy-1; both CD97 and Thy-1 blocking mAbs partly block binding [PMID:22210915].","molecular_requirements":"CD97 engages Thy-1 through its stalk: stalk-directed mAb blocked more than EGF-like-domain mAb, and CD97 lacking the stalk and soluble EMR2 failed to bind. Binding was calcium independent [PMID:22210915].","affinity_potency":[],"species_and_systems":"Human: PMNC, CHO transfectants, activated dermal endothelial cells and immobilised protein [PMID:22210915].","localisation_and_range":"Thy-1 on activated endothelial cells binds CD97 on myeloid cells, so contact-dependent (juxtacrine). Note ADGRE5 carries a secreted flag [flag] but the paper describes cell adhesion [PMID:22210915].","caveats":"Abstract only; blocking was partial; no affinity reported [PMID:22210915].","key_references":[{"PMID":"22210915","why":"Thy-1 as CD97 binding partner, stalk-dependent"}],"covers":["LR003391","LR006592"]},"LR006604":{"pair":"TIMP2 -> MMP14","headline":"TIMP-2 binding to MT1-MMP is asserted by multiple databases; no curated paper confirmed it here.","interaction_type":"database-asserted only","direction_and_effect":"BioGRID lists reconstituted-complex, affinity-capture and co-localisation records for TIMP2-MMP14 [DB:BioGRID]; IntAct lists co-IP records [DB:IntAct]; Reactome describes MMP14 (MT1-MMP) binding TIMP2 and a plasma-membrane MMP14:TIMP2 complex [DB:Reactome].","molecular_requirements":"not reported in our evidence.","affinity_potency":[],"species_and_systems":"Species and system are not reported in our evidence.","localisation_and_range":"Reactome places the MMP14:TIMP2 complex at the plasma membrane [DB:Reactome]; MMP14 is flagged non-secreted [flag].","caveats":"No paper passed curation (two abstract_insufficient). Support is database records only, and the dossier gives no signalling or effect direction.","key_references":[],"covers":["LR003403","LR006604"]},"LR003409":{"pair":"TNC -> CNTN2","headline":"Tenascin-C binds TAG-1/axonin-1 (CNTN2) with Kd about 9 nM in vitro; single abstract-read paper.","interaction_type":"direct binding","direction_and_effect":"Specific binding of TAG-1/axonin-1 to tenascin-C was observed; the two proteins also overlapped in embryonic and early postnatal nervous tissue [PMID:8663515]. Directionality of signalling is not reported in our evidence.","molecular_requirements":"not reported in our evidence.","affinity_potency":[{"value":"Kd approximately 9 nM","assay":"binding assay (as described in the abstract)","system":"TAG-1/axonin-1 with tenascin-C","cite":"PMID:8663515"}],"species_and_systems":"Experiment species not stated in the dossier; tissue used was nervous tissue; both human and mouse pairs are ortholog-inferred [PMID:8663515].","localisation_and_range":"CNTN2 is flagged secreted as well as receptor, and TNC secreted [flag]; the paper concerns cell-adhesion and extracellular matrix context [PMID:8663515].","caveats":"Abstract only. Tenascin-C was a secondary finding next to neurocan, phosphacan and N-CAM. Directional signalling effect is the curated label 'agonist' without functional data.","key_references":[{"PMID":"8663515","why":"Kd approximately 9 nM binding of TAG-1 to tenascin-C"}],"covers":["LR003409","LR006610"]},"LR001483":{"pair":"TNC -> EGFR","headline":"Tenascin-C EGF-like repeats act as low-affinity agonist ligands of EGFR in human/rodent-derived cell assays; one abstract-level paper.","interaction_type":"direct binding","direction_and_effect":"Select EGF-like repeats of tenascin-C elicited EGFR autophosphorylation and mitogenesis in an EGFR-dependent manner, and activated ERK MAP kinase [PMID:11470832]. Activity was lost in cells expressing a kinase-inactive EGFR [PMID:11470832].","molecular_requirements":"The active ligand is the EGF-like repeats within tenascin-C, not the whole protein; micromolar concentrations were needed, and bead-tethered presentation (mimicking the hexabrachion) raised avidity [PMID:11470832].","affinity_potency":[{"value":"micromolar concentrations (1\u20134 uM) of repeat proteins","assay":"mitogenesis / EGFR autophosphorylation, not a Kd","system":"NR6 cells","cite":"PMID:11470832"}],"species_and_systems":"Experiments used human ligand and human receptor per the curator record; NR6 cells expressing wild-type or kinase-dead EGFR were used [PMID:11470832]. Mouse pair is projected from human evidence.","localisation_and_range":"Ligand flagged as secreted, non-transmembrane [flag]; presented as extracellular matrix, so acts locally on adjacent cells.","caveats":"Only one paper, assessed with abstract plus excerpts. Activity was weak: EGF-like repeats gave EGFR phosphorylation small compared with EGF or Y13G (about 2 nM and about 0.1 uM Kd for those reference ligands) [PMID:11470832]. No Kd for the repeats is given [PMID:11470832].","key_references":[{"PMID":"11470832","why":"EGF-like repeats of tenascin-C activate EGFR; binding by immunofluorescence and cross-linking"}],"covers":["LR001483","LR004878"]},"LR007072":{"pair":"TNC -> ITGAV:ITGB6","headline":"AlphaVbeta6 binds tenascin-C and contributes to EMT-like change in human MCF-7 breast cancer cells; abstract-level.","interaction_type":"direct binding","direction_and_effect":"TNC induced alphavbeta6 accumulation in focal adhesions; neutralizing antibodies against alphav and beta1 blocked TNC-induced EMT-like change, and combined anti-beta1 plus anti-alphavbeta6 inhibited TGF-beta1/TNC-induced EMT [PMID:23958855].","molecular_requirements":"Alpha-v and beta6 needed; antibody to alphav alone also inhibited, and alphavbeta1 heterodimers increased after TNC [PMID:23958855].","affinity_potency":[],"species_and_systems":"Human MCF-7 breast cancer cells [PMID:23958855].","localisation_and_range":"Ligand flagged as secreted, non-transmembrane [flag]; presented as extracellular matrix, so acts locally on adjacent cells.","caveats":"Abstract read with excerpts; the effect of alphavbeta6 alone was not sufficient to block EMT. UniProt record concerns fibronectin, not TNC [DB:UniProt]. Reactome record concerns alphaVbeta3 [DB:Reactome].","key_references":[{"PMID":"23958855","why":"alphav integrins binding TNC drive EMT-like change"}],"covers":["LR007072"]},"LR006613":{"pair":"TNC -> TLR4","headline":"Tenascin-C binds the TLR4 ectodomain directly and activates TLR4 signalling, shown with human proteins and cells.","interaction_type":"direct binding","direction_and_effect":"Tenascin-C acts as an agonist of TLR4 and drives NF-kB activation and inflammatory cytokine synthesis [PMID:29150600]. Activity was blocked by a neutralizing TLR4 antibody or the antagonist TAK 242 [PMID:29150600]. Three sites in tenascin-C are reported to interact directly and cooperatively with TLR4 [PMID:29150600].","molecular_requirements":"The fibrinogen-like globe (FBG) domain of tenascin-C was sufficient to bind the TLR4 extracellular domain and activate cells; positively charged residues in loop 5 were needed for activation [PMID:29150600]. Co-receptors (MD-2, CD14) are not reported in our evidence.","affinity_potency":[{"value":"KD ~50-60 nM","assay":"solid phase binding of FBG domains (FBG-C, -R, -W) to TLR4 extracellular domain","system":"recombinant proteins","cite":"PMID:29150600"}],"species_and_systems":"Human proteins; THP1 NF-kB reporter cells and primary human macrophages [PMID:29150600]. An IntAct ELISA record supports the pair [DB:IntAct].","localisation_and_range":"Tenascin-C is flagged secreted, a matrix protein induced upon tissue damage [flag][PMID:29150600].","caveats":"The KD range is quoted for FBG domains of tenascin-C, -R and -W together, not tenascin-C alone. Endotoxin contamination was excluded by LPS quantification and polymyxin B treatment [PMID:29150600]. Curators read the abstract only for the row, but excerpts come from the full text.","key_references":[{"PMID":"29150600","why":"Maps tenascin-C binding sites and TLR4 activation"}],"covers":["LR003412","LR006613"]},"LR004903":{"pair":"TNF -> TNFRSF1A","headline":"TNF binds TNFR1 directly, with structural, affinity and signalling-complex evidence from human and mouse systems.","interaction_type":"direct binding","direction_and_effect":"TNF acts as an agonist at TNFR1 [PMID:33495441][PMID:7852363]. After TNF stimulation TNFR1 forms a membrane complex I (TNFR1, TRADD, RIP1, TRAF2) that signals NF-kB activation, and a later cytoplasmic complex II with FADD and caspase-8 can induce apoptosis [PMID:12887920].","molecular_requirements":"TNF is a trimer; in the absence of compound it binds three TNFR1 molecules, while a small-molecule-distorted trimer binds a dimer of TNFR1 [PMID:33495441]. In deletion mapping, domain 3 but not domain 4 of TNFR-1 binds ligand directly [PMID:7852363].","affinity_potency":[{"value":"KD ~290 nM","assay":"binding affinity comparison of TNF-alpha with the mutein TNF-SAM2 (abstract gives 2. 9x1-7 M)","system":"human proteins, Colo205 cells","cite":"PMID:17195449"}],"species_and_systems":"Human TNF and TNFR1 in structural, SPR and mass-spectrometry work [PMID:33495441] and deletion mapping [PMID:7852363]. The complex I/II study used mouse proteins per the curator [PMID:12887920]. A mouse pair was projected from human evidence.","localisation_and_range":"TNF is flagged secreted and transmembrane, so both soluble and membrane forms are possible [flag].","caveats":"The KD comes from an abstract with garbled exponent; the curator reads it as ~290 nM, so check it against the paper [PMID:17195449]. Several papers were read as abstract only. One confirming paper (PMID:19084540) mainly concerns receptor-selective TNF mutants and gives no constant for wild-type TNF [PMID:19084540].","key_references":[{"PMID":"33495441","why":"Crystal structure and affinity of TNF-TNFR1 complex"},{"PMID":"12887920","why":"TNFR1 signalling complexes I and II"},{"PMID":"7852363","why":"Domain mapping of TNF binding to TNFR1"}],"covers":["LR001513","LR004903"]},"LR008620":{"pair":"TNFRSF18 -> TNFSF18","headline":"GITR (TNFRSF18) and its ligand GITRL (TNFSF18); the curated paper identifies them together, and database structures support binding.","interaction_type":"direct binding","direction_and_effect":"The 1999 paper reports a new receptor (AITR, the TNFRSF18 entry) and its ligand AITRL, a previously undescribed TNF family member expressed in endothelial cells; the receptor induces NF-kappaB via TRAF2 [PMID:10037686]. The pair is stored receptor-to-ligand, so TNFSF18 is the signalling ligand.","molecular_requirements":"AITR associates with TRAF1, TRAF2 and TRAF3 [PMID:10037686]. Subunit or stoichiometry requirements are not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human cells and tissues (lymph node, peripheral blood leukocytes, endothelial cells) [PMID:10037686]. IntAct lists surface plasmon resonance records [DB:IntAct]; PDB 7KHD and 7LAW contain both chains [DB:PDB 7KHD]; Reactome has a TNFSF18 binds TNFRSF18 reaction [DB:Reactome].","localisation_and_range":"TNFSF18 is flagged membrane-bound, not secreted [flag].","caveats":"The paper was read only as an abstract and does not describe the binding assay [PMID:10037686]. Direct binding rests mainly on database records.","key_references":[{"PMID":"10037686","why":"Identification of AITR and its ligand"}],"covers":["LR008620"]},"LR001492":{"pair":"TNFSF10 -> TNFRSF10A","headline":"TRAIL activates DR4 (TNFRSF10A) to induce apoptosis; physical binding is documented in databases, curated papers are functional.","interaction_type":"direct binding","direction_and_effect":"The human TRAIL receptor DR4 contains a cytoplasmic death domain that engages the cell-death machinery but not NF-kappaB in the system studied, and does not use FADD [PMID:9082980]. A later paper restates DR4 as a TRAIL receptor and describes DR5 and a decoy receptor [PMID:9325248]. Effect: agonist, pro-apoptotic.","molecular_requirements":"Three TNFRSF10A molecules interact with the TNFSF10 homotrimer [DB:UniProt]. PDB 5CIR contains both chains [DB:PDB 5CIR].","affinity_potency":[],"species_and_systems":"Human proteins and cells in both papers [PMID:9082980]. Database support includes BioGRID affinity capture-western [DB:BioGRID], IntAct surface plasmon resonance and coimmunoprecipitation [DB:IntAct], and Reactome [DB:Reactome]. TRAIL is flagged secreted and transmembrane [flag].","localisation_and_range":"TRAIL is flagged both secreted and transmembrane, so soluble and membrane forms may both act [flag].","caveats":"Both curated papers are abstract-only and functional; DR4 competes with other TRAIL receptors, and UniProt says TRAIL also binds TRAILR2, R3, R4 and possibly OPG [DB:UniProt]. The GtoPdb record has no type or affinity [DB:GtoPdb].","key_references":[{"PMID":"9082980","why":"Identification of DR4 as a TRAIL receptor"},{"PMID":"9325248","why":"Companion paper adding DR5 and a decoy receptor"}],"covers":["LR001492"]},"LR005353":{"pair":"TNFSF12 -> CD163","headline":"CD163 is proposed as a scavenger receptor that takes up TWEAK; one abstract-level human paper.","interaction_type":"functional only","direction_and_effect":"CD163-expressing macrophages bind and internalise TWEAK protein added to the supernatant, consistent with a scavenger role [PMID:19473660]. Higher CD163 in atherosclerotic plaques was associated with lower TWEAK [PMID:19473660]. Effect: clearance, not signalling.","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Cultured human macrophages, human carotid plaques and plasma from human subjects [PMID:19473660]. The mouse pair is projected, with no mouse experiments shown.","localisation_and_range":"TWEAK is flagged secreted and transmembrane [flag]; CD163 has a receptor flag only [flag].","caveats":"CD163 is called a 'potential' scavenger receptor. Binding is shown in cells, and direct binding and affinity are not reported in our evidence. One paper, abstract only, no database records.","key_references":[{"PMID":"19473660","why":"CD163 binds and internalises TWEAK in macrophages"}],"covers":["LR002025","LR005353"]},"LR007441":{"pair":"TNFSF15 -> TNFRSF6B","headline":"TL1A binds soluble decoy DcR3, which antagonises it; evidence from abstracts and databases.","interaction_type":"direct binding","direction_and_effect":"TL1A is a ligand for DR3 and decoy receptor TR6/DcR3, and TR6-Fc antagonised TL1A-induced effects [PMID:11911831]. DcR3 binding to membrane ligands triggers reverse signalling into monocytes [PMID:14697332]. UniProt says binding blocks TNFSF15 activation [DB:UniProt].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Both papers abstract only [PMID:11911831][PMID:14697332].","localisation_and_range":"DcR3 is a soluble protein [PMID:14697332]; TNFSF15 flagged secreted and transmembrane, DcR3 not transmembrane [flag].","caveats":"Decoy sequestration rather than receptor signalling; direction functionally inverted in the reverse-signalling paper. Structures in PDB [DB:PDB 3K51][DB:PDB 3MI8].","key_references":[{"PMID":"11911831","why":"TL1A binds DR3 and DcR3"},{"PMID":"14697332","why":"DcR3 reverse signalling"}],"covers":["LR007441"]},"LR003418":{"pair":"TNR -> PTPRZ1","headline":"Tenascin-R binds the RPTPzeta ectodomain, with crystal structure, Kd values and a PNN functional test; strong support.","interaction_type":"direct binding","direction_and_effect":"TNR associates with the RPTPzeta ectodomain; a structural basis is given, and interface mutation (RPTPzeta-AAA, Y368/Q369/D370) disrupted perineuronal net assembly, so the interaction is needed for net architecture [PMID:37356715]. Signalling effect on RPTPzeta not reported in our evidence.","molecular_requirements":"A loop in the single FN domain of phosphacan inserts into a groove in the C-terminal Fg domain of TNR; the GAG region is not essential for net rescue [PMID:37356715]. Phosphacan is the secreted RPTPzeta splice form.","affinity_potency":[{"value":"KD 112 nM","assay":"binding assay with Ca2+ (5 mM CaCl2)","system":"TNR with RPTPzeta ectodomain, recombinant","cite":"PMID:37356715"},{"value":"KD 712 nM","assay":"binding assay with EDTA (5 mM)","system":"same, divalent cations removed","cite":"PMID:37356715"}],"species_and_systems":"Recombinant proteins and crystals for binding; mouse cortical cultures from Ptprz1 knockout mice for function [PMID:37356715]. Human and mouse pairs are ortholog-inferred.","localisation_and_range":"TNR is a matricellular/extracellular matrix protein [PMID:37356715]; PTPRZ1 is flagged secreted and transmembrane [flag], the ectodomain or phosphacan form acts.","caveats":"Curator verified from abstract; full-text excerpts used. Affinity falls six-fold without Ca2+ [PMID:37356715]. BioGRID and PDB records are consistent [DB:BioGRID, DB:PDB 8FN9].","key_references":[{"PMID":"37356715","why":"Structure, KD and perineuronal net function of TNR-RPTPzeta"}],"covers":["LR003418","LR006619"]},"LR006622":{"pair":"TRIM21 -> CLEC1A","headline":"TRIM21 was identified as an endogenous CLEC-1 ligand by pulldown, co-IP, Biacore and ELISA; CLEC-1 acts as a myeloid checkpoint.","interaction_type":"direct binding","direction_and_effect":"Antagonism of CLEC-1 function is the therapeutic angle: CLEC-1 blockade with chemotherapy prolonged mouse survival, and antihuman CLEC-1 antagonist antibodies enhanced antitumor immunity in CLEC-1 humanized mice [PMID:36399563]. Whether TRIM21 itself activates or inhibits CLEC-1 signalling is not reported in our evidence; CLEC-1 loss increased cross-presentation by cDC1 [PMID:36399563].","molecular_requirements":"Fc-CLEC-1 and His-CLEC-1 both bound TRIM21; direct interaction of recombinant human TRIM21 with human CLEC-1 was validated by Biacore and ELISA [PMID:36399563].","affinity_potency":[],"species_and_systems":"Human recombinant proteins, UV-treated necrotic human cell lines (Raji, Hpb-all), mouse tumour models and CLEC-1 humanized mice [PMID:36399563].","localisation_and_range":"TRIM21 is released by necrotic cells and is flagged secreted [flag]; it is also a cytosolic protein, so its extracellular role is damage-associated [PMID:36399563].","caveats":"TRIM21 is an intracellular protein; the Fc part was controlled for by using His-CLEC-1. A purified-protein affinity value is not given in the excerpts. Mouse ortholog pair is inferred.","key_references":[{"PMID":"36399563","why":"TRIM21 identified and validated as a CLEC-1 ligand; CLEC-1 checkpoint"}],"covers":["LR003421","LR006622"]},"LR003427":{"pair":"TULP1 -> TYRO3","headline":"Tulp1 binds Tyro3 as one of three TAM receptors; one abstract-read paper.","interaction_type":"direct binding","direction_and_effect":"Agonist: Tulp1 interacts with Tyro3, Axl and MerTK of the TAM subfamily [PMID:20978472]. Tyro3-specific activation is not separately described in the abstract. [PMID:20978472]","molecular_requirements":"Five minimal phagocytic determinants (K/R(X)1-2KKK) in the Tulp1 N-terminus are essential for MerTK binding, receptor phosphorylation and phagocytosis; the C-terminal region binds phagocytic prey [PMID:20978472].","affinity_potency":[],"species_and_systems":"Retinal pigment epithelium and macrophage phagocytosis assays; species not stated in the abstract [PMID:20978472]. One of the human/mouse pairs is ortholog-inferred.","localisation_and_range":"Unconventionally secreted, no classical signal peptide [PMID:20978472]; ligand flagged secreted and not transmembrane [flag].","caveats":"Abstract read only; no affinity value. Evidence for each TAM receptor shares the same sentence, so receptor-specific binding strength not reported in our evidence. Detailed motif mapping is for MerTK.","key_references":[{"PMID":"20978472","why":"Tulp1 interacts with Tyro3, Axl and MerTK"}],"covers":["LR003427","LR006628"]},"LR004912":{"pair":"UCN -> CRHR1","headline":"Urocortin 1 binds CRF1 receptor with sub-nanomolar affinity in several radioligand and binding studies; abstract-level evidence, strong and consistent.","interaction_type":"direct binding","direction_and_effect":"Urocortin acts as an agonist: synthetic human urocortin binds CRF receptor types 1, 2 alpha and 2 beta and stimulates cAMP accumulation in transfected cells [PMID:8612563]. GtoPdb records a full agonist [DB:GtoPdb].","molecular_requirements":"No co-receptor or subunit requirement is reported in our evidence. Binding was to the single CRF1 receptor expressed recombinantly [PMID:9423932]. The CRF-binding protein also binds human urocortin and can prevent its ACTH-releasing effect in vitro [PMID:8612563].","affinity_potency":[{"value":"Kd 0.18-0.31 nM","assay":"[3H]-rat urocortin saturation binding, reported across human CRF1, rat CRF2alpha and rat CRF2beta receptors and rat cerebellum","system":"stably transfected cell homogenates","cite":"PMID:9423932"},{"value":"pKd 8.3 to 9.8","assay":"GtoPdb curated affinity range","system":"not specified in dossier","cite":"PMID:11123370"}],"species_and_systems":"Binding experiments used human CRF1 in transfected cells with rat urocortin as the radioligand [PMID:9423932]; human and Xenopus receptors were compared with human and rat urocortin [PMID:11123370]; human urocortin was tested on rat pituitary cells [PMID:8612563]. The dossier covers human and mouse pairs; the mouse pair is ortholog-inferred.","localisation_and_range":"Ligand is flagged secreted and receptor flagged as transmembrane receptor [flag], suggesting a secreted peptide acting on a cell-surface GPCR.","caveats":"All four cited papers were read as abstracts only (one browser-read Results sentence is unverified [PMID:11416224]). Urocortin binds CRF1 with affinity similar to other CRF-family peptides in one study [PMID:9423932], so it is not selective for CRF1.","key_references":[{"PMID":"8612563","why":"Human urocortin binds CRF receptors and stimulates cAMP"},{"PMID":"9423932","why":"[3H]-urocortin Kd on recombinant CRF1"},{"PMID":"11123370","why":"Urocortin high-affinity binding with agonist or antagonist radioligands"}],"covers":["LR001522","LR004912"]},"LR001519":{"pair":"UCN2 -> CRHR2","headline":"Urocortin 2 binds and activates CRF2 receptor selectively; supported by two abstract-level papers plus GtoPdb.","interaction_type":"direct binding","direction_and_effect":"Agonist: Ucn II binds selectively to CRF-R2 with no appreciable activity on CRF-R1 [PMID:11226328]. Stresscopin-related peptide, equated to UCN2 by the curators, was identified as a specific type 2 CRH receptor ligand [PMID:11329063]. GtoPdb records a full agonist [DB:GtoPdb].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[{"value":"pKd 8.5 to 8.6","assay":"GtoPdb curated affinity range","system":"not specified in dossier","cite":"PMID:15450949"}],"species_and_systems":"Mouse peptide and receptor in the Ucn II study [PMID:11226328]; human peptide and receptor in the stresscopin study [PMID:11329063]. Both human and mouse pairs are listed, neither ortholog-inferred.","localisation_and_range":"Ligand flagged secreted, receptor transmembrane [flag]; Ucn II acts centrally after central administration in rodent [PMID:11226328].","caveats":"Both primary papers were read as abstracts only. Linking stresscopin-related peptide to UCN2 rests on the curator note. No Kd or Ki is given in the abstracts.","key_references":[{"PMID":"11226328","why":"Cloning of Ucn II and selective CRF-R2 binding"},{"PMID":"11329063","why":"Stresscopin-related peptide as type 2 CRH receptor ligand"}],"covers":["LR001519","LR004909"]},"LR006631":{"pair":"UNC5A -> FLRT2","headline":"Extracellular binding of UNC5A and FLRT2 shown in a mouse-protein screen; one full-text paper, no affinity.","interaction_type":"direct binding","direction_and_effect":"Binding was seen in an ELISA-based screen with AP/Fc-tagged extracellular domains, with every FLRT1-3 x Unc5A-D pair reported at or near saturation (mean Abs650nm value = 2.14) [PMID:26633812]. Titration with purified protein and CHO.K1 cell aggregation confirmed the family pairs [PMID:26633812]. In this paper Unc5-expressing neurons are repelled by FLRT, so FLRT acts as ligand and Unc5 as receptor, the reverse of the listed direction [PMID:26633812]. ","molecular_requirements":"Extracellular domains of both partners are used; no co-receptor or extra subunit is reported in our evidence.","affinity_potency":[],"species_and_systems":"Mouse proteins in recombinant ELISA and cell-aggregation assays; the human pair is ortholog-inferred and the mouse pair is the direct one [PMID:26633812].","localisation_and_range":"UNC5A is annotated as a transmembrane receptor and FLRT2 as both secreted and transmembrane [flag]; contact-mediated signalling is likely, but this is not tested here.","caveats":"The binding statement is family-wide rather than specific to this pair. Pair-specific functional data are absent. Unc5A stripes gave no attractive or repulsive neuronal response (n=257/257, 100% permissive) [PMID:26633812]. UniProt records the interaction [DB:UniProt].","key_references":[{"PMID":"26633812","why":"Extracellular screen and titration binding of all FLRT x Unc5 pairs, mouse proteins"}],"covers":["LR003430","LR006631"]},"LR001528":{"pair":"VCAM1 -> ITGA9","headline":"VCAM-1 supports alpha9beta1-mediated adhesion in human cells; one confirmed paper, ITGA9 recorded alone.","interaction_type":"functional only","direction_and_effect":"alpha9beta1 mediates stable adhesion to recombinant VCAM-1 and to TNF-alpha-induced VCAM-1 on HUVEC; neutrophil migration on VCAM-1 was partially blocked by anti-alpha9beta1 or anti-alpha4 antibodies and fully blocked by both [PMID:10209034].","molecular_requirements":"The partner is alpha9beta1 heterodimer; ITGA9 alone was not tested [PMID:10209034].","affinity_potency":[],"species_and_systems":"Human: transfected SW480 and CHO cells, HUVEC and neutrophils [PMID:10209034]. Mouse pair is ortholog-inferred.","localisation_and_range":"Adhesion to cell-surface and recombinant VCAM-1; VCAM1 flagged secreted and transmembrane [flag].","caveats":"Functional adhesion, not binding affinity. Single paper. Reactome records the reaction [DB:Reactome].","key_references":[{"PMID":"10209034","why":"alpha9beta1 adhesion to VCAM-1 and neutrophil migration"}],"covers":["LR001528","LR004917"]},"LR004921":{"pair":"VCAM1 -> ITGB7","headline":"alpha4beta7 can bind VCAM-1 given strong activation; five confirmed rows but one paper also recorded as pair absent.","interaction_type":"conflicting","direction_and_effect":"alpha4beta7 binds VCAM-1, but this requires greater integrin activation than binding to MAdCAM-1 [PMID:7687523]. CXCL10 primes alpha4beta7 for VCAM-1 while CCL25 lowers it [PMID:29789438]. Phorbol ester or TCR-CD3 activation caused beta7 integrin binding to VCAM-1 [PMID:12682249].","molecular_requirements":"Receptor is alpha4beta7; the alpha4 blocking antibody HP2/1 abolished adhesion [PMID:29789438].","affinity_potency":[],"species_and_systems":"Lymphocytes and TK1/38C13 cells, species unspecified in the curated row [PMID:7687523]; human lymphocyte lines [PMID:29789438]; activated T cells [PMID:12682249]. Human and mouse rows are not ortholog-inferred.","localisation_and_range":"Cell-surface adhesion; VCAM1 flagged secreted and transmembrane [flag].","caveats":"Same paper PMID 7687523 is both confirmed and a propagated pair_absent row. VCAM-1 binding is conditional on activation or chemokine. Mostly abstract-level; chain-only entry.","key_references":[{"PMID":"29789438","why":"chemokine-dependent alpha4beta7 switch toward VCAM-1"},{"PMID":"7687523","why":"alpha4beta7 binds VCAM-1 only with strong activation"},{"PMID":"12682249","why":"T cell activation induces beta7 binding to VCAM-1"}],"covers":["LR001532","LR004921"]},"LR001537":{"pair":"VEGFA -> FLT1","headline":"VEGFA binds FLT1 directly, supported by structure and mutagenesis; signalling role is complex and the soluble form acts as a trap.","interaction_type":"direct binding","direction_and_effect":"VEGF residues Asp63, Glu64 and Glu67 are associated with FLT-1 binding, separable from the KDR determinant, and FLT-1-deficient mutants still induced normal endothelial proliferation, implicating KDR rather than FLT-1 in mitogenesis [PMID:8621427]. Soluble FLT1 sequesters VEGF-A in mouse cornea, maintaining avascularity (decoy role) [PMID:17051153]. In bovine endothelial cells PGI2 synthesis required a VEGFR-1/VEGFR-2 heterodimer [PMID:15637071].","molecular_requirements":"Flt-1 domains 2 and 3 are necessary and sufficient for near-native VEGF binding; domain 2 alone binds 60-fold less tightly [PMID:9393862]. Prostacyclin response needs FLT1 plus KDR together [PMID:15637071].","affinity_potency":[],"species_and_systems":"Human VEGF with human FLT-1 in the structure and mutagenesis papers [PMID:9393862, PMID:8621427]; bovine aortic endothelial cells [PMID:15637071]; mouse cornea in vivo [PMID:17051153]. Crystal structures 1FLT, 1QTY, 5T89 [DB:PDB 1FLT].","localisation_and_range":"VEGFA is flagged secreted and FLT1 transmembrane [flag]; the soluble FLT1 isoform is secreted per the cornea paper [PMID:17051153].","caveats":"Three of four papers were read as abstracts only. The cornea paper is about the soluble isoform, not the full-length receptor. No affinity values in our evidence. Database support: Reactome, IntAct, BioGRID, GtoPdb [DB:Reactome].","key_references":[{"PMID":"9393862","why":"Crystal structure of VEGF with Flt-1 domain 2"},{"PMID":"8621427","why":"Mutagenesis mapping of FLT-1 and KDR binding determinants"},{"PMID":"17051153","why":"Soluble FLT1 traps VEGF-A in cornea"}],"covers":["LR001537","LR004926"]},"LR004930":{"pair":"VEGFA -> KDR","headline":"VEGFA binds and activates KDR (VEGFR2); well supported by binding, affinity and functional papers.","interaction_type":"direct binding","direction_and_effect":"KDR expressed in CMT-3 cells gives saturable 125I-VEGF binding [PMID:1417831]; mouse Flk-1 binds VEGF and mediates VEGF-dependent Ca2+ efflux [PMID:8356051]. Alanine-scanning shows VEGF Arg82, Lys84 and His86 are critical for KDR binding, and KDR rather than FLT-1 drives endothelial mitogenesis [PMID:8621427]. Stimulatory (agonist) [DB:GtoPdb].","molecular_requirements":"Coreceptors modify binding: neuropilin-1 crosslinks to 125I-VEGF165 with VEGFR2 on HUVECs [PMID:17318185]; SCUBE2 forms a complex with VEGF and VEGFR2 and facilitates binding [PMID:27834687]. PGI2 synthesis in bovine cells needs a VEGFR-1/VEGFR-2 heterodimer [PMID:15637071]. VEGFR2 monomers and dimers bind VEGF differently, with a 45-fold difference in affinity [PMID:31023826].","affinity_potency":[{"value":"KD = 75 pM","assay":"saturable 125I-VEGF binding","system":"KDR-transfected CMT-3 cells","cite":"PMID:1417831"}],"species_and_systems":"Human VEGF with human KDR in most papers; mouse Flk-1 in Xenopus oocytes [PMID:8356051]; bovine aortic endothelial cells [PMID:15637071]. The mouse pair is ortholog-inferred.","localisation_and_range":"VEGFA flagged secreted, KDR transmembrane [flag].","caveats":"Most papers read as abstract only. Several confirmations are indirect (coreceptor or heterodimer studies) rather than pure KDR binding. Affinity depends on the receptor association state [PMID:31023826].","key_references":[{"PMID":"1417831","why":"KDR expression gives high-affinity VEGF binding, KD = 75 pM"},{"PMID":"31023826","why":"Binding affinities of VEGF for VEGFR2 monomer versus dimer"},{"PMID":"8621427","why":"VEGF residues for KDR binding"}],"covers":["LR001541","LR004930"]},"LR003445":{"pair":"VEGFA -> PTPRZ1","headline":"VEGF165 interacts directly with PTPRZ1 (RPTPbeta/zeta) in endothelial and glioma cells by co-IP and proximity ligation, independent of VEGFR2; one paper.","interaction_type":"direct binding","direction_and_effect":"VEGF165 interacts with RPTPbeta/zeta, which mediates VEGF165-induced c-Src-dependent beta3 Tyr773 phosphorylation, cell-surface nucleolin localisation and endothelial migration; RPTPbeta/zeta knockdown abolished these effects [PMID:25644401].","molecular_requirements":"Interaction was seen in a VEGFR-independent manner; VEGFR2 did not associate with RPTPbeta/zeta, and the VEGF-RPTPbeta/zeta signal persisted with bevacizumab present in PLA (legend) [PMID:25644401]. No subunit requirement reported.","affinity_potency":[],"species_and_systems":"Human umbilical vein endothelial cells and U87MG glioma cells, with endogenous VEGF; co-IP/Western, double immunofluorescence and proximity ligation [PMID:25644401]. Mouse pair is ortholog-inferred.","localisation_and_range":"VEGFA flagged secreted; PTPRZ1 flagged both secreted and transmembrane [flag]. The paper describes it as a transmembrane phosphatase [PMID:25644401].","caveats":"Single paper; the evidence is co-IP and in situ proximity, not purified-protein binding with affinity, so directness is inferred from the authors' interpretation. BioGRID records the same paper [DB:BioGRID]. No affinity reported.","key_references":[{"PMID":"25644401","why":"VEGF165-RPTPbeta/zeta interaction in HUVEC and U87MG cells"}],"covers":["LR003445","LR006646"]},"LR001546":{"pair":"VEGFC -> FLT4","headline":"VEGF-C is a well-supported agonist ligand of FLT4 (VEGFR-3), with two concurrent discovery papers, functional and in vivo studies, and structures.","interaction_type":"direct binding","direction_and_effect":"VEGF-C binds Flt4 and induces tyrosine autophosphorylation of VEGFR-3 and VEGFR-2 [PMID:8617204]. VRP, described in the notes as later recognised as VEGF-C, binds the Flt4 extracellular domain and stimulates its phosphorylation, without appreciable binding to Flt1 or Flk1 [PMID:8700872]. Effect is stimulatory.","molecular_requirements":"VEGF-C is proteolytically processed [PMID:8617204], and ADAMTS3 with CCBE1 is needed to convert VEGFC into an active ligand in the in vivo study [PMID:27159393]. In lymphatic endothelial cells VEGF-C also induced VEGFR-3/VEGFR-2 heterodimers in which VEGFR-3 was phosphorylated at three of five sites [PMID:12881528].","affinity_potency":[],"species_and_systems":"Human ligand and receptor in all shown papers, including primary lymphatic endothelial cells and isolated lymphatic endothelial cells [PMID:12881528] [PMID:11532940]; mouse genetics are described in the in vivo paper [PMID:27159393]. Mouse pair is ortholog-inferred.","localisation_and_range":"VEGFC flagged secreted and FLT4 transmembrane [flag].","caveats":"All papers were read as abstracts. The cancer-invasion paper treats the pairing as background [PMID:16530705]. Eleven rows were confirmed but only six are shown here; two more were review-only. No affinity in our evidence. Structures exist [DB:PDB 4BSK].","key_references":[{"PMID":"8617204","why":"VEGF-C identified as Flt4 ligand"},{"PMID":"8700872","why":"independent discovery, specific Flt4 binding"},{"PMID":"27159393","why":"proteolytic activation of VEGFC in vivo"}],"covers":["LR001546","LR004935"]},"LR001555":{"pair":"VIP -> VIPR1","headline":"Well-established direct VIP agonist binding to VPAC1, with many human recombinant studies, sub-nanomolar to low-nanomolar affinity, and structures.","interaction_type":"direct binding","direction_and_effect":"VIP binds human VPAC1 and stimulates cAMP; in transfectants it also raised intracellular calcium [PMID:8074647]. GtoPdb lists agonist [DB:GtoPdb].","molecular_requirements":"VIP residues His1, Val5, Arg14, Lys15, Lys21, Leu23 and Ile26 interact with VPAC1 by alanine scan [PMID:10801840]. Receptor N-terminal ectodomain is essential: E36A abolished 125I-VIP binding [PMID:9454823], W67A abolished binding [PMID:11027527], and VIP Phe6-Tyr22 contacts fragment 104-108 of that domain [PMID:15247290]. A PDB structure exists [DB:PDB 8E3Z].","affinity_potency":[{"value":"Kd 0.2-0.8 nM","assay":"[125I]VIP binding","system":"HEK293/CHO stable transfectants, human VIP1 receptor","cite":"PMID:8074647"},{"value":"Kd 0.8 nM","assay":"saturable VIP binding","system":"COS-7 and 293 cells, human receptor","cite":"PMID:8390245"},{"value":"Ki 0.9 nM","assay":"competition of [125I]VIP binding","system":"CHO clone, human VIP1 receptor","cite":"PMID:8791009"},{"value":"Ki 3.4 nM","assay":"competitive binding","system":"CHO transfectants, human VIPR1","cite":"PMID:9152366"}],"species_and_systems":"Mostly human recombinant receptor in CHO, HEK293 and COS cells; native HT29 cells also respond [PMID:8074647]. Mouse pair is not ortholog-inferred in the record, but no mouse experiment is shown in the papers displayed.","localisation_and_range":"VIP is flagged secreted and VIPR1 transmembrane [flag].","caveats":"Many papers are analogue or mutagenesis studies using VIP as reference, not studies of the endogenous pair itself. VIP also binds VPAC2 with similar affinity, so it is not VPAC1-selective [PMID:10801840]. Only abstracts were read for the papers shown.","key_references":[{"PMID":"8074647","why":"Human VPAC1 binds VIP, couples to cAMP and calcium"},{"PMID":"8791009","why":"Pharmacology of recombinant human VIP1 receptor; VIP highest affinity"},{"PMID":"10801840","why":"Alanine scan of VIP on VPAC1 and VPAC2"}],"covers":["LR001555","LR004944"]},"LR001564":{"pair":"VTN -> ITGB6","headline":"A vitronectin fragment, VTN(381-397), binds alphaVbeta6 and antagonises TGF-beta1 activation; full-length vitronectin is not shown.","interaction_type":"direct binding","direction_and_effect":"In a competition assay the VTN(381-397) peptide bound only alphaVbeta6 and prevented TGF-beta1 activation in human fibroblast-like synoviocytes, acting as an antagonist [PMID:33526813].","molecular_requirements":"Beta6 acts as alphaVbeta6; the evidence is for a fragment, not the whole protein [PMID:33526813].","affinity_potency":[{"value":"IC50 = 3.2 \u00b5M","assay":"competition with radiolabelled echistatin","system":"recombinant human alphaVbeta6, VTN(381-397) peptide","cite":"PMID:33526813"},{"value":"IC50 = 0.79 \u00b5M","assay":"same competition assay","system":"VTN(365-381) fragment at alphaVbeta6","cite":"PMID:33526813"}],"species_and_systems":"Human integrin and primary human synoviocytes [PMID:33526813]; mouse pair is ortholog-inferred.","localisation_and_range":"Vitronectin is flagged as secreted and not transmembrane [flag]; the integrin is a membrane receptor, so signalling is by cell contact with soluble or matrix-bound ligand. The dossier's papers do not describe range further.","caveats":"The fragment, not intact vitronectin, was tested at alphaVbeta6. The paper also noted that 10 ng/mL fragment increased alpha-SMA. Chain-only entry. 3 other abstracts were insufficient. One of the confirmed papers (full text) is the only support.","key_references":[{"PMID":"33526813","why":"VTN fragment competition at alphaVbeta6 with IC50 values"}],"covers":["LR001564","LR004953"]},"LR003454":{"pair":"VWF -> ITGAV","headline":"VWF strings on endothelial cells bind integrin alphavbeta3; functional evidence in one abstract-only paper.","interaction_type":"functional only","direction_and_effect":"RGDS peptide or a function-blocking anti-alphavbeta3 antibody reduced the number of VWF strings formed, integrin alphav decorated the strings, and alphav shRNA knockdown impaired string retention [PMID:18927433]. The curated effect is agonist.","molecular_requirements":"The integrin is alphavbeta3, so ITGB3 is also required; P-selectin is also implicated in anchoring [PMID:18927433].","affinity_potency":[],"species_and_systems":"Live human umbilical vein endothelial cells after histamine stimulation, with shear flow [PMID:18927433]. Mouse pair is ortholog-inferred.","localisation_and_range":"VWF strings several hundred micrometers long are tethered to the endothelial cell surface [PMID:18927433].","caveats":"Abstract-only read. Functional anchoring evidence, not purified binding; no affinity. Database support is for alphaVbeta3:VWF [DB:Reactome].","key_references":[{"PMID":"18927433","why":"alphavbeta3 anchors VWF strings on endothelial cells"}],"covers":["LR003454","LR006654"]},"LR003463":{"pair":"WNT1 -> FZD6","headline":"Recombinant WNT-1 changes FZD6 membrane mobility in a FRAP assay in HEK293T/17 cells; functional evidence.","interaction_type":"functional only","direction_and_effect":"Recombinant WNT-1 increased the FZD6-GFP mobile fraction, indicating action on this receptor, classed as agonist [PMID:24873871].","molecular_requirements":"Changes in FZD6 mobility appear linked to putative precoupling of Gi/o proteins, since pertussis toxin and N-ethylmaleimide altered the effect [PMID:24873871].","affinity_potency":[],"species_and_systems":"Human FZD6-GFP in HEK293T/17 cells; the recombinant WNT proteins' species is not confirmed in the text [PMID:24873871]. Mouse pair is ortholog-inferred.","localisation_and_range":"WNT1 is flagged secreted and non-transmembrane [flag]; the receptor is flagged as a receptor [flag], so signalling is presumably paracrine, but range is not reported in our evidence.","caveats":"Lateral-mobility readout is indirect and not a binding or affinity measurement; no affinity reported in our evidence.","key_references":[{"PMID":"24873871","why":"FRAP shows WNT-1 acts on FZD6"}],"covers":["LR003463","LR006663"]},"LR011239":{"pair":"WNT10A -> FZD10:LRP5","headline":"Database-asserted only: an IntAct co-IP record, with no confirmed paper for WNT10A with FZD10:LRP5.","interaction_type":"database-asserted only","direction_and_effect":"No confirmed paper. IntAct EBI-54877040 records an association by anti-tag coimmunoprecipitation [DB:IntAct]; the record is not specific to this complex.","molecular_requirements":"Subunit requirements not reported in our evidence.","affinity_potency":[],"species_and_systems":"Species and system of the IntAct record are not reported in our evidence.","localisation_and_range":"WNT10A is flagged as secreted [flag], so signalling would be paracrine or autocrine; this comes from the annotation flag.","caveats":"Judged papers: pending 3.","key_references":[],"covers":["LR011239"]},"LR005362":{"pair":"WNT10A -> FZD8","headline":"Functional evidence only: WNT10A induced reporter signalling via FZD8 in a human cell FZD-knockout rescue panel; no binding measured.","interaction_type":"functional only","direction_and_effect":"In HEK293 reporter cells with multiplex FZD knockouts, Wnt10a induced signalling via FZD5 and FZD8, i.e. an activating, canonical-signalling effect [PMID:28733458].","molecular_requirements":"Rescue was with individual FZDs, so FZD8 alone appears sufficient to restore signalling; LRP co-receptor requirement is not reported in our evidence. FZD5 also responded to Wnt10a, so the receptor is not exclusive [PMID:28733458].","affinity_potency":[],"species_and_systems":"Human cells (HEK293 reporter, FZD knockout panel, curator-recorded human ligand and receptor); a human pair, mouse entry is ortholog-inferred [PMID:28733458].","localisation_and_range":"Ligand flagged secreted, receptor not secreted [flag]; the assay used cells expressing both, so range is not tested.","caveats":"Signalling readout in a genetic rescue assay, not physical binding. The paper notes FZD5 and FZD8 are the most promiscuous receptors [PMID:28733458]. Full text was read.","key_references":[{"PMID":"28733458","why":"FZD rescue map: Wnt10a signals via FZD5 and FZD8 in HEK293 reporter cells"}],"covers":["LR002036","LR005362"]},"LR010744":{"pair":"WNT10B -> FZD10:LRP6","headline":"Complex-level pair with no curated paper; rests on one IntAct co-immunoprecipitation record only.","interaction_type":"database-asserted only","direction_and_effect":"Direction and effect (agonist or antagonist) not reported in our evidence. The only support is an IntAct record of association by anti-tag coimmunoprecipitation [DB:IntAct EBI-21797268].","molecular_requirements":"Receptor is listed as a two-chain complex; whether both chains, or either alone, are required is not reported in our evidence. ","affinity_potency":[],"species_and_systems":"Pair is human; the experimental system of the IntAct record is not reported in our evidence.","localisation_and_range":"Ligand is flagged secreted [flag]; the receptor chains are flagged as receptors, with LRP chain transmembrane [flag]. Range is not otherwise reported in our evidence.","caveats":"Only one paper row, judged review-only; the pair rests on the database record alone.","key_references":[],"covers":["LR010744"]},"LR011248":{"pair":"WNT10B -> FZD2:LRP5","headline":"Complex-level pair with no curated paper; rests on one IntAct co-immunoprecipitation record only.","interaction_type":"database-asserted only","direction_and_effect":"Direction and effect (agonist or antagonist) not reported in our evidence. The only support is an IntAct record of association by anti-tag coimmunoprecipitation [DB:IntAct EBI-54924173].","molecular_requirements":"Receptor is listed as a two-chain complex; whether both chains, or either alone, are required is not reported in our evidence. ","affinity_potency":[],"species_and_systems":"Pair is human; the experimental system of the IntAct record is not reported in our evidence.","localisation_and_range":"Ligand is flagged secreted [flag]; the receptor chains are flagged as receptors, with LRP chain transmembrane [flag]. Range is not otherwise reported in our evidence.","caveats":"Two curation rows are still pending; no paper has been judged.","key_references":[],"covers":["LR011248"]},"LR001582":{"pair":"WNT2 -> FZD8","headline":"Functional evidence only: WNT2 with FZD8 activates TCF reporter in human cell lines; one abstract-level paper.","interaction_type":"functional only","direction_and_effect":"Canonical Wnt/TCF signalling was activated when Wnt-2 and Frizzled-8 were co-expressed; a dominant-negative Wnt-2 construct blocked it [PMID:23815780].","molecular_requirements":"Not reported in our evidence (no co-receptor or subunit test).","affinity_potency":[],"species_and_systems":"Human cell lines (293T, 293, A549, A427) and a xenograft mouse model; mouse pair is projected from human evidence [PMID:23815780].","localisation_and_range":"WNT2 is annotated as secreted [flag]; FZD8 is a receptor, not secreted [flag].","caveats":"No direct binding shown; co-expression readout only. Read from abstract only, so details are limited [PMID:23815780]. Mouse pair is ortholog-inferred.","key_references":[{"PMID":"23815780","why":"Co-expression activates TCF reporter; dominant-negative Wnt-2 blocks it"}],"covers":["LR001582","LR004971"]},"LR003481":{"pair":"WNT2B -> FZD6","headline":"Direct binding evidence: WNT2B transfers to purified FZD6-CRD (preprint, human proteins).","interaction_type":"direct binding","direction_and_effect":"WNT2B was rapidly transferred from SFRP2 and GPC4 to FZD6-CRD; the paper treats WNT2B as non-canonical and FZD6 rescued FZD-knockout cells [PMID:39229119].","molecular_requirements":"FZD6 cysteine-rich domain sufficient for transfer; carriers SFRP2 or GPC4 used [PMID:39229119].","affinity_potency":[],"species_and_systems":"Purified human proteins and HEK293 cells [PMID:39229119]. Mouse pair is ortholog-inferred.","localisation_and_range":"WNT2B is annotated as secreted [flag].","caveats":"bioRxiv preprint, not peer reviewed. No affinity value reported [PMID:39229119].","key_references":[{"PMID":"39229119","why":"WNT2B transferred to FZD6-CRD"}],"covers":["LR003481","LR006681"]},"LR008044":{"pair":"WNT3 -> FZD10:LRP6","headline":"No paper evidence; only an IntAct surface plasmon resonance record.","interaction_type":"database-asserted only","direction_and_effect":"Not reported in our evidence beyond a database record [DB:IntAct].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"IntAct record O75581-P56703 from PMID 31036956 by surface plasmon resonance; species not stated [DB:IntAct].","localisation_and_range":"Not reported in our evidence.","caveats":"No verified paper. Judged papers were review-only, abstract-insufficient or a different entity. The IntAct record could not be matched to a complex here [DB:IntAct].","key_references":[],"covers":["LR008044"]},"LR003490":{"pair":"WNT3A -> FZD3","headline":"Functional evidence only: FZD3 mediates Wnt-3a-driven neurite outgrowth via a noncanonical route.","interaction_type":"functional only","direction_and_effect":"Recombinant Wnt-3a stimulated neurite formation in Ewing sarcoma family tumor cells, and Fzd3 antiserum or siRNA markedly reduced it [PMID:18212053]. Disrupting the Wnt/Fzd/LRP complex or LRP5/LRP6 knockdown enhanced neuritogenesis, indicating a beta-catenin-independent response [PMID:18212053].","molecular_requirements":"Dishevelled-2 and Dvl-3 knockdown suppressed outgrowth [PMID:18212053]. LRP5/6 were not required.","affinity_potency":[],"species_and_systems":"Human Ewing sarcoma family tumor cells, recombinant Wnt-3a [PMID:18212053]. Mouse interaction is ortholog-inferred.","localisation_and_range":"WNT3A is flagged secreted and not transmembrane [flag], so signalling is expected to be paracrine or autocrine; range is not measured in our evidence.","caveats":"Abstract-only; no direct binding assay shown in our evidence and no affinity. A second confirmed paper exists but is not shown. No database record.","key_references":[{"PMID":"18212053","why":"Fzd3 needed for Wnt-3a-induced neurite outgrowth"}],"covers":["LR003490","LR006690"]},"LR008134":{"pair":"WNT3A -> FZD3:LRP5","headline":"No curated paper confirms this complex; support is limited to database records.","interaction_type":"database-asserted only","direction_and_effect":"Direction and effect are not reported in our evidence for this complex.","molecular_requirements":"Receptor is a complex of FZD3 and LRP5.; whether both chains are needed is not reported in our evidence.","affinity_potency":[],"species_and_systems":"No experiments in our verified evidence. UniProt notes for LRP5 say an interaction is enhanced by WNT1 or WNT3A without naming a direct contact [DB:UniProt] [PMID:11336703] [PMID:14731402].","localisation_and_range":"WNT3A is flagged secreted and not transmembrane [flag], so signalling is expected to be paracrine or autocrine; range is not measured in our evidence.","caveats":"Only review articles or abstracts too thin to judge were found (outcome counts show review_only and abstract_insufficient), so no primary evidence is verified.","key_references":[],"covers":["LR008134"]},"LR008161":{"pair":"WNT3A -> FZD6:LRP5","headline":"No curated paper for this complex; database records only.","interaction_type":"database-asserted only","direction_and_effect":"Direction and effect are not reported in our evidence beyond database records.","molecular_requirements":"Complex requirement is not shown. The only complex-relevant records are UniProt subunit notes [DB:UniProt].","affinity_potency":[],"species_and_systems":"Species and experimental system are not reported in our evidence for this complex.","localisation_and_range":"WNT3A carries a secreted flag and no transmembrane flag [flag], so it acts as a secreted ligand; range is not reported in our evidence.","caveats":"GtoPdb lists WNT3A-FZD6 agonist interactions, which concern FZD6 alone [DB:GtoPdb]; UniProt notes are generic [DB:UniProt]. Papers were review_only or abstract_insufficient.","key_references":[],"covers":["LR008161"]},"LR008170":{"pair":"WNT3A -> FZD7:LRP5","headline":"No curated paper for this complex; database notes only.","interaction_type":"database-asserted only","direction_and_effect":"Direction and effect are not reported in our evidence.","molecular_requirements":"Complex requirement is not shown in our evidence.","affinity_potency":[],"species_and_systems":"Species and system are not reported in our evidence.","localisation_and_range":"WNT3A carries a secreted flag and no transmembrane flag [flag], so it acts as a secreted ligand; range is not reported in our evidence.","caveats":"Records are IntAct entries from one study [DB:IntAct] and UniProt subunit notes [DB:UniProt] that do not show WNT3A binding to this complex. Papers were review_only.","key_references":[],"covers":["LR008170"]},"LR001591":{"pair":"WNT3A -> LRP6","headline":"WNT3A binds the LRP6 E3E4 propeller region directly and activates canonical signalling; well supported.","interaction_type":"direct binding","direction_and_effect":"Wnt3a activates canonical signalling through LRP6 [PMID:12897152]. Wnt3a-class antibodies binding the third propeller block Wnt3a signalling [PMID:20713706].","molecular_requirements":"Wnt3a binds LRP6 at the third and fourth beta-propeller domains (E3E4); it binds with Fz8 CRD in a reconstituted complex, and Wnt3a and Wnt9b can bind LRP6 simultaneously [PMID:20093360]. Wnt3a binding also involves the third propeller [PMID:20713706]. Wnt triggers an intracellular conformational switch [PMID:12897152].","affinity_potency":[],"species_and_systems":"Purified insect-cell mouse Fz8 CRD and human LRP6 ectodomain [PMID:20093360]; MMTV-Wnt3 xenografts [PMID:20713706]; HEK293T co-IP [PMID:30594556]. Mouse version listed separately, not projected.","localisation_and_range":"Ligand flagged secreted, LRP6 transmembrane [flag]; membrane-level Wnt-co-receptor complex with FZD [DB:Reactome].","caveats":"Most papers read as abstracts. A binding-affinity determination is mentioned but the values are not in our evidence. Database support: BioGRID, IntAct, Reactome and UniProt [DB:BioGRID] [DB:IntAct]. PMID 30594556 is mainly about SMOC-2 enhancing the interaction.","key_references":[{"PMID":"20093360","why":"purified-protein binding of Wnt3a to LRP6 E3E4"},{"PMID":"20713706","why":"antibody epitope mapping of Wnt3a-class LRP6 site"},{"PMID":"12897152","why":"Wnt activation of LRP6 signalling"}],"covers":["LR001591","LR004980"]},"LR010672":{"pair":"WNT4 -> FZD1:LRP6","headline":"No curator-verified paper; only a UniProt statement that argues against WNT4 activating FZD1.","interaction_type":"database-asserted only","direction_and_effect":"Not reported in our evidence as confirmed.","molecular_requirements":"The pair is a FZD1 plus LRP6 complex; no verified evidence for the complex.","affinity_potency":[],"species_and_systems":"Not reported in our evidence.","localisation_and_range":"Ligand flagged secreted [flag].","caveats":"Papers were judged abstract-insufficient or review-only. UniProt says FZD1 is apparently not activated by WNT4 [DB:UniProt].","key_references":[],"covers":["LR010672"]},"LR006703":{"pair":"WNT4 -> LRP6","headline":"One co-IP result in mouse cells shows a Wnt4-LRP6 complex; other papers were abstract-insufficient.","interaction_type":"direct binding","direction_and_effect":"Co-IP revealed a Wnt4-LRP6 binding complex [PMID:31216173].","molecular_requirements":"Wnt4-Fzd1/Fzd2/Fzd6 complexes and LRP-Fzd complexes were also found, so a Frizzled may bridge the interaction [PMID:31216173].","affinity_potency":[],"species_and_systems":"Co-IP in MC3T3 (mouse) cells, per curator note [PMID:31216173]. Human pair ortholog-inferred.","localisation_and_range":"Ligand flagged secreted and LRP6 flagged transmembrane [flag].","caveats":"Single browser-read result, not spot-checked; co-IP does not show direct binding. No affinity in our evidence.","key_references":[{"PMID":"31216173","why":"co-IP of Wnt4 with LRP in MC3T3 cells"}],"covers":["LR003503","LR006703"]},"LR005371":{"pair":"WNT5A -> FZD3","headline":"Wnt5a binds the FZD3 CRD in BLI and is competed by a nanobody; the paper is mainly structural and does not give Wnt5a affinity.","interaction_type":"direct binding","direction_and_effect":"A nanobody (Nb8) bound to the FZD3 CRD reduced Wnt5a binding, indicating competition for FZD3; Nb8 fused to DKK1 C-terminal domain acted as a FZD3-specific Wnt surrogate activating beta-catenin signalling [PMID:39174501]. Wnt5a itself is described as binding immobilized FZD3 CRD in the BLI sensorgrams [PMID:39174501].","molecular_requirements":"The FZD3 CRD lipid-binding groove is the site; Nb8 would impede access of the Wnt palmitoleic moiety [PMID:39174501]. Co-receptors not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human FZD CRDs, biolayer interferometry and crystallography (Nb8 with FZD3 CRD, 1.8 \u00c5) [PMID:39174501].","localisation_and_range":"WNT5A is flagged secreted and not transmembrane [flag], so signalling would be paracrine or autocrine by this annotation.","caveats":"The direct Wnt5a-FZD3 evidence is a competition assay with a nanobody; no Wnt5a affinity is reported in our evidence. The curator read only the abstract; the excerpts supply the BLI details. The surrogate activates signalling independently of native Wnt5a.","key_references":[{"PMID":"39174501","why":"FZD3 CRD-Nb8 structure; Nb8 competes with Wnt5a for FZD3"}],"covers":["LR002045","LR005371"]},"LR001609":{"pair":"WNT5A -> MCAM","headline":"CD146 (MCAM) is reported to bind Wnt5a with high affinity and to signal through Dvl/JNK; one abstract-only paper.","interaction_type":"direct binding","direction_and_effect":"CD146 binds Wnt5a with high affinity, required for Wnt5a-induced Dvl and JNK activation, promoting cell migration; CD146 also inhibits canonical Wnt signalling by promoting beta-catenin degradation [PMID:24335906]. Curated agonist.","molecular_requirements":"The Dvl2-binding region of CD146 is needed for JNK activation and migration [PMID:24335906]. Co-receptors not reported in our evidence.","affinity_potency":[],"species_and_systems":"Cell migration assays and zebrafish convergent extension [PMID:24335906].","localisation_and_range":"MCAM is flagged non-secreted and non-transmembrane, which looks inconsistent with a cell-surface receptor [flag]; ligand flagged secreted [flag].","caveats":"Abstract only; the 'high affinity' value is not given in our evidence.","key_references":[{"PMID":"24335906","why":"CD146 as a high-affinity Wnt5a receptor"}],"covers":["LR001609","LR004998"]},"LR003508":{"pair":"WNT5A -> TLR2","headline":"WNT5A binds TLR2 directly (SPR, pulldown) and signals through it in human myeloid cells; one paper.","interaction_type":"direct binding","direction_and_effect":"Agonist: Wnt5a binds TLR2 and TLR4 and drives MyD88-dependent signalling; in human myeloid cells it induces IL-10 and tolerance, while in mouse cells the profile is pro-inflammatory [PMID:31098409].","molecular_requirements":"Dominant-negative TLR2/TLR4 in THP-1 cells reduced Wnt5a-induced IL-10 and IL-8; the IL-10 response depended on TLR2/4-MyD88 [PMID:31098409]. Other subunits or co-receptors for TLR2: not reported in our evidence.","affinity_potency":[{"value":"KD 26.5 \u00b1 4.5 nM","assay":"SPR, TLR2 on surface, Wnt5a injected (Table 1)","system":"recombinant proteins","cite":"PMID:31098409"}],"species_and_systems":"Human THP-1 cells and primary monocytes plus mouse cells; recombinant proteins for binding [PMID:31098409].","localisation_and_range":"Ligand is annotated as secreted [flag], so paracrine or endocrine range is implied by the annotation only.","caveats":"Single paper, curated from the abstract although full-text excerpts were available. Antibodies against the LPS-binding site of TLR2/4 did not block Wnt5a-induced IL-10 [PMID:31098409]. The text gives ~27, 45 and 36 nM in the order TLR4, TLR4/MD2, TLR2, which does not match Table 1 [PMID:31098409].","key_references":[{"PMID":"31098409","why":"SPR binding, pulldown/MS and TLR-dependence in myeloid cells"}],"covers":["LR003508","LR006708"]},"LR006712":{"pair":"WNT5B -> FZD1","headline":"WNT5B binds the FZD1 CRD only weakly in one binding study; UniProt says FZD1 is apparently not activated by WNT5B.","interaction_type":"conflicting","direction_and_effect":"Binding only: WNT-5B showed weak binding (KD > 40 nm) to FZD CRDs including FZD1 per the paper's sentence [PMID:25605717]. UniProt says FZD1 is apparently not activated by WNT5B [DB:UniProt].","molecular_requirements":"CRD only was tested; co-receptors not reported in our evidence.","affinity_potency":[{"value":"KD > 40 nm","assay":"bio-layer interferometry, FZD CRD-Fc","system":"purified mouse proteins","cite":"PMID:25605717"}],"species_and_systems":"Mouse proteins (purified WNT binding to FZD CRD-Fc), bio-layer interferometry [PMID:25605717]; human pair is ortholog-inferred.","localisation_and_range":"Ligand is annotated as secreted [flag], so paracrine or endocrine range is implied by the annotation only.","caveats":"Binding only; Wnt5b was not shown to activate signalling in this paper (the abstract reports WNT-3A but not WNT-5A as the activator in 32D cells) [PMID:25605717]. Only the abstract was curated, with excerpts from a browser read. The sentence groups FZD1/2/4 for WNT-5A; WNT-5B is described as weak to 'these' CRDs.","key_references":[{"PMID":"25605717","why":"BLI mapping of WNT-FZD CRD binding"}],"covers":["LR003512","LR006712"]},"LR008116":{"pair":"WNT5B -> FZD1:LRP5","headline":"No verified paper supports this WNT5B complex; the only database line says FZD1 is apparently not activated by WNT5B.","interaction_type":"database-asserted only","direction_and_effect":"Direction and effect not reported in our evidence. UniProt says FZD1 is apparently not activated by WNT5B (nor WNT5A, WNT4, WNT6) [DB:UniProt].","molecular_requirements":"Annotated as FZD1 plus LRP5; no evidence on which subunits are required.","affinity_potency":[],"species_and_systems":"Not reported in our evidence.","localisation_and_range":"Ligand is annotated as secreted [flag], so paracrine or endocrine range is implied by the annotation only.","caveats":"Papers read were review-only or abstract-insufficient, none confirmed. The sole database record is a negative statement for FZD1 [DB:UniProt].","key_references":[],"covers":["LR008116"]},"LR008080":{"pair":"WNT5B -> FZD6:LRP6","headline":"Only a FZD6 docking study exists; LRP6 is not addressed.","interaction_type":"computational prediction only","direction_and_effect":"Direction not reported; in silico docking of hWnt5b to hFzd isoforms only [PMID:31285641].","molecular_requirements":"The abstract mentions FZD CRD docking, not LRP6; complex requirement not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human homology models, docking only [PMID:31285641].","localisation_and_range":"Ligand is annotated as secreted [flag], so paracrine or endocrine range is implied by the annotation only.","caveats":"Computational and abstract only; evidence concerns FZD6 alone. Others were review-only or insufficient.","key_references":[{"PMID":"31285641","why":"docking of hWnt5b against hFzd isoforms"}],"covers":["LR008080"]},"LR003517":{"pair":"WNT6 -> FZD4","headline":"Wnt6 and FZD4 knockdown or antibody blockade reduce centrosome amplification; binding is suggested, not shown.","interaction_type":"functional only","direction_and_effect":"Agonist: secreted Wnt6-FZD4-beta-catenin signalling is upstream of ROCK1 and 14-3-3 sigma; Wnt6 or FZD4 siRNA or antibodies attenuated centrosome amplification [PMID:31618077].","molecular_requirements":"Beta-catenin dependent; co-receptors not reported in our evidence.","affinity_potency":[],"species_and_systems":"Cultured cells (species not stated in the abstract) and diabetic mouse colon tissue [PMID:31618077].","localisation_and_range":"Ligand is annotated as secreted [flag], so paracrine or endocrine range is implied by the annotation only.","caveats":"Binding is only suggested ('It is suggested that secreted Wnt6 binds to FZD4') [PMID:31618077]. Abstract only.","key_references":[{"PMID":"31618077","why":"Wnt6-FZD4-beta-catenin in diabetes-linked centrosome amplification"}],"covers":["LR003517","LR006717"]},"LR008035":{"pair":"WNT7A -> FZD1:LRP6","headline":"No paper evidence; the only record says FZD1 is apparently not activated by WNT7A.","interaction_type":"database-asserted only","direction_and_effect":"No confirmed paper. UniProt says FZD1 is apparently not activated by WNT7A or WNT7B [DB:UniProt].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Not reported in our evidence.","localisation_and_range":"WNT7A is flagged secreted and non-transmembrane [flag]; LRP6 is flagged transmembrane [flag].","caveats":"Only abstract-insufficient or review-only judgements exist; the database record argues against the pair.","key_references":[],"covers":["LR008035"]},"LR006721":{"pair":"WNT7A -> FZD6","headline":"WNT-7A changes FZD6 surface mobility in one full-text FRAP study; functional evidence only.","interaction_type":"functional only","direction_and_effect":"Recombinant WNT-7A, among others, increased the mobile fraction of FZD6-GFP, taken as acting on this receptor; WNT-5B and WNT-11 had no effect [PMID:24873871].","molecular_requirements":"Changes in FZD6 mobility relate to putative precoupling of Gi/o proteins [PMID:24873871].","affinity_potency":[],"species_and_systems":"Human FZD6-GFP in HEK293T/17 cells; the species of the recombinant WNT proteins is not confirmed in the text [PMID:24873871].","localisation_and_range":"WNT7A is flagged secreted and non-transmembrane [flag]; acts on the cell-surface receptor.","caveats":"Receptor mobility is not binding; one paper.","key_references":[{"PMID":"24873871","why":"FRAP shows WNT-7A affects FZD6 mobility"}],"covers":["LR003521","LR006721"]},"LR003526":{"pair":"WNT7B -> ADGRA2","headline":"WNT7B-ADGRA2 (GPR124) has abstract-level support: binding to the GPR124:RECK complex and a requirement for GPR124 in Wnt synergy.","interaction_type":"functional only","direction_and_effect":"WNT7A/B bind the GPR124:RECK complex, not WNT3A; GPR124 ectodomain mediates RECK/WNT7 canonical signalling [PMID:30304675]. WNT1/WNT7B synergistic signalling requires GPR124 (ADGRA2) and RECK [PMID:28289266]. UniProt: Gpr124 works with RECK to let brain endothelial cells respond to Wnt7A or B [DB:UniProt].","molecular_requirements":"RECK, FZD5/FZD8 and LRP6 are required for the WNT1/WNT7B synergy [PMID:28289266].","affinity_potency":[],"species_and_systems":"Human proteins per curator fields; HEK293-type cell data not detailed in abstracts [PMID:30304675, PMID:28289266]. Mouse pair ortholog-inferred.","localisation_and_range":"Ligand is flagged secreted and non-transmembrane [flag], so paracrine or autocrine action is expected; the paper's own data on range are not reported in our evidence. ADGRA2 is flagged transmembrane [flag].","caveats":"Both papers abstract-only. Binding is shown for the GPR124:RECK complex, not demonstrated for GPR124 alone in these abstracts; the second paper is functional.","key_references":[{"PMID":"30304675","why":"WNT7 binds GPR124:RECK complex"},{"PMID":"28289266","why":"GPR124 and RECK needed for WNT1/WNT7B synergy"}],"covers":["LR003526","LR006726"]},"LR008017":{"pair":"WNT7B -> ADGRA2:FZD5:LRP6:RECK","headline":"Complex row: WNT7B with GPR124 and RECK has abstract-level support; FZD5 and LRP6 are not shown by the paper.","interaction_type":"direct binding","direction_and_effect":"Reck binds the disordered linker of Wnt7, and Gpr124 plus Reck let brain endothelial cells selectively respond to Wnt7; Reck-bound Wnt7 is recruited into Wnt/Frizzled/Lrp5/6 signalosomes [PMID:30026314]. UniProt agrees [DB:UniProt].","molecular_requirements":"Complex needs ADGRA2, RECK, FZD5 and LRP6 in this row, but only the ADGRA2:RECK part is supported; FZD5 and the LRP are not named in the abstract [PMID:30026314]. Scoring by the least-expressed subunit may over-require them.","affinity_potency":[{"value":"low micromolar","assay":"Reck binding to Wnt7 linker region","system":"abstract states low micromolar affinity, no assay detail","cite":"PMID:30026314"}],"species_and_systems":"Curator lists human proteins in brain endothelial cells; abstract-only reading [PMID:30026314].","localisation_and_range":"Ligand is flagged secreted and non-transmembrane [flag], so paracrine or autocrine action is expected; the paper's own data on range are not reported in our evidence.","caveats":"Abstract only. Affinity is for RECK-Wnt7, not for the full complex. Ligand is not specified as WNT7B versus WNT7A in the abstract beyond Wnt7.","key_references":[{"PMID":"30026314","why":"Reck binds Wnt7 linker; Gpr124/Reck confer Wnt7 selectivity"}],"covers":["LR008017"]},"LR001618":{"pair":"WNT7B -> FZD10","headline":"WNT7B-FZD10: cell-surface binding in one abstract and a hedged knockdown result in another.","interaction_type":"direct binding","direction_and_effect":"Wnt7b bound Fzd10 on the cell surface and cooperatively activated canonical signalling with LRP5 [PMID:15923619]. Fzd10 knockdown reduced Wnt7b- and Wnt10a-induced Wnt/beta-catenin activation, which authors say implies they may be ligands [PMID:29844390].","molecular_requirements":"LRP5 is needed for cooperative canonical activation [PMID:15923619].","affinity_potency":[],"species_and_systems":"Human per curator fields; lung cells and bleomycin in vivo model in the second study, species not stated in the abstract [PMID:29844390].","localisation_and_range":"Ligand is flagged secreted and non-transmembrane [flag], so paracrine or autocrine action is expected; the paper's own data on range are not reported in our evidence.","caveats":"Both abstract only. The second paper's evidence is inferential. Fzd10 is expressed in airway epithelium [PMID:15923619].","key_references":[{"PMID":"15923619","why":"Cell-surface binding of Wnt7b to Fzd10"},{"PMID":"29844390","why":"Fzd10 knockdown reduces Wnt7b-induced signalling"}],"covers":["LR001618","LR005007"]},"LR006730":{"pair":"WNT7B -> RECK","headline":"WNT7B directly binds RECK, a GPI-anchored receptor that stabilises active WNT7; strong direct-binding evidence.","interaction_type":"direct binding","direction_and_effect":"WNT7A and WNT7B, but not WNT3A, directly bind purified soluble RECK, cell-surface RECK and the GPR124:RECK complex [PMID:30304675]. RECK acts as a selective WNT7 receptor mediating GPR124/FZD/LRP-dependent canonical signalling (agonist) [PMID:30304675]. UniProt notes interaction with RECK confers Wnt7 selectivity in brain endothelial cells [DB:UniProt].","molecular_requirements":"RECK works with GPR124, whose ectodomain mediates canonical signalling, plus FZD/LRP co-receptors [PMID:30304675]. WNT7B bound sRECK-Fc but not the VEGFR2 ECD-Fc negative control, and sRECK-Fc dose-dependently inhibited RECK/GPR124/WNT7B reporter activity [PMID:30304675]. 1:1 stoichiometry and stabilisation of monomeric active ligand were shown for WNT7A.","affinity_potency":[],"species_and_systems":"Human WNT constructs in HEK293 RECK-knockout cells; rat brain vessels used for GPR124-RECK association [PMID:30304675].","localisation_and_range":"RECK is GPI-anchored (cell surface); a soluble RECK also binds WNT7B. GPR124:RECK acted in cis (same cell), not trans [PMID:30304675].","caveats":"Abstract plus full-text excerpts. Stoichiometry and stabilisation data are for WNT7A, not WNT7B. The mouse pair is projected from human.","key_references":[{"PMID":"30304675","why":"WNT7A/B bind RECK directly; RECK-GPR124 signalling"}],"covers":["LR003530","LR006730"]},"LR005380":{"pair":"WNT8A -> FZD5","headline":"WNT8A induces signalling via FZD5 in a FZD-knockout reporter map; functional evidence from one paper.","interaction_type":"functional only","direction_and_effect":"Wnt8a induced signalling via FZD5 and FZD8 [PMID:28733458]. Wnt8a acts through a restricted set of FZD genes [PMID:28733458].","molecular_requirements":"FZD5 alone sufficed in the rescue setup; co-receptor need is not reported in our evidence.","affinity_potency":[],"species_and_systems":"HEK293 cells with multiplex FZD CRISPR knockouts [PMID:28733458]; ligand and receptor species fields are not given in this record. The mouse pair is projected from human.","localisation_and_range":"WNT ligand is flagged secreted and not transmembrane [flag], so signalling would be paracrine or autocrine; no paper in our evidence measured range.","caveats":"Single paper, a functional rescue map in HEK293 cells; promiscuous FZD5/FZD8 (about 70% homology) may be redundant [PMID:28733458].","key_references":[{"PMID":"28733458","why":"Wnt-FZD functional interaction map"}],"covers":["LR002054","LR005380"]},"LR008071":{"pair":"WNT8A -> FZD5:LRP6","headline":"WNT8A signalling via FZD5:LRP6 supported by one functional paper; LRP6 co-receptor is not tested.","interaction_type":"functional only","direction_and_effect":"Wnt8a induced signalling via FZD5 and FZD8 in reporter cells [PMID:28733458].","molecular_requirements":"Evidence concerns the Frizzled chain only; LRP6 involvement is not reported in our evidence.","affinity_potency":[],"species_and_systems":"HEK293-type reporter cells with FZD knockouts [PMID:28733458]; species not stated in this record.","localisation_and_range":"WNT ligand is flagged secreted and not transmembrane [flag], so signalling would be paracrine or autocrine; no paper in our evidence measured range.","caveats":"The complex pair rests on a FZD-only result, so it is chain-only evidence; other judged papers were review_only or abstract_insufficient.","key_references":[{"PMID":"28733458","why":"Wnt-FZD functional interaction map"}],"covers":["LR008071"]},"LR003535":{"pair":"WNT8B -> FZD5","headline":"WNT8B induces signalling via FZD5 in a FZD-knockout reporter map; functional evidence from one paper.","interaction_type":"functional only","direction_and_effect":"Wnt8b induced signalling via FZD5 and FZD8 [PMID:28733458].","molecular_requirements":"FZD5 alone sufficed in the rescue setup; co-receptor need is not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human ligand and receptor constructs in HEK293 reporter cells with FZD knockouts [PMID:28733458]. The mouse pair is projected from human.","localisation_and_range":"WNT ligand is flagged secreted and not transmembrane [flag], so signalling would be paracrine or autocrine; no paper in our evidence measured range.","caveats":"Single paper, a functional rescue map in HEK293 cells; promiscuous FZD5/FZD8 (about 70% homology) may be redundant [PMID:28733458].","key_references":[{"PMID":"28733458","why":"Wnt-FZD functional interaction map"}],"covers":["LR003535","LR006735"]},"LR008152":{"pair":"WNT8B -> FZD5:LRP5","headline":"WNT8B activates FZD5 signalling in a reporter-cell rescue map; one functional paper, no binding data.","interaction_type":"functional only","direction_and_effect":"WNT8B induced canonical (TCF/Wnt-reporter) signalling via FZD5, i.e. ligand-to-receptor agonism in a functional readout [PMID:28733458].","molecular_requirements":"The receptor is listed as FZD5 plus LRP5; the paper's statement names only the Frizzled, and a requirement for LRP5 is not reported in our evidence.","affinity_potency":[],"species_and_systems":"Experiments used reporter cells in a rescue design with FZD-mutant lines [PMID:28733458]; species of the cells is not stated in the excerpts.","localisation_and_range":"Secreted ligand per the entity annotation flag [flag]; paracrine range is inferred from that flag only, not reported in the papers.","caveats":"Functional reporter readout only; no direct binding shown. Paper is a genetic rescue map of Wnt-FZD pairs, so paralog FZDs differ in specificity [PMID:28733458].","key_references":[{"PMID":"28733458","why":"Multiplex CRISPR FZD-knockout rescue map of Wnt-Frizzled signalling (full text read)."}],"covers":["LR008152"]},"LR008125":{"pair":"WNT9A -> FZD10:LRP5","headline":"WNT9A signals through FZD10 in a reporter-cell rescue map; functional evidence from one paper, no binding data.","interaction_type":"functional only","direction_and_effect":"WNT9A signalled only via FZD4 and FZD10 among the FZDs tested, inducing canonical reporter signalling (agonism) [PMID:28733458].","molecular_requirements":"The receptor is listed as FZD10 plus LRP5; the paper's statement names only the Frizzled, and a requirement for LRP5 is not reported in our evidence.","affinity_potency":[],"species_and_systems":"Experiments used reporter cells in a rescue design with FZD-mutant lines [PMID:28733458]; species of the cells is not stated in the excerpts.","localisation_and_range":"Secreted ligand per the entity annotation flag [flag]; paracrine range is inferred from that flag only, not reported in the papers.","caveats":"Functional reporter readout only; no direct binding shown. Paper is a genetic rescue map of Wnt-FZD pairs, so paralog FZDs differ in specificity [PMID:28733458].","key_references":[{"PMID":"28733458","why":"Multiplex CRISPR FZD-knockout rescue map of Wnt-Frizzled signalling (full text read)."}],"covers":["LR008125"]},"LR003544":{"pair":"WNT9A -> MUSK","headline":"WNT9A binds MuSK extracellular domain and induces MuSK dimerization and phosphorylation; reported by one abstract-level study.","interaction_type":"direct binding","direction_and_effect":"Wnt9a and Wnt11 bind directly to the extracellular domain of MuSK, inducing MuSK dimerization and tyrosine phosphorylation; curators label it agonist [PMID:22309736].","molecular_requirements":"Wnt-induced acetylcholine receptor (AChR) clustering requires both MuSK and LRP4 [PMID:22309736]. AChR clustering by Wnt9a was dose-dependent and non-additive to agrin [PMID:22309736].","affinity_potency":[],"species_and_systems":"Cell/muscle-cell system; curators list human ligand and receptor, and the human pair is ortholog-inferred while the mouse pair is not, suggesting mouse experiments [PMID:22309736].","localisation_and_range":"WNT9A is flagged secreted [flag]; acts on the muscle MuSK receptor, so paracrine/synaptic.","caveats":"Read at abstract level only (read_depth abstract_only); binding affinity not reported. LRP4 requirement means MuSK alone may not suffice.","key_references":[{"PMID":"22309736","why":"Wnt9a binds MuSK ectodomain, induces dimerization, requires LRP4"}],"covers":["LR003544","LR006744"]},"LR010753":{"pair":"WNT9B -> FZD2:LRP6","headline":"Database-asserted WNT9B to FZD2:LRP6 complex; no curator-verified paper supports the complex as a unit.","interaction_type":"database-asserted only","direction_and_effect":"Direction and effect are not reported in our evidence. UniProt subunit notes assert that FZD-family O14905 (WNT9B) interacts directly in the complex with LRP6 and that LRP6 (via beta-propeller regions 1 and 2) interacts with WNT9B [DB:UniProt].","molecular_requirements":"The complex is the FZD2 plus LRP6 pair; no experiment in our evidence tests the combination. Support is from UniProt notes about WNT9B and LRP6 only [DB:UniProt].","affinity_potency":[],"species_and_systems":"Not reported in our evidence; the UniProt records cite PMID 20093360 and PMID 11357136 but no dossier paper was verified for this complex [DB:UniProt].","localisation_and_range":"WNT9B is flagged as secreted [flag], so signalling would be paracrine; the receptor is a membrane receptor [flag].","caveats":"Rests on database records alone; the notes do not name the Frizzled chain. Papers were judged only as review_only or abstract_insufficient. Treat as a projection from WNT9B-LRP6 evidence.","key_references":[],"covers":["LR010753"]},"LR002059":{"pair":"WNT9B -> FZD4","headline":"WNT9B activates canonical signalling through FZD4 in a human reporter-cell rescue map; one functional study.","interaction_type":"functional only","direction_and_effect":"Wnt9b induced canonical signalling with FZD4 and FZD10, as well as FZD5 and FZD8; effect is activating [PMID:28733458].","molecular_requirements":"FZD4 was tested as a single rescue receptor; FZD4 and FZD10 behaved similarly in clustering; the sgRNA design carried a 1-mismatch to FZD4 so knockout may have been partial [PMID:28733458].","affinity_potency":[],"species_and_systems":"HEK293 Wnt reporter cells (human; TCF4 luciferase) with FZD knockout and rescue [PMID:28733458]; mouse pair is ortholog-inferred.","localisation_and_range":"WNT9B is flagged as secreted [flag], so signalling would be paracrine; the receptor is a membrane receptor [flag].","caveats":"Functional reporter only; no binding data. The pan-FZD sgRNA had one mismatch at FZD4 per the excerpts, which complicates the knockout background.","key_references":[{"PMID":"28733458","why":"FZD knockout/rescue reporter map showing WNT9B signalling"}],"covers":["LR002059","LR005385"]},"LR008062":{"pair":"WNT9B -> FZD4:LRP6","headline":"Database-asserted WNT9B to FZD4:LRP6 complex; no curator-verified paper supports the complex as a unit.","interaction_type":"database-asserted only","direction_and_effect":"Direction and effect are not reported in our evidence. UniProt subunit notes assert that FZD-family O14905 (WNT9B) interacts directly in the complex with LRP6 and that LRP6 (via beta-propeller regions 1 and 2) interacts with WNT9B [DB:UniProt].","molecular_requirements":"The complex is the FZD4 plus LRP6 pair; no experiment in our evidence tests the combination. Support is from UniProt notes about WNT9B and LRP6 only [DB:UniProt].","affinity_potency":[],"species_and_systems":"Not reported in our evidence; the UniProt records cite PMID 20093360 and PMID 11357136 but no dossier paper was verified for this complex [DB:UniProt].","localisation_and_range":"WNT9B is flagged as secreted [flag], so signalling would be paracrine; the receptor is a membrane receptor [flag].","caveats":"Rests on database records alone; the notes do not name the Frizzled chain. Papers were judged only as review_only or abstract_insufficient. Treat as a projection from WNT9B-LRP6 evidence.","key_references":[],"covers":["LR008062"]},"LR012373":{"pair":"ZNRF3 -> FZD3:LRP6","headline":"Database-asserted only: ZNRF3 (an E3 ligase) is listed as inhibiting a FZD:LRP receptor complex; no curator-verified paper.","interaction_type":"database-asserted only","direction_and_effect":"Marked inhibitory in the resource, with ZNRF3 acting as a membrane receptor-receptor regulator rather than a classical secreted ligand [flag]. UniProt states ZNRF3 interacts with LRP6, FZD4, FZD5, FZD6 and FZD8 [PMID:22575959][DB:UniProt]; IntAct records anti-bait co-immunoprecipitation (Q9ULT6-O75581) [DB:IntAct]; BioGRID records ZNRF3 - LRP6: Affinity Capture-Western; LRP6 - ZNRF3: Affinity Capture-Western [DB:BioGRID]; Reactome lists ZNRF3,RNF43 binding the FZD:LRP5/6 receptor complex [DB:Reactome]. Functional effect not reported in our evidence.","molecular_requirements":"The listed FZD3 partner is not named in the UniProt statement; LRP6 evidence is present [DB:UniProt]. Whether FZD or LRP alone suffices is not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human. Experimental system not reported in our evidence beyond the database assay labels.","localisation_and_range":"ZNRF3 is flagged as a receptor, not secreted [flag]; this is a membrane-level interaction.","caveats":"All papers for this pair are pending or insufficient; support comes only from databases. The pair is a receptor-receptor complex projection and a given FZD paralog may not have been tested individually.","key_references":[],"covers":["LR012373"]},"LR012157":{"pair":"ZNRF3 -> FZD7:LRP5","headline":"Database-asserted only: ZNRF3 (an E3 ligase) is listed as inhibiting a FZD:LRP receptor complex; no curator-verified paper.","interaction_type":"database-asserted only","direction_and_effect":"Marked inhibitory in the resource, with ZNRF3 acting as a membrane receptor-receptor regulator rather than a classical secreted ligand [flag]. BioGRID records FZD7 - ZNRF3: Affinity Capture-Western; ZNRF3 - FZD7: Affinity Capture-Western [DB:BioGRID]. Functional effect not reported in our evidence.","molecular_requirements":"Evidence concerns FZD7 only; LRP5 is not covered in our evidence. Whether FZD or LRP alone suffices is not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human. Experimental system not reported in our evidence beyond the database assay labels.","localisation_and_range":"ZNRF3 is flagged as a receptor, not secreted [flag]; this is a membrane-level interaction.","caveats":"All papers for this pair are pending or insufficient; support comes only from databases. The pair is a receptor-receptor complex projection and a given FZD paralog may not have been tested individually.","key_references":[],"covers":["LR012157"]},"LR004309":{"pair":"IL1A -> IL1R2","headline":"IL-1 alpha binds the type II IL-1 receptor, a decoy-type receptor; direct binding shown in one abstract-read paper.","interaction_type":"direct binding","direction_and_effect":"Soluble and cell-surface type II IL-1 receptor bind IL-1 alpha and IL-1 beta; the soluble form acts as a specific inhibitor of IL-1 beta activity [PMID:7878046]. This indicates a decoy/inhibitory role rather than signalling, though the dossier labels the pair Stimulatory [flag].","molecular_requirements":"Not reported in our evidence beyond the receptor itself; binding was to the same regions on IL-1 beta for soluble and cell-surface forms [PMID:7878046].","affinity_potency":[],"species_and_systems":"Human Raji B cell line, radioligand competition binding [PMID:7878046]. Mouse pair is projected from human evidence.","localisation_and_range":"Ligand annotated as secreted [flag]; the receptor exists as membrane-bound and released soluble forms [PMID:7878046].","caveats":"Abstract-only reading. The paper's detail concerns IL-1 beta more than IL-1 alpha. IntAct (coimmunoprecipitation) and Reactome records support binding [DB:IntAct][DB:Reactome]. One further paper is pending.","key_references":[{"PMID":"7878046","why":"Competition binding of IL-1 alpha and beta to type II receptor, soluble and cell-surface"}],"covers":["LR000879","LR004309"]}};